/// Trust (path-guard walk, COLLAPSE MODE 3): the `VcKind::UnsupportedMir { kind, .. }`
/// tag `generate_vcs` returns, once per function, when the path-guard walk hit
/// its FRONTIER budget — the pop / live-queue caps that bound that walk
/// (`generate::safety::MAX_PATH_WALK_STEPS` / `MAX_PATH_WALK_QUEUE`).
///
/// The tag exists because that collapse is otherwise INVISIBLE. It degrades
/// every block of the function to an unguarded path, which is fail-closed
/// (hypotheses are removed, never added) but indistinguishable in the emitted
/// rows from a function whose blocks genuinely had no path condition: MEASURED
/// 2026-09-09 on `ay-arrays::final_check`, the 20 emitted VCs hashed
/// byte-identically with the budget tripping and with it switched off.
///
/// Public so the compiler's reporting seams and the tests that pin them match on
/// the exact tag rather than on prose. The string is the published seal's
/// (trust 321aaeda75), so the row keeps its identity across the two.
pub const VCGEN_PATH_GUARD_FRONTIER_BUDGET_KIND: &str = "TrustPathGuardFrontierBudgetTripped";

/// Record the verified target's pointer width. The value lives in
/// [`trust_types::target_pointer_bits`], so the bridge reads the same fact.
pub fn set_target_pointer_bits(bits: u32) {
    trust_types::set_target_pointer_bits(bits);
}

/// Trust (2026-09-27): the pointer width, in bits, of the target this compilation
/// verifies for. It defaults to 64 when no compiler has recorded one, so that tools and
/// unit tests, which run on a 64-bit host with no target in hand, behave as before.
///
/// Read by the allocation lane's bounded-source grant, which rests on 64-bit
/// address-space facts and is withheld on any other width
/// (`docs/KNOWN_HAZARDS.md`, "the bounded-source capacity grant").
pub(crate) fn target_pointer_bits() -> u32 {
    trust_types::target_pointer_bits().unwrap_or(64)
}
