// Lever A steps 3+4: non-recursive datatype equations over the modeled
// Level/Expr/ExprKind cluster. This lane deliberately remains separate from
// `generate_vcs`: it emits a POSITIVE functional equation, whereas the generic
// solver pipeline consumes violation formulas (SAT means counterexample).
// Public so the controlled trust-certify adapter and end-to-end integration
// gate consume the exact emitted VC without rebuilding its shape.
pub mod datatype_functional;
// WALL C: recursive-datatype-function INDUCTION VCs — per-constructor
// induction-case obligations (recursive calls replaced by IH variables) plus
// the tagged conclusion, for a SELF-recursive fn over a modeled Ty::Datatype.
// `pub` (not pub(crate)): trust-integration-tests drives the emitted bundle
// end-to-end into trust-certify's recursive_datatype_functional discharge.
pub mod recursive_datatype_functional;
// WALL C scaled to MUTUAL SCCs: fuel-indexed mutual-cluster INDUCTION VCs —
// per-member base (fuel = 0) and step (fuel = S k) case obligations where a
// call to ANY cluster member becomes an IH atom (`[calls=..]`-tagged), plus
// the ONE joint `[mutual-induction:..]`-tagged conclusion — the machine twin
// of the Aristotle-proved MutualCluster.lean VC-decomposition view. `pub`:
// trust-integration-tests drives the emitted bundle end-to-end into
// trust-certify's mutual_recursive_datatype_functional discharge.
pub mod mutual_recursive_datatype_functional;
// SN-vs-fuel RESOLUTION item 1: the STATE-THREADED numeric-budget induction
// lane — the mutual shape upgraded from each-at-k structural fuel to a
// threaded (remainder-passing) budget with per-entry decrement, model-vs-
// reference postconditions, and remainder-threading IH atoms. `pub`:
// trust-integration-tests drives the emitted bundle end-to-end into
// trust-certify's threaded_budget_functional discharge.
pub mod threaded_budget_functional;
// SN-vs-fuel RESOLUTION items 2+3: fail-closed exhaustion arms with
// Done-conditional postconditions (outcome-returning fuel models) and the
// loop -> fuel-model per-iteration simulation VCs. `pub`: driven end-to-end
// into trust-certify's fuel_outcome_functional discharge.
pub mod fuel_outcome_functional;
