/// Whether stdlib-span behavioral memory-safety rows belong to this exact
/// compilation subject. Missing or mismatched context returns `false`, matching
/// the pre-context dependency behavior; compiler integration always supplies
/// the crate-ownership classification explicitly.
#[must_use]
pub(crate) fn verify_stdlib_subject_memory_safety_for(def_path: &str) -> bool {
    with_current_vcgen_context(def_path, |context| context.verify_stdlib_subject_memory_safety)
        .unwrap_or(false)
}

/// The contract-panic payloads for `def_path`, or empty when no active context
/// belongs to that exact function (fail-closed: no cross-function stamping).
#[must_use]
pub(crate) fn contract_panic_annotations_for(def_path: &str) -> Vec<String> {
    with_current_vcgen_context(def_path, |context| context.contract_panic_annotations.clone())
        .unwrap_or_default()
}

/// The declared process-signal policy for `def_path`, or `None` when no active
/// context belongs to that exact function or none was declared (fail-closed: an
/// undeclared policy leaves the `ProcessSemantics` mandate open).
#[must_use]
pub(crate) fn process_signal_policy_for(def_path: &str) -> Option<String> {
    with_current_vcgen_context(def_path, |context| context.process_signal_policy.clone()).flatten()
}

/// Whether the compiler judged `callee` (its rendered name) NON-REENTRANT for
/// `def_path` — a vanilla sysroot routine that can dispatch into no user code.
/// Missing or mismatched context is fail-closed (`false`: unclassified).
#[must_use]
pub(crate) fn callee_is_nonreentrant_for(def_path: &str, callee: &str) -> bool {
    with_current_vcgen_context(def_path, |context| context.nonreentrant_callees.contains(callee))
        .unwrap_or(false)
}

/// Trust (2026-09-25): the compiler's recursion-SCC facts for `def_path`, read
/// back out of the owner-checked context. `None` — no context, a mismatched
/// owner, or a function in no multi-member SCC — leaves the direct-self
/// termination lanes exactly as they were.
#[must_use]
pub(crate) fn recursion_scc_context_for(def_path: &str) -> Option<RecursionSccContext> {
    with_current_vcgen_context(def_path, |context| context.recursion_scc.clone()).flatten()
}

/// Trust (ARGS-FINGERPRINT-READ-1 round 3, 2026-10-07): whether the compiler's
/// `DefId`-decided direct-self-call set for `def_path` admits `block`.
/// `true` when no set is installed (no context, a mismatched owner, or a
/// non-compiler caller): the rendered-path comparison then decides alone, as
/// before. See `VcgenContext::direct_self_call_blocks`.
#[must_use]
pub(crate) fn compiler_admits_direct_self_call(def_path: &str, block: BlockId) -> bool {
    with_current_vcgen_context(def_path, |context| {
        context.direct_self_call_blocks.as_ref().map(|blocks| blocks.contains(&block.0))
    })
    .flatten()
    .unwrap_or(true)
}

/// Trust (GENERIC-CALL-KEY-ALIAS-1 with ARGS-FINGERPRINT-READ-1 round 4,
/// 2026-10-10): whether the compiler's `DefId`-decided direct-self-call set for
/// `def_path` is INSTALLED and files `block`. Unlike
/// [`compiler_admits_direct_self_call`], no installed set (no context, a
/// mismatched owner, a non-compiler caller) answers `false`: this is the only
/// authority that may read an alias-tagged call as a self call, and it never
/// defaults open.
#[must_use]
pub(crate) fn compiler_files_direct_self_call(def_path: &str, block: BlockId) -> bool {
    with_current_vcgen_context(def_path, |context| {
        context.direct_self_call_blocks.as_ref().map(|blocks| blocks.contains(&block.0))
    })
    .flatten()
    .unwrap_or(false)
}

/// Trust (ALLOC-STRIDE-ADT-2, 2026-10-07): the compiler's lower bound of
/// `size_of` for the lowered type `ty`, as recorded for `func` — `Some(n)` with
/// `n >= 1`, or `None`.
///
/// Fail-closed at every step: `None` without an active context, for a context
/// owned by another def path (the owner check every per-function read uses),
/// without an installed table, when `func`'s type digest is not the one the table
/// was bound to (another instance sharing the def path, or a function whose types
/// were changed after install), and for a key with no sized row.
#[must_use]
pub(crate) fn compiler_elem_size_lower_bound(
    func: &trust_types::VerifiableFunction,
    ty: &trust_types::Ty,
) -> Option<u64> {
    compiler_elem_size_table(func)?.table.lower_bound(ty)
}

/// One owner/type-bound table per pass. Exact-size consumers must use
/// `exact_size`, never the minimum of distinct source representations.
pub(crate) fn compiler_elem_size_table(
    func: &trust_types::VerifiableFunction,
) -> Option<std::sync::Arc<elem_sizes::ElemSizeBinding>> {
    let binding = with_current_vcgen_context(&func.def_path, |context| context.elem_sizes.clone())
        .flatten()?;
    (generate::elem_size_binding_digest_for(func)? == binding.bound_digest).then_some(binding)
}

/// Read the whole-body-bound compiler table once per consumer pass, not once
/// per length query. A foreign owner, absent table or changed body fails closed.
pub(crate) fn compiler_primitive_decimal_strings(
    func: &trust_types::VerifiableFunction,
) -> Option<std::sync::Arc<PrimitiveDecimalStringTable>> {
    let table = with_current_vcgen_context(&func.def_path, |context| {
        context.primitive_decimal_strings.clone()
    })
    .flatten()?;
    table.matches_body(func).then_some(table)
}

pub(crate) fn inherited_primitive_decimal_strings(
    def_path: &str,
) -> Option<std::sync::Arc<PrimitiveDecimalStringTable>> {
    with_current_vcgen_context(def_path, |context| context.primitive_decimal_strings.clone())
        .flatten()
}

/// The element-size binding of the TOP frame when it is owned by `def_path`, for
/// a fresh frame of the same function to carry (regeneration parity). Another
/// owner's binding never crosses.
fn inherited_elem_sizes(def_path: &str) -> Option<std::sync::Arc<elem_sizes::ElemSizeBinding>> {
    with_current_vcgen_context(def_path, |context| context.elem_sizes.clone()).flatten()
}

/// The `DefId`-decided direct-self-call blocks of the TOP frame when it is owned
/// by `def_path`, for a fresh frame of the same function to carry (regeneration
/// parity; see [`VcgenContext::for_function_inheriting_regeneration_facts`]).
fn inherited_direct_self_call_blocks(def_path: &str) -> Option<std::collections::BTreeSet<usize>> {
    with_current_vcgen_context(def_path, |context| context.direct_self_call_blocks.clone())
        .flatten()
}

/// Trust (2026-09-25): run `f` under a context that carries ONLY `scc` for
/// `def_path`, or with no new frame at all when `scc` is `None`.
///
/// This exists for ONE consumer: the compiler's verifier-API bundle
/// construction, which re-derives a function's source-bound recursion
/// `decreases` rows (`regenerate_recursion_decreases_production_variants`) to
/// check them byte-for-byte against the rows the production generation
/// supplied. That regeneration takes no context argument, and a recursion-SCC
/// member's rows depend on the compiler's SCC facts; without them the fresh set
/// would lack every mutual-call row and a sound authored measure could never
/// discharge its clause. Every other policy bit stays at its default, which is
/// what that regeneration saw before this frame existed.
pub fn with_recursion_scc_context<R>(
    def_path: &str,
    scc: Option<RecursionSccContext>,
    f: impl FnOnce() -> R,
) -> R {
    with_termination_identity_context(def_path, scc, None, f)
}

/// [`with_recursion_scc_context`], also carrying the compiler's `DefId`-decided
/// direct-self-call blocks (ARGS-FINGERPRINT-READ-1 round 3; see
/// `VcgenContext::direct_self_call_blocks`), so the bundle constructor's
/// recursion-`decreases` regeneration classifies self calls exactly as the
/// production generation did. With both `None` no frame is pushed.
pub fn with_termination_identity_context<R>(
    def_path: &str,
    scc: Option<RecursionSccContext>,
    direct_self_call_blocks: Option<std::collections::BTreeSet<usize>>,
    f: impl FnOnce() -> R,
) -> R {
    if scc.is_none() && direct_self_call_blocks.is_none() {
        return f();
    }
    let mut context = VcgenContext::for_function(def_path)
        .with_recursion_scc(scc)
        .with_direct_self_call_blocks(direct_self_call_blocks);
    // Trust (ALLOC-STRIDE-ADT-2): a regeneration of the SAME function sees
    // the same element-size table the production generation saw; the
    // binding digest still rejects a changed function at the read.
    context.elem_sizes = inherited_elem_sizes(def_path);
    with_vcgen_context(&context, f)
}

/// Trust (2026-10-05, ORD-WITNESS-CONSISTENT-1): whether the active context's
/// compiler-established set names `name` as an ADT whose `PartialOrd` operators
/// are one consistent total order. Missing context or entry fails closed to
/// `false`: the ordering-witness lane then credits no comparison guard.
#[must_use]
pub(crate) fn is_order_consistent_adt(name: &str) -> bool {
    with_current_callee_summaries(|summaries| summaries.facts.order_consistent_adts.contains(name))
        .unwrap_or(false)
}

/// Trust (TINV step 10.2): the type-invariant use set installed in the active context.
/// Missing context or set fails closed to `None`: no use-site fact.
#[must_use]
pub(crate) fn current_type_invariants() -> Option<std::sync::Arc<type_invariant::TinvUseSet>> {
    with_current_callee_summaries(|summaries| summaries.facts.type_invariants.clone()).flatten()
}

#[must_use]
pub(crate) fn is_backing_struct_certified(name: &str) -> bool {
    with_current_callee_summaries(|summaries| {
        summaries.facts.certified_backing_structs.contains(name)
    })
    .unwrap_or(false)
}

/// Trust (Clean-origin definitional grounding, assert-refutation lane): the
/// Clean-origin definitional call model installed in the active
/// [`VcgenContext`] for the callee sealed as `identity` — an EXACT identity
/// lookup, no name anywhere in the decision. Missing context or entry fails
/// closed to `None`; callers must treat `None` as "no model", never as a
/// licence to fall back to the rendered callee name.
#[must_use]
pub(crate) fn clean_origin_definitional_model_for(
    identity: &trust_types::CalleeIdentity,
) -> Option<modular::CleanOriginDefinitionalCallModel> {
    with_current_callee_summaries(|summaries| {
        summaries.facts.clean_origin_definitional_models.get(identity).cloned()
    })
    .flatten()
}

#[must_use]
pub(crate) fn has_any_clean_origin_definitional_models() -> bool {
    with_current_callee_summaries(|summaries| {
        !summaries.facts.clean_origin_definitional_models.is_empty()
    })
    .unwrap_or(false)
}

/// Which calls reach a summarized body — the value side of
/// `CalleeSummaryFacts::summary_body_identities`, compared against a call's
/// [`trust_types::CalleeIdentity`] by [`call_reaches_summarized_body`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SummaryBodyIdentity {
    /// Every call whose identity names this `DefId`, at any instantiation: the def
    /// IS the body (a free function, or a method of an inherent impl). A summary is
    /// derived from the one generic body, so it holds at each instantiation.
    Item { stable_crate_id: u64, def_index: u32 },
    /// Exactly the calls carrying this identity: a method of a trait impl. A call
    /// names the TRAIT item, whose identity does not determine the body, so only the
    /// impl's own fully concrete trait-reference arguments select it, and only when
    /// rustc resolves that instantiation to this body (the compiler checks with
    /// `Instance::try_resolve`).
    Instance(trust_types::CalleeIdentity),
}

/// True iff `term` is a call that REACHES the body its callee's summaries were
/// derived from: the call carries an identity, and that identity is the recorded
/// identity of the summarized body (`summary_body_identities`).
///
/// Every body-derived callee summary (return bounds, constant sets, return
/// discriminants, bool predicates, trivial setters) is keyed by the def path of the
/// body it was derived from and looked up by the call's rendered name, and a
/// rendering is not an identity. Two ways it names the wrong body, each measured as
/// callers PROVED, kernel-certified, that panic:
///
///  * NO identity (2026-09-30, `fdbae3cb63a`): the extractor withholds one while the
///    instantiation still mentions a type parameter
///    (`trust_mir_extract::convert::callee_identity_for`), and such a call can
///    dispatch anywhere: a blanket `impl<T: Marker> Tr for T` has def path
///    `<T as krate::Tr>::m`, and so does the unresolvable `t.m(x)` inside
///    `fn f<T: Tr>`, which runs `impl Tr for Foo` at `T = Foo` (residual 1 of
///    `direct_call_def_path`); `summary_needs_a_resolved_call_refused.rs`.
///  * ANOTHER body's identity (2026-09-30, round 7): a type nested inside a path is
///    not namespace-tagged (residual 7c of `apply_cross_namespace_tag`), so a
///    concrete call to a trait DEFAULT method, or to a generic inherent impl, can
///    render exactly like an override or a concrete inherent impl elsewhere while
///    carrying the identity of the default or generic item it really calls;
///    `summary_needs_the_summarized_body_refused.rs`.
pub(crate) fn call_reaches_summarized_body(term: &Terminator) -> bool {
    let Terminator::Call { callee_identity: Some(_), .. } = term else {
        return false;
    };
    with_current_callee_summaries(|summaries| summaries.call_reaches_summarized_body(term))
        .unwrap_or(false)
}

/// `callee` with every `->` turned into `-~`, the same length, so a bracket-depth
/// scan does not read the `>` of a function type's arrow as a closing bracket and
/// every byte offset into the result is an offset into `callee`. Every bracket-depth
/// parser of a rendered callee in this crate scans the masked spelling.
///
/// Trust (2026-10-01, review round 29): a callee rendering carries the type of a
/// fn-item callable inside its generics (`<Map<Copied<Iter<'_, u8>>, fn(u8) -> u32
/// {big}> as Iterator>::sum::<u32>`). Read as a bracket, that `>` closed the
/// qualifier early, `iterator_integer_fold_call` missed the call, and the fold row
/// charging its overflow was never minted, while the compiler, which decides on
/// `DefId`s, granted the call as charged: an overflowing `.map(big).sum()` was
/// CERTIFIED and panicked.
pub(crate) fn mask_fn_arrows(callee: &str) -> std::borrow::Cow<'_, str> {
    if callee.contains("->") {
        std::borrow::Cow::Owned(callee.replace("->", "-~"))
    } else {
        std::borrow::Cow::Borrowed(callee)
    }
}

/// Trust (2026-10-01): whether `def_path` selects exactly one summarized body: it is
/// in the compiler's body-identity map, which keeps a def path only when one body
/// carries it and that body is not interposable, an intrinsic or a trait item. For a
/// summary consumed WITHOUT a call terminator to compare identities with (a closure
/// passed by value to `Iterator::map`), this is the identity gate.
///
/// When `stable_crate_id` is given, the one body must also be an item of THAT
/// crate: a callable constant names its crate, and a local body sharing a foreign
/// callable's rendered path (one `--crate-name` for two crates) must not lend its
/// summary to it (review round 32).
pub(crate) fn summary_body_is_unique_in(def_path: &str, stable_crate_id: Option<u64>) -> bool {
    with_current_callee_summaries(|summaries| {
        match (summaries.facts.summary_body_identities.get(def_path), stable_crate_id) {
            (None, _) => false,
            (Some(_), None) => true,
            (Some(SummaryBodyIdentity::Item { stable_crate_id: body, .. }), Some(id)) => {
                *body == id
            }
            (Some(_), Some(_)) => false,
        }
    })
    .unwrap_or(false)
}

#[cfg(test)]
/// Test contexts: record each summarized def path as the body of the synthetic
/// identity the unit tests' concrete call sites carry (crate 1, index 1).
pub(crate) fn test_summary_body_identities(
    def_paths: impl IntoIterator<Item = String>,
) -> trust_types::fx::FxHashMap<String, SummaryBodyIdentity> {
    def_paths
        .into_iter()
        .map(|p| (p, SummaryBodyIdentity::Item { stable_crate_id: 1, def_index: 1 }))
        .collect()
}

/// Read a whole-crate function return upper bound installed in the active
/// [`VcgenContext`] (compute it with [`compute_return_bound_summaries`]).
/// Consumed at call sites: a call `dest = callee(..)` whose `callee` has a
/// recorded bound `b` licenses the SSA-gated, staleness-versioned fact
/// `dest <= b`, discharging a guarded access through a bounding helper
/// (`arr[clamp_idx(i)]`). Missing context or entry fails closed to `None`.
#[must_use]
pub fn callee_return_upper_bound(callee: &str) -> Option<i128> {
    with_current_callee_summaries(|summaries| summaries.facts.return_bounds.get(callee).copied())
        .flatten()
}

/// Read a whole-crate function return lower bound from the active context
/// (compute it with [`compute_return_lower_bound_summaries`]). Consumed at
/// call sites: a call `dest = callee(..)` whose `callee` has a recorded lower
/// bound `c` licenses the SSA-gated, staleness-versioned fact `dest >= c`
/// (discharging e.g. a Rem-by-zero obligation on `h % small_den(g)`).
#[must_use]
pub fn callee_return_lower_bound(callee: &str) -> Option<i128> {
    with_current_callee_summaries(|summaries| {
        summaries.facts.return_lower_bounds.get(callee).copied()
    })
    .flatten()
}

/// Trust (G1, 2026-10-27): the C symbol whose documented pointer return contract the
/// same-crate wrapper `callee` returns unchanged (compute it with
/// [`compute_return_ffi_pointer_summaries`]). A caller must also check
/// [`call_reaches_summarized_body`]. Missing context or entry fails closed to `None`.
#[must_use]
pub(crate) fn callee_ffi_pointer_return_symbol(callee: &str) -> Option<String> {
    with_current_callee_summaries(|summaries| {
        summaries.facts.return_ffi_pointer_contracts.get(callee).cloned()
    })
    .flatten()
}

/// Read a whole-crate return interval from the active context (compute it with
/// [`compute_return_interval_summaries`]): `(lower, upper)`, each side present
/// only when tighter than the callee's return type. Consumed at call sites that
/// reach the summarized body, as `dest >= lower` / `dest <= upper`.
#[must_use]
pub fn callee_return_interval(callee: &str) -> Option<(Option<i128>, Option<i128>)> {
    with_current_callee_summaries(|summaries| summaries.facts.return_intervals.get(callee).copied())
        .flatten()
}

/// Read a whole-crate PAYLOAD return interval from the active context (compute it
/// with [`compute_return_payload_interval_summaries`]): `(variant, lower, upper)` for
/// a callee returning a std `Option<iN>`/`Result<iN, E>`. Consumed only on the
/// payload a caller extracts from a call that reaches the summarized body.
#[must_use]
pub fn callee_return_payload_interval(callee: &str) -> Option<(usize, Option<i128>, Option<i128>)> {
    with_current_callee_summaries(|summaries| {
        summaries.facts.return_payload_intervals.get(callee).copied()
    })
    .flatten()
}

/// Read a whole-crate function's exact constant return set from the active
/// context (compute with [`compute_return_const_set_summaries`]; only functions whose
/// EVERY return site is a constant are recorded). Consumed at call sites as the
/// disjunction `dest == c1 ∨ … ∨ dest == ck` — strictly stronger than the two
/// bound facts. Missing context or entry fails closed to `None`.
#[must_use]
pub fn callee_return_const_set(callee: &str) -> Option<Vec<i128>> {
    with_current_callee_summaries(|summaries| {
        summaries.facts.return_const_sets.get(callee).cloned()
    })
    .flatten()
}

