/// Whether Trust already COVERS this call — either the separation engine models
/// it (`sep_engine::call_is_modeled`, emitting an obligation / tracking it) or the
/// unsafe-fn name heuristic recognizes it (block obligation). Exposed so the
/// compiler can cross-check against rustc's AUTHORITATIVE function safety
/// (`fn_sig().safety()`) and emit a fail-closed obligation for any rustc-unsafe
/// call Trust does NOT already cover — making unsafe-call detection complete (no
/// unsafe call silently escapes) instead of relying on the name lists alone.
#[must_use]
/// THE ONE DECISION: does `span` belong to a source file the compiler
/// AUTHENTICATED as the real standard library?
///
/// Both consumers call exactly this function with exactly the same table, which
/// is what makes "the engine and the compiler agree on every span" a structural
/// fact rather than a claim about two predicates:
///
///   * `sep_engine::is_trusted_std_span` passes the table installed on the
///     active [`VcgenContext`], and a `true` DISCHARGES the span's
///     `[unsafe:sep:*]` rows (and suppresses the stand-in `generate_safety_vcs`
///     would mint for the operation).
///   * `rustc_mir_transform::trust_verify`'s unmodeled-unsafe-CALL generator
///     passes the table it built from its own `TyCtxt`, and a `true` DECLINES
///     the audit flag for a std-macro-authored unsafe call (`thread_local!` →
///     `LazyStorage::get_or_init`). Std is the trusted TCB the verifier
///     hard-skips; this is not a proof, it declines a finding whose obligation
///     belongs to std.
///
/// UNTIL 2026-09-20 THIS TOOK ONLY THE SPAN and answered by matching
/// `span.file` against `library/<std-crate>/src/` and `<std-crate>/src/`
/// prefixes. `SourceSpan::file` is the unremapped local path the user compiled,
/// so a user who put their code in a directory named `core/src/` silenced BOTH
/// consumers at once. The `files` parameter is the fix: the verdict now comes
/// from `is_real_sysroot_crate(tcx, SourceFile::cnum)` — artifact residency —
/// and the path is a join key into that authenticated table.
///
/// Fail-closed: an empty or not-installed table answers `false` for every span
/// (keep every obligation, mint every finding), as does a file the table does
/// not name. See [`trust_types::TrustedStdSourceFiles`] for the full list of
/// ways it falls closed, including the collision rule.
///
/// THE SPAN IS THE FIRST PARAMETER ON PURPOSE. `sep_engine`'s crate-wide
/// forgeable-key census classifies a predicate by the TYPE OF ITS FIRST
/// PARAMETER, which is how it sees span and file-path keys at all — the
/// round-6 widening added exactly that because a `span:`-name-only scan had
/// lost `contracts.rs::source_span_contains(outer: &SourceSpan)`. Putting the
/// table first would read better and would make this function INVISIBLE to the
/// census, which is the one thing a commit in this campaign may not do.
pub fn span_is_trusted_std(
    span: &trust_types::SourceSpan,
    files: &trust_types::TrustedStdSourceFiles,
) -> bool {
    files.contains(&span.file)
}

/// THE COMPILER'S SUPPRESSION DECISION, MADE ON THE CALLEE'S KEY.
///
/// `rustc_mir_transform::trust_verify` calls this at its unsafe-call
/// COMPLETENESS check, and a `true` WITHHOLDS the authoritative, fail-closed
/// `[unsafe:unmodeled-call]` obligation for that call. Until 2026-09-20 it asked
/// [`call_has_unsafe_model`] — a substring predicate — over
/// `trust_mir_extract::safe_def_path_str(tcx, did)`, and for a LOCAL callee that
/// string is THE USER'S OWN PATH. `is_unsafe_fn_call`'s table is BARE,
/// UN-NAMESPACED LEAF NAMES (`"set_len"`, `"get_unchecked"`, `"assume_init"`,
/// `"new_unchecked"`, `"unreachable_unchecked"`, `"from_u32_unchecked"`,
/// `"from_bytes_with_nul_unchecked"`), so a user who NAMED A METHOD `set_len`
/// decided whether their own `unsafe fn` call got the completeness obligation at
/// all. That is the substring class, at the one site where it could still
/// suppress a refutation, and this closes it.
///
/// THE RULE, in the order it is decided:
///
///  1. `key.sysroot_item` names one of the DECLARED sysroot items
///     (`trust_types::callee_key::DECLS`) — the closed vocabulary the mint
///     recognizes, resolved by the extractor from `(TyCtxt, DefId)` alone. Trust
///     models the call, so the completeness row would double-flag it. TRUE.
///  2. The callee's crate is NOT the compiler's own sysroot
///     (`is_real_sysroot_crate` — ARTIFACT RESIDENCY, not a crate name). FALSE,
///     unconditionally: a user path, a dependency's path, an impersonating
///     `core`'s path may not suppress the obligation whatever it spells. THIS
///     IS THE DEFECT'S FIX.
///  3. Otherwise the callee IS a genuine sysroot item outside the declared
///     vocabulary, and the legacy text predicate decides — over
///     `safe_def_path_str` of a DEFINITION in a crate the compiler
///     authenticated. What it reads there is the sysroot's own def path: the
///     string carries no generic arguments (`def_path_str`, not
///     `def_path_str_with_args`) and no user-supplied content, so the
///     attacker-chosen text that every round of this campaign has been about
///     cannot reach it. It keeps the `::ffi::` / `::intrinsics::` namespace arms
///     and `is_unsafe_fn_call`'s leaf table working for the sysroot items the
///     vocabulary does not yet name (`ptr::swap`, `ptr::replace`,
///     `slice::index`'s `SliceIndex::get_unchecked`, every
///     `intrinsics::simd::*`), each of which keeps its byte-frozen stand-in
///     instead — so this commit does not silently re-flag half the sysroot.
///
/// VCGEN NO LONGER PREDICTS ANY OF THIS. The round-5 fail-open (vcgen predicting
/// a row the compiler does not mint) was closed structurally on 2026-09-20: the
/// mint is handed the compiler's own rows through
/// [`VcgenContext::with_compiler_unmodeled_call_blocks`], so changing the rule
/// here cannot desynchronize a mirror — there is no mirror. The mint sees
/// exactly the rows this function let through, whatever they are.
#[must_use]
pub fn call_has_unsafe_model_keyed(key: &trust_types::CalleeKey, callee: &str) -> bool {
    // A refusal-only tag (std thread spawn) names an item Trust does NOT model;
    // it falls through to the legacy sysroot predicate exactly as an untagged
    // sysroot item does.
    if key.modeled_sysroot_item().is_some() {
        return true;
    }
    if !key.krate_is_real_sysroot {
        return false;
    }
    call_has_unsafe_model(callee)
}

/// A refusal-only std thread-spawn tag must never read as an unsafe-call model:
/// `Builder::spawn_unchecked` is an `unsafe fn`, and a tag that answered `true`
/// here deleted its fail-closed `[unsafe:unmodeled-call]` row.
#[cfg(test)]
mod refusal_only_tag_tests {
    #[test]
    fn std_thread_spawn_tags_are_not_unsafe_models() {
        let key = |item| trust_types::CalleeKey {
            sysroot_item: Some(item),
            krate_is_real_sysroot: true,
            krate_name_is_ambiguous: false,
            stable_crate_id: 7,
            krate_name: "std".to_string(),
            foreign_block_leaf: None,
            upstream_foreign_link_symbol: None,
            diverging_entry: None,
        };
        let path = "std::thread::builder::Builder::spawn_unchecked";
        assert!(!super::call_has_unsafe_model(path), "the legacy predicate has no model");
        for &item in trust_types::STD_THREAD_SPAWN_ITEMS {
            assert!(trust_types::callee_key::item_is_refusal_only(item));
            assert_eq!(key(item).modeled_sysroot_item(), None, "{item:?}");
            assert!(!super::call_has_unsafe_model_keyed(&key(item), path), "{item:?}");
        }
        // A modeled tag still answers from the key.
        let modeled = key(trust_types::SysrootItem::PtrRead);
        assert!(!trust_types::callee_key::item_is_refusal_only(trust_types::SysrootItem::PtrRead));
        assert!(super::call_has_unsafe_model_keyed(&modeled, "whatever"));
    }
}

pub fn call_has_unsafe_model(callee: &str) -> bool {
    let lower: std::borrow::Cow<'_, str> =
        if callee.bytes().any(|b| b.is_ascii_uppercase()) || !callee.is_ascii() {
            std::borrow::Cow::Owned(callee.to_lowercase())
        } else {
            std::borrow::Cow::Borrowed(callee)
        };
    // T5A parity note: "::ffi::" was DELETED from `is_unsafe_fn_call`'s name
    // list (it matched a NAMESPACE and falsely flagged safe std::ffi paths in
    // unsafe-block detection), but it is retained HERE. This predicate only
    // reaches rustc-UNSAFE, non-foreign calls (the compiler gates on
    // `fn_sig().safety()` first), and every such call under a `::ffi::` path
    // (`CStr::from_ptr`, `CString::from_raw`, …) IS still covered by Trust's
    // block-obligation lane — now via the authoritative
    // `Terminator::Call::is_unsafe_sig` instead of the name. Claiming coverage
    // keeps the compiler from double-flagging those calls with an
    // always-refuting [unsafe:unmodeled-call] VC; safe ::ffi:: paths never get
    // here, so the old false-positive surface cannot return through this door.
    //
    // `"::intrinsics::"` is retained for EXACTLY the same reason, and by the
    // same argument. `is_unsafe_fn_call` no longer answers `true` for the whole
    // intrinsics namespace (it now decides on the callee's declared safety), so
    // without this arm every rustc-unsafe intrinsic outside the transcribed
    // leaf sets — `intrinsics::simd::*`, `intrinsics::mir::*`, anything
    // `library/core` adds later — would newly acquire an always-refuting
    // `[unsafe:unmodeled-call]` VC. Those calls ARE covered by the block-
    // obligation lane through the authoritative `is_unsafe_sig`. And the
    // reverse direction cannot leak: a SAFE intrinsic never reaches this
    // predicate, because the compiler gates on `fn_sig().safety()` first
    // (`trust_verify.rs:15666-15691`).
    sep_engine::call_is_modeled(&lower)
        || unsafe_verify::detection::is_unsafe_fn_call(callee)
        || lower.contains("::ffi::")
        || lower.contains("::intrinsics::")
}

/// Trust: Filter VCs by verification level.
///
/// Only keeps VCs at or below the specified maximum level.
/// L0 = safety only, L1 = safety + functional, L2 = all.
#[must_use]
pub fn filter_vcs_by_level(
    vcs: Vec<VerificationCondition>,
    max_level: ProofLevel,
) -> Vec<VerificationCondition> {
    vcs.into_iter().filter(|vc| vc_within_level(vc, max_level)).collect()
}

/// Trust (T3 L4, C07): whether `vc` is at or below `max_level` — the one predicate
/// [`filter_vcs_by_level`] applies, for a carrier that filters its rows in place (the
/// compiler's `BodyRows`, which moves each row with its id).
#[must_use]
pub fn vc_within_level(vc: &VerificationCondition, max_level: ProofLevel) -> bool {
    vc.kind.proof_level() <= max_level
}

