/// Extract discovered guard clauses from a function's MIR control flow.
///
/// Returns all guard conditions discovered from SwitchInt and Assert
/// terminators. This is the raw clause output before path accumulation.
///
/// Public API for guard clause discovery and JSON report output.
#[must_use]
pub fn discover_clauses(func: &VerifiableFunction) -> Vec<DiscoveredClause> {
    func.body.discovered_clauses()
}

/// Build the path map for a function, showing accumulated guards per block.
///
/// Each entry gives the conjunction of guard conditions required to reach
/// that block from the entry point.
///
/// Public API for path condition queries and JSON report output.
#[must_use]
pub fn build_path_map(func: &VerifiableFunction) -> Vec<PathMapEntry> {
    func.body.path_map()
}

/// Resolve the type of an operand from the function's local declarations.
///
/// Promoted to `pub` for use by trust-transval translation validation.
pub fn operand_ty(func: &VerifiableFunction, op: &Operand) -> Option<Ty> {
    match op {
        Operand::Copy(place) | Operand::Move(place) => place_ty(func, place),
        Operand::Constant(cv) => Some(match cv {
            ConstValue::Bool(_) => Ty::Bool,
            // SOUNDNESS (P0, hunt-revealed): `ConstValue::Int` carries no width, so it
            // was ALWAYS typed i64 — but an i128 constant SUBEXPRESSION (`i128::MAX-1`,
            // `i128::MIN+1`, `(i128::MAX/2)*2`) holds a value OUTSIDE i64's range, and
            // the i64-width in-range PREMISE then emitted for it (`i64::MIN <= v <=
            // i64::MAX`) is CONSTANT-FALSE — vacuously discharging any downstream
            // overflow VC (default-mode false proof: `let x=i128::MAX-1; x+b` proved
            // yet overflows). The value tells the width: a signed literal that does NOT
            // fit i64 cannot be narrower than i128 (Rust has no i65..i127), so widen to
            // 128. A value that fits i64 keeps width 64 — its in-range premise stays
            // TRUE and the OPERATION's type (not the const's) drives its overflow VC —
            // so this only corrects the previously-vacuous wide-constant case.
            ConstValue::Int(v) => {
                let width =
                    if (i64::MIN as i128..=i64::MAX as i128).contains(v) { 64 } else { 128 };
                Ty::Int { width, signed: true }
            }
            // ConstValue::Uint now carries bit width from MIR extraction.
            ConstValue::Uint(_, w) => Ty::Int { width: *w, signed: false },
            ConstValue::Float(_) => Ty::Float { width: 64 },
            ConstValue::FloatBits { width, .. } => Ty::Float { width: *width },
            ConstValue::Unit | ConstValue::CallableItem { .. } => Ty::Unit,
            // Trust (2026-09-12, -O print machinery): a string-literal constant is a
            // `&str` fat pointer, modeled on the legacy verifier lane as its byte view
            // `&[u8]` (`ty_convert.rs` spells `str` as `Slice { elem: u8 }`). Without
            // this arm the const fell to `_ => None`, and the `&str -> &[u8]`
            // transmute that `format_args!` emits at -O reported "source operand type
            // is unavailable" — a spurious `unsupported_mir` row on every printing
            // program built with optimizations. The CHC lowering already models the
            // constant itself as a fresh symbolic fat pointer (`str_smt_var_name`).
            ConstValue::Str { .. } => Ty::Ref {
                mutable: false,
                inner: Box::new(Ty::Slice { elem: Box::new(Ty::Int { width: 8, signed: false }) }),
            },
            // A typed opaque integer value carries its declared integer type; its
            // identity is its `origin` (OPAQUE-SCALAR-ID-1), never this type.
            ConstValue::OpaqueScalar { width, signed, .. } => {
                Ty::Int { width: *width, signed: *signed }
            }
            // Trust: piece #7a — a const-generic PARAM value carries its declared
            // integer type, identical to `OpaqueScalar`; identity is in the name.
            // `width == 1 && !signed` is the in-band encoding of a BOOL
            // const-generic (`const B: bool`, e.g. aterm-lz4's `USE_DICT`):
            // Rust has no 1-bit integer type, so the pattern is unambiguous.
            // It types as `Ty::Bool` so guards over it get the Bool sort that
            // its every use site expects — the correlation across `if B { … }`
            // branches (one shared symbol) is what keeps dict-gated paths from
            // decorrelating into spurious counterexamples.
            ConstValue::ConstParam { width: 1, signed: false, .. } => Ty::Bool,
            ConstValue::ConstParam { width, signed, .. } => {
                Ty::Int { width: *width, signed: *signed }
            }
            // Sound fallback for unknown ConstValue variants.
            // ConstValue is #[non_exhaustive], so new variants may appear.
            // Returning None (unknown type) is conservative — the caller will
            // use a default type, and VCs will be over-approximate.
            _ => return None,
        }),
        Operand::Symbolic(formula) => formula_ty(formula),
        // Sound fallback for unknown Operand variants.
        // Operand is #[non_exhaustive], so new variants may appear.
        // Return None rather than panicking — this causes callers to skip
        // VC generation for the unknown operand, which is sound (no missed bugs,
        // just potentially missed VCs).
        Operand::Unsupported { .. } => None,
        _ => None,
    }
}

/// Resolve an operand's type as a `Cow<Ty>` — the borrowed counterpart of `operand_ty`.
///
/// For a `Copy`/`Move` of a place this funnels through `place_ty_cow`, so a BARE FULL-VALUE
/// read of a fat-`Ty::Adt` local (`Operand::Move(whole_expr_local)`, the proof-combinator
/// family's `Expr`/`Eq`/`Name` arguments) resolves WITHOUT cloning the multi-MB declared
/// root — the dominant `TrustVcGenWorkBudgetExceeded` driver after the `place_ty` borrowed
/// walk. The `Constant`/`Symbolic` arms synthesize small owned types (a scalar `Ty`), so
/// they are returned `Cow::Owned`; nothing fat is ever cloned here.
///
/// Use this for any `operand_ty` caller that only INSPECTS the type (a `matches!`,
/// `is_integer`/`int_width`/`is_signed`, `sort_for_ty`/`ty_byte_size`, or an equality
/// check). A caller that needs an OWNED `Ty` (to store / feed a `VcKind`) keeps calling
/// `operand_ty` (or `.into_owned()`s this result), which meters the materialized clone
/// exactly as baseline.
///
/// SOUNDNESS: byte-identical RESULT to `operand_ty` — same resolution, the only difference
/// is that the fat root is BORROWED rather than cloned (`Ty` is immutable during VC-gen).
/// Inert/identical outside a VC-gen scope. DROP-ONLY: it never weakens or deletes an
/// obligation; under-charging the meter for a clone that never happens can only let MORE
/// functions complete (Unknown → Proved/runtime-checked), never manufacture a false-prove.
pub(crate) fn operand_ty_cow<'a>(
    func: &'a VerifiableFunction,
    op: &Operand,
) -> Option<std::borrow::Cow<'a, Ty>> {
    use std::borrow::Cow;
    match op {
        Operand::Copy(place) | Operand::Move(place) => place_ty_cow(func, place),
        // The non-place arms synthesize small scalar types — borrowing buys nothing, so
        // reuse `operand_ty`'s exact construction and own the (cheap) result. This keeps
        // the `ConstValue::Int` i64/i128 width-widening soundness fix (and every other
        // arm) in ONE place.
        _ => operand_ty(func, op).map(Cow::Owned),
    }
}

fn formula_ty(formula: &Formula) -> Option<Ty> {
    let sort = formula_sort(formula)?;
    match sort {
        Sort::Bool => Some(Ty::Bool),
        Sort::Int => Some(Ty::Int { width: 64, signed: true }),
        Sort::BitVec(width) => Some(Ty::Int { width, signed: false }),
        Sort::Array(_, _) => None,
        _ => None,
    }
}

pub(crate) fn formula_sort(formula: &Formula) -> Option<Sort> {
    match formula {
        Formula::Bool(_) => Some(Sort::Bool),
        Formula::Int(_) | Formula::UInt(_) => Some(Sort::Int),
        Formula::BitVec { width, .. } => Some(Sort::BitVec(*width)),
        Formula::Var(_, sort) | Formula::SymVar(_, sort) => Some(sort.clone()),
        Formula::Not(_)
        | Formula::And(_)
        | Formula::Or(_)
        | Formula::Implies(_, _)
        | Formula::Eq(_, _)
        | Formula::Lt(_, _)
        | Formula::Le(_, _)
        | Formula::Gt(_, _)
        | Formula::Ge(_, _)
        | Formula::BvULt(_, _, _)
        | Formula::BvULe(_, _, _)
        | Formula::BvSLt(_, _, _)
        | Formula::BvSLe(_, _, _)
        | Formula::Forall(_, _)
        | Formula::Exists(_, _) => Some(Sort::Bool),
        Formula::Add(_, _)
        | Formula::Sub(_, _)
        | Formula::Mul(_, _)
        | Formula::Div(_, _)
        | Formula::Rem(_, _)
        | Formula::Neg(_)
        | Formula::BvToInt(_, _, _) => Some(Sort::Int),
        Formula::BvAdd(_, _, width)
        | Formula::BvSub(_, _, width)
        | Formula::BvMul(_, _, width)
        | Formula::BvUDiv(_, _, width)
        | Formula::BvSDiv(_, _, width)
        | Formula::BvURem(_, _, width)
        | Formula::BvSRem(_, _, width)
        | Formula::BvAnd(_, _, width)
        | Formula::BvOr(_, _, width)
        | Formula::BvXor(_, _, width)
        | Formula::BvNot(_, width)
        | Formula::BvShl(_, _, width)
        | Formula::BvLShr(_, _, width)
        | Formula::BvAShr(_, _, width)
        | Formula::IntToBv(_, width) => Some(Sort::BitVec(*width)),
        Formula::BvExtract { high, low, .. } => Some(Sort::BitVec(high.saturating_sub(*low) + 1)),
        Formula::BvConcat(lhs, rhs) => {
            Some(Sort::BitVec(formula_bit_width(lhs)?.saturating_add(formula_bit_width(rhs)?)))
        }
        Formula::BvZeroExt(inner, extra) | Formula::BvSignExt(inner, extra) => {
            Some(Sort::BitVec(formula_bit_width(inner)?.saturating_add(*extra)))
        }
        Formula::Ite(_, then_formula, else_formula) => {
            let then_sort = formula_sort(then_formula)?;
            (then_sort == formula_sort(else_formula)?).then_some(then_sort)
        }
        Formula::Select(array, _) => match formula_sort(array)? {
            Sort::Array(_, elem) => Some(*elem),
            _ => None,
        },
        Formula::Store(array, _, _) => formula_sort(array),
        Formula::ConstArray { index_sort, elem_sort, .. } => {
            Some(Sort::Array(Box::new(index_sort.clone()), Box::new(elem_sort.clone())))
        }
        _ => None,
    }
}

fn formula_bit_width(formula: &Formula) -> Option<u32> {
    match formula_sort(formula)? {
        Sort::BitVec(width) => Some(width),
        _ => None,
    }
}

// ── verifier-perf: mid-generation VC-WORK budget (a sound, additive bound) ──
//
// A function can have modest *per-place* types yet still explode the VC-generator,
// because the generation walk MATERIALIZES (clones) the declared `Ty` tree once per
// `place_ty`/`place_sort`/`operand_ty` query, of which there are O(places ×
// statements). When the declared type is a deeply-nested recursive ADT — the kernel's
// `Expr`/`ExprKind`/`Name`/`Environment` lower to fat `Ty::Adt` trees (flattened
// enums) — those repeated deep clones drive VC-gen to multi-GB RSS.
// `clean-kernel`'s `build_ind_app` (`for fv in param_fvars { app = Expr::app(app, fv) }`)
// is the witness: modest declared signature, thousands of fat-`Adt` clones, minutes of
// stall with the verifier making zero visible progress.
//
// (This sentence used to end "and never complete", one clause before offering "minutes
// of stall" as its own evidence. See the CORRECTION on `MAX_BUNDLE_ADT_BUDGET` below:
// the observation on record is memory exhaustion and multi-minute stalls, never a
// demonstrated non-termination, and the escalation to "non-terminating" in
// `tests/self-proof/trust-semantics.baseline` was measured false on 2026-08-28.)
//
// FIX (a TRUE mid-generation work-bound): meter the ACTUAL generation work — the
// structural `Ty`-node count materialized by every type clone the generation walk
// performs. `place_ty` is the funnel through which the walk materializes an owned
// declared/projected `Ty`; `place_sort_from_declared_type` → `sort_for_ty` is the
// second O(datatype-size) hot path (it builds a `Sort` WITHOUT cloning the `Ty`, so it
// bypasses `place_ty`). Accumulate the node count per function in a thread-local; once
// it crosses the budget, set a sticky `tripped` flag and, from then on, have these hot
// paths hand back cheap fail-closed values (a `Ty::Unsupported` leaf / `Sort::Int`) so
// the in-flight walk finishes in bounded time rather than stalling. The per-function
// VC-gen entry points reset the meter on entry and, on exit, if it tripped, DISCARD
// every (partial, possibly leaf-degraded) obligation the walk produced and emit a single
// fail-closed `UnsupportedMir` for the whole function — degrading it, and only it, to
// Unknown.
//
// SOUNDNESS (paramount): this can only ADD Unknown, never manufacture a PROVE.
//  * The `tripped` flag is sticky for the function. Any obligation generated after the
//    trip — degraded leaf or not — is DISCARDED by the entry point, so the leaf returns
//    never reach a reported verdict.
//  * A non-tripping function clones identically to baseline (the meter only counts; it
//    never alters a type), so its verdicts are byte-identical.
//  * A tripping function is replaced wholesale by `unsupported_mir_vc`, which
//    preclassifies to Unknown and is NEVER Proved, and never a guaranteed-violation.
// Each function's VC-gen is independent (its own reset on entry); the meter is inert
// outside a scope, so a stray `place_ty` call behaves as pre-bound baseline.

/// Default mid-generation work budget, counted as structural `Ty` nodes MATERIALIZED
/// across the two O(datatype-size) generation hot paths during ONE function's VC-gen:
/// the `place_ty` `Ty`-tree clones AND the `place_sort_from_declared_type` →
/// `sort_for_ty` builds (each called O(places × statements) times). Sized FAR above any
/// ordinary function (a typical function touches a few small types a few hundred times —
/// well under ~500K nodes) but FAR below the many millions a `build_ind_app`-shaped
/// aggregate-loop explosion reaches before it stalls at multi-GB RSS. So only the
/// genuinely pathological generation-explosion functions trip it, and they trip EARLY
/// (bounding peak memory). The production value is deterministic because crossing this
/// bound changes the fail-closed obligation inventory.
const MAX_GENERATION_WORK_BUDGET: usize = 2_000_000;

mod gen_work {
    //! Thread-local mid-generation work meter (see the block comment above
    //! `place_ty`). A re-entrancy DEPTH guard makes the meter scope the OUTERMOST
    //! VC-gen entry for a function: nested calls (e.g.
    //! `…_and_summaries` → `…_with_discharge` → `generate_vcs`) share one meter, so
    //! the work the outer call already accumulated (callsite preconditions,
    //! abstract-interp pre-pass) is not clobbered by an inner reset. The meter resets
    //! only on the 0→1 entry and the budget/flag persist for the whole function's
    //! generation.
    use std::cell::{Cell, RefCell};

    thread_local! {
        /// Cumulative structural `Ty`-node work materialized this function.
        static WORK: Cell<usize> = const { Cell::new(0) };
        /// Sticky: set once `WORK` crosses the budget for this function.
        static TRIPPED: Cell<bool> = const { Cell::new(false) };
        /// Per-function cached deterministic budget.
        /// `usize::MAX` disables the bound.
        static BUDGET: Cell<usize> = const { Cell::new(super::MAX_GENERATION_WORK_BUDGET) };
        /// Re-entrancy depth: reset fires only on the 0→1 transition.
        static DEPTH: Cell<usize> = const { Cell::new(0) };
        /// Locals whose declared-type materialization has ALREADY been charged this
        /// scope, keyed by `(locals-slice ptr, local index)`. The meter measures PEAK
        /// materialization, not cumulative re-query CHURN: every projected place type is a
        /// SUBTREE of its base local's declared type (`<= that local's node count`, itself
        /// `<= 8_000` — the extractor's `MAX_TYPE_LOWERING_PRODUCED_NODES` cap) and every
        /// clone is TRANSIENT (built into a `Sort`, then dropped), so at most O(1) fat clone
        /// is live at a time. Charging a local's declared-type nodes ONCE (an upper bound
        /// covering all its projections) bounds peak by `Sigma_{distinct locals} nodes(ty)`;
        /// re-charging the same local per query mistook cumulative churn for peak and tripped
        /// spuriously (aterm-spec `eval`: a few `Expr`-typed locals re-queried hundreds of
        /// times across lanes). The `ptr` discriminator keeps the key correct under a
        /// cross-function nested `enter()` reusing a bare index.
        static CHARGED: RefCell<trust_types::fx::FxHashSet<(usize, usize)>> =
            RefCell::new(trust_types::fx::FxHashSet::default());
    }

    #[cfg(test)]
    thread_local! {
        static TEST_BUDGET: Cell<Option<usize>> = const { Cell::new(None) };
    }

    /// The production work budget is fixed because crossing it changes the
    /// fail-closed obligation inventory. Tests use an explicit thread-local
    /// override rather than ambient process state.
    fn read_budget() -> usize {
        #[cfg(test)]
        if let Some(budget) = TEST_BUDGET.with(Cell::get) {
            return if budget == 0 { usize::MAX } else { budget };
        }
        super::MAX_GENERATION_WORK_BUDGET
    }

    #[cfg(test)]
    pub(super) fn set_test_budget(budget: Option<usize>) {
        TEST_BUDGET.with(|slot| slot.set(budget));
    }

    /// Enter a VC-gen scope. On the OUTERMOST entry (depth 0→1) the meter is reset and
    /// the budget re-read. Returns a guard that decrements depth on drop.
    #[must_use]
    pub(super) fn enter() -> Guard {
        let depth = DEPTH.with(|d| {
            let n = d.get();
            d.set(n + 1);
            n
        });
        if depth == 0 {
            WORK.with(|w| w.set(0));
            TRIPPED.with(|t| t.set(false));
            BUDGET.with(|b| b.set(read_budget()));
            CHARGED.with(|c| c.borrow_mut().clear());
            // A fresh outermost scope is a fresh function: drop any memoized
            // place types/Sorts from the previous one (see `place_memo`), and
            // the per-function body analyses (see `fn_memo`).
            super::place_memo::reset();
            super::fn_memo::reset();
            // Same boundary, same reason, for the opaque-deref/havoc-name memo.
            super::havoc_memo::reset();
        }
        Guard
    }

    /// RAII scope guard: decrements the re-entrancy depth on drop and, when the
    /// OUTERMOST scope exits (depth→0), clears the meter so a tripped state can never
    /// leak into a later, unscoped `place_ty` call on the same thread.
    pub(super) struct Guard;
    impl Drop for Guard {
        fn drop(&mut self) {
            let depth = DEPTH.with(|d| {
                let n = d.get().saturating_sub(1);
                d.set(n);
                n
            });
            if depth == 0 {
                WORK.with(|w| w.set(0));
                TRIPPED.with(|t| t.set(false));
                CHARGED.with(|c| c.borrow_mut().clear());
                // The function's generation is over: free the memoized place
                // types/Sorts so nothing can leak into a later scope (or into an
                // unscoped call, where the memo is inert anyway). Same for the
                // per-function body analyses.
                super::place_memo::reset();
                super::fn_memo::reset();
                super::havoc_memo::reset();
            }
        }
    }

    /// Enter a VC-gen scope with the work meter DISABLED for the scope's whole extent.
    ///
    /// WHY THIS EXISTS. The four generation memos (`place_memo` name/ty/sort,
    /// `havoc_memo`'s flags/`version_oracle`) gate on
    /// `scope_active()` ALONE — they are pure caches and are inert outside a scope. The
    /// work METER is a separate concern that happens to share the same scope. A replay
    /// path that needs BYTE-IDENTICAL output (the row replays of `generate::RowReplayScope`;
    /// until T3 C05 also the overflow-elision join-table replay) must have the memos and
    /// must NOT have the meter: a trip there substitutes `gen_work_degraded_leaf()` into
    /// the materialized types, which changes the rendered formula, which changes the
    /// row — silently, instead of reporting.
    ///
    /// WHY IT CANNOT CHANGE A ROW. With `BUDGET == usize::MAX` both `record` and
    /// `charge_local_once` return `false` on every call without touching `WORK`, so
    /// `is_tripped()` stays false and NO degraded leaf can ever be produced. What
    /// remains is the memo layer, which is observationally identical to recomputation
    /// (each memoized value is a pure function of `func` plus the key, and the memo is
    /// keyed on function identity). So the scope changes only the COST of this path,
    /// never a byte of its output.
    ///
    /// FULLY TRANSPARENT TO AN ENCLOSING METER. The budget/trip/work triple is saved
    /// and restored around the scope regardless of depth, so a nested use neither
    /// inherits an enclosing budget (which could truncate this path) nor charges the
    /// enclosing generation for this replay's walk (which could truncate THAT path).
    #[must_use]
    pub(super) fn enter_unmetered() -> UnmeteredGuard {
        let prev_budget = BUDGET.with(Cell::get);
        let prev_tripped = TRIPPED.with(Cell::get);
        let prev_work = WORK.with(Cell::get);
        let inner = enter();
        BUDGET.with(|b| b.set(usize::MAX));
        TRIPPED.with(|t| t.set(false));
        UnmeteredGuard { inner: Some(inner), prev_budget, prev_tripped, prev_work }
    }

    /// Guard for [`enter_unmetered`]: drops the ordinary scope guard first (so the
    /// depth→0 memo reset runs at the right moment), then restores the enclosing meter
    /// state.
    pub(super) struct UnmeteredGuard {
        inner: Option<Guard>,
        prev_budget: usize,
        prev_tripped: bool,
        prev_work: usize,
    }

    impl Drop for UnmeteredGuard {
        fn drop(&mut self) {
            drop(self.inner.take());
            BUDGET.with(|b| b.set(self.prev_budget));
            TRIPPED.with(|t| t.set(self.prev_tripped));
            WORK.with(|w| w.set(self.prev_work));
        }
    }

    /// Enter the scope of a public entry that has NO meter of its own (the call-site
    /// producers, `generate::EntryScope`): it JOINS an enclosing scope, and outermost
    /// it is [`enter_unmetered`].
    ///
    /// WHY NOT ONE OF THE TWO. Unscoped, such an entry ran with every memo inert and
    /// the meter inert. Called from inside a metered generation (the per-body pass
    /// holds one across its call-site lane), it ran with that generation's memos and
    /// was CHARGED to its meter, a trip of which degrades the whole function. So:
    ///
    /// * nested, a plain [`enter`] at depth > 0 — a depth increment and nothing else:
    ///   no reset, the enclosing budget, trip and work untouched, so the entry is
    ///   charged to the enclosing meter, as it was before the scope, and to no other.
    ///   It is not charged exactly as before: `generate::EntryScope` pairs this scope
    ///   with an analysis frame, and an analysis the frame reuses asks no place query,
    ///   so the charge can only FALL, and at the budget's edge a function the meter
    ///   used to degrade can now finish. [`enter_unmetered`] here would stop charging
    ///   even the work the entry still does, so the meter would no longer bound it;
    /// * outermost, [`enter_unmetered`]: the memos on and the meter off, which is what
    ///   an unscoped call meters (nothing: `record`, `charge_local_once` and
    ///   `is_tripped` all answer `false` outside a scope, and with `BUDGET ==
    ///   usize::MAX` inside one). A metered [`enter`] here would START metering it, and
    ///   its trip would put degraded leaves into rows nobody discards.
    ///
    /// THE HOLDER'S CONTRACT is `enter_unmetered`'s, plus one: run no METERED entry
    /// inside it. A metered entry nested here is at depth > 0, so it neither resets
    /// nor meters (it inherits `usize::MAX`); one the holder needs (the L0 replay's
    /// callee generation) runs before the scope opens.
    #[must_use]
    pub(super) fn enter_joined() -> JoinedGuard {
        if scope_active() {
            JoinedGuard { _joined: Some(enter()), _unmetered: None }
        } else {
            JoinedGuard { _joined: None, _unmetered: Some(enter_unmetered()) }
        }
    }

    /// Guard for [`enter_joined`]: exactly one of the two is held.
    pub(super) struct JoinedGuard {
        _joined: Option<Guard>,
        _unmetered: Option<UnmeteredGuard>,
    }

    /// Charge a LOCAL's declared-type materialization ONCE per scope (peak-work metering).
    /// `locals_ptr` is `func.body.locals.as_ptr() as usize` (the per-function discriminator);
    /// `nodes_for_cap` computes the node count given the remaining headroom `cap` (called ONLY
    /// on the first metered touch of this local). Returns whether the meter is now tripped —
    /// on `true` the caller degrades to a leaf. A re-touch of an already-charged local, an
    /// inert scope, a tripped meter, or a disabled budget all charge 0. See the `CHARGED` doc
    /// for the peak-vs-cumulative soundness argument (drop-only; never a false PROVE).
    pub(super) fn charge_local_once(
        locals_ptr: usize,
        local: usize,
        nodes_for_cap: impl FnOnce(usize) -> usize,
    ) -> bool {
        if !scope_active() {
            return false;
        }
        if TRIPPED.with(Cell::get) {
            return true;
        }
        if BUDGET.with(Cell::get) == usize::MAX {
            return false;
        }
        let newly = CHARGED.with(|c| c.borrow_mut().insert((locals_ptr, local)));
        if !newly {
            return false;
        }
        let cap = remaining().saturating_add(1);
        record(nodes_for_cap(cap))
    }

    /// Whether a VC-gen scope is currently active on this thread. Outside any scope the
    /// meter is inert, so a stray `place_ty` call behaves as pre-bound baseline.
    pub(super) fn scope_active() -> bool {
        DEPTH.with(Cell::get) > 0
    }

    /// Record `nodes` of materialized type-clone work; trip if the cumulative total
    /// crosses the budget. Returns whether the meter is now tripped. Inert (returns
    /// false, records nothing) when no scope is active.
    pub(super) fn record(nodes: usize) -> bool {
        if !scope_active() {
            return false;
        }
        if TRIPPED.with(Cell::get) {
            return true;
        }
        let budget = BUDGET.with(Cell::get);
        if budget == usize::MAX {
            return false;
        }
        let total = WORK.with(|w| {
            let n = w.get().saturating_add(nodes);
            w.set(n);
            n
        });
        if total > budget {
            TRIPPED.with(|t| t.set(true));
            if crate::trust_vcgen_env_var_present("TRUST_VCGEN_TRACE_BUDGET") {
                use std::io::Write as _;
                let _ = writeln!(
                    std::io::stderr(),
                    "[GEN_WORK_BUDGET] tripped: cumulative type-clone work {total} > budget {budget} (function degraded to Unsupported)"
                );
                let _ = std::io::stderr().flush();
            }
            true
        } else {
            false
        }
    }

    /// Whether this function's VC-gen tripped the work budget. Inert (false) when no
    /// scope is active.
    pub(super) fn is_tripped() -> bool {
        scope_active() && TRIPPED.with(Cell::get)
    }

    /// Remaining work headroom before the budget trips (saturating). Used to cap
    /// per-call node counting at O(headroom) so a single huge type costs no more than
    /// what is needed to decide the trip. `usize::MAX` when the bound is disabled.
    pub(super) fn remaining() -> usize {
        let budget = BUDGET.with(Cell::get);
        if budget == usize::MAX {
            return usize::MAX;
        }
        budget.saturating_sub(WORK.with(Cell::get))
    }

    /// Cumulative work recorded this function (diagnostic / threshold-calibration).
    pub(super) fn used() -> usize {
        WORK.with(Cell::get)
    }
}

// ── verifier-perf: per-function place-type/Sort memo for the metered hot paths ──
//
// `place_ty` and `place_sort_from_declared_type` are DETERMINISTIC in `(func, place)`:
// they read only the function's declared local types (immutable for the whole VC-gen
// pass, see `place_ty_cow`) and the place's projection path. Yet the generation walk
// queries the SAME places O(places × statements) times per lane, and each owned query
// re-materializes (deep-clones / re-builds) the same resolved `Ty`/`Sort` tree. For a
// long straight-line function over moderate flattened ADTs (`Vec<LinearConstraint>` /
// `Result<…>` with `BTreeMap<String, _>`/`String` internals — ~50-300-node `Ty::Adt`
// trees), that re-clone PRODUCT alone crosses `MAX_GENERATION_WORK_BUDGET` and
// fail-closes a function whose types are individually harmless (ny-cert's
// `crown::Relu1Problem::certify` is the witness).
//
// FIX: memoize the computed `Ty`/`Sort` per function, keyed by `(local, encoded
// projection path)`. The meter charge is the peak per-local `charge_local_once` (the
// base local's declared type covers every projected subtree, paid once per scope); a
// HIT charges `HIT_COST` (~a map lookup), so the meter reflects real
// first-materialization work instead of an O(queries) re-clone artifact.
//
// KEY STABILITY: only projection variants whose payload is a STABLE MIR identifier are
// encoded (`Field`/`Downcast` indices, the `Index` LOCAL — the resolved TYPE of an
// index step does not depend on the runtime index value — and `ConstantIndex`/
// `Subslice` offsets, `Deref`). `OpaqueCast`/`UnwrapUnsafeBinder` embed an inline
// replacement `Ty`, and `Projection` is `#[non_exhaustive]`; paths containing them —
// or any future variant — take the UNCACHED path (`key_for` returns `None`), so an
// unencodable projection can never alias a cached entry.
//
// SOUNDNESS: pure memoization of a deterministic function — a HIT replays the
// byte-identical `Ty`/`Sort` the first query computed, so every downstream VC is
// unchanged. The memo is inert outside a `gen_work` scope (out-of-scope calls behave
// byte-identically to baseline), is cleared on every outermost scope entry AND exit,
// and entries are bound to a function identity (address + locals buffer + name) that a
// query for any OTHER function fails, so a stale entry cannot survive into another
// function's generation. Degraded (post-trip) leaves are NEVER stored: on a trip the
// callers return before the store, so the cache only ever holds real resolved values.
//
// METER FIDELITY FOR THE PATHOLOGICAL SHAPES: a resolved tree over
// `MAX_MEMOIZED_TY_NODES` is never cached, and a kernel-scale fat local
// (`Expr`/`ExprKind`/`Name`, ~10^5+ nodes) trips `charge_local_once` on its FIRST
// touch (its declared-type node count alone crosses the budget), degrading the
// function exactly as before. A HIT's real (uncharged) work is bounded by one
// ≤`MAX_MEMOIZED_TY_NODES` clone, and the hard wall-clock watchdog remains the
// fail-closed backstop on total time. Retained memory is bounded too: every entry is
// ≤`MAX_MEMOIZED_TY_NODES` nodes, entries are keyed by the function's finitely many
// `(local, projection-path)` places, and the memo is cleared on every outermost
// scope boundary.
// verifier-perf: per-function memo for the whole-body ANALYSES the obligation
// walk re-derives from inside its inner loops that neither `place_memo` (below)
// nor `havoc_memo` covers — `v2_array_version_prepass`,
// `local_versions_collapse_to_bare`, the whole-local base->index table, and the
// two Call-havoc name lists individually. Same scope/identity discipline as
// `place_memo`; the census bodies that tripped the per-function budget during
// VC generation are its motivation and its regression fixtures
// (`tests/vcgen_budget_realmir.rs`). It also owns the crate's analysis
// computation COUNTERS, including for the analyses the other two memos serve.
mod fn_memo;
pub use fn_memo::{
    AnalysisMemoStats, analysis_memo_stats, reset_analysis_memo_stats, with_analysis_memo_disabled,
};

mod place_memo {
    use std::cell::RefCell;

    use trust_types::fx::FxHashMap;

    use super::{Place, Projection, Sort, Ty, VerifiableFunction};

    /// Work-meter charge for a memo HIT: the real cost of a hit is a hash lookup plus a
    /// bounded (≤ `MAX_MEMOIZED_TY_NODES`) clone, not a full resolve + materialize.
    pub(super) const HIT_COST: usize = 1;

    /// Largest resolved tree (structural `Ty` nodes, as counted by
    /// `gen_work_datatype_nodes`) the memo will hold. Sized comfortably above the
    /// moderate flattened-ADT trees the memo exists for (~50-300 nodes) and far below
    /// the kernel-scale recursive-`Expr` trees the work meter exists for, so those
    /// stay uncached and keep tripping the budget on their first
    /// `charge_local_once` touch. Also bounds a HIT's real (uncharged) clone work.
    /// `pub(super)` so the store callers can count the resolved tree against
    /// `cap = MAX_MEMOIZED_TY_NODES + 1`: a cap-truncated count exceeds the bound and
    /// is refused by `store_ty`/`store_sort`, so a STORED `nodes` is always the TRUE
    /// tree size.
    pub(super) const MAX_MEMOIZED_TY_NODES: usize = 4_096;

    /// `(local, encoded projection path)` — see `key_for`.
    pub(super) type Key = (usize, Vec<u64>);

    struct State {
        /// Identity of the function the entries were computed for: the function's
        /// address, its locals buffer's address + length, and its name (owned Strings /
        /// integers only — no stale pointer is ever dereferenced). A query for a
        /// non-matching function misses (lookup) or rebinds-and-clears (store);
        /// combined with the clear-on-scope-boundary hooks, reusing an entry across
        /// functions would need an in-scope allocator address reuse AND a name
        /// collision — and the VC-gen scope only queries functions it holds borrowed
        /// for the whole pass.
        func_ptr: usize,
        locals_ptr: usize,
        locals_len: usize,
        func_name: String,
        tys: FxHashMap<Key, Ty>,
        sorts: FxHashMap<Key, Sort>,
        /// `place_to_var_name` results. Same determinism argument as `tys`/
        /// `sorts` — the SMT name is a pure function of the function's local
        /// table and the place's projection path — and the same key, so an
        /// unencodable projection takes the uncached path here too.
        names: FxHashMap<Key, std::rc::Rc<str>>,
        /// `canonical_place` results: the place a name is minted from. Same
        /// determinism argument and key as `names` (Trust: 2026-10-12,
        /// UNION-SIBLING-WRITE-2 — `generate::union_write_cover_name` asks it per
        /// written place, on the per-statement search's hot path).
        places: FxHashMap<Key, Place>,
        /// The local-table summary every uncached name mint consults
        /// (`LocalNameTable`), computed once per function.
        local_names: Option<std::rc::Rc<super::LocalNameTable>>,
    }

    impl State {
        fn is_for(&self, func: &VerifiableFunction) -> bool {
            let (func_ptr, locals_ptr, locals_len) = identity(func);
            self.func_ptr == func_ptr
                && self.locals_ptr == locals_ptr
                && self.locals_len == locals_len
                && self.func_name == func.name
        }
    }

    thread_local! {
        static MEMO: RefCell<Option<State>> = const { RefCell::new(None) };
    }

    fn identity(func: &VerifiableFunction) -> (usize, usize, usize) {
        (
            std::ptr::from_ref(func) as usize,
            func.body.locals.as_ptr() as usize,
            func.body.locals.len(),
        )
    }

    /// Clear the memo. Called by `gen_work` on every outermost scope entry AND exit so
    /// entries can never leak across functions (or linger while no VC-gen runs).
    pub(super) fn reset() {
        MEMO.with(|m| *m.borrow_mut() = None);
    }

    /// The memo key for `place`, or `None` when the place must take the UNCACHED path:
    /// outside a `gen_work` scope (the memo is inert there, matching the meter), or
    /// when the projection path contains a variant that embeds an inline `Ty`
    /// (`OpaqueCast`/`UnwrapUnsafeBinder`) or is unknown (`Projection` is
    /// `#[non_exhaustive]`). Each encoded variant has a distinct tag and a fixed
    /// payload arity, so the encoding is injective (a prefix code) — distinct
    /// projection paths can never collide on one key.
    pub(super) fn key_for(place: &Place) -> Option<Key> {
        if !super::gen_work::scope_active() {
            return None;
        }
        let mut path = Vec::with_capacity(place.projections.len() * 2);
        for proj in &place.projections {
            match proj {
                Projection::Deref => path.push(0),
                Projection::Field(i) => path.extend([1, *i as u64]),
                Projection::Index(local) => path.extend([2, *local as u64]),
                Projection::Downcast(v) => path.extend([3, *v as u64]),
                Projection::ConstantIndex { offset, min_length, from_end } => {
                    path.extend([4, *offset as u64, *min_length as u64, u64::from(*from_end)]);
                }
                Projection::Subslice { from, to, from_end } => {
                    path.extend([5, *from as u64, *to as u64, u64::from(*from_end)]);
                }
                // `OpaqueCast`/`UnwrapUnsafeBinder` embed an inline replacement `Ty`;
                // any future variant is unknown here. Fail to the UNCACHED path.
                _ => return None,
            }
        }
        Some((place.local, path))
    }

    pub(super) fn lookup_ty(func: &VerifiableFunction, key: &Key) -> Option<Ty> {
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.tys.get(key).cloned()
        })
    }

    /// The memoized SMT name for a place, if one was computed for THIS function.
    pub(super) fn lookup_name(func: &VerifiableFunction, key: &Key) -> Option<std::rc::Rc<str>> {
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.names.get(key).cloned()
        })
    }

    /// The local-table summary of `func` (see `LocalNameTable`): memoized once per
    /// function inside a scope, computed fresh outside one (the scan the uncached
    /// path always did).
    /// [`local_names`] when the memo is ALREADY bound to `func` inside a generation
    /// scope; `None` otherwise (outside a scope the table would be rebuilt per call,
    /// and for another function looking it up would REBIND the memo — clearing the
    /// bound function's place names, types and sorts — so a direct scan is cheaper).
    pub(super) fn local_names_scoped(
        func: &VerifiableFunction,
    ) -> Option<std::rc::Rc<super::LocalNameTable>> {
        if !super::gen_work::scope_active() {
            return None;
        }
        let bound = MEMO.with(|m| m.borrow().as_ref().map(|state| state.is_for(func)));
        if bound != Some(true) {
            return None;
        }
        Some(local_names(func))
    }

    pub(super) fn local_names(func: &VerifiableFunction) -> std::rc::Rc<super::LocalNameTable> {
        if !super::gen_work::scope_active() {
            return std::rc::Rc::new(super::LocalNameTable::of(func));
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.local_names.clone()
        }) {
            return hit;
        }
        let table = std::rc::Rc::new(super::LocalNameTable::of(func));
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).local_names = Some(std::rc::Rc::clone(&table));
        });
        table
    }

    /// Store a computed SMT name.
    ///
    /// verifier-perf: `place_to_var_name` rebuilds an `FxHashSet` over EVERY
    /// local (the `local_indices_are_unique` screen) and makes two more
    /// O(locals) passes (the matching decl, the shared-source-name count) on
    /// every call — and it is called once per place occurrence in every formula
    /// the generator builds or rewrites, which made it the single hottest leaf
    /// in a stack sample of the wedged generator (the allocation inside that
    /// per-call `FxHashSet` alone). The result is a pure function of the
    /// function's local table and the place, so it memoizes exactly.
    pub(super) fn store_name(func: &VerifiableFunction, key: Key, name: &std::rc::Rc<str>) {
        if !super::gen_work::scope_active() {
            return;
        }
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).names.insert(key, std::rc::Rc::clone(name));
        });
    }

    /// The memoized canonical place for a place, if one was computed for THIS function.
    pub(super) fn lookup_place(func: &VerifiableFunction, key: &Key) -> Option<Place> {
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.places.get(key).cloned()
        })
    }

    /// Store a computed canonical place (see `State::places`).
    pub(super) fn store_place(func: &VerifiableFunction, key: Key, place: &Place) {
        if !super::gen_work::scope_active() {
            return;
        }
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).places.insert(key, place.clone());
        });
    }

    pub(super) fn lookup_sort(func: &VerifiableFunction, key: &Key) -> Option<Sort> {
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.sorts.get(key).cloned()
        })
    }

    /// Store a resolved place type. `nodes` is the resolved tree's node count as
    /// counted by `gen_work_datatype_nodes` with `cap = MAX_MEMOIZED_TY_NODES + 1`
    /// (see the const doc): a cap-truncated count exceeds the bound and is refused
    /// below — so a STORED `nodes` is always the TRUE tree size, and the
    /// `MAX_MEMOIZED_TY_NODES` comparison is exact.
    pub(super) fn store_ty(func: &VerifiableFunction, key: Key, ty: &Ty, nodes: usize) {
        if nodes > MAX_MEMOIZED_TY_NODES || !super::gen_work::scope_active() {
            return;
        }
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).tys.insert(key, ty.clone());
        });
    }

    /// Store a resolved declared-type `Sort`. `nodes` is the resolved `Ty`'s node
    /// count (counted against `cap = MAX_MEMOIZED_TY_NODES + 1`); see `store_ty` for
    /// why it is always exact.
    pub(super) fn store_sort(func: &VerifiableFunction, key: Key, sort: &Sort, nodes: usize) {
        if nodes > MAX_MEMOIZED_TY_NODES || !super::gen_work::scope_active() {
            return;
        }
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).sorts.insert(key, sort.clone());
        });
    }

    /// The memo state bound to `func`, clearing and rebinding first if it was bound to
    /// a different function (or to nothing).
    ///
    /// Not `match memo { Some(state) if state.is_for(func) => state, _ => memo.insert(..) }`:
    /// returning the arm's borrow while the other arm writes `memo` is NLL problem case #3,
    /// which trustc's default Polonius accepts and the stock compiler that D12's double
    /// compile builds this crate with rejects (E0499; DECISION_QUEUE.md PERF-SEP26-DEFAULTS).
    fn bind<'a>(memo: &'a mut Option<State>, func: &VerifiableFunction) -> &'a mut State {
        // A state bound to another function is dropped, so the insert below rebinds.
        memo.take_if(|state| !state.is_for(func));
        memo.get_or_insert_with(|| {
            let (func_ptr, locals_ptr, locals_len) = identity(func);
            State {
                func_ptr,
                locals_ptr,
                locals_len,
                func_name: func.name.clone(),
                tys: FxHashMap::default(),
                sorts: FxHashMap::default(),
                names: FxHashMap::default(),
                places: FxHashMap::default(),
                local_names: None,
            }
        })
    }
}

// ── verifier-perf: per-function opaque-deref / havoc-name memo ──
//
// THE DEFECT THIS CLOSES. `generate::path_defs::deref_store_havoc_names` and its
// prefix sibling `writes_until` are queried once per (read site x name) by
// `StmtVersionCtx::version_token_at`, and each query re-ran a WHOLE-FUNCTION
// analysis:
//
//   * `deref_pointer_is_opaque(func, local)` -> `resolve_referent` ->
//     `local_defs::unique_value_def`, which scans every block and every statement — and
//     it is called once per statement inside `deref_store_havoc_names`' `.any()`
//     AND again per prefix statement in `deref_store_havoc_names_over`;
//   * `mutably_borrowed_local_names(func)`, another full block/statement scan,
//     whose `Vec::contains` dedup is itself quadratic in the name count;
//   * `mutable_pointer_local_names(func)`, a scan of every local with the same
//     quadratic `Vec::contains` dedup.
//
// The product is cubic in function size (measured: exponent ~2.9 on statement
// count before this memo, ~1.2 after — `tests/vcgen_havoc_scaling.rs`), which is
// why `nn-core`, `ny-core` and `clean-kernel` never completed VC GENERATION.
//
// WHY IT CANNOT GO STALE. Every memoized value is a pure function of `func`
// alone (plus a block id / local index / statement index that selects WITHIN
// that fixed `func`): they read `func.body.blocks`, `func.body.locals` and
// nothing else, and `func` is borrowed immutably for the whole VC-gen pass — the
// same premise `place_memo` above already relies on. On top of that this memo
// takes `place_memo`'s identity discipline VERBATIM rather than inventing a
// second one:
//
//   * entries are bound to a function identity (address + locals buffer address
//     + locals length + name) that a query for any OTHER function fails, so a
//     hit can only ever replay a value computed for the very same function;
//   * the memo is INERT outside a `gen_work` scope (`scope_active()` false =>
//     never read, never written), so an unscoped call is byte-identical to
//     baseline;
//   * it is cleared on every outermost `gen_work` scope ENTRY and EXIT (see
//     `gen_work::enter` / `Guard::drop`), so an entry cannot outlive the
//     generation of the function it describes — reusing one across functions
//     would additionally require an in-scope allocator address reuse AND a name
//     collision.
//
// A hit therefore replays the byte-identical set the first query computed, so
// every downstream kill, version token and VC is unchanged. This is pure
// memoization of a deterministic function: it has no fail-closed direction to
// get wrong, because it does not change any value — only how often it is
// computed. `tests/vcgen_havoc_memoization.rs` pins that equivalence by running
// the whole obligation set with the memo forced off and forced on.
//
// MEMORY. The havoc list and the per-local/per-block flags are O(locals +
// blocks); the per-PLACE opacity flags (`opaque_place`, added 2026-09-18) are
// O(distinct projected deref-store places), which is at most one per `Assign`
// and in practice far fewer — the map is written only for a store the per-local
// answer already declined. The statement-version oracle is one linear-size value
// per function. (The statement-PREFIX `writes_until` sets used to be memoized here
// too — O(statements) sets of up to O(names) each, capped at 400k stored names;
// the oracle's per-block write index answers those queries without materialising
// the sets, so the memo and its cap are gone.)
mod havoc_memo {
    use std::cell::RefCell;
    use std::rc::Rc;

    use trust_types::fx::{FxHashMap, FxHashSet};

    use super::VerifiableFunction;

    struct State {
        func_ptr: usize,
        locals_ptr: usize,
        locals_len: usize,
        func_name: String,
        /// `mutably_borrowed_havoc_names(func) ++ mutable_pointer_local_names(func)`
        /// — the whole-function havoc list, independent of any block.
        havoc: Option<Rc<Vec<String>>>,
        /// The same list as a set (the per-call refinements' membership questions).
        havoc_set: Option<Rc<FxHashSet<String>>>,
        /// `deref_pointer_is_opaque(func, local)`, per local.
        opaque: FxHashMap<usize, bool>,
        /// `deref_store_is_opaque`'s PLACE refinement, per written place — asked
        /// only for a store whose place carries projections BEYOND the leading
        /// `Deref`, and only when the per-local answer above was `false`. A
        /// separate map from `opaque` on purpose: the two are keyed on different
        /// things and a place answer must never serve a local query, nor the
        /// reverse.
        opaque_place: FxHashMap<super::Place, bool>,
        /// Whether a block contains an opaque deref store, per `BlockId.0`.
        block_has_opaque_store: FxHashMap<usize, bool>,
        /// `referent_fold::is_stable(func, local, referent, extra)`, per `(local,
        /// referent, the filtered guard list the walk used)`, each verdict with the
        /// STACK CERTIFICATE it replays under (`referent_fold::FoldEntry`).
        ///
        /// Trust: 2026-09-30 — this held TOP-LEVEL verdicts only ("a nested walk's
        /// answer depends on what is on the stack and is never stored"). The
        /// dependence is real, but it is exactly the set of in-progress marks the
        /// computation CONSULTED, and a verdict replays verbatim in any stack that
        /// answers those consultations the same way (see `FoldEntry`). Storing
        /// nothing for a nested walk re-ran it from scratch in every enclosing walk.
        fold_stable: FxHashMap<
            usize,
            Vec<(
                super::Place,
                Vec<super::Place>,
                Vec<Rc<super::referent_fold::FoldEntry>>,
            )>,
        >,
        /// The referent fold's body-global index (`referent_fold::FoldIndex`),
        /// built once per function.
        fold_index: Option<Rc<super::referent_fold::FoldIndex>>,
        /// The statement-granular version oracle (`generate::StmtVersionCtx`),
        /// held type-erased because it is defined in a child module. Exactly one
        /// concrete type is ever stored here, and `version_oracle` checks the
        /// downcast rather than assuming it.
        version_oracle: Option<Rc<dyn std::any::Any>>,
    }

    impl State {
        fn is_for(&self, func: &VerifiableFunction) -> bool {
            let (func_ptr, locals_ptr, locals_len) = identity(func);
            self.func_ptr == func_ptr
                && self.locals_ptr == locals_ptr
                && self.locals_len == locals_len
                && self.func_name == func.name
        }
    }

    thread_local! {
        static MEMO: RefCell<Option<State>> = const { RefCell::new(None) };
    }

    fn identity(func: &VerifiableFunction) -> (usize, usize, usize) {
        (
            std::ptr::from_ref(func) as usize,
            func.body.locals.as_ptr() as usize,
            func.body.locals.len(),
        )
    }

    /// Clear the memo. Called by `gen_work` on every outermost scope entry AND
    /// exit, exactly like `place_memo::reset`.
    pub(super) fn reset() {
        MEMO.with(|m| *m.borrow_mut() = None);
    }

    /// The per-block cache key: the ADDRESS of the block's statement buffer.
    ///
    /// Deliberately NOT `BlockId.0`. Every block-keyed value here is a function
    /// of `block.stmts`, and two distinct live statement buffers cannot share an
    /// address — so this key is exact even if a caller ever passes a block that
    /// is not the `func.body.blocks[id]` its id names. An EMPTY `stmts` has the
    /// same dangling-but-aligned address for every block, which is harmless: the
    /// predicates keyed on it are all `false`/empty for a block with no
    /// statements, so a shared key can only ever replay the identical value.
    pub(crate) fn block_key(block: &trust_types::BasicBlock) -> usize {
        block.stmts.as_ptr() as usize
    }

    /// The memo state bound to `func`, clearing and rebinding first if it was
    /// bound to a different function (or to nothing).
    ///
    /// Not `match memo { Some(state) if state.is_for(func) => state, _ => memo.insert(..) }`:
    /// returning the arm's borrow while the other arm writes `memo` is NLL problem case #3,
    /// which trustc's default Polonius accepts and the stock compiler that D12's double
    /// compile builds this crate with rejects (E0499; DECISION_QUEUE.md PERF-SEP26-DEFAULTS).
    fn bind<'a>(memo: &'a mut Option<State>, func: &VerifiableFunction) -> &'a mut State {
        // A state bound to another function is dropped, so the insert below rebinds.
        memo.take_if(|state| !state.is_for(func));
        memo.get_or_insert_with(|| {
            let (func_ptr, locals_ptr, locals_len) = identity(func);
            State {
                func_ptr,
                locals_ptr,
                locals_len,
                func_name: func.name.clone(),
                havoc: None,
                havoc_set: None,
                opaque: FxHashMap::default(),
                opaque_place: FxHashMap::default(),
                block_has_opaque_store: FxHashMap::default(),
                fold_stable: FxHashMap::default(),
                fold_index: None,
                version_oracle: None,
            }
        })
    }

    /// Memoize a `bool` keyed by `slot`-selected map and `key`.
    fn cached_flag(
        func: &VerifiableFunction,
        key: usize,
        which: Which,
        compute: impl FnOnce() -> bool,
    ) -> bool {
        if !super::gen_work::scope_active() {
            return compute();
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            which.map(state).get(&key).copied()
        }) {
            return hit;
        }
        let value = compute();
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            which.map_mut(bind(&mut memo, func)).insert(key, value);
        });
        value
    }

    #[derive(Clone, Copy)]
    enum Which {
        Opaque,
        BlockHasOpaqueStore,
    }

    impl Which {
        fn map(self, state: &State) -> &FxHashMap<usize, bool> {
            match self {
                Which::Opaque => &state.opaque,
                Which::BlockHasOpaqueStore => &state.block_has_opaque_store,
            }
        }
        fn map_mut(self, state: &mut State) -> &mut FxHashMap<usize, bool> {
            match self {
                Which::Opaque => &mut state.opaque,
                Which::BlockHasOpaqueStore => &mut state.block_has_opaque_store,
            }
        }
    }

    /// `deref_pointer_is_opaque(func, local)`, computed once per local.
    pub(crate) fn opaque_pointer(
        func: &VerifiableFunction,
        local: usize,
        compute: impl FnOnce() -> bool,
    ) -> bool {
        cached_flag(func, local, Which::Opaque, compute)
    }

    /// `deref_store_is_opaque`'s place refinement, computed once per distinct
    /// written place. Not a `Which` arm because the key is a `Place`, not a
    /// `usize`; everything else — the identity check, the scope gate, the
    /// borrow released BEFORE `compute` runs so the nested referent-fold memo
    /// traffic the probe generates cannot re-enter a live `RefCell` borrow —
    /// is `cached_flag`'s discipline verbatim.
    pub(crate) fn opaque_store_place(
        func: &VerifiableFunction,
        place: &super::Place,
        compute: impl FnOnce() -> bool,
    ) -> bool {
        if !super::gen_work::scope_active() {
            return compute();
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.opaque_place.get(place).copied()
        }) {
            return hit;
        }
        let value = compute();
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).opaque_place.insert(place.clone(), value);
        });
        value
    }

    /// A stored `referent_fold::is_stable` entry for `(local, referent, guards)` whose
    /// stack certificate `valid` accepts, if any.
    pub(crate) fn fold_stable(
        func: &VerifiableFunction,
        local: usize,
        referent: &super::Place,
        guards: &[super::Place],
        valid: impl Fn(&super::referent_fold::FoldEntry) -> bool,
    ) -> Option<Rc<super::referent_fold::FoldEntry>> {
        if !super::gen_work::scope_active() {
            return None;
        }
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state
                .fold_stable
                .get(&local)?
                .iter()
                .find(|(r, g, _)| r == referent && g.as_slice() == guards)
                .and_then(|(_, _, entries)| entries.iter().find(|entry| valid(entry)).cloned())
        })
    }

    /// At most this many certificates are kept per `(local, referent, guards)`. A
    /// question that finds no stored certificate valid is recomputed, so the cap
    /// bounds memory and never changes an answer.
    const FOLD_ENTRIES_PER_KEY: usize = 16;

    /// Store a `referent_fold::is_stable` verdict with its stack certificate.
    pub(crate) fn store_fold_stable(
        func: &VerifiableFunction,
        local: usize,
        referent: &super::Place,
        guards: &[super::Place],
        entry: super::referent_fold::FoldEntry,
    ) {
        if !super::gen_work::scope_active() {
            return;
        }
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            let by_local = bind(&mut memo, func).fold_stable.entry(local).or_default();
            if let Some((_, _, entries)) =
                by_local.iter_mut().find(|(r, g, _)| r == referent && g.as_slice() == guards)
            {
                if entries.len() < FOLD_ENTRIES_PER_KEY {
                    entries.push(Rc::new(entry));
                }
            } else {
                by_local.push((referent.clone(), guards.to_vec(), vec![Rc::new(entry)]));
            }
        });
    }

    /// The referent fold's body-global index for `func`, built once per function.
    /// Outside a VC-gen scope the memo is inert and every call builds afresh.
    pub(crate) fn fold_index(
        func: &VerifiableFunction,
        compute: impl FnOnce() -> super::referent_fold::FoldIndex,
    ) -> Rc<super::referent_fold::FoldIndex> {
        if !super::gen_work::scope_active() {
            return Rc::new(compute());
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.fold_index.clone()
        }) {
            return hit;
        }
        // The borrow is released before `compute` runs, as everywhere in this module.
        let value = Rc::new(compute());
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).fold_index = Some(Rc::clone(&value));
        });
        value
    }

    /// "does this block contain an opaque deref store", computed once per block.
    pub(crate) fn block_has_opaque_store(
        func: &VerifiableFunction,
        block_id: usize,
        compute: impl FnOnce() -> bool,
    ) -> bool {
        cached_flag(func, block_id, Which::BlockHasOpaqueStore, compute)
    }

    /// The whole-function havoc list, computed once per function.
    pub(crate) fn havoc_list(
        func: &VerifiableFunction,
        compute: impl FnOnce() -> Vec<String>,
    ) -> Rc<Vec<String>> {
        if !super::gen_work::scope_active() {
            return Rc::new(compute());
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.havoc.clone()
        }) {
            return hit;
        }
        let value = Rc::new(compute());
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).havoc = Some(Rc::clone(&value));
        });
        value
    }

    /// The whole-function havoc list as a set, computed once per function.
    pub(crate) fn havoc_set(
        func: &VerifiableFunction,
        compute: impl FnOnce() -> FxHashSet<String>,
    ) -> Rc<FxHashSet<String>> {
        if !super::gen_work::scope_active() {
            return Rc::new(compute());
        }
        if let Some(hit) = MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.havoc_set.clone()
        }) {
            return hit;
        }
        let value = Rc::new(compute());
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).havoc_set = Some(Rc::clone(&value));
        });
        value
    }

    /// The statement-granular version oracle, built once per function.
    ///
    /// WHY. `StmtVersionCtx::build` is called at ~20 sites — including
    /// `generate::overflow_vc` and
    /// `block_defs::v2_formula_with_block_defs_at_point_recorded`, which run once
    /// per OBLIGATION. When the build was two whole-function reaching-version
    /// fixpoints, rebuilding it per program point made VC generation cubic; the
    /// build is now linear-size (a dominator index, a write index and a lazily
    /// resolved SSA oracle), and sharing it also shares the oracle's resolved
    /// joins across every obligation of the function.
    ///
    /// The oracle's answers are a pure function of `func` (its join memo only
    /// fills in), so sharing one `Rc` among every site is observationally
    /// identical to each building its own.
    pub(crate) fn cached_version_oracle<T: 'static>(func: &VerifiableFunction) -> Option<Rc<T>> {
        if !super::gen_work::scope_active() {
            return None;
        }
        MEMO.with(|m| {
            let memo = m.borrow();
            let state = memo.as_ref()?;
            if !state.is_for(func) {
                return None;
            }
            state.version_oracle.clone()?.downcast::<T>().ok()
        })
    }

    pub(crate) fn version_oracle<T: 'static>(
        func: &VerifiableFunction,
        compute: impl FnOnce() -> T,
    ) -> Rc<T> {
        if !super::gen_work::scope_active() {
            return Rc::new(compute());
        }
        if let Some(hit) = cached_version_oracle(func) {
            return hit;
        }
        let value = Rc::new(compute());
        MEMO.with(|m| {
            let mut memo = m.borrow_mut();
            bind(&mut memo, func).version_oracle = Some(Rc::clone(&value) as Rc<dyn std::any::Any>);
        });
        value
    }
}

/// Cumulative mid-generation work recorded for the current function (diagnostic).
/// Exposed for threshold calibration; not part of the verification verdict.
#[must_use]
pub fn gen_work_used() -> usize {
    gen_work::used()
}

/// Enter a VC-gen work-meter scope (see `gen_work`). Hold the returned guard for the
/// duration of a public entry point's VC generation; the meter resets only on the
/// outermost entry, so nested entries share one per-function budget.
#[must_use]
pub(crate) fn gen_work_scope() -> gen_work::Guard {
    gen_work::enter()
}

/// Enter a VC-gen scope whose MEMOS are live but whose work METER is disabled for the
/// scope's whole extent (see `gen_work::enter_unmetered`). Reserved for replay paths
/// whose output must be byte-identical to a production VC — today exactly one, the
/// overflow-elision join table — where a meter trip would degrade a formula and break a
/// join instead of reporting an overrun. Such a path must carry its own reportable
/// bound; this scope removes the meter, it does not remove the obligation to terminate.
#[must_use]
pub(crate) fn gen_work_scope_unmetered() -> gen_work::UnmeteredGuard {
    gen_work::enter_unmetered()
}

/// Enter the VC-gen scope of a public entry with no meter of its own: it joins an
/// enclosing scope, and outermost it is the unmetered one (see `gen_work::enter_joined`).
/// Held through `generate::EntryScope`.
#[must_use]
pub(crate) fn gen_work_scope_joined() -> gen_work::JoinedGuard {
    gen_work::enter_joined()
}

/// Trust: 2026-10-17 (gate-rca deadline) — the memos of a VC-generation scope, for a
/// producer called OUTSIDE every scope: `Some` unmetered scope when none is active,
/// `None` (keep the enclosing scope, metered or not) otherwise.
///
/// Outside a scope the memos (`fn_memo`, `place_memo`, `havoc_memo`) are inert and so is
/// the work meter. Inside an unmetered scope the meter stays inert (`gen_work::record`
/// and `charge_local_once` answer `false` at `BUDGET == usize::MAX`, so no degraded leaf
/// can appear) and only the memos change, which serve the value the uncached analysis
/// computes (`fn_memo`'s module doc). So the producer's output is the one it computes
/// unscoped today, at the cost of a memoized run instead of re-deriving every whole-body
/// analysis at every query. Inside an enclosing scope nothing changes at all.
#[must_use]
pub(crate) fn gen_work_memo_scope_if_unscoped() -> Option<gen_work::UnmeteredGuard> {
    (!gen_work::scope_active()).then(gen_work::enter_unmetered)
}

/// Whether the current function's VC-gen tripped the mid-generation work budget (and so
/// must be degraded wholesale to a single fail-closed `Unsupported`).
#[must_use]
pub(crate) fn gen_work_tripped() -> bool {
    gen_work::is_tripped()
}

/// Count the TOTAL structural `Ty` nodes reachable from `ty` — every constructor AND its
/// nested children — short-circuiting once `cap` is reached so a huge tree costs O(cap),
/// not O(size). This is the TRUE per-materialization clone cost the generation walk pays
/// at each owned `place_ty`/`place_sort` query: `Ty::clone()` (and `sort_for_ty`)
/// deep-copies the WHOLE tree.
///
/// IMPORTANT: the kernel's recursive `Expr`/`ExprKind`/`Name`/`Environment` lower to
/// deeply-nested **`Ty::Adt`** trees (flattened enums: `{Adt expr::Expr { fields:[(kind,
/// Adt ExprKind {…}), …]}}`), so the `Ty::Adt` arm is the dominant cost. Both the
/// struct/union `fields` view AND each enum `variants[].fields` list are deep-copied by
/// `Ty::clone`, so both are counted here to faithfully reflect the materialization cost.
fn gen_work_datatype_nodes(ty: &Ty, cap: usize) -> usize {
    fn go(ty: &Ty, cap: usize, acc: &mut usize) {
        if *acc >= cap {
            return;
        }
        *acc += 1;
        match ty {
            Ty::Ref { inner, .. } => go(inner, cap, acc),
            Ty::RawPtr { pointee, .. } => go(pointee, cap, acc),
            Ty::Slice { elem } | Ty::Array { elem, .. } | Ty::SymArray { elem, .. } => {
                go(elem, cap, acc)
            }
            Ty::Tuple(tys) => tys.iter().for_each(|t| go(t, cap, acc)),
            Ty::Adt { fields, variants, .. } => {
                for (_, t) in fields {
                    go(t, cap, acc);
                }
                for v in variants {
                    for (_, t) in &v.fields {
                        go(t, cap, acc);
                    }
                }
            }
            // Lever A: charge a modeled datatype's variant-field nodes so the VC-gen
            // work meter still bounds a `Ty::Datatype` materialization (a by-name
            // ref is empty and costs just the `+1` leaf above).
            Ty::Datatype { variants, .. } => {
                for (_, fs) in variants {
                    for (_, t) in fs {
                        go(t, cap, acc);
                    }
                }
            }
            Ty::Closure { upvars, .. } | Ty::Coroutine { upvars, .. } => {
                upvars.iter().for_each(|t| go(t, cap, acc));
            }
            // Scalar leaves (Int/Bool/Float/…) count as the single `*acc += 1` above with
            // no descent — they are cheap but non-zero, so a function with thousands of
            // scalar place-queries still accrues bounded work.
            _ => {}
        }
    }
    let mut acc = 0;
    go(ty, cap, &mut acc);
    acc
}

/// The cheap fail-closed leaf returned by owned type materialization once the work
/// meter has tripped, so the rest of the (about-to-be-discarded) walk costs O(1) per
/// query instead of cloning the fat ADT tree. Identical in kind/detail shape to the
/// existing recursive-ADT marker
/// (`collect_type_unsupported`'s `kind == "TyKind::Adt" && detail.starts_with("recursive")`
/// arm), so even if a downstream consumer inspects it, it fails closed exactly as a
/// genuinely recursive ADT would.
fn gen_work_degraded_leaf() -> Ty {
    Ty::Unsupported {
        kind: "TyKind::Adt".to_string(),
        detail: "recursive ADT (degraded: function exceeded VC-generation work budget)".to_string(),
    }
}

// ── verifier-perf: fat-`Ty::Adt` budget for the NON-VC-gen bundle path ──────
//
// The mid-generation work-bound above bounds trust-vcgen's VC-GENERATION walk. But the
// full-verification path also constructs a native trust-ir bundle
// (`trust_verify::build_full_verification_input` → `function_to_verifier_api_bundle` /
// `trust_ir_bridge::lower`) that recursively walks the UN-degraded declared `Ty::Adt`
// tree with many O(datatype-size) walks. For the kernel's `Expr`/`ExprKind`/`Name`
// cluster (a 464 MB serialized recursor type) those walks drive RSS to multi-GB — the
// `build_ind_app` stall — and the per-function wall-clock budget is enforced only at
// SMT dispatch, AFTER bundle construction, so it does not bound this.
//
// CORRECTION 2026-08-28 — this comment used to say those walks "never complete", and
// that phrase propagated into `tests/self-proof/trust-semantics.baseline` as
// "NEVER COMPLETES ... raising it re-opens a NON-TERMINATING lowering", which is what
// stopped anyone from raising a budget for two months. No run ever backed it. The
// runs on record (`b9b201ecc4`) describe an OOM-KILL WITH PROGRESS — "29/1771 fns in
// 40 min" — i.e. memory exhaustion, not divergence, and the process was killed rather
// than hung. `trust_mir_extract::ty_convert`'s own block comment already said OOM and
// already said the stall lives in the EXTRACTOR, "not in trust-vcgen". Measured
// directly on 2026-08-28 by ablating the extractor's budget to 100_000_000 under a
// 900 s watchdog: extraction TERMINATED on its own in 164 s against a 171 s baseline.
// Say "exhausts memory" or "is superlinear"; do not say "does not terminate" unless a
// run shows it.
//
// SCOPE, so this correction is not over-read: the ablation was on
// `crates/trust-semantics`, where THIS budget (`MAX_BUNDLE_ADT_BUDGET`) fires ZERO
// times — its `"over per-function bundle ADT budget"` marker occurs nowhere in a full
// verified run of that crate. Nothing here is a measurement of the clean-kernel
// corpus this bound was written for, and this bound is NOT being relaxed.
//
// FIX: degrade an over-budget function's fat recursive `Ty::Adt` declared types to the
// existing recursive-ADT fail-closed marker `Ty::Unsupported { kind: "TyKind::Adt",
// detail: "recursive …" }` ONCE, up front, so the bundle builders see the cheap type.
// This introduces NO new type modeling: it degrades a fat `Ty::Adt` (which already
// exists on this branch) to the SAME `Ty::Unsupported` shape trust-mir-extract already
// produces for genuinely recursive ADTs — the load-bearing `detail.starts_with(
// "recursive")` shape `collect_type_unsupported` already skips on the declaration walk.
//
// SOUNDNESS (paramount): DROP-ONLY. Borrowed (no clone) for the in-budget common case —
// byte-identical to baseline. For an over-budget function the recursive types become the
// fail-closed recursive-ADT marker, so the bundle reverts to its sound, fail-closed
// verdict for THAT function: it can only LOSE a would-be proof (turn it Unknown), never
// manufacture a false PROVE and never a guaranteed-violation.

/// Per-function fat-ADT node budget for the bundle path. A function whose declared
/// local/return types exceed this many structural `Ty` nodes has its recursive `Ty::Adt`
/// types degraded to the fail-closed marker before bundle construction. Sized so an
/// ordinary function (small types) is never touched, while the pathological fat-recursor
/// cluster trips. The production value is deterministic because degradation changes the
/// fail-closed obligation inventory.
const MAX_BUNDLE_ADT_BUDGET: usize = 2_000_000;

#[cfg(test)]
thread_local! {
    static TEST_BUNDLE_ADT_BUDGET: std::cell::Cell<Option<usize>> = const {
        std::cell::Cell::new(None)
    };
}

/// The deterministic bundle-path fat-ADT node budget.
fn bundle_adt_budget() -> usize {
    #[cfg(test)]
    if let Some(budget) = TEST_BUNDLE_ADT_BUDGET.with(std::cell::Cell::get) {
        return if budget == 0 { usize::MAX } else { budget };
    }
    MAX_BUNDLE_ADT_BUDGET
}

#[cfg(test)]
pub(crate) fn set_bundle_adt_test_budget(budget: Option<usize>) {
    TEST_BUNDLE_ADT_BUDGET.with(|slot| slot.set(budget));
}

/// Total structural-`Ty`-node cost of `func`'s declared local + return types,
/// short-circuited at `cap` so an enormous function costs O(cap), not O(size).
fn func_adt_cost(func: &VerifiableFunction, cap: usize) -> usize {
    let mut total = 0usize;
    for decl in &func.body.locals {
        total += gen_work_datatype_nodes(&decl.ty, cap.saturating_sub(total));
        if total >= cap {
            return total;
        }
    }
    total += gen_work_datatype_nodes(&func.body.return_ty, cap.saturating_sub(total));
    total
}

/// Recursively replace every fat recursive `Ty::Adt` in `ty` with the fail-closed
/// recursive-ADT marker `Ty::Unsupported { kind: "TyKind::Adt", detail: "recursive …" }`.
/// The `"recursive"` detail prefix is load-bearing: it is the exact shape
/// `collect_type_unsupported` skips on the *declaration* walk (a recursive ADT value
/// carries no obligation) while still failing closed on any *use* — i.e. byte-identical
/// to what trust-mir-extract produces for genuinely recursive ADTs. All non-ADT
/// structure is preserved.
fn degrade_fat_adts(ty: &mut Ty) {
    match ty {
        Ty::Adt { .. } => {
            *ty = Ty::Unsupported {
                kind: "TyKind::Adt".to_string(),
                detail: "recursive ADT (degraded: over per-function bundle ADT budget)".to_string(),
            };
        }
        Ty::Ref { inner, .. } => degrade_fat_adts(inner),
        Ty::RawPtr { pointee, .. } => degrade_fat_adts(pointee),
        Ty::Slice { elem } | Ty::Array { elem, .. } | Ty::SymArray { elem, .. } => {
            degrade_fat_adts(elem)
        }
        Ty::Tuple(tys) => tys.iter_mut().for_each(degrade_fat_adts),
        Ty::Closure { upvars, .. } | Ty::Coroutine { upvars, .. } => {
            upvars.iter_mut().for_each(degrade_fat_adts);
        }
        _ => {}
    }
}

/// verifier-perf: enforce the per-function fat-`Ty::Adt` bundle budget. Returns the
/// function unchanged (BORROWED) when its declared-type node cost is within budget — the
/// overwhelmingly common case, so no allocation. When the cost exceeds the budget,
/// returns an OWNED clone whose every recursive `Ty::Adt` (in declared local/return
/// types) is degraded to the fail-closed recursive-ADT `Unsupported` marker, so the
/// bundle builders process that single function's cheap, fail-closed type in bounded
/// time/memory.
///
/// Call this once at the entry of the bundle-construction path, before any
/// O(datatype-size) walk, so the degrade is seen uniformly by every builder.
///
/// SOUNDNESS: DROP-ONLY (see the block comment above). Borrowed in-budget = baseline;
/// over-budget = fail-closed Unknown for that one function. Never a false PROVE.
#[must_use]
/// Cached `TRUST_*` diagnostic environment variable presence lookup for `trust-vcgen`.
/// Avoids repeated process-environment lock acquisitions across hot VC-generation loops.
pub(crate) fn trust_vcgen_env_var_present(name: &str) -> bool {
    static PRESENT: std::sync::OnceLock<trust_types::fx::FxHashSet<String>> =
        std::sync::OnceLock::new();
    PRESENT
        .get_or_init(|| {
            std::env::vars_os()
                .filter_map(|(k, _)| {
                    let s = k.into_string().ok()?;
                    s.starts_with("TRUST_").then_some(s)
                })
                .collect()
        })
        .contains(name)
}

pub fn enforce_datatype_budget(
    func: &VerifiableFunction,
) -> std::borrow::Cow<'_, VerifiableFunction> {
    let cap = bundle_adt_budget();
    if cap == usize::MAX {
        return std::borrow::Cow::Borrowed(func);
    }
    // +1 so a cost that exactly hits the cap is still distinguished from "over";
    // short-circuited so an enormous function costs O(cap), not O(size).
    let cost = func_adt_cost(func, cap.saturating_add(1));
    if cost <= cap {
        return std::borrow::Cow::Borrowed(func);
    }
    if trust_vcgen_env_var_present("TRUST_VCGEN_TRACE_BUDGET") {
        eprintln!(
            "[BUNDLE_ADT_BUDGET] degraded {} adt_node_cost>={cost} cap={cap} (reverted to fail-closed recursive-ADT Unsupported)",
            func.name,
        );
    }
    let mut owned = func.clone();
    for decl in &mut owned.body.locals {
        degrade_fat_adts(&mut decl.ty);
    }
    degrade_fat_adts(&mut owned.body.return_ty);
    std::borrow::Cow::Owned(owned)
}

/// Borrow a local's declared type WITHOUT cloning (and without metering — the meter
/// charges materialization, and a borrow materializes nothing). The borrow is valid for
/// the function's whole VC-gen pass (`func.body.locals[].ty` is owned and immutable
/// during generation), so any caller that only inspects/projects the type should use
/// this instead of materializing it through `place_ty` to avoid deep-cloning the fat
/// recursive-ADT root.
pub(crate) fn local_ty_ref(func: &VerifiableFunction, local: usize) -> Option<&Ty> {
    // verifier-perf: asked for every place the extraction sorts, so a scan of the
    // locals per call made sorting a body O(places x locals). Inside a generation scope
    // the per-function local table answers it (the FIRST declaration carrying
    // `local`, exactly what the scan finds); outside one the scan is the cheaper form.
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.first_decl(func, local).map(|decl| &decl.ty);
    }
    func.body.locals.iter().find(|decl| decl.index == local).map(|decl| &decl.ty)
}

pub(crate) fn sort_for_ty(ty: &Ty) -> Sort {
    match ty {
        Ty::Bool => Sort::Bool,
        // Source-level integer VCs use mathematical Ints unless a preserved
        // symbolic payload supplies a stricter machine sort.
        Ty::Int { .. } => Sort::Int,
        _ => Sort::from_ty(ty),
    }
}

/// R0: `ty` itself, unless it is a bare `Ty::Datatype { variants: [] }` marker
/// that THIS function body's explicit out-of-band table defines.
///
/// The inline definition always wins; the table is consulted only for a marker
/// that carries no structure at all, and only under that marker's own name.
/// A marker the table does not define comes back untouched, so the caller
/// declines exactly as it did before the table existed. Never a body-wide search
/// for a same-name definitional occurrence — that design is fail-open and was
/// withdrawn (see `trust_types::resolve_datatype_marker`).
pub(crate) fn resolved_ty<'a>(
    func: &'a VerifiableFunction,
    ty: &'a Ty,
) -> std::borrow::Cow<'a, Ty> {
    trust_types::resolved_datatype(&func.body.datatype_defs, ty)
}

/// [`sort_for_ty`] at a DEFINITIONAL position — a local's, parameter's or return
/// slot's own declared type, i.e. the places whose sort a `declare-datatype` is
/// built from.
///
/// Only the OUTERMOST marker is widened. Datatype-typed FIELDS keep the by-name
/// `Sort::Datatype { constructors: [] }` spelling that `datatype_sort_from_ty`
/// deliberately cuts recursion with — that is the standard natively-recursive
/// SMT-LIB encoding, and inlining there would both diverge from
/// `collect_datatype_decls` and fail to terminate on a self-recursive type.
pub(crate) fn sort_for_ty_in(func: &VerifiableFunction, ty: &Ty) -> Sort {
    sort_for_ty(&resolved_ty(func, ty))
}

pub(crate) fn operand_sort(func: &VerifiableFunction, op: &Operand) -> Option<Sort> {
    match op {
        Operand::Copy(place) | Operand::Move(place) => place_sort(func, place),
        Operand::Constant(cv) => Some(match cv {
            ConstValue::Bool(_) => Sort::Bool,
            ConstValue::Int(_) | ConstValue::Uint(_, _) => Sort::Int,
            ConstValue::Float(_) => Sort::BitVec(64),
            ConstValue::FloatBits { width, .. } => Sort::BitVec(*width),
            ConstValue::Unit | ConstValue::CallableItem { .. } => Sort::Int,
            // A typed opaque integer value has integer sort (matching the Int/Uint
            // arms above); its identity is its `origin`, spelled by the renderer.
            ConstValue::OpaqueScalar { .. } => Sort::Int,
            // Trust: piece #7a — a const-generic PARAM value has integer sort,
            // identical to `OpaqueScalar`; its identity lives in the symbol name.
            // Exception: a BOOL const-generic (in-band `width==1 && !signed`,
            // see `operand_ty`) is Bool-sorted end-to-end.
            ConstValue::ConstParam { width: 1, signed: false, .. } => Sort::Bool,
            ConstValue::ConstParam { .. } => Sort::Int,
            _ => return None,
        }),
        Operand::Symbolic(formula) => formula_sort(formula),
        Operand::Unsupported { .. } => None,
        _ => None,
    }
}

pub(crate) fn place_sort(func: &VerifiableFunction, place: &Place) -> Option<Sort> {
    // Trust: the BARE array local of an array-theory-eligible array has the SMT
    // Array sort (Int -> elem). Element *reads* keep their scalar sort (they are
    // `Select` results), so this only fires for the whole-array term itself.
    if place.projections.is_empty()
        && let Some(model) = array_theory_local(func, place.local)
    {
        return Some(Sort::Array(Box::new(Sort::Int), Box::new(model.elem_sort)));
    }
    symbolic_assignment_sort_for_place(func, place)
        .or_else(|| place_sort_from_declared_type(func, place))
        .or_else(|| place_ty(func, place).map(|ty| sort_for_ty(&ty)))
}

/// One projection step of `place_sort_from_declared_type`'s DECLARED-type walk,
/// as a borrow.
///
/// Byte-identical to the logic it was factored out of; it became a function only
/// so the walk can thread a `Cow`. R0 makes that necessary: a marker resolved
/// through the body's out-of-band table is a freshly built `Ty` and therefore
/// owned, while an inline definition must stay BORROWED from the function to
/// keep the fat-ADT clone-free win this path was tuned for.
fn declared_ty_step<'a>(
    ty: &'a Ty,
    proj: &'a Projection,
    pending_variant: &mut Option<usize>,
) -> Option<&'a Ty> {
    match proj {
        Projection::Downcast(v) => {
            *pending_variant = Some(*v);
            Some(ty)
        }
        Projection::Field(idx) => {
            if let (Some(v), Ty::Adt { fields, .. }) = (*pending_variant, ty) {
                *pending_variant = None;
                fields
                    .iter()
                    .filter(|(name, _)| {
                        name.strip_prefix("__v")
                            .and_then(|rest| rest.split_once('_'))
                            .is_some_and(|(digits, _)| {
                                enum_entry::canonical_usize_matches(v, digits)
                            })
                    })
                    .nth(*idx)
                    .map(|(_, field_ty)| field_ty)
            } else if let Ty::Datatype { variants, .. } = ty {
                // Lever A: a `Field` after a `Downcast(v)` selects variant v's
                // i-th field; a bare `Field` on a single-variant (struct-like)
                // datatype selects variant 0's i-th field. A multi-variant
                // datatype with no preceding downcast is ambiguous — fail closed
                // (None), exactly as the `Ty::Adt` path does. Resolving the
                // datatype field gives it a concrete `Sort::from_ty`-modeled
                // sort, so `place_sort` no longer returns None and the place
                // stops false-stamping `TrustSymbolicAggregateFieldSortMissing`.
                let v = match pending_variant.take() {
                    Some(v) => v,
                    None if variants.len() == 1 => 0,
                    None => return None,
                };
                variants.get(v).and_then(|(_, fs)| fs.get(*idx)).map(|(_, t)| t)
            } else {
                *pending_variant = None;
                project_ty_ref(ty, proj)
            }
        }
        _ => {
            *pending_variant = None;
            project_ty_ref(ty, proj)
        }
    }
}

fn place_sort_from_declared_type(func: &VerifiableFunction, place: &Place) -> Option<Sort> {
    use std::borrow::Cow;

    // R0: the base local's declared type may be a BARE `Ty::Datatype` marker
    // under markers-everywhere. Widen it through this body's explicit table
    // before ANYTHING reads it — including the work meter below, which must
    // charge the structure that will actually be materialized, not the 29-byte
    // marker standing in for it. `resolved_ty` is the identity on every other
    // shape and on a marker the table does not define.
    let declared = resolved_ty(func, local_ty_ref(func, place.local)?);
    let base_ty: &Ty = &declared;
    // Charge the BASE local's declared-type materialization ONCE per scope (every projected
    // subtree below is `<=` it). Degrade to the cheap `Sort::Int` on trip.
    if gen_work::charge_local_once(func.body.locals.as_ptr() as usize, place.local, |cap| {
        gen_work_datatype_nodes(base_ty, cap)
    }) {
        return Some(Sort::Int);
    }
    // verifier-perf (place-Sort memo, see `place_memo` and the meter comment below):
    // the declared-type Sort is deterministic in `(func, place)` for the whole VC-gen
    // pass, so a repeat query replays the memoized Sort for a `HIT_COST` charge instead
    // of re-walking the projections and re-building the fat `Sort` tree. The meter
    // charge is the peak `charge_local_once` above (which covers every projected
    // subtree), so the memo is pure CPU reuse here; nothing is looked up or stored
    // once tripped.
    let memo_key = if gen_work::is_tripped() { None } else { place_memo::key_for(place) };
    if let Some(key) = &memo_key
        && let Some(cached) = place_memo::lookup_sort(func, key)
    {
        if gen_work::record(place_memo::HIT_COST) {
            return Some(Sort::Int);
        }
        return Some(cached);
    }

    let mut ty: Cow<'_, Ty> = Cow::Borrowed(base_ty);
    let mut pending_variant: Option<usize> = None;

    for proj in &place.projections {
        // R0: a datatype reached PARTWAY down a projection chain (a recursive
        // child, `((*_1) as Two).0 as Leaf`) is spelled bare too, so the table is
        // consulted at every step, not just at the base. Resolution is SHALLOW —
        // one level per step — which is exactly what a chain of steps needs and
        // is why it terminates on a self-recursive type.
        if let Some(resolved) = trust_types::resolve_datatype_marker(&func.body.datatype_defs, &ty)
        {
            ty = Cow::Owned(resolved);
        }
        ty = match ty {
            // Still borrowing the function's declared type — step by reference so
            // the fat recursive root is never cloned.
            Cow::Borrowed(t) => Cow::Borrowed(declared_ty_step(t, proj, &mut pending_variant)?),
            // Owning a table-resolved definition, whose borrow cannot escape this
            // frame: step against it and clone the (small) field result to re-own.
            Cow::Owned(t) => Cow::Owned(declared_ty_step(&t, proj, &mut pending_variant)?.clone()),
        };
    }
    // The place may land ON a datatype (a local or field whose own type is the
    // cut point). Widen once more so the emitted `Sort` carries the constructor
    // list a `declare-datatype` is built from rather than an empty by-name
    // reference — and so the memo's node count below measures what was built.
    let ty: Cow<'_, Ty> = match resolved_ty(func, &ty) {
        Cow::Owned(resolved) => Cow::Owned(resolved),
        Cow::Borrowed(_) => ty,
    };
    let ty: &Ty = &ty;

    // verifier-perf mid-generation work-bound: this is the OTHER O(datatype-size) hot
    // path the generation walk hammers — `sort_for_ty` builds a fresh `Sort` mirroring
    // the modeled type, and `place_sort` is called O(places × statements) times (it does
    // NOT clone the `Ty`, so it bypasses `place_ty`'s meter). Meter the resolved type's
    // node cost here too; once the per-function budget trips, return the cheap
    // fail-closed `Sort::Int` instead of building the fat `Sort`. The whole function is
    // discarded on trip, so this never reaches a verdict.
    //
    // SOUNDNESS: DROP-ONLY — a tripped function is degraded wholesale to Unknown, never
    // Proved; inert outside a VC-gen scope.
    if gen_work::is_tripped() {
        return Some(Sort::Int);
    }
    let sort = sort_for_ty(ty);
    if let Some(key) = memo_key {
        // The store bound needs the TRUE tree size. Count it against the memo cap (the
        // meter charge here is the peak `charge_local_once` at the top, not a per-call
        // record): a cap-truncated count exceeds `MAX_MEMOIZED_TY_NODES`, so
        // `store_sort` refuses it and an oversized tree is never cached.
        let nodes =
            gen_work_datatype_nodes(ty, place_memo::MAX_MEMOIZED_TY_NODES.saturating_add(1));
        place_memo::store_sort(func, key, &sort, nodes);
    }
    Some(sort)
}

fn project_ty_ref<'a>(ty: &'a Ty, proj: &'a Projection) -> Option<&'a Ty> {
    match proj {
        Projection::Downcast(_) => Some(ty),
        Projection::OpaqueCast(ty) | Projection::UnwrapUnsafeBinder(ty) => Some(ty),
        Projection::Field(idx) => match ty {
            Ty::Tuple(fields) => fields.get(*idx),
            Ty::Adt { fields, .. } => fields.get(*idx).map(|(_, field_ty)| field_ty),
            Ty::Closure { upvars, .. } => upvars.get(*idx),
            // Lever A: a bare `Field` on a single-variant (struct-like) datatype
            // selects variant 0's i-th field. A multi-variant datatype reached
            // without a `Downcast` is ambiguous here (the downcast-aware resolution
            // lives in `place_sort_from_declared_type`/`place_ty`); fail closed.
            Ty::Datatype { variants, .. } if variants.len() == 1 => {
                variants[0].1.get(*idx).map(|(_, field_ty)| field_ty)
            }
            _ => None,
        },
        Projection::Deref => match ty {
            Ty::Ref { inner, .. } => Some(inner),
            Ty::RawPtr { pointee, .. } => Some(pointee),
            _ => None,
        },
        Projection::Index(_) | Projection::ConstantIndex { .. } => match ty {
            // Trust: piece #7a — indexing a const-generic array steps to its
            // element type, exactly like a concrete `[T; N]`.
            Ty::Array { elem, .. } | Ty::Slice { elem } | Ty::SymArray { elem, .. } => Some(elem),
            _ => None,
        },
        // Subslice changes array length/slice extent. `place_ty` still handles
        // that owned synthetic type; fall back there instead of guessing here.
        Projection::Subslice { .. } => None,
        _ => None,
    }
}

fn symbolic_assignment_sort_for_place(func: &VerifiableFunction, query: &Place) -> Option<Sort> {
    // verifier-perf: asked by `place_sort` for every place the extraction sorts, and a
    // whole-body scan per question made sorting a body quadratic. Every contributing
    // assignment is keyed on ONE place (its destination, or one aggregate field
    // place), so the answers for all places are computed in one pass per function.
    let answer = fn_memo::symbolic_sorts(func, || symbolic_assignment_sorts(func))
        .map(|table| table.get(query).cloned().flatten());
    if let Some(answer) = answer {
        #[cfg(test)]
        if generate::differential_enabled() {
            assert_eq!(answer, symbolic_assignment_sort_for_place_scan(func, query));
        }
        return answer;
    }
    symbolic_assignment_sort_for_place_scan(func, query)
}

/// Every place some `Assign` gives a symbolic sort, with the sort — or `None` when two
/// assignments disagree (the scan's "conflict" answer).
fn symbolic_assignment_sorts(func: &VerifiableFunction) -> FxHashMap<Place, Option<Sort>> {
    let mut out: FxHashMap<Place, Option<Sort>> = FxHashMap::default();
    let mut note = |place: Place, sort: Sort| match out.entry(place) {
        std::collections::hash_map::Entry::Vacant(v) => {
            v.insert(Some(sort));
        }
        std::collections::hash_map::Entry::Occupied(mut o) => {
            if o.get().as_ref().is_some_and(|existing| existing != &sort) {
                o.insert(None);
            }
        }
    };
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else {
                continue;
            };
            // `symbolic_assignment_sort_for_query`'s two contributions, per place.
            match rvalue {
                Rvalue::Use(Operand::Symbolic(formula)) => {
                    if let Some(sort) = formula_sort(formula) {
                        note(place.clone(), sort);
                    }
                }
                Rvalue::Cast(Operand::Symbolic(_), to_ty) => {
                    note(place.clone(), sort_for_ty(to_ty));
                }
                Rvalue::Aggregate(kind, operands) => {
                    for (index, operand) in operands.iter().enumerate() {
                        let Operand::Symbolic(formula) = operand else { continue };
                        let Some(field_place) =
                            aggregate_field_place(place, kind, index, operands.len())
                        else {
                            continue;
                        };
                        if let Some(sort) = formula_sort(formula) {
                            note(field_place, sort);
                        }
                    }
                }
                _ => {}
            }
        }
    }
    out
}

fn symbolic_assignment_sort_for_place_scan(
    func: &VerifiableFunction,
    query: &Place,
) -> Option<Sort> {
    let mut found = None;

    for block in &func.body.blocks {
        for stmt in &block.stmts {
            let Statement::Assign { place, rvalue, .. } = stmt else {
                continue;
            };
            let Some(sort) = symbolic_assignment_sort_for_query(place, rvalue, query) else {
                continue;
            };
            if found.as_ref().is_some_and(|existing| existing != &sort) {
                return None;
            }
            found = Some(sort);
        }
    }

    found
}

fn symbolic_assignment_sort_for_query(
    place: &Place,
    rvalue: &Rvalue,
    query: &Place,
) -> Option<Sort> {
    if place == query {
        match rvalue {
            Rvalue::Use(Operand::Symbolic(formula)) => return formula_sort(formula),
            Rvalue::Cast(Operand::Symbolic(_), to_ty) => return Some(sort_for_ty(to_ty)),
            _ => {}
        }
    }

    let Rvalue::Aggregate(kind, operands) = rvalue else {
        return None;
    };
    operands.iter().enumerate().find_map(|(index, operand)| {
        let field_place = aggregate_field_place(place, kind, index, operands.len())?;
        if &field_place != query {
            return None;
        }
        match operand {
            Operand::Symbolic(formula) => formula_sort(formula),
            _ => None,
        }
    })
}

pub(crate) fn aggregate_field_place(
    place: &Place,
    kind: &AggregateKind,
    index: usize,
    field_count: usize,
) -> Option<Place> {
    let projection = match kind {
        AggregateKind::Tuple
        | AggregateKind::Adt { active_field: None, .. }
        | AggregateKind::Closure { .. } => Projection::Field(index),
        AggregateKind::Array => {
            Projection::ConstantIndex { offset: index, min_length: field_count, from_end: false }
        }
        _ => return None,
    };

    let mut field_place = place.clone();
    field_place.projections.push(projection);
    Some(field_place)
}

// Trust: enum-variant payload place for an ADT aggregate, projected through a
// `Downcast(variant)` so it matches how a `match`-arm payload READ is named. A
// MIR enum-payload read is `((o as Some).0)` → projection `[Downcast(1),
// Field(0)]` → `o@1.0`, whereas `aggregate_field_place` names the same write
// `o.0` (no downcast); the two never unify, leaving the variant payload write
// unconstrained (the solver was then free to pick an overflowing value). Emitting
// *both* names fixes that without needing to tell a struct (read `o.0`) from an
// enum (read `o@v.0`) — a distinction `AggregateKind::Adt` cannot express.
// Returns `None` for non-ADT and union (`active_field: Some`) aggregates, whose
// field reads do not go through a downcast.
pub(crate) fn aggregate_variant_field_place(
    place: &Place,
    kind: &AggregateKind,
    index: usize,
) -> Option<Place> {
    let AggregateKind::Adt { variant, active_field: None, .. } = kind else {
        return None;
    };
    let mut field_place = place.clone();
    field_place.projections.push(Projection::Downcast(*variant));
    field_place.projections.push(Projection::Field(index));
    Some(field_place)
}

pub(crate) fn is_thin_pointer_identity_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    is_thin_pointer_ty(from_ty) && is_thin_pointer_ty(to_ty)
}

/// Trust (verified-sysroot §5 step 3, slice 1): the provenance-EXPOSE cast — a
/// THIN pointer's address read as the pinned-width unsigned address word
/// (`p.addr()`'s `*const () -> usize` transmute, `p as usize`,
/// `NonNull::addr`'s newtype leg). Under the collapsed allocation-identity
/// model (`trust_types::alloc_model`: a pointer's `Sort::Int` model value IS
/// `base(A) + offset`), this cast is VALUE-PRESERVING — `dest == source` is a
/// theorem of the model — which is what makes `*mut T::add::
/// precondition_check`-shaped address arithmetic STATABLE over the pointer's
/// own term instead of a fresh unconstrained integer.
///
/// FAIL-CLOSED guards, each carried by an audited classifier:
///   * source: `is_thin_pointer_ty` — fat pointers (slice/str/dyn) have no
///     single-address model value and REFUSE; so does every non-pointer.
///   * target: `alloc_model::ptr_expose_target_is_address_word` — exactly
///     `Ty::Int { width: 64, signed: false }`. Narrowing (`as u32`) and signed
///     reinterpret (`as i64`) change the mathematical value and REFUSE.
///   * direction: EXPOSE only. The RECOVER direction (integer -> pointer)
///     manufactures provenance the integer does not carry and stays refused
///     everywhere (`unsupported_cast_reason`'s ptr/int arm).
pub(crate) fn is_thin_pointer_address_expose_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    is_thin_pointer_ty(from_ty)
        && trust_types::alloc_model::ptr_expose_target_is_address_word(to_ty)
}

/// Trust (G1, 2026-10-27): MIR `CastKind::FnPtrToPtr` — a function pointer read as a
/// THIN raw pointer (`on_signal as *const ()`, the `sighandler_t` idiom). The result is
/// an OPAQUE CODE ADDRESS: every lane models it as a fresh value of the destination
/// sort (never identity with the fn pointer, never a value fact), so nothing about its
/// value is assumed, and a dereference of it reaches the separation engine as an
/// untracked pointer whose null/allocation/alignment rows stay unproved (a code
/// address is no data allocation). Only a thin raw pointer target: a fat target, a
/// reference, an integer (the expose `fn as usize` is `PointerExposeProvenance`, an
/// `OpaqueScalar` havoc) and every other source stay on the fail-closed arms.
pub(crate) fn is_fn_pointer_to_code_address_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    matches!(from_ty, Ty::FnPtr { .. })
        && matches!(to_ty, Ty::RawPtr { pointee, .. } if is_thin_pointer_pointee(pointee))
}

pub(crate) fn is_callable_reification_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    match (from_ty, to_ty) {
        (Ty::Unit, Ty::FnPtr { .. }) => true,
        (Ty::FnDef { sig: from_sig, .. }, Ty::FnPtr { sig: to_sig }) => from_sig == to_sig,
        _ => false,
    }
}

pub(crate) fn is_fn_pointer_identity_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    matches!(
        (from_ty, to_ty),
        (Ty::FnPtr { sig: from_sig }, Ty::FnPtr { sig: to_sig }) if from_sig == to_sig
    )
}

/// `&[T; N] -> &[T]` unsize coercion: a reference to an array becomes a reference
/// to a slice of the same element type (`&str` is `&[u8]`-shaped here, so it is
/// covered too). The bridge lowers this precisely (the slice carries the array's
/// length); for VC generation it is a metadata-only coercion that introduces no
/// new arithmetic/bounds obligation, so it is a supported cast.
pub(crate) fn is_array_to_slice_ref_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    let (Ty::Ref { inner: from_p, .. }, Ty::Ref { inner: to_p, .. }) = (from_ty, to_ty) else {
        return false;
    };
    // Trust: piece #7a — a concrete `[T; N]` or const-generic `[T; _]` array unsizes
    // to a slice `[T]` the same metadata-only way; recognizing it suppresses a spurious
    // "unsupported cast" obligation. Compare the element type MODULO `disc_index_safe`
    // (a lowering REPRESENTATION artifact — the array-context and slice-context
    // spellings of the SAME element enum can differ only in that flag, so a plain `==`
    // false-rejected the coercion and left the cast an `unsupported_mir` coverage gap,
    // as `array_to_slice_pointer_cast` in trust-ir-bridge did before commit 79a7f91100).
    // Sound: introduces no new arithmetic/bounds fact (the slice length stays opaque);
    // a genuine element-type change still yields `false`.
    match (from_p.as_ref(), to_p.as_ref()) {
        (Ty::Array { elem: a, .. }, Ty::Slice { elem: b })
        | (Ty::SymArray { elem: a, .. }, Ty::Slice { elem: b }) => {
            a.eq_ignoring_disc_index_safe(b)
        }
        _ => false,
    }
}

/// True when a cast TARGET is a reference (or raw pointer) to a slice (`&[T]` /
/// `*const [T]`; `&str` lowers to a `&[u8]`-shaped slice). `convert.rs` only emits
/// an `Rvalue::Cast` with such a target for a metadata-only array→slice unsize
/// coercion (trait objects go to `OpaqueConst`), which carries NO panic/overflow
/// obligation. The typed case is `is_array_to_slice_ref_cast`, but that fails when
/// the source lost its `&[T;N]` type — e.g. a promoted array constant (`let t:
/// &[T] = &[a,b,c]`) that lowered to `OpaqueConst` (Unit), or an array whose
/// element is itself a fat pointer. Accepting the cast by TARGET stays sound: the
/// slice length stays opaque (`push_borrow_slice_len` only asserts a length when
/// the source length is determinable), so no false fact is emitted.
pub(crate) fn cast_target_is_slice_ref(to_ty: &Ty) -> bool {
    let pointee = match to_ty {
        Ty::Ref { inner, .. } => inner,
        Ty::RawPtr { pointee, .. } => pointee,
        _ => return false,
    };
    matches!(**pointee, Ty::Slice { .. })
}

/// True when a cast TARGET is a reference or raw pointer to a trait object
/// (`&dyn T` / `&mut dyn T` / `*const dyn T` / `*mut dyn T`) — the trait-object
/// POINTER unsize coercion.
///
/// `convert.rs` emits an `Rvalue::Cast` with such a target ONLY for
/// `PointerCoercion::Unsize` (see `unsize_target_is_trait_object_pointer`);
/// Rust rejects a thin→fat `as` cast, so no other construct can produce one.
/// Before commit d806992cd4 this coercion lowered to `Use(OpaqueConst)` and
/// reached no cast predicate at all; that commit made the oracle spell it
/// precisely but left this lane's accept-list untaught, so every `&T -> &dyn T`
/// in the program fell to `unsupported_mir` and poisoned its whole function.
///
/// Sound: the coercion is an infallible vtable attach (no panic/overflow/alloc),
/// so it carries NO obligation. The result's vtable lane is not modeled here, so
/// callers admit it as a FRESH UNCONSTRAINED value — never the source operand's
/// formula, which would falsely assert a fat pointer equals the thin one it was
/// built from. That is exactly the `OpaqueConst` over-approximation this lane had
/// before, so nothing can be proved that was not provable then.
pub(crate) fn cast_target_is_trait_object_pointer(to_ty: &Ty) -> bool {
    let pointee = match to_ty {
        Ty::Ref { inner, .. } => inner,
        Ty::RawPtr { pointee, .. } => pointee,
        _ => return false,
    };
    matches!(**pointee, Ty::Dynamic { .. })
}

/// Trust (2026-09-12): a cast whose source and target types are syntactically
/// identical is a no-op on the value and carries no obligation. Refuses
/// `Ty::Unsupported` on either side: two unsupported types being "equal" says
/// nothing about their values, so nothing is claimed for them.
pub(crate) fn is_syntactic_identity_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    from_ty == to_ty && !matches!(from_ty, Ty::Unsupported { .. })
}

/// Trust (2026-09-12): the `&str -> &[u8]` byte-view transmute (`str::as_bytes`'s
/// exact operation; `format_args!` emits it for string literals at -O). `str` IS
/// `[u8]` with a UTF-8 validity invariant, and this direction DROPS that
/// invariant (a `&str`'s bytes are always a valid `&[u8]`), so it is a
/// value-preserving identity with no obligation. The REVERSE direction
/// (`&[u8] -> &str`) would ASSERT UTF-8 validity and is deliberately NOT
/// matched — it stays on the fail-closed arm. On the legacy lane `str` is already
/// spelled `Slice { u8 }` and this collapses into `is_syntactic_identity_cast`;
/// the explicit arm serves the faithful lane's distinct `Ty::Str`.
pub(crate) fn is_str_ref_to_byte_slice_ref_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    let is_u8 = |t: &Ty| matches!(t, Ty::Int { width: 8, signed: false });
    match (from_ty, to_ty) {
        (Ty::Ref { inner: from_inner, .. }, Ty::Ref { inner: to_inner, .. }) => {
            matches!(from_inner.as_ref(), Ty::Str)
                && matches!(to_inner.as_ref(), Ty::Slice { elem } if is_u8(elem))
        }
        _ => false,
    }
}

/// Trust (2026-09-12): a FAT raw pointer cast to a THIN raw pointer
/// (`*const str -> *const u8`, `*const [T] -> *const T`): a metadata DROP that
/// preserves the address. Fat pointers carry no single-address model value
/// (see `is_thin_pointer_ty`), so the result cannot be expressed as identity;
/// the CHC lowering models it as a FRESH UNCONSTRAINED thin pointer — the same
/// sound over-approximation the `&T -> &dyn Trait` unsize uses — and it mints
/// no VC (the drop is infallible; any later deref keeps its own validity
/// obligation). DIRECTION-GATED: the reverse (thin -> fat) would FABRICATE
/// metadata from a bare pointer and stays fail-closed, pinned by
/// `thin_to_fat_raw_ptr_cast_stays_fail_closed`. Raw-to-raw only.
pub(crate) fn is_fat_to_thin_raw_ptr_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    match (from_ty, to_ty) {
        (Ty::RawPtr { pointee: from_p, .. }, Ty::RawPtr { pointee: to_p, .. }) => {
            !is_thin_pointer_pointee(from_p) && is_thin_pointer_pointee(to_p)
        }
        _ => false,
    }
}

/// Trust (2026-10-08): core's `repr(transparent)` pointer wrapper around a FAT
/// pointer, cast to the raw fat pointer it wraps with the SAME pointee: `NonNull<[T]>
/// -> *const [T]` / `Unique<[T]> -> *const [T]`. The elaborated deref of a
/// `Box<[T]>` reads its contents this way (`copy (_1.0.0) as *const [T]`), so every
/// `b.len()` / `b[i]` on a boxed slice hit the fail-closed arm. The wrapper's bits
/// ARE the pointer, so the cast is infallible and keeps the address and the length
/// metadata (`guards::push_cast_slice_len` ties the length). Exact core paths only,
/// one level of `Unique`/`NonNull` nesting each, and an identical non-thin pointee.
pub(crate) fn is_pointer_wrapper_to_raw_fat_ptr_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    let Ty::RawPtr { pointee: to_p, .. } = to_ty else { return false };
    if is_thin_pointer_pointee(to_p) {
        return false;
    }
    let mut ty = from_ty;
    for _ in 0..3 {
        match ty {
            Ty::RawPtr { pointee, .. } => return ty != from_ty && pointee == to_p,
            Ty::Adt { name, fields, .. }
                if (name == "core::ptr::non_null::NonNull"
                    || name == "core::ptr::unique::Unique"
                    // Trust (1.101): `Box` is `(BoxRaw<T>, A)` and the elaborated
                    // deref casts the BoxRaw value itself (`copy (_1.0) as
                    // *const [T]`, CastKind::BoxDerefTransmute); BoxRaw's field 0
                    // is the same NonNull the Unique leg descended to.
                    || name == "alloc::boxed::BoxRaw")
                    && fields.len() >= 1 =>
            {
                ty = &fields[0].1;
            }
            _ => return false,
        }
    }
    false
}

/// Trust (2026-09-12): the `usize -> NonNull<T>` transmute — the ONE
/// value-to-`NonNull` transmute `trust-mir-extract` deliberately admits (the
/// `fmt::Arguments` packing, a std bit identity over a thin pointee). The
/// extractor emits it as `Rvalue::Cast`; without this arm the CHC lane refused
/// what the extractor had admitted, and the native lane (which threads the
/// newtype) had nothing to own. Modeled as a FRESH UNCONSTRAINED pointer
/// newtype: no provenance is laundered (identity would be — it is exactly what
/// the ptr/int arm of `unsupported_cast_reason` refuses), and any later deref
/// keeps its own validity obligation. NARROW BY CONSTRUCTION: the target must
/// be a single-pointer NEWTYPE ADT (`is_single_pointer_newtype_adt`), never a
/// bare `RawPtr`, so `usize -> *const T` (a genuine provenance recover) is
/// untouched — `ptr_recover_cast_stays_fail_closed` pins it.
pub(crate) fn is_ptr_width_int_to_pointer_newtype_transmute(from_ty: &Ty, to_ty: &Ty) -> bool {
    matches!(from_ty, Ty::Int { width: 64, signed: false })
        && matches!(to_ty, Ty::Adt { .. })
        && is_single_pointer_newtype_adt(to_ty, POINTER_NEWTYPE_FUEL)
}

pub(crate) fn is_modeled_identity_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    // Trust (2026-09-12): a syntactic no-op, and the `&str -> &[u8]` byte view,
    // are value-preserving identities — see the two predicates above.
    if is_syntactic_identity_cast(from_ty, to_ty)
        || is_str_ref_to_byte_slice_ref_cast(from_ty, to_ty)
    {
        return true;
    }
    if let (Ty::Int { width: fw, signed: fs }, Ty::Int { width: tw, signed: ts }) = (from_ty, to_ty)
    {
        // soundness (round-8): an int->int `as` cast is value-preserving
        // (and thus soundly modeled as identity `dest == source`) ONLY when it
        // cannot change the mathematical value for ANY input:
        //   - same width AND signedness (a pure no-op), or
        //   - a widening (tw > fw) that is NOT signed->unsigned (unsigned source
        //     zero-extends and fits; signed->signed sign-extends; signed->unsigned
        //     would wrap negatives, so it is excluded).
        // Narrowing (truncation mod 2^tw), same-width signedness reinterpret, and
        // signed->unsigned widening all change the value, so modeling them as
        // identity was a false-PROVE of properties over the casted value (e.g.
        // `(x as u8) as u32 == x`). Returning false routes them to the fail-closed
        // path (no value-fact in the v2 lowering; Err/unsupported in chc). Correct
        // modular/reinterpret modeling is a future completeness item.
        return (*fw == *tw && *fs == *ts) || (*tw > *fw && !(*fs && !*ts));
    }
    is_thin_pointer_identity_cast(from_ty, to_ty)
        || is_fn_pointer_identity_cast(from_ty, to_ty)
        // Trust (verified-sysroot §5 step 3, slice 1): thin-pointer address
        // EXPOSE is identity over the collapsed allocation model's value —
        // see `is_thin_pointer_address_expose_cast` for the model and guards.
        || is_thin_pointer_address_expose_cast(from_ty, to_ty)
}

/// Is this trust `Ty` an inhabited zero-sized type, syntactically? `()`,
/// arrays of inhabited ZSTs (any length; a zero-length array of anything),
/// and tuples of inhabited ZSTs. Deliberately syntactic and narrow: ADTs,
/// enums/datatypes, closures, fn items and `!` are NOT judged here — the
/// extractor's layout-based ZST transmute leg is the authority for those,
/// and a shape it admits that this predicate misses stays fail-closed in
/// the cast lanes rather than guessed at.
pub(crate) fn ty_is_inhabited_zst(ty: &Ty) -> bool {
    match ty {
        Ty::Unit => true,
        Ty::Array { elem, len } => *len == 0 || ty_is_inhabited_zst(elem),
        Ty::SymArray { elem, .. } => ty_is_inhabited_zst(elem),
        Ty::Tuple(fields) => fields.iter().all(ty_is_inhabited_zst),
        _ => false,
    }
}

/// A cast between two inhabited zero-sized types — the ZST `transmute`
/// `trust-mir-extract` admits on layout evidence. Both sides have exactly
/// one value, so the cast moves that value: it cannot overflow, trap, or
/// reinterpret a single byte, and every equality between two values of
/// one such type is runtime-true. The three cast accept-lists (`chc.rs`,
/// `generate/checked_vcs.rs`, `generate/slice_conversion.rs`) admit it in
/// step; upstream's ZST const-prop is what started spelling these casts
/// with constant aggregate operands (the nested units of
/// `tests/ui/trust/trust_ir_huge_array_types_first_class.rs`).
pub(crate) fn is_zst_to_zst_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    ty_is_inhabited_zst(from_ty) && ty_is_inhabited_zst(to_ty)
}

/// A numeric `as` cast that crosses the float boundary (`int -> float`,
/// `float -> int`, `float -> float`). Rust models these as infallible (no panic:
/// `float -> int` saturates since 1.45), so they carry NO safety obligation —
/// the only thing we cannot model precisely is the resulting *value* (IEEE-754
/// semantics over our BitVec float sort). Treat the destination as a fresh
/// unconstrained value rather than refusing the whole function: sound
/// over-approximation — value-dependent obligations stay `unknown`, never
/// falsely proved, but the function's other obligations are no longer poisoned.
pub(crate) fn is_float_numeric_cast(from_ty: &Ty, to_ty: &Ty) -> bool {
    matches!(from_ty, Ty::Float { .. }) || matches!(to_ty, Ty::Float { .. })
}

pub(crate) fn unsupported_cast_reason(from_ty: &Ty, to_ty: &Ty) -> String {
    if from_ty.is_fn_ptr() || to_ty.is_fn_ptr() {
        if let (Some(from_sig), Some(to_sig)) =
            (callable_signature(from_ty), callable_signature(to_ty))
            && from_sig != to_sig
        {
            return format!(
                "function pointer cast changes callable signature from {from_sig:?} to {to_sig:?}; signature-changing callable casts are not modeled"
            );
        }
        return "function pointer casts require callable address/provenance semantics; only opaque zero-capture reification and fn pointer identity casts are modeled"
            .to_string();
    }

    if from_ty.is_pointer_like() || to_ty.is_pointer_like() {
        if from_ty.is_pointer_like() && to_ty.is_pointer_like() {
            return "pointer cast changes or depends on fat-pointer metadata/provenance; only thin pointer-to-pointer identity casts are modeled"
                .to_string();
        }
        return "pointer/integer casts expose or recover provenance and require explicit pointer provenance semantics"
            .to_string();
    }

    "only bool-to-integer, integer-to-integer, and thin pointer-to-pointer identity cast semantics are modeled"
        .to_string()
}

fn callable_signature(ty: &Ty) -> Option<&trust_types::FnSig> {
    match ty {
        Ty::FnDef { sig, .. } | Ty::FnPtr { sig } => Some(sig),
        _ => None,
    }
}

pub(crate) fn callable_reification_token(dest_name: &str, sort: Sort) -> Formula {
    Formula::Var(format!("__trust_callable_reify_{dest_name}"), sort)
}

pub(crate) fn is_thin_pointer_ty(ty: &Ty) -> bool {
    match ty {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => is_thin_pointer_pointee(inner),
        // A single-pointer NEWTYPE struct (`Box`/`Unique`/`NonNull`) IS a thin
        // pointer: after stripping zero-sized pad fields (`PhantomData`/`Unit`) it
        // has exactly one non-pad field that recursively resolves to a thin
        // pointer. This lets the `vec!`/`Box` machinery's `*mut u8 -> Box` /
        // `NonNull -> *const` transmutes (lowered as `Rvalue::Cast`) be modeled as
        // value-preserving thin-pointer identity casts in the v2 SMT path, matching
        // the native trust-mc wrap/unwrap. Fail-closed for any non-newtype / fat
        // pointer (the address bits are preserved; pointee validity is separate).
        Ty::Adt { .. } => is_single_pointer_newtype_adt(ty, POINTER_NEWTYPE_FUEL),
        _ => false,
    }
}

const POINTER_NEWTYPE_FUEL: u32 = 8;

/// A zero-sized pad field (`PhantomData` lowers to an empty-field `Adt`; `Unit`)
/// — skipped when testing whether a struct is a single-pointer NEWTYPE.
fn is_zero_sized_newtype_pad(ty: &Ty, fuel: u32) -> bool {
    if fuel == 0 {
        return false;
    }
    match ty {
        Ty::Unit => true,
        Ty::Adt { fields, .. } => {
            fields.iter().all(|(_, f)| is_zero_sized_newtype_pad(f, fuel - 1))
        }
        _ => false,
    }
}

/// True iff `ty` is a single-pointer newtype struct: exactly one non-pad field
/// that (recursively) resolves to a thin pointer. Fail-closed for a multi-field
/// struct, an enum, or a fat-pointer leaf, so no value transmute is modeled as a
/// pointer identity cast.
fn is_single_pointer_newtype_adt(ty: &Ty, fuel: u32) -> bool {
    if fuel == 0 {
        return false;
    }
    let Ty::Adt { fields, .. } = ty else {
        return false;
    };
    let mut non_pad = fields.iter().map(|(_, f)| f).filter(|f| !is_zero_sized_newtype_pad(f, fuel));
    let Some(inner) = non_pad.next() else {
        return false;
    };
    if non_pad.next().is_some() {
        return false;
    }
    is_thin_pointer_ty(inner) || is_single_pointer_newtype_adt(inner, fuel - 1)
}

fn is_thin_pointer_pointee(ty: &Ty) -> bool {
    is_thin_pointer_pointee_fueled(ty, 8)
}

/// Whether a pointer to `ty` is THIN (no metadata word).
///
/// The direct unsized sorts are the easy half. The half the original negative
/// gate missed — found by an adversarial probe against the expose-cast arm —
/// is an ADT whose LAST field is unsized (`struct S { len: usize, tail: [u8] }`):
/// a pointer to it carries the tail's metadata, so it is FAT, but the pointee
/// spells `Ty::Adt`, which the bare `!matches!` accepted as thin. That made
/// `*const S -> usize` admissible as an identity expose-cast, silently dropping
/// the metadata word. Not reachable from valid MIR today (the lowering declines
/// such ADTs upstream), but this gate must not be the thing that depends on it.
///
/// So the tail recurses: an ADT/tuple/datatype pointee is thin only if its last
/// field is. Fuel bounds pathological nesting; running out fails CLOSED (fat).
fn is_thin_pointer_pointee_fueled(ty: &Ty, fuel: u8) -> bool {
    let Some(fuel) = fuel.checked_sub(1) else {
        return false;
    };
    match ty {
        Ty::Slice { .. } | Ty::Str | Ty::Dynamic { .. } | Ty::Unsupported { .. } => false,
        // Trust (2026-10-02, proof-loss class 9 — aterm-objc `IvarSlot::<T>::dispose`):
        // a UNION is always `Sized`. rustc rejects a union field of dynamically
        // sized type (every union field must be `Copy` or `ManuallyDrop<_>` of a
        // sized type), so a pointer to a union — or to an ADT whose tail is one —
        // carries no metadata, whatever its fields mention. Without this arm a
        // generic `MaybeUninit<T>` tail walked down to `T`'s `Unsupported`
        // `TyKind::Param` leaf and failed closed as FAT, so the null/alignment
        // checks' `p as *const ()` casts of `*mut IvarSlot<T>` got no `dest == p`
        // definition and every check addressed its own free integer: the check
        // that passed on `slot` said nothing about the `slot` a later borrow used.
        // `adt_kind` is stamped only by the extractor, from rustc's `AdtDef`
        // (`None` on synthetic types, which keep the tail walk below).
        Ty::Adt { adt_kind: Some(trust_types::AdtKind::Union), .. } => true,
        Ty::Adt { fields, .. } => {
            fields.last().is_none_or(|(_, tail)| is_thin_pointer_pointee_fueled(tail, fuel))
        }
        Ty::Tuple(fields) => {
            fields.last().is_none_or(|tail| is_thin_pointer_pointee_fueled(tail, fuel))
        }
        Ty::Datatype { variants, .. } => variants.iter().all(|(_, fields)| {
            fields.last().is_none_or(|(_, tail)| is_thin_pointer_pointee_fueled(tail, fuel))
        }),
        _ => true,
    }
}

pub(crate) fn project_ty(ty: Ty, proj: &Projection) -> Option<Ty> {
    match proj {
        Projection::Downcast(_) => Some(ty),
        Projection::OpaqueCast(ty) | Projection::UnwrapUnsafeBinder(ty) => Some(ty.clone()),
        Projection::Field(idx) => match ty {
            Ty::Tuple(fields) => fields.get(*idx).cloned(),
            Ty::Adt { fields, .. } => fields.get(*idx).map(|(_, field_ty)| field_ty.clone()),
            Ty::Closure { upvars, .. } => upvars.get(*idx).cloned(),
            // Lever A: a bare `Field` on a single-variant (struct-like) datatype
            // selects variant 0's i-th field (multi-variant needs a `Downcast`,
            // handled by `place_ty`); fail closed otherwise.
            Ty::Datatype { variants, .. } if variants.len() == 1 => {
                variants[0].1.get(*idx).map(|(_, field_ty)| field_ty.clone())
            }
            _ => None,
        },
        Projection::Deref => match ty {
            Ty::Ref { inner, .. } => Some(*inner),
            Ty::RawPtr { pointee, .. } => Some(*pointee),
            _ => None,
        },
        Projection::Index(_) | Projection::ConstantIndex { .. } => match ty {
            // Trust: piece #7a — indexing a const-generic array steps to its
            // element type, exactly like a concrete `[T; N]`.
            Ty::Array { elem, .. } | Ty::Slice { elem } | Ty::SymArray { elem, .. } => Some(*elem),
            _ => None,
        },
        Projection::Subslice { from, to, from_end } => match ty {
            Ty::Array { elem, len } => {
                let result_len = if *from_end {
                    len.checked_sub(*from as u64)?.checked_sub(*to as u64)?
                } else {
                    if to < from || *to as u64 > len {
                        return None;
                    }
                    (to - from) as u64
                };
                Some(Ty::Array { elem, len: result_len })
            }
            Ty::Slice { elem } => Some(Ty::Slice { elem }),
            // Trust: piece #7a — a subslice of a const-generic array has an
            // unknown resulting length; fail closed rather than guess (this is
            // 7c/7d territory, not 7a). Sound: returns no synthetic type, so the
            // downstream length lookup fails and the range check fails-closed.
            _ => None,
        },
        _ => None,
    }
}

pub(crate) fn place_ty(func: &VerifiableFunction, place: &Place) -> Option<Ty> {
    // OWNED resolution: walk by reference (`place_ty_cow`), then materialize. The work
    // meter charges the RESOLVED type's node cost here (what `into_owned` clones), exactly
    // as before — so an OWNED query trips byte-identically to baseline. A borrowing caller
    // that only inspects the type should call `place_ty_cow` instead and pay no clone (and
    // no metering of a clone it never performs); see that function.
    //
    // verifier-perf (place-type memo, see `place_memo`): the resolved type is
    // deterministic in `(func, place)` for the whole VC-gen pass, so the FIRST owned
    // query per distinct place performs the full materialization — metered by the peak
    // `charge_local_once` below — and every repeat replays the memoized result for a
    // `HIT_COST` charge instead of re-performing the O(places × statements) re-clone
    // product that fail-closed moderate-typed functions.
    //
    // SOUNDNESS: pure efficiency. The resolved type is structurally identical to the old
    // owned walk (`Ty` is immutable during VC-gen; a memo HIT replays the identical
    // first-query result), so every downstream VC is byte-identical, and the meter still
    // bounds a pathological OWNED materialization (a budget-crossing local trips
    // `charge_local_once` on first touch; an over-`MAX_MEMOIZED_TY_NODES` tree is never
    // cached, with the wall-clock watchdog backstopping its uncached repeat queries).
    // On a trip the whole function is discarded (DROP-ONLY: Unknown, never Proved),
    // and nothing is stored.
    let memo_key = if gen_work::is_tripped() { None } else { place_memo::key_for(place) };
    if let Some(key) = &memo_key
        && let Some(cached) = place_memo::lookup_ty(func, key)
    {
        if gen_work::record(place_memo::HIT_COST) {
            return Some(gen_work_degraded_leaf());
        }
        return Some(cached);
    }
    let ty = place_ty_cow(func, place)?;
    // Charge the BASE local's declared-type materialization ONCE per scope (shared `CHARGED`
    // memo with `place_sort_from_declared_type`, so a local pays at most once total).
    // The resolved `ty` is a subtree of `decl_ty(local)` except for `place_ty_cow`'s synthetic
    // OpaqueCast/Subslice steps, which are themselves 8k-capped — a bounded under-count, and the
    // meter is drop-only, so never a false PROVE.
    if gen_work::charge_local_once(func.body.locals.as_ptr() as usize, place.local, |cap| {
        // R0: charge the RESOLVED declared type. A bare marker is 29 bytes and one
        // node while the definition it stands for can be thousands, so metering the
        // marker would silently defeat this budget on exactly the fat recursive
        // roots it exists to bound. (Under-counting is drop-only and never a false
        // PROVE — but it is the guard, so keep it honest.)
        local_ty_ref(func, place.local)
            .map_or(0, |t| gen_work_datatype_nodes(&resolved_ty(func, t), cap))
    }) {
        return Some(gen_work_degraded_leaf());
    }
    let ty = ty.into_owned();
    if let Some(key) = memo_key {
        // The store bound needs the TRUE tree size. Count it against the memo cap (the
        // meter charge here is the peak `charge_local_once` above, not a per-call
        // record): a cap-truncated count exceeds `MAX_MEMOIZED_TY_NODES`, so `store_ty`
        // refuses it and an oversized tree is never cached.
        let nodes =
            gen_work_datatype_nodes(&ty, place_memo::MAX_MEMOIZED_TY_NODES.saturating_add(1));
        place_memo::store_ty(func, key, &ty, nodes);
    }
    Some(ty)
}

/// Resolve a place's type as a `Cow<Ty>` — the borrowed core of `place_ty`. The declared
/// type is walked by REFERENCE and only the synthetic `Subslice`/`OpaqueCast`/variant-field
/// steps allocate (`step_place_ty_cow`), so the kernel's fat recursive-`Ty::Adt` declared
/// types (`Expr`/`ExprKind`/`Name`) are resolved WITHOUT ever cloning the multi-MB root.
///
/// This is the load-bearing memory-efficiency entry: a caller that only INSPECTS the
/// resolved type (`matches!`, `is_integer`, `int_width`, `sort_for_ty`, equality, …) must
/// use this instead of `place_ty` — it then never materializes the fat root and is never
/// charged the (never-performed) clone, so the function does not trip the VC-gen work
/// budget on a bare full-value read. A caller that needs an OWNED `Ty` (to store / mutate /
/// feed a `VcKind`) calls `place_ty` (or `.into_owned()` on this result), which meters the
/// materialized clone exactly as baseline.
///
/// SOUNDNESS: byte-identical RESULT to `place_ty` (`Ty` is immutable during VC-gen, so the
/// borrowed walk resolves the structurally-identical subtree the owned walk cloned). On a
/// tripped function it returns the same cheap fail-closed leaf `place_ty` would, so the
/// wholesale fail-closed degrade is preserved. DROP-ONLY, never a false-prove.
pub(crate) fn place_ty_cow<'a>(
    func: &'a VerifiableFunction,
    place: &Place,
) -> Option<std::borrow::Cow<'a, Ty>> {
    place_prefix_ty_cow(func, place.local, &place.projections)
}

pub(crate) fn place_prefix_ty_cow<'a>(
    func: &'a VerifiableFunction,
    local: usize,
    projections: &[Projection],
) -> Option<std::borrow::Cow<'a, Ty>> {
    use std::borrow::Cow;
    // Once tripped, the function is about to be discarded — hand back the cheap fail-closed
    // leaf so the rest of the (doomed) walk costs O(1) per query, identical to `place_ty`.
    if gen_work::is_tripped() {
        return Some(Cow::Owned(gen_work_degraded_leaf()));
    }
    let mut ty: Cow<'a, Ty> = Cow::Borrowed(local_ty_ref(func, local)?);
    // a MIR `Field` after a `Downcast(v)` is *variant-relative* (the
    // i-th field of variant v). `lower_enum_adt` flattens an enum to fields
    // `[__tag, __v{v}_{f}, ...]`, so resolving such a `Field` with a flat lookup
    // returns the wrong slot — `Field(0)` lands on `__tag` (an Int) instead of
    // variant v's first payload. For a nested enum that makes the inner payload's
    // type resolve to the tag's Int, and a discriminant read on it false-fails as
    // InvalidDiscriminant. Track the pending downcast variant and select the
    // i-th `__v{v}_*` field instead.
    let mut pending_variant: Option<usize> = None;
    for proj in projections {
        ty = place_ty_step(&func.body.datatype_defs, ty, proj, &mut pending_variant)?;
    }
    Some(ty)
}

/// Trust (RECURSIVE-ENUM DISCRIMINANT DOMAIN, false REFUTATION): [`place_ty_cow`] with
/// the RESULT's outermost bare `Ty::Datatype { variants: [] }` marker widened through
/// THIS body's out-of-band definition table — the one widening `place_ty_step` applies
/// before every projection step but never after the last one.
///
/// A consumer that READS a type's declaration (its variant list, discriminants, payload
/// field types) must use this, not [`place_ty_cow`]: every recursive enum is spelled as a
/// bare marker at its use sites (`&T<X>` lowers to `Ref(Datatype("T<X>", []))`, with the
/// definition in `body.datatype_defs`), so `(*_1)` resolved through `place_ty_cow` is the
/// marker and the declaration is invisible. Measured on `enum T<X> { A, B(Box<T<X>>),
/// Ext(X) }` at `T<NoExt>` (`enum NoExt {}`): the discriminant-domain fact was never
/// published, so the `otherwise -> Unreachable` arm rustc emits for the dead `Ext` was
/// REFUTED at `_2 = 2`, while the same enum with a non-recursive `B(Box<u8>)` (lowered
/// INLINE as a `Ty::Adt`) proved.
///
/// SOUNDNESS: the identity on every type that is not a bare marker, and on a marker the
/// table does not define (both via `trust_types::datatype_marker_definition`, which is
/// keyed on the marker's own generics-bearing name and re-validates the entry's name on
/// read). The definition served is the SAME one `place_ty_step` already substitutes for
/// that marker at every projection step, so this grants a consumer no type the body's own
/// place typing does not already rely on. Shallow — one level — so it terminates on a
/// self-recursive type.
pub(crate) fn place_ty_resolved_cow<'a>(
    func: &'a VerifiableFunction,
    place: &Place,
) -> Option<std::borrow::Cow<'a, Ty>> {
    use std::borrow::Cow;
    let ty = place_ty_cow(func, place)?;
    Some(match trust_types::datatype_marker_definition(&func.body.datatype_defs, ty.as_ref()) {
        Some(definition) => Cow::Borrowed(definition),
        None => ty,
    })
}

/// One projection step of [`place_ty_cow`], factored out (TINV step 4) so the place-write
/// classifier walks place prefixes with the SAME typing. It never consults
/// `gen_work::is_tripped()`: a trip left over from another function on this thread must
/// not hand the classifier a degraded leaf type. `pending_variant` carries a `Downcast`
/// to the `Field` it qualifies.
pub(crate) use trust_types::place_ty::place_ty_step;
/// Trust (OD-1 T3 class D, 2026-10-10): the type [`place_ty_step`] actually
/// steps from — `ty` with a bare recursive-datatype marker widened through THIS
/// body's definition table — and whether that widening happened.
///
/// A walker that must JUDGE the type a projection is applied to (D33's
/// unsafe-operation census asks "is this `Field` a union field? is this `Deref`
/// through a reference?") calls this first, judges the result, then calls
/// [`place_ty_step`] on it, so the judged type and the stepped type are one
/// value. It is the SAME resolution `place_ty_step` performs
/// (`trust_types::datatype_marker_definition`, the primitive
/// `resolve_datatype_marker` is built on), borrowed from the table rather than
/// cloned: the identity on every type that is not a bare marker and on a marker
/// the table does not define (a `compact_oversized_field` marker never has an
/// entry — the producer's write-authority rule — so it stays bare and the
/// walker declines on it as before). Never a by-name guess.
pub(crate) use trust_types::place_ty::place_ty_step_input;
/// One projection step of `place_ty`'s borrowed walk. Threads a `Cow<'a, Ty>` so a
/// borrowed accumulator stays borrowed across borrowed steps (the fat-ADT win), and an
/// owned accumulator (after a synthetic `Subslice`/`OpaqueCast` step) clones the next
/// projection result to keep ownership. Byte-identical RESULT to `project_ty` on the
/// equivalent owned `Ty`.
pub(crate) use trust_types::place_ty::step_place_ty_cow;

pub(crate) fn raw_ptr_aggregate_support_error(
    func: &VerifiableFunction,
    pointee_ty: &Ty,
    mutable: bool,
    operands: &[Operand],
) -> Option<String> {
    if operands.len() != 2 {
        return Some(format!(
            "raw pointer aggregate must have data pointer and metadata operands; got {} operands",
            operands.len()
        ));
    }

    if let Some(reason) = single_lane_raw_ptr_pointee_error(pointee_ty) {
        return Some(format!(
            "raw pointer aggregate for pointee {pointee_ty:?} requires fat-pointer metadata semantics: {reason}"
        ));
    }

    match operand_ty_cow(func, &operands[0]).as_deref() {
        Some(Ty::RawPtr { mutable: data_mutable, pointee }) => {
            if *data_mutable != mutable {
                return Some(format!(
                    "raw pointer aggregate data pointer mutability {data_mutable} does not match aggregate mutability {mutable}"
                ));
            }
            if let Some(reason) = single_lane_raw_ptr_pointee_error(pointee) {
                return Some(format!(
                    "raw pointer aggregate data operand must be a thin raw pointer; got {pointee:?}: {reason}"
                ));
            }
        }
        Some(other) => {
            return Some(format!(
                "raw pointer aggregate first operand must be a raw pointer; got {other:?}"
            ));
        }
        None => {
            return Some(
                "raw pointer aggregate first operand type is unknown; cannot prove it is a thin raw pointer"
                    .to_string(),
            );
        }
    }

    match operand_ty_cow(func, &operands[1]).as_deref() {
        Some(Ty::Unit) => None,
        Some(other) => {
            Some(format!("thin raw pointer aggregate metadata must be unit; got {other:?}"))
        }
        None => {
            Some("thin raw pointer aggregate metadata type is unknown; expected unit".to_string())
        }
    }
}

fn single_lane_raw_ptr_pointee_error(pointee_ty: &Ty) -> Option<String> {
    match pointee_ty {
        Ty::Slice { .. } => Some("slice pointers carry a length metadata lane".to_string()),
        Ty::Dynamic { .. } => {
            Some("trait-object pointers carry a vtable metadata lane".to_string())
        }
        Ty::Unsupported { kind, detail } => {
            Some(format!("pointee type {kind} is unsupported: {detail}"))
        }
        _ => None,
    }
}

pub(crate) fn place_has_raw_deref(func: &VerifiableFunction, place: &Place) -> bool {
    if place.projections.is_empty() {
        return false;
    }
    // verifier-perf: walk the declared type by REFERENCE (no fat-root clone) — this is a
    // pure structural inspection (does any deref hit a raw pointer?), never a move.
    use std::borrow::Cow;
    let Some(mut ty) = local_ty_ref(func, place.local).map(Cow::Borrowed) else {
        return false;
    };

    for proj in &place.projections {
        match proj {
            Projection::Deref => {
                if matches!(ty.as_ref(), Ty::RawPtr { .. }) {
                    return true;
                }
                // Borrow the pointee when the accumulator is still borrowed; clone only
                // if we are already on a synthetic owned intermediate. Non-ref => stop.
                ty = match ty {
                    Cow::Borrowed(Ty::Ref { inner, .. }) => Cow::Borrowed(inner),
                    Cow::Owned(Ty::Ref { inner, .. }) => Cow::Owned(*inner),
                    _ => return false,
                };
            }
            _ => {
                let Some(next_ty) = step_place_ty_cow(ty, proj) else {
                    return false;
                };
                ty = next_ty;
            }
        }
    }

    false
}

pub(crate) fn operand_has_raw_deref(func: &VerifiableFunction, operand: &Operand) -> bool {
    match operand {
        Operand::Copy(place) | Operand::Move(place) => place_has_raw_deref(func, place),
        _ => false,
    }
}

pub(crate) fn slice_len_formula(func: &VerifiableFunction, operand: &Operand) -> Option<Formula> {
    let place = match operand {
        Operand::Copy(place) | Operand::Move(place) => place,
        _ => return None,
    };
    place_slice_len_formula(func, place)
}

pub(crate) fn place_slice_len_formula(func: &VerifiableFunction, place: &Place) -> Option<Formula> {
    // Trust: an `as_bytes()` result has EXACTLY the byte length of its receiver
    // (byte-length-preserving; `str` is modeled as `[u8]`), so resolve its length to
    // the receiver's OWN length var. This unifies an `!s.is_empty()` guard (length on
    // `s`) with an `s.as_bytes()[i]` index bound (length on the fresh `as_bytes`
    // result) — so guarded string indexing PROVES instead of over-refuting. SOUND +
    // fail-closed: the length transfers only when the receiver itself has a slice
    // length (see `guards::as_bytes_length_receiver`), and an UNguarded index still
    // refutes (the receiver's len var is unconstrained without the guard).
    if place.projections.is_empty() {
        if let Some(recv) = guards::as_bytes_length_receiver(func, place.local) {
            // The receiver is a slice/str (`slice_len_formula`) OR a SHARED owned
            // container (`&String`/`&Vec` — `String::as_bytes()` etc.); in both the
            // byte length equals the receiver's own length var, so an
            // `!s.is_empty()` guard discharges an `s.as_bytes()[i]` bound. The
            // owned-container fallback is SHARED-ref-gated (see
            // `guards::owned_container_len_var`) — a `&mut` receiver declines, so the
            // resize hazard stays refuted.
            return slice_len_formula(func, recv)
                .or_else(|| guards::owned_container_len_var(func, recv));
        }
    }

    match place_ty_cow(func, place)?.as_ref() {
        // A reference or raw pointer to a FIXED-SIZE array (`&[T; N]` / `&mut [T; N]` /
        // `*const [T; N]` / `*mut [T; N]`) or const-generic array (`&[T; N]`) has a
        // STATICALLY-KNOWN length `N` (or per-param symbol) — the length is part of the
        // type and is immutable, exactly as for a bare `[T; N]`. So `&bytes[a..b]` /
        // `(&mut bytes)[a..b]` (the idiomatic `bytes[a..b].copy_from_slice(..)`
        // shape on a `let mut bytes = [0u8; N];`) resolves its bound to the constant
        // `N` and the `b <= N` range check PROVES, instead of hitting the
        // unmodeled-len fail-close (`Formula::Bool(true)`) the RangeIndex body emits
        // when no length is found — which a forced-violation escalation then wrongly
        // reports as a GUARANTEED out-of-bounds on provably in-bounds code.
        // SOUNDNESS: `N` is the EXACT array length (never an over-approximation), so
        // this can only PROVE a genuinely in-bounds index, never hide a real OOB (an
        // out-of-range constant `b > N` still folds the violation to true). GENERAL —
        // arrays, no datatype modeling.
        // For slice (`[T]`) or `str` pointees, references and raw pointers (e.g. the
        // `FakeForPtrMetadata` pointer that `<[T]>::len()` reads on a `&mut [T]`) are
        // fat pointers whose metadata is the slice/UTF-8 byte length; their `__slice_len`
        // var is tied to the referent slice's length by the `AddressOf` block definition
        // (guards.rs).
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => match inner.as_ref() {
            Ty::Array { len, .. } => Some(Formula::Int(i128::from(*len))),
            Ty::SymArray { len_sym, .. } => Some(sym_array_len_formula(len_sym)),
            Ty::Slice { .. } | Ty::Str => Some(Formula::var_owned(
                format!("{}__slice_len", place_to_var_name(func, place)),
                Sort::Int,
            )),
            _ => None,
        },
        Ty::Slice { .. } | Ty::Str => Some(Formula::var_owned(
            format!("{}__slice_len", place_to_var_name(func, place)),
            Sort::Int,
        )),
        Ty::Array { len, .. } => Some(Formula::Int(i128::from(*len))),
        // Trust: piece #7a — a bare const-generic array `[T; N]` resolves its
        // length to the per-param symbol `__trust_constparam_{index}_{name}`,
        // the SAME symbol the const-generic value `N` lowers to. The bounds VC
        // `i >= N ∨ i < 0` is then SAT (REFUTED) with no guard, and UNSAT
        // (PROVED) under a guard `i < N`. SOUNDNESS: keyed on the param identity,
        // never on `(width, signed)`, so an index on `[T; M]` cannot be
        // discharged by a guard on a DIFFERENT param `N` (M != N -> distinct
        // symbols). See INV-1 in the piece #7a blueprint.
        Ty::SymArray { len_sym, .. } => Some(sym_array_len_formula(len_sym)),
        _ => None,
    }
}

/// The exact Rust `PtrMetadata` shape for a public TrustIR operand.
///
/// Collection length and pointer metadata are deliberately separate: arrays
/// have a useful collection length but pointers to arrays are thin and their
/// metadata type is `()`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum PtrMetadataModel {
    /// Slice/str fat-pointer metadata, represented by the canonical byte/item
    /// length term.
    Length(Formula),
    /// Metadata for a pointer to a sized pointee.
    Unit,
    /// A pointer-shaped operand whose metadata (notably a dyn vtable) is not
    /// modeled and must remain an explicit fail-closed row.
    Unsupported,
    /// Not a faithful pointer operand at all.
    Invalid,
}

pub(crate) fn ptr_metadata_model(func: &VerifiableFunction, operand: &Operand) -> PtrMetadataModel {
    let Some(ty) = operand_ty_cow(func, operand) else {
        return match operand {
            Operand::Unsupported { .. } => PtrMetadataModel::Unsupported,
            // A pointer-shaped CONSTANT whose type the producer does not retain
            // — a GVN-propagated `PtrMetadata(const "abc")` `Str`, an opaque
            // reference constant, a promoted `&Enum::Variant` reference — is a
            // faithful rustc carrier whose metadata value simply is not
            // modeled. Keep it a row-level fail-closed obligation (the
            // unsupported walker emits the visible `Rvalue::UnaryOp(PtrMetadata)`
            // row) rather than collapsing the whole function as malformed.
            // Every other unresolvable operand stays Invalid.
            Operand::Constant(
                ConstValue::Str { .. }
                | ConstValue::OpaqueConst(_)
                | ConstValue::UnitVariantRef { .. }
                | ConstValue::EmptyClosureRef { .. }
                // Trust: EFHT-P — same faithful-but-unmodeled carrier class.
                | ConstValue::StructScalarFieldsRef { .. },
            ) => PtrMetadataModel::Unsupported,
            _ => PtrMetadataModel::Invalid,
        };
    };
    let pointee = match ty.as_ref() {
        Ty::Ref { inner, .. } | Ty::RawPtr { pointee: inner, .. } => inner.as_ref(),
        _ => return PtrMetadataModel::Invalid,
    };
    match pointee {
        Ty::Slice { .. } | Ty::Str => slice_len_formula(func, operand)
            .map_or(PtrMetadataModel::Unsupported, PtrMetadataModel::Length),
        Ty::Dynamic { .. } | Ty::Unsupported { .. } => PtrMetadataModel::Unsupported,
        // A thin pointer's metadata is `()`. That unit model is authoritative
        // only where the extraction agrees with it: if this body writes THIS
        // operand's metadata into any non-`()` destination, the metadata lane
        // is not the faithfully-typed rustc shape, and the read must stay a
        // row-level fail-closed obligation — neither an asserted unit model nor
        // a whole-function malformed collapse.
        _ => {
            if thin_metadata_written_to_non_unit_destination(func, operand) {
                PtrMetadataModel::Unsupported
            } else {
                PtrMetadataModel::Unit
            }
        }
    }
}

/// Whether any `PtrMetadata` read of `operand` in this body is assigned to a
/// destination that is not `()`-typed (or whose type cannot be resolved).
/// Consulted only on the thin-pointee arm of [`ptr_metadata_model`].
fn thin_metadata_written_to_non_unit_destination(
    func: &VerifiableFunction,
    operand: &Operand,
) -> bool {
    let (Operand::Copy(source) | Operand::Move(source)) = operand else {
        return false;
    };
    func.body.blocks.iter().flat_map(|block| &block.stmts).any(|stmt| {
        let Statement::Assign {
            place,
            rvalue:
                Rvalue::UnaryOp(
                    trust_types::UnOp::PtrMetadata,
                    Operand::Copy(read) | Operand::Move(read),
                ),
            ..
        } = stmt
        else {
            return false;
        };
        read == source
            && !(place.projections.is_empty()
                && matches!(local_ty_ref(func, place.local), Some(Ty::Unit)))
            && place_ty_cow(func, place).as_deref() != Some(&Ty::Unit)
    })
}

/// Trust: piece #7a — the ONE canonical length formula for a const-generic
/// array, a fresh unconstrained `Sort::Int` var named on the param identity. It
/// deliberately does NOT end with `__slice_len`, so `conjoin_slice_len_bounds`
/// (suffix-gated) will not attach a spurious `0 <= N <= isize::MAX` fact (INV-4).
/// The name matches, byte-for-byte, the symbol the const-generic VALUE `N`
/// produces via `operand_to_formula`'s `ConstValue::ConstParam` arm and the
/// native `chc.rs` arm, so a guard `i < N` and the length share one SMT term.
pub(crate) fn sym_array_len_formula(len_sym: &trust_types::ConstLen) -> Formula {
    Formula::var_owned(trust_types::const_param_symbol(len_sym.index, &len_sym.name), Sort::Int)
}

/// Convert an already-decoded NON-NEGATIVE magnitude into a Formula without
/// truncation.
///
/// Values that fit in i128 become `Formula::Int` for compatibility with the
/// mathematical-integer encoding used elsewhere. Values above `i128::MAX`
/// use `Formula::UInt` to avoid silent high-bit truncation.
///
/// # NOT for a raw MIR `SwitchInt` arm label
///
/// A MIR arm label is a two's-complement BIT PATTERN at the scrutinee's width,
/// not a magnitude: on an `i32`, `-1` arrives here as `4294967295`, and this
/// function renders it as the mathematical integer `4294967295`. Conjoined with
/// that scrutinee's own (correct) `i32` range fact it is UNSAT, so the arm's
/// path condition becomes VACUOUS and every obligation under it discharges for
/// free — a FALSE PROOF. The typed decode is [`switch_label_to_formula`]; this
/// function deliberately takes no type parameter precisely because it may only
/// be reached with a value whose sign is already settled (a variant INDEX, a
/// shift bound, a computed magnitude).
pub(crate) fn unsigned_value_to_formula(value: u128) -> Formula {
    match i128::try_from(value) {
        Ok(n) => Formula::Int(n),
        Err(_) => Formula::UInt(value),
    }
}

/// Decode a RAW two's-complement `SwitchInt` arm label into the mathematical
/// integer it denotes UNDER `ty` — the declared type of the scrutinee it is
/// compared against — and render it as a Formula constant.
///
/// The single decode is `trust_types::decode_raw_two_complement`, shared with
/// the extraction boundary that decodes enum TAG values, so an arm constant and
/// the `_d ∈ {tags}` membership fact are byte-identical terms and cancel.
///
/// Returns `None` — and every caller must then fail CLOSED (drop the equality,
/// decline the lane) rather than fall back to the raw value — when `ty` is not
/// an integer-like type whose width and signedness this can establish (`Bool`
/// included: a bool switch is a polarity, not an equality, and each caller
/// renders it itself), when the label has bits set ABOVE `ty`'s width, or when
/// `ty` is `char` and the label is not a valid scalar value.
///
/// For an UNSIGNED `ty` the result is byte-identical to
/// [`unsigned_value_to_formula`], so the unsigned switch row is unchanged.
pub(crate) fn switch_label_to_formula(ty: &Ty, value: u128) -> Option<Formula> {
    // A 128-bit unsigned label above `i128::MAX` has no `i128` spelling; keep
    // the `Formula::UInt` rendering the untyped helper gives it.
    if ty.int_width() == Some(128) && !ty.is_signed() {
        return Some(unsigned_value_to_formula(value));
    }
    ty.decode_switch_label(value).map(Formula::Int)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ExplicitDiscriminantField {
    pub place: Place,
    pub ty: Ty,
    pub name: String,
}

pub(crate) fn explicit_discriminant_field_for_place(
    func: &VerifiableFunction,
    place: &Place,
) -> Result<ExplicitDiscriminantField, String> {
    // verifier-perf: borrowed resolve — a `SetDiscriminant` on a fat-ADT place (e.g. an
    // `Expr`/`Name`-typed local) would otherwise deep-clone the multi-MB declared root
    // just to locate one tag field. Walk by reference; only the small resolved tag field
    // (`field_ty`/`field_name`) is cloned, at the end.
    let place_ty = place_ty_cow(func, place).ok_or_else(|| {
        format!(
            "place `{}` has unknown type; cannot locate an explicit discriminant/tag field",
            place_to_var_name(func, place)
        )
    })?;

    let Ty::Adt { name: adt_name, fields, adt_kind, .. } = place_ty.as_ref() else {
        return Err(format!(
            "place `{}` has type {place_ty:?}; SetDiscriminant is modeled only for tagged ADTs with an explicit discriminant/tag field",
            place_to_var_name(func, place)
        ));
    };

    // TAG-FIELD-1 (the trust-ir bridge's `explicit_discriminant_field` twin): the tag
    // lane is the extractor's own `__tag` (`lower_enum_adt`), and only an ADT that
    // can carry one has it. A `Struct`- or `Union`-stamped ADT's fields are named by
    // the user, so a field called `tag`, `discriminant` or `__tag` there is data. An
    // `Enum`-stamped or unstamped (hand-built / pre-W19 decoded) ADT keeps the lane.
    let may_carry_tag_lane =
        !matches!(adt_kind, Some(trust_types::AdtKind::Struct | trust_types::AdtKind::Union));
    let Some((field_index, (field_name, field_ty))) = fields
        .iter()
        .enumerate()
        .find(|(_, (field_name, _))| may_carry_tag_lane && field_name == "__tag")
    else {
        let field_list =
            fields.iter().map(|(field_name, _)| field_name.as_str()).collect::<Vec<_>>().join(", ");
        return Err(format!(
            "ADT `{adt_name}` has no explicit discriminant/tag field in the TrustIr layout; fields=[{field_list}]"
        ));
    };

    if !matches!(field_ty, Ty::Bool | Ty::Int { .. }) {
        return Err(format!(
            "ADT `{adt_name}` discriminant/tag field `{field_name}` has type {field_ty:?}; expected bool or integer"
        ));
    }

    let mut discr_place = place.clone();
    discr_place.projections.push(Projection::Field(field_index));
    Ok(ExplicitDiscriminantField {
        place: discr_place,
        ty: field_ty.clone(),
        name: field_name.clone(),
    })
}

/// The value a flat `SetDiscriminant` defines for a tag field of type `ty`: `tag`
/// is the DECODED declared discriminant of `variant_index` (`Ty::variant_tag`),
/// never the index itself (triage ticket 216), and a value the field cannot hold
/// under `Ty::flat_tag_fits` fails closed. `variant_index` is only for the
/// message. For a tag in `0..=i128::MAX` the formula is the one
/// `unsigned_value_to_formula` gives.
pub(crate) fn explicit_discriminant_value_formula(
    ty: &Ty,
    tag: i128,
    variant_index: usize,
) -> Result<(Sort, Formula), String> {
    match ty {
        Ty::Bool => match tag {
            0 => Ok((Sort::Bool, Formula::Bool(false))),
            1 => Ok((Sort::Bool, Formula::Bool(true))),
            _ => Err(format!(
                "discriminant {tag} of variant {variant_index} does not fit bool discriminant/tag field"
            )),
        },
        Ty::Int { width, signed } => {
            let width = *width;
            let signed = *signed;
            if width == 0 || width > 128 {
                return Err(format!(
                    "integer discriminant/tag width {width} is outside the supported 1..=128 range"
                ));
            }

            if !ty.flat_tag_fits(tag) {
                return Err(format!(
                    "discriminant {tag} of variant {variant_index} does not fit {}{} discriminant/tag field",
                    if signed { "i" } else { "u" },
                    width
                ));
            }

            Ok((Sort::Int, Formula::Int(tag)))
        }
        other => {
            Err(format!("discriminant/tag field type {other:?} is not modeled as bool or integer"))
        }
    }
}

pub(crate) fn float_bits_magnitude_is_zero(bits: u128, width: u32) -> bool {
    if !(2..=128).contains(&width) {
        return false;
    }
    let magnitude_mask = (1u128 << (width - 1)) - 1;
    bits & magnitude_mask == 0
}

fn sanitize_symbol_fragment(input: &str) -> String {
    let mut out = String::with_capacity(input.len().min(64));
    for ch in input.chars() {
        if out.len() >= 64 {
            break;
        }
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
        } else if !out.ends_with('_') {
            out.push('_');
        }
    }
    out.trim_matches('_').to_string()
}

/// Convert an operand to an SMT formula variable.
/// Uses Sort::Int for integer types (mathematical integers) to enable
/// range-based overflow checking.
///
/// Internal total renderer for admitted bodies. External callers must use
/// [`try_operand_to_formula`] so diagnostic carriers cannot acquire a shared
/// solver meaning at a public API boundary.
pub(crate) fn operand_to_formula(func: &VerifiableFunction, op: &Operand) -> Formula {
    // Trust: existing call sites stay byte-identical — they get the scalar path
    // (array-theory context = None). Only the v2 VC-builder path, which owns the
    // version prepass, calls the `_with_array_ctx` variant with `Some`.
    operand_to_formula_with_array_ctx(func, op, None)
}

/// Render a proof operand only after rejecting diagnostic memory images.
///
/// Allocation observations have no approved value semantics. In particular,
/// their bytes, static names and allocation IDs must not become solver identity.
/// The historical total renderer is crate-private: body-generation entries
/// must reject these carriers before reaching it, including dead operands.
pub fn try_operand_to_formula(
    func: &VerifiableFunction,
    op: &Operand,
) -> Result<Formula, VcgenError> {
    if generate::body_contains_memory_image_for(func)
        || matches!(op, Operand::Constant(value) if value.contains_memory_image())
    {
        return Err(memory_image_error(&func.name));
    }
    Ok(operand_to_formula(func, op))
}

pub(crate) const MEMORY_IMAGE_KIND: &str = "ConstValue::MemoryImage";
pub(crate) const MEMORY_IMAGE_DETAIL: &str =
    "diagnostic allocation observations have no proof-authoritative value semantics";

pub(crate) fn memory_image_error(context: &str) -> VcgenError {
    VcgenError::UnsupportedMirOp {
        op: MEMORY_IMAGE_KIND.into(),
        context: format!("{context}: {MEMORY_IMAGE_DETAIL}"),
        span: None,
    }
}

/// Whole-body refusal before formula construction, branch pruning, or summary
/// shortcuts. This is an Unknown row, not a claim that an execution violates a
/// property; `true` is the conservative violation formula for direct solvers.
pub(crate) fn memory_image_vc(func: &VerifiableFunction) -> Option<VerificationCondition> {
    generate::body_contains_memory_image_for(func).then(|| memory_image_vc_at(&func.name, &func.span))
}

pub(crate) fn memory_image_vc_at(function: &str, span: &SourceSpan) -> VerificationCondition {
    VerificationCondition {
        kind: trust_types::VcKind::UnsupportedMir {
            kind: MEMORY_IMAGE_KIND.into(),
            detail: MEMORY_IMAGE_DETAIL.into(),
        },
        function: function.into(),
        location: span.clone(),
        formula: Formula::Bool(true),
        contract_metadata: None,
        obligation: None,
    }
}

/// Convert a place directly to its scalar SMT formula variable without cloning the place
/// into a temporary `Operand::Copy`.
pub(crate) fn place_to_formula(func: &VerifiableFunction, place: &Place) -> Formula {
    let name = place_to_var_name(func, place);
    let sort = place_sort(func, place).unwrap_or(Sort::Int);
    Formula::var(&name, sort)
}

/// Trust: array-theory-aware `operand_to_formula`. When `array_ctx` is `Some`
/// AND `op` reads an element of an array-theory-eligible local, returns a
/// `Select` term keyed on the live array version; otherwise falls through to the
/// scalar path, byte-identical to the old behavior.
pub(crate) fn operand_to_formula_with_array_ctx(
    func: &VerifiableFunction,
    op: &Operand,
    array_ctx: Option<&ArrayReadCtx<'_>>,
) -> Formula {
    if let Some(ctx) = array_ctx
        && let Some(select) = array_element_select(func, op, ctx)
    {
        return select;
    }
    match op {
        Operand::Copy(place) | Operand::Move(place) => place_to_formula(func, place),
        Operand::Constant(cv) => match cv {
            ConstValue::Bool(b) => Formula::Bool(*b),
            ConstValue::Int(n) => Formula::Int(*n),
            ConstValue::Uint(n, _) => match i128::try_from(*n) {
                Ok(n) => Formula::Int(n),
                Err(_) => Formula::UInt(*n),
            },
            // Model float constants as their IEEE-754 bit pattern so guard
            // propagation can relate comparisons like `y == 0.0` to later
            // safety VCs on the same operand.
            ConstValue::Float(f) => Formula::BitVec { value: i128::from(f.to_bits()), width: 64 },
            ConstValue::FloatBits { bits, width } => match i128::try_from(*bits) {
                Ok(value) => Formula::BitVec { value, width: *width },
                Err(_) => Formula::var_owned(
                    format!("__trust_float_bits_{width}_{bits:x}"),
                    Sort::BitVec(*width),
                ),
            },
            ConstValue::Unit => Formula::Int(0),
            ConstValue::CallableItem { def_path, kind, def_path_hash } => Formula::var_owned(
                ConstValue::callable_smt_var_name(def_path, *kind, *def_path_hash),
                Sort::Int,
            ),
            // a `&str` literal as an opaque integer term, named
            // injectively from its bytes so distinct strings never share a term
            // (a shared term would let the solver "prove" a false disequality).
            ConstValue::Str { bytes } => {
                Formula::var_owned(ConstValue::str_smt_var_name(bytes), Sort::Int)
            }
            // A typed opaque integer value (an unevaluated `size_of::<T>()` /
            // associated const / `const {}` in a generic body, or a runtime value
            // the extractor does not model: `ptr as usize`, `f32 -> u32`,
            // `[u8; N] -> uN`, `MaybeUninit<uN> -> uN`): an integer-sorted symbol
            // spelled from its `origin` (OPAQUE-SCALAR-ID-1). Two occurrences share
            // a symbol only when they provably denote one value — the same MIR
            // site (one statement's most recent execution) or the same keyed
            // constant. Before this, every occurrence of a width was ONE symbol and
            // `if a as usize != b as usize { panic!() }` was proved and certified.
            // The two value-decision folds that could otherwise false-prove over it —
            // `v2_const_eq_truth` (branch pruning) and `v2_divisor_is_zero_formula`
            // (div/rem-by-zero) — match on the `ConstValue` STRUCTURALLY before
            // formula conversion and are fixed to treat `OpaqueScalar` as
            // unknown-valued, so they never consult this symbol. The native-bundle
            // path lowers each occurrence to an INDEPENDENT fresh symbol in
            // `emit_const`; overflow builders reject this carrier (it has no range
            // bound), and CHC rejects it (a site symbol is one execution, not one
            // per loop iteration).
            ConstValue::OpaqueScalar { width, signed, origin } => Formula::var_owned(
                ConstValue::opaque_scalar_smt_var_name(*width, *signed, origin),
                Sort::Int,
            ),
            // Trust: piece #7a — a const-generic PARAM value `N` read as an
            // operand (e.g. the `N` in a guard `if i < N`). It lowers to the ONE
            // canonical per-param symbol `__trust_constparam_{index}_{name}` — the
            // SAME string `Ty::SymArray`'s length uses — so the guard fact and the
            // bounds VC share one SMT term. SOUNDNESS: keyed on the param IDENTITY,
            // NEVER on `(width, signed)`, so two distinct usize params `M`, `N`
            // never collide (the M==N false-proof). The symbol is unconstrained
            // (asserts no value); the `v2_const_eq_truth` / `v2_divisor_is_zero`
            // folds get parallel `ConstParam` arms so a const-param value stays
            // unknown-valued in both (never "definitely unequal" / "provably
            // nonzero"), preserving div/branch soundness.
            // A BOOL const-generic (in-band `width==1 && !signed`) lowers to the
            // same ONE canonical per-param symbol, Bool-sorted: every `if B`
            // guard across the function shares it, so the true- and false-branch
            // path conditions stay mutually exclusive (the decorrelation that
            // previously minted spurious `overflow` counterexamples on
            // dict-gated arithmetic is structurally impossible). Unconstrained:
            // the proof must hold for BOTH instantiations, which is exactly the
            // semantics of verifying the polymorphic body once.
            ConstValue::ConstParam { index, name, width: 1, signed: false } => {
                Formula::var_owned(trust_types::const_param_symbol(*index, name), Sort::Bool)
            }
            ConstValue::ConstParam { index, name, .. } => {
                Formula::var_owned(trust_types::const_param_symbol(*index, name), Sort::Int)
            }
            // An opaque REFERENCE carrier (an unmodeled pointer / reference /
            // aggregate value: `usize as *const T`, `Box<T> -> Box<dyn Trait>`, a
            // promoted `&[..]` table, a static, `&None`, `&Struct(..)`): an
            // unconstrained symbol spelled from the occurrence's `origin`
            // (OPAQUE-REF-ID-1), exactly as `OpaqueScalar` above. Two occurrences
            // share a symbol only when they are the same MIR site. Before this,
            // EVERY such carrier was the one symbol `__unknown_const`, so
            // `let p = x as *const u8; let q = y as *const u8; if p != q { panic!() }`
            // was PROVED and certified — and, with no `UnsupportedMir` row on this
            // carrier, `t[if p == q { 0 } else { 9 }]` was accepted under the strict
            // policy. CHC refuses these carriers (its `_` constant arm), so no lane
            // reuses a site symbol across loop iterations.
            ConstValue::OpaqueConst(origin)
            | ConstValue::UnitVariantRef { origin, .. }
            | ConstValue::EmptyClosureRef { origin, .. }
            | ConstValue::StructScalarFieldsRef { origin, .. } => {
                Formula::var_owned(ConstValue::opaque_reference_smt_var_name(origin), Sort::Int)
            }
            // Sound fallback for unknown ConstValue variants (a `MemoryImage` is
            // refused before any renderer runs, see `memory_image_vc`). Produce an
            // unconstrained symbolic variable rather than panicking. It is ONE
            // symbol, so a new carrier must get its own identity arm above before
            // it can reach a proof; every variant that exists today has one.
            _ => Formula::var("__unknown_const", Sort::Int),
        },
        Operand::Symbolic(formula) => formula.clone(),
        // An operand the extractor refused (it also yields an `UnsupportedMir` row):
        // an unconstrained symbol named by the occurrence's `origin`, never by its
        // diagnostic text (OPAQUE-REF-ID-1) — two `f16` constants, or two constants
        // of one projection type, are two values. The kind is decoration only.
        Operand::Unsupported { kind, origin, .. } => Formula::var_owned(
            Operand::unsupported_operand_smt_var_name(origin, &sanitize_symbol_fragment(kind)),
            Sort::Int,
        ),
        // Sound fallback for unknown Operand variants.
        // Produce an unconstrained symbolic variable rather than panicking.
        // Use interned SymVar.
        _ => Formula::var("__unknown_operand", Sort::Int),
    }
}

/// Build a human-readable variable name from a Place.
// Render an array-literal element read `a[_i]` (where `_i` is a
// provable constant `c`) as the same `[c;min=N]` name that
// `aggregate_field_place` gives the literal's element *write*. Without this the
// read is a fresh, unconstrained variable disconnected from the constructed
// value (`a = [1,2,3,4]` then `a[0] + a[1]` false-fails an overflow VC because
// the solver may pick max values for the reads). Returns `None` — keeping the
// conservative `[_i]` name — unless the indexed thing is the bare array local
// AND that local is construction-immutable. Both guards are load-bearing for
// soundness: equating a read to the constructed value is only valid when no
// element store, mutable borrow, or re-construction can change it between
// construction and the read. When unmet we fall back to the old unconstrained
// name, which fails closed (Failed/Unknown), never false-proves.
fn constant_array_index_segment(
    func: &VerifiableFunction,
    place: &Place,
    pos: usize,
    index_local: usize,
) -> Option<String> {
    let c = index_local_const(func, index_local)?;
    // Shape A — `base[idx]`: Index is the first projection, so the indexed value is
    // the base local itself and its immutability is decidable from the base alone.
    // Nested forms (`s.f[idx]`) fall back.
    if pos == 0 {
        // verifier-perf: borrow the declared type — only the `len` (a Copy u64) is read.
        let Ty::Array { len, .. } = local_ty_ref(func, place.local)? else {
            return None;
        };
        // Trust: an eligible array-theory local routes EVERY element read
        // (including a const index) through `Select`, never the `[c;min=len]`
        // literal-naming path — returning None here keeps the two channels
        // disjoint.
        if array_theory_local(func, place.local).is_some() {
            return None;
        }
        if !array_local_index_naming_stable(func, place.local) {
            return None;
        }
        return Some(format!("[{c};min={len}]"));
    }
    // — Shape B — the indexed array sits at `place.projections[..pos]`,
    // reached from a *shared-reference* root that is never reseated, through a
    // leading Deref and then only Field / constant-Index steps. A shared reference's
    // pointee cannot be mutated or `&mut`-aliased through it, and Field/const-Index
    // navigation introduces no new mutable access, so `(*r)…[c]` observes the same
    // element at every read; the constant index `c` makes two reads converge despite
    // their distinct MIR index temps. Examples this covers: `(*r)[c]` (pos 1),
    // `(*r).f[c]` (struct field then index), `(*r)[c1][c2]` (nested array).
    //
    // Conservative gates, all load-bearing for soundness:
    //  * `&mut` root, or a written/reseated root, falls back — the pointee may be
    //    written between reads.
    //  * Any *further* Deref in the prefix falls back — it dereferences an inner
    //    reference (possibly `&mut`) whose pointee is not guaranteed immutable.
    //  * A non-constant index in the prefix falls back — its MIR temp need not
    //    converge between reads, so the path itself would not be stable.
    let prefix = &place.projections[..pos];
    let immutable_shared_path = matches!(prefix.first(), Some(Projection::Deref))
        // verifier-perf: borrow the declared type — only a variant check, no move.
        && matches!(local_ty_ref(func, place.local)?, Ty::Ref { mutable: false, .. })
        && local_is_never_written(func, place.local)
        && prefix[1..].iter().all(|p| match p {
            Projection::Field(_) | Projection::ConstantIndex { .. } => true,
            Projection::Index(l) => index_local_const(func, *l).is_some(),
            _ => false,
        });
    if !immutable_shared_path {
        return None;
    }
    // Type of the array being indexed = the place truncated to the prefix.
    match place_prefix_ty_cow(func, place.local, prefix)?.as_ref() {
        Ty::Array { len, .. } => Some(format!("[{c};min={len}]")),
        Ty::Slice { .. } => Some(format!("[{c};slice]")),
        _ => None,
    }
}

// true iff the storage rooted at `local` is never the base of any
// assignment — neither reseated (`local = …`) nor written through a projection
// (`*local = …`, `local.f = …`, `local[i] = …`). For a function argument this means
// the value, and everything reachable from it, is fixed for the whole body, so a
// deref/index expressed relative to `local` denotes the same place at every read.
pub(crate) fn local_is_never_written(func: &VerifiableFunction, local: usize) -> bool {
    !any_local_write_stmt(
        func,
        &func.body.blocks,
        local,
        |_block, stmt| matches!(stmt, Statement::Assign { place, .. } if place.local == local),
    )
}

// Resolve a local to a single constant `usize` index, or `None`.
// Sound only if *every* value the local can hold is the *same* non-negative
// integer constant (and there is at least one): then the local holds that value
// wherever it is read. Any non-constant assignment, or two differing constants
// (e.g. a loop induction variable, or a switch-merged index), yields `None`.
// Round-13: the scan also poisons on the WRITE CHANNELS a stmt-only def scan
// cannot see — a call destination, and a slot-write channel of the local
// (`generate::own_storage_write_borrow`: `&mut`, `&raw mut`, and since 2026-09-30
// `&raw const` of an owned place; `*r = 9;` assigns through the pointer, not this
// local) — which now matters
// because this resolver feeds float-lane DISCHARGES (aggregate const-index
// tracing, place-name rendering) where a stale constant claims the wrong
// element.
//
// `&raw const` (INT-RAWCONST-HAVOC-1, 2026-10-06): `let mut i = 1; let p = &raw
// const i; AtomicUsize::from_ptr(p as *mut usize).store(1_000_000, ..); a[i]` with
// `a: [u8; 4]` read `a[i]` as `a[1]` and reported the bounds row `proved` while the
// runtime index is 1_000_000. Main's H2 (2026-09-30, landed 2026-10-08) fixed the same
// gap; at the wave-19 merge (2026-10-09) the borrow test is main's
// `generate::own_storage_write_borrow`, the one statement of the rule in this crate.
//
// THE ENTRY DEFINITION. A PARAMETER's first value is written at ENTRY and no
// statement in `body.blocks` carries it, so the constants this scan agrees on are
// the parameter's SECOND..Nth values, never its first. Unlike the counting
// channel, a wrong answer here cannot be rescued downstream: the constant is
// INLINED into a place NAME (`constant_array_index_segment` renders `a[_i]` as
// `[c;min=N]`, the literal's element), so version renaming has nothing left to
// bind. `p5` — `fn p5(mut i: usize, c: bool) { let a=[9,1,9,9]; let b=[7;4];
// if c { i=1; } if i>3 { return 0 } b[a[i] as usize] }` — read `a[i]` as `a[1] ==
// 1` and PROVED `b[1]` in bounds, kernel-certified, while the c=false path indexes
// `b[9]`. Pinned by `param_reassigned_once_const_index_still_refutes`.
//
// The sibling COUNTER `index_local_stable` has had this arm (`usize::from(is_param)`)
// since before the seam existed; `array_theory_local` gates this resolver behind it,
// but `constant_array_index_segment` calls it directly, which is the path `p5` took.
pub(crate) fn index_local_const(func: &VerifiableFunction, local: usize) -> Option<usize> {
    let mut found: Option<u128> = None;
    let poisoned =
        any_local_write_candidate(func, &func.body.blocks, local, |block, item| match item {
            Some(stmt) => {
                let Statement::Assign { place, rvalue, .. } = stmt else {
                    return false;
                };
                // Trust: 2026-10-08 (H2 RAW-CONST-STORE) — a `&raw const local` writes
                // too (`generate::own_storage_write_borrow`).
                if let Some(borrowed) = generate::own_storage_write_borrow(func, rvalue)
                    && borrowed.local == local
                {
                    return true;
                }
                if place.local != local || !place.projections.is_empty() {
                    return false;
                }
                let v = match rvalue {
                    Rvalue::Use(Operand::Constant(ConstValue::Uint(v, _))) => *v,
                    Rvalue::Use(Operand::Constant(ConstValue::Int(v))) if *v >= 0 => *v as u128,
                    // Assigned something that is not a known non-negative constant.
                    _ => return true,
                };
                match found {
                    Some(prev) if prev != v => true,
                    _ => {
                        found = Some(v);
                        false
                    }
                }
            }
            None => {
                matches!(&block.terminator, Terminator::Call { dest, .. } if dest.local == local)
            }
        });
    if poisoned {
        return None;
    }
    // The entry definition (see the note above). A parameter with no explicit
    // definition never reaches here with `found.is_some()`, so this costs nothing
    // for the entry-stable formal that the aggregate/float lanes actually trace.
    if found.is_some() && crate::local_defs::is_parameter(func, local) {
        return None;
    }
    found.and_then(|v| usize::try_from(v).ok())
}

// A local has "stable index naming" if every const-index read of
// it converges, under SSA last-write-wins, with the array literal and with any
// in-place const-index store — so equating a read of element `c` to the value
// most recently written to `c` is sound. The requirements:
//   * exactly one whole-local store (the construction);
//   * every *element/subslice* store uses a compile-time-constant `Index` — its
//     place name `[c;min=len]` then matches the literal's and the const-read's, so
//     a later store correctly overrides the stale literal (`seen_dests` within a
//     block at guards.rs, `extend_killing_redefs` across blocks);
//   * no slot-write channel of the local (`generate::own_storage_write_borrow`:
//     `&mut`, `&raw mut`, `&raw const` of an owned place).
//
// widens the old "construction-immutable" gate (which bailed on *any*
// element store) to admit *constant*-index stores: `a = [10,1]; a[0] = 0; …` now
// keeps stable naming, and the store's `[0;min=len]` fact overrides the literal's,
// so `a[0]+a[1]` proves and `a[0]-a[1]` correctly FAILS (0-1 underflow). The bail
// cases below are all load-bearing for soundness — each prevents a *stale literal*
// surviving a write it cannot match, which would otherwise vacuously discharge a
// real overflow (a false-PROVE):
//   * a VARIABLE-index store could touch any element, so it must not be modeled as
//     overriding one element's fact while the others' literals survive;
//   * a ConstantIndex/Subslice store has a name (`from_end`, span) that need not
//     equal the literal's `[c;min=len]`, so its write could be lost;
//   * a `&mut`/`&raw` borrow can mutate elements through an alias we don't track.
// In every bail case we return `false`, falling back to opaque per-index naming:
// the whole array reads as free (a sound false-FAIL), never a false-PROVE.
fn array_local_index_naming_stable(func: &VerifiableFunction, local: usize) -> bool {
    let unstable_stmt = any_local_write_stmt(func, &func.body.blocks, local, |_block, stmt| {
        let Statement::Assign { place, rvalue, .. } = stmt else {
            return false;
        };
        if place.local == local && !place.projections.is_empty() {
            // An in-place element/subslice store: stable only for a
            // compile-time-constant `Index`. Everything else bails (see above).
            for p in &place.projections {
                match p {
                    Projection::Index(idx) if index_local_const(func, *idx).is_some() => {}
                    Projection::Index(_)
                    | Projection::ConstantIndex { .. }
                    | Projection::Subslice { .. } => return true,
                    _ => {}
                }
            }
        }
        // A mutable borrow or a raw address-of of either mutability could mutate
        // elements later (`&raw const` of the local's own storage included,
        // 2026-10-08 H2: `generate::own_storage_write_borrow`).
        matches!(
            generate::own_storage_write_borrow(func, rvalue),
            Some(borrowed) if borrowed.local == local
        )
    });
    if unstable_stmt {
        return false;
    }
    // Trust: 2026-10-20 (VGAPS-G2-FOLLOWUP (4), the design's §3.3 audit of the other
    // stability scans) — AND no `UnsafeCell` byte of the array is covered by a SHARED
    // borrow (`generate::shared_borrowed_cell_places`, the clause `place_source_is_stable`
    // asks): an element type is unrestricted here, and `poke(&a[0])` for
    // `a: [Cell<usize>; 2]` rewrites an element through `Cell::set` with no store, no
    // `&mut` and no `&raw` in this body, so the literal's `[c;min=len]` value would name a
    // stale element. G2 also havocs that array at every call (the slot half joins the
    // havoc list); this clause keeps the naming itself from claiming one value. The other
    // scans of the family cannot see a cell and say so where they are pinned
    // (`interior_mut_channel_tests::the_scans_without_the_cell_clause_cannot_see_a_cell`).
    //
    // The scan above decides the PROJECTED stores and the borrow kills; whether the
    // local's WHOLE value is single is `local_defs::has_one_explicit_def`, which also
    // counts a `Call` destination and charges a PARAMETER for its implicit ENTRY
    // definition — an array parameter reassigned once has two values, and the
    // `whole_assigns == 1` this replaces read that as one.
    crate::local_defs::has_one_explicit_def(func, local)
        && generate::shared_borrowed_cell_places(func, local).is_empty()
}

// =====================================================================
// Trust: McCarthy array-theory channel for STRAIGHT-LINE variable-index
// array code.
//
// SOUNDNESS by construction: this channel engages ONLY for array locals in
// functions whose CFG has NO JOIN BLOCK (every basic block has <= 1
// predecessor). With no joins there are no control-flow merges, so no stale
// array fact can ever leak across a join, and the branch_merge /
// arm_definition_map passes never fire for these functions. Any array in a
// function with a branch/loop merge stays in the sound opaque-poison
// fallback (false-FAIL) — that path is untouched.
//
// `array_theory_local` returning `Some` implies `array_local_index_naming_stable`
// is `false` (the latter bails on the variable-index store), so the two channels
// are disjoint.
// =====================================================================

/// A scalar-element array local that is eligible for the McCarthy array-theory
/// channel. `len` is the declared array length (informational); `elem_sort` is
/// the SMT sort of one element (always a scalar: Int / Bool / BitVec).
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ArrayModel {
    pub len: Option<u64>,
    pub elem_sort: Sort,
}

/// True iff the CFG of `func` has no join block — every basic block is listed as
/// a successor by at most one terminator. This also excludes loops (a loop
/// header has >= 2 predecessors: the entry edge and the back edge).
pub(crate) fn func_has_no_join(func: &VerifiableFunction) -> bool {
    crate::generate::func_has_no_join_for(func)
}

pub(crate) fn func_has_no_join_uncached(func: &VerifiableFunction) -> bool {
    let n = func.body.blocks.len();
    // PERF-COMPILER-VCGEN-773: a block becomes a join as soon as it is seen a second
    // time as a terminator target, so 1 bit per block suffices. Use a stack-allocated
    // `[u64; 4]` bitset for CFGs up to 256 blocks (zero heap allocation) and fall back
    // to `vec![false; n]` for larger CFGs.
    if n <= 256 {
        let mut seen = [0u64; 4];
        for block in &func.body.blocks {
            let mut has_join = false;
            for_each_terminator_target(&block.terminator, |target| {
                if target.0 < n {
                    let word = &mut seen[target.0 >> 6];
                    let mask = 1u64 << (target.0 & 63);
                    if (*word & mask) != 0 {
                        has_join = true;
                    } else {
                        *word |= mask;
                    }
                }
            });
            if has_join {
                return false;
            }
        }
        return true;
    }
    let mut seen = vec![false; n];
    for block in &func.body.blocks {
        let mut has_join = false;
        for_each_terminator_target(&block.terminator, |target| {
            if target.0 < n {
                if seen[target.0] {
                    has_join = true;
                } else {
                    seen[target.0] = true;
                }
            }
        });
        if has_join {
            return false;
        }
    }
    true
}

/// Visit all successor block ids of a terminator without allocating a `Vec<BlockId>`.
pub(crate) fn for_each_terminator_target(terminator: &Terminator, mut f: impl FnMut(BlockId)) {
    match terminator {
        Terminator::Goto(target) => f(*target),
        Terminator::SwitchInt { targets, otherwise, .. } => {
            for (_, t) in targets {
                f(*t);
            }
            f(*otherwise);
        }
        Terminator::Call { target: Some(target), .. } => f(*target),
        Terminator::Assert { target, .. } | Terminator::Drop { target, .. } => f(*target),
        Terminator::Opaque { targets, .. } => {
            for &t in targets {
                f(t);
            }
        }
        Terminator::Return
        | Terminator::Call { target: None, .. }
        | Terminator::TailCall { .. }
        | Terminator::Unreachable
        | Terminator::Resume => {}
        // `Terminator` is non_exhaustive; an unknown terminator has no modeled
        // successors here (conservative — counts no predecessors for it).
        _ => {}
    }
}

/// True iff `target` is one of `terminator`'s normal successor block ids.
pub(crate) fn terminator_targets_block(terminator: &Terminator, target: BlockId) -> bool {
    let mut found = false;
    for_each_terminator_target(terminator, |t| {
        if t == target {
            found = true;
        }
    });
    found
}

/// All successor block ids of a terminator (every branch target it may take).
fn terminator_target_blocks(terminator: &Terminator) -> Vec<BlockId> {
    let mut blocks = Vec::new();
    for_each_terminator_target(terminator, |t| blocks.push(t));
    blocks
}

/// True iff the storage rooted at `local` may be mutated through an alias the
/// array-theory channel does not model. Conservative: when unsure, returns true
/// (the channel then bails to the sound opaque fallback). Specifically true if:
///   * a `&mut`/`&raw mut`/`&raw const` borrow whose canonical base local is `local`;
///   * any `Terminator::Call` passing an operand referencing `local`
///     (`Move(local)`, or a `Ref`/`AddressOf` whose canonical base is `local`);
///   * a call destination projected into `local`.
fn array_local_escapes(func: &VerifiableFunction, local: usize) -> bool {
    let base_is_local = |place: &Place| {
        if place.projections.is_empty() {
            place.local == local
        } else {
            canonicalize_place(func, place.clone(), 16).local == local
        }
    };
    for block in &func.body.blocks {
        for stmt in &block.stmts {
            // `&raw const` of the local's own storage included (2026-10-08 H2:
            // `generate::own_storage_write_borrow`).
            if let Statement::Assign { rvalue, .. } = stmt
                && let Some(place) = generate::own_storage_write_borrow(func, rvalue)
                && base_is_local(place)
            {
                return true;
            }
        }
        if let Terminator::Call { args, dest, .. } = &block.terminator {
            // A call destination into `local` reassigns/mutates it: a projected
            // dest (`a[i] = f()`) mutates an element in place, and a WHOLE-local
            // dest (`a = fresh()`) reseats the entire array to an unmodeled value
            // -- both invalidate the McCarthy version chain seeded before the
            // call. (Construction via a literal `[..]`/`[x; n]` is a
            // Statement::Assign, not a Call, so it is unaffected.)
            if dest.local == local {
                return true;
            }
            for arg in args {
                match arg {
                    Operand::Move(place) if place.local == local => return true,
                    Operand::Symbolic(_) | Operand::Unsupported { .. } => {
                        // Cannot inspect — fail closed.
                        return true;
                    }
                    _ => {}
                }
            }
        }
    }
    // A reference operand to `local` passed to a call may mutate it via the
    // callee. Scan rvalues that *create* such references and are then handed to a
    // call. Conservatively, any `&mut`/raw borrow already returned true above; a
    // shared `&local` passed to a call cannot mutate `local`, so it is safe.
    false
}

/// True iff `stmt` is an *element store* `a[Index(idx)] = w` into `local` whose
/// index is a NON-constant `Index` projection (so it engages array theory). The
/// leading projection must be `Index`.
pub(crate) fn is_array_theory_element_store(
    func: &VerifiableFunction,
    local: usize,
    stmt: &Statement,
) -> bool {
    let Statement::Assign { place, .. } = stmt else {
        return false;
    };
    if place.local != local {
        return false;
    }
    // Trust: once an array is eligible (which REQUIRES a variable-index store),
    // EVERY `Index` element store to it must flow through the array channel and
    // bump the version — including a const-FOLDING `a[Index(j)]` where `j`
    // resolves to a constant. Such a store is NOT a "variable-index store" for
    // eligibility, but the scalar `[c;min=len]` path is bypassed for eligible
    // arrays, so dropping it here would make it vanish entirely and a later
    // same-slot read would see a STALE value (false-PROVE). `index_local_const`
    // is therefore deliberately NOT consulted: the index term is the index
    // local's value either way (a const-folding index reads via its `_j == c`
    // scalar fact), and the read and store sides agree because both count a
    // store via this one predicate.
    let _ = func;
    matches!(place.projections.first(), Some(Projection::Index(_)))
}

/// Decide whether `local` is an eligible array-theory local. Returns `Some`
/// (with the element sort) IFF all of:
///   * `local`'s type is `Ty::Array{elem, len}` and `elem` has a SCALAR sort
///     (Int / Bool / BitVec) — nested Array/Slice/Adt/Tuple/Ref elems bail;
///   * `func_has_no_join(func)` — the CFG has no control-flow merge;
///   * there is >= 1 element store to `local` with a NON-constant `Index`;
///   * NO `ConstantIndex`/`Subslice` store to `local`, and no escape.
/// Trust: a local is value-STABLE if it has at most one definition reaching its
/// uses -- a pure input parameter defined at entry and never reassigned, or a
/// single-assignment temporary -- AND it cannot be mutated through an alias. A
/// `Terminator::Call` dest and an `&mut`/escaping-call use also count via
/// `array_local_escapes`. Used for the McCarthy array index and for widening-mul
/// cast operands; both can become false-PROVE vectors if a reassigned runtime
/// value is still encoded at a stale SMT name or narrowed source width.
pub(crate) fn index_local_stable(func: &VerifiableFunction, local: usize) -> bool {
    let is_param = (1..=func.body.arg_count).contains(&local);
    let mut defs = usize::from(is_param);
    if any_local_write_candidate(func, &func.body.blocks, local, |block, item| {
        match item {
            Some(stmt) => {
                if let Statement::Assign { place, .. } = stmt
                    && place.local == local
                    && place.projections.is_empty()
                {
                    defs += 1;
                }
            }
            // Trust: a `Terminator::Call` whose dest IS the index local reassigns it
            // (`i = f()`), invisible to a Statement::Assign-only scan. Count it as a
            // definition so a reassigned-via-call index is NOT stable.
            None => {
                if let Terminator::Call { dest, .. } = &block.terminator
                    && dest.local == local
                {
                    defs += 1;
                }
            }
        }
        defs > 1
    }) {
        return false;
    }
    // Trust: the index could also be mutated through an alias between the store
    // and the read (`let r = &mut i; mutate(r)`, or passed by Move/opaquely to a
    // callee). `array_local_escapes` detects exactly those events for a local; if
    // the index can escape-mutate, it is not stable.
    !array_local_escapes(func, local)
}

pub(crate) fn array_theory_local(func: &VerifiableFunction, local: usize) -> Option<ArrayModel> {
    fn_memo::array_model(func, local, || array_theory_local_uncached(func, local))
}

fn array_theory_local_uncached(func: &VerifiableFunction, local: usize) -> Option<ArrayModel> {
    // verifier-perf: borrow the declared type (no fat-root clone) — this only inspects
    // the element type/sort, never moves the `Ty`.
    let Ty::Array { elem, len } = local_ty_ref(func, local)? else {
        return None;
    };
    // The element must be a SCALAR with one of the modeled sorts (Int / Bool /
    // BitVec). `sort_for_ty` falls back to `Sort::Int` for NON-scalar types
    // (Array/Slice/Adt/Tuple/Ref/...), so a sort check alone would wrongly admit
    // them — gate on the element TYPE directly, then confirm the sort.
    if !matches!(**elem, Ty::Bool | Ty::Int { .. } | Ty::Float { .. } | Ty::Bv(_)) {
        return None;
    }
    let elem_sort = sort_for_ty(elem);
    if !matches!(elem_sort, Sort::Int | Sort::Bool | Sort::BitVec(_)) {
        return None;
    }
    if !func_has_no_join(func) {
        return None;
    }
    // The version chain names the array's value at entry `v0` and gives `v0`
    // AT MOST ONE definition: the whole-local write that constructs it (a
    // seed), or, for a parameter, the caller's value (no seed); with none,
    // `v0` is simply unconstrained. A second whole-local definition would give
    // `v0` two — two constructions would equate two different arrays, and a
    // reassignment after element stores would leave later reads on the stale
    // chain — so it declines the channel (the opaque fallback). The seam's
    // count is exactly that question: it charges a parameter's entry
    // definition, counts whole-local writes (call destinations included) and
    // makes an unlocatable one inexact, which never licenses.
    if !crate::local_defs::value_count(func, local).is_at_most(1) {
        return None;
    }
    let mut has_variable_index_store = false;
    let mut invalid_store = false;
    any_local_write_stmt(func, &func.body.blocks, local, |_block, stmt| {
        let Statement::Assign { place, .. } = stmt else {
            return false;
        };
        if place.local != local || place.projections.is_empty() {
            return false;
        }
        match place.projections.first() {
            Some(Projection::Index(idx)) => {
                // Trust (index-staleness): the index local of EVERY element
                // store (const-folding OR variable) must be STABLE -- never
                // reassigned. Otherwise a store `Store(v, idx, w)` and a later
                // read `Select(v, idx)` at the SAME SMT name would let ROW1
                // fire spuriously after `idx` is reassigned between them
                // (e.g. `a[i]=0; i=j; a[i]`), forcing the read to the stored
                // value though the real indices differ -- a false-PROVE.
                // Bail to the sound opaque fallback.
                if !index_local_stable(func, *idx) {
                    invalid_store = true;
                    return true;
                }
                if index_local_const(func, *idx).is_none() {
                    has_variable_index_store = true;
                }
                false
            }
            // A ConstantIndex / Subslice store has a name that need not match
            // the Select/Store model; bail to the sound opaque fallback.
            Some(Projection::ConstantIndex { .. } | Projection::Subslice { .. }) => {
                invalid_store = true;
                true
            }
            _ => false,
        }
    });
    if invalid_store {
        return None;
    }
    if !has_variable_index_store {
        return None;
    }
    if array_local_escapes(func, local) {
        return None;
    }
    Some(ArrayModel { len: Some(*len), elem_sort })
}

/// The SMT term for version `version` of array `local` with element sort `elem`.
/// Distinct versions get distinct names so a `Store` chain links them.
pub(crate) fn array_term_var(local: usize, version: u32, elem: Sort) -> Formula {
    Formula::Var(
        format!("arr${local}$v{version}"),
        Sort::Array(Box::new(Sort::Int), Box::new(elem)),
    )
}

/// The SMT term for version `version` of array `local`, resolving the element
/// sort from `array_theory_local` (defaulting to Int when not eligible).
fn array_term_formula(func: &VerifiableFunction, local: usize, version: u32) -> Formula {
    let elem = array_theory_local(func, local).map(|m| m.elem_sort).unwrap_or(Sort::Int);
    array_term_var(local, version, elem)
}

/// The SMT index term for an element-access projection.
pub(crate) fn array_index_formula(func: &VerifiableFunction, idx_proj: &Projection) -> Formula {
    match idx_proj {
        Projection::Index(l) => {
            Formula::var_owned(place_to_var_name(func, &Place::local(*l)), Sort::Int)
        }
        Projection::ConstantIndex { offset, .. } => Formula::Int(*offset as i128),
        // Other projections never reach here (the caller gates on element access).
        _ => Formula::Int(0),
    }
}

/// Linear version context for the no-join (acyclic) CFG: the entry version of
/// each eligible array local at the start of each block. Because there are no
/// joins, every block inherits its unique predecessor's exit version, so no
/// havoc is ever needed.
#[derive(Debug, Clone, Default)]
pub(crate) struct ArrayVersionCtx {
    entry: FxHashMap<(BlockId, usize), u32>,
}

/// Count the element stores to `local` in `stmts[..end]` (in program order).
/// This is the SINGLE store-count oracle used by both the read side and the
/// store side, so versions never disagree.
pub(crate) fn count_element_stores(
    func: &VerifiableFunction,
    local: usize,
    stmts: &[Statement],
) -> u32 {
    stmts.iter().filter(|s| is_array_theory_element_store(func, local, s)).count() as u32
}

impl ArrayVersionCtx {
    /// The array version live at `stmts[stmt_idx]` of `block` (i.e. the version
    /// to READ): the block's entry version plus the element stores strictly
    /// before `stmt_idx`.
    pub(crate) fn live_version(
        &self,
        func: &VerifiableFunction,
        local: usize,
        block: BlockId,
        stmt_idx: usize,
    ) -> u32 {
        let entry = self.entry.get(&(block, local)).copied().unwrap_or(0);
        let block_ref = func
            .body
            .blocks
            .get(block.0)
            .filter(|b| b.id == block)
            .or_else(|| func.body.blocks.iter().find(|b| b.id == block));
        let bumped = block_ref
            .map(|b| count_element_stores(func, local, &b.stmts[..stmt_idx.min(b.stmts.len())]))
            .unwrap_or(0);
        entry + bumped
    }
}

/// Forward topological version prepass over the no-join (acyclic) CFG.
/// `entry[(entry_block, local)] = 0` for each eligible local; each block's exit
/// version = its entry version + element-store count, propagated to every
/// successor (which has this block as its unique predecessor, or — for a branch
/// — shares this same exit across all successors).
pub(crate) fn v2_array_version_prepass(func: &VerifiableFunction) -> std::rc::Rc<ArrayVersionCtx> {
    // verifier-perf: a whole-function walk that `extract_block_definitions_until`
    // re-ran on EVERY call — i.e. once per `writes_until` probe, once per
    // block-def conjoin — computed once per function per scope instead
    // (`fn_memo`). Pure function of `func.body`.
    fn_memo::array_prepass(func, || v2_array_version_prepass_uncached(func))
}

fn v2_array_version_prepass_uncached(func: &VerifiableFunction) -> ArrayVersionCtx {
    let mut ctx = ArrayVersionCtx::default();
    if func.body.blocks.is_empty()
        || !func.body.locals.iter().any(|d| matches!(d.ty, Ty::Array { .. }))
        || !func_has_no_join(func)
    {
        return ctx;
    }
    // Eligible locals — computed once.
    let eligible: Vec<usize> = func
        .body
        .locals
        .iter()
        .map(|d| d.index)
        .filter(|&l| array_theory_local(func, l).is_some())
        .collect();
    if eligible.is_empty() {
        return ctx;
    }
    let n_blocks = func.body.blocks.len();
    ctx.entry.reserve(n_blocks.saturating_mul(eligible.len()));
    let entry_block = func.body.blocks[0].id;
    for &local in &eligible {
        ctx.entry.insert((entry_block, local), 0);
    }
    // Forward BFS/topo walk: each block, once its entry version is known, sets
    // its successors' entry version to its own exit version. The no-join CFG is
    // acyclic, so a simple worklist over a finite number of edges terminates.
    let mut worklist = Vec::with_capacity(n_blocks);
    worklist.push(entry_block);
    let mut seen: trust_types::fx::FxHashSet<BlockId> =
        trust_types::fx::FxHashSet::with_capacity_and_hasher(n_blocks, Default::default());
    while let Some(bid) = worklist.pop() {
        if !seen.insert(bid) {
            continue;
        }
        let Some(block) = func
            .body
            .blocks
            .get(bid.0)
            .filter(|b| b.id == bid)
            .or_else(|| func.body.blocks.iter().find(|b| b.id == bid))
        else {
            continue;
        };
        for &local in &eligible {
            let entry = ctx.entry.get(&(bid, local)).copied().unwrap_or(0);
            let exit = entry + count_element_stores(func, local, &block.stmts);
            for_each_terminator_target(&block.terminator, |succ| {
                // Unique predecessor (no-join) => safe to set; first writer wins
                // and there is only ever one writer.
                ctx.entry.entry((succ, local)).or_insert(exit);
            });
        }
        for_each_terminator_target(&block.terminator, |succ| {
            worklist.push(succ);
        });
    }
    ctx
}

/// Read context for `operand_to_formula`: which array version to use for an
/// element read happening at `(block, stmt_idx)`.
pub(crate) struct ArrayReadCtx<'a> {
    versions: &'a ArrayVersionCtx,
    block: BlockId,
    stmt_idx: usize,
}

impl<'a> ArrayReadCtx<'a> {
    pub(crate) fn new(versions: &'a ArrayVersionCtx, block: BlockId, stmt_idx: usize) -> Self {
        ArrayReadCtx { versions, block, stmt_idx }
    }
}

/// If `op` is a Copy/Move of an *element access* (`a[i]` / `a[const]`) into an
/// array-theory-eligible local, return its `Select(arr$local$v{n}, idx)` term.
/// `n` is the version live at the read point per the single store-count oracle.
fn array_element_select(
    func: &VerifiableFunction,
    op: &Operand,
    ctx: &ArrayReadCtx<'_>,
) -> Option<Formula> {
    let place = match op {
        Operand::Copy(place) | Operand::Move(place) => place,
        _ => return None,
    };
    // The element access must be `local[idx]` directly (leading Index /
    // ConstantIndex into the bare array local) — the only shape the store side
    // models. Nested forms keep the scalar path.
    let idx_proj = place.projections.first()?;
    if !matches!(idx_proj, Projection::Index(_) | Projection::ConstantIndex { .. }) {
        return None;
    }
    // Only a single index projection (a scalar element read), no further nesting.
    if place.projections.len() != 1 {
        return None;
    }
    // Confirm eligibility (also disjoint from the scalar `[c;min=len]` channel).
    let model = array_theory_local(func, place.local)?;
    // A FROM-END constant index (`let [.., last] = a` reads `a[1 of 1 from
    // end]`) names lane `len - offset`, not lane `offset`: read the lane it
    // names, or decline (the scalar path) when the length is not known.
    let index = match idx_proj {
        Projection::ConstantIndex { offset, from_end: true, .. } => {
            let lane = model.len?.checked_sub(*offset as u64)?;
            Formula::Int(i128::from(lane))
        }
        _ => array_index_formula(func, idx_proj),
    };
    let version = ctx.versions.live_version(func, place.local, ctx.block, ctx.stmt_idx);
    Some(Formula::Select(Box::new(array_term_formula(func, place.local, version)), Box::new(index)))
}

// Follow a reference local back to the place it points to, so a deref `*L` is named
// by its underlying storage instead of an opaque `L*`. Match guards on references
// re-borrow the binding (`_4 = &_3; _9 = *_4; if *_9 < K { ... *_3 + 1 ... }`), so the
// guard reads `*_9` while the arithmetic reads `*_3`; both alias the same payload yet
// get distinct SMT names, so the guard never constrains the overflow VC — a Goal-1
// false-fail. Only the local's UNIQUE VALUE is followed, so the referent is
// unambiguous; `&mut` is safe because a write through the alias canonicalizes to the
// same place name, keeping reads and writes consistent.
//
// The resolver itself is `local_defs::unique_value_def` — the one place that knows a
// PARAMETER is defined at ENTRY, so a once-reassigned parameter's single `Assign` is
// never handed back as that parameter's universal value.

// The place a reference *value* read from `source` ultimately points to.
fn referent_of_source(
    func: &VerifiableFunction,
    source: &Place,
    fuel: u32,
    extra: &[Place],
) -> Option<Place> {
    if fuel == 0 {
        return None;
    }
    // Trust: 2026-09-17 (round A12, fixer) — THE CARRIERS OF AN ADDRESS. A referent
    // read OUT OF a slot (`L = copy *M` with `M ≡ &x`, `x ≡ &P`) is `P`, and `P`'s
    // guards must hold from `x`'s definition to the read. That interval is covered
    // by `x`'s own walk (def(x)..the borrow `&x`), by the walk of EVERY local that
    // carried `x`'s address from that borrow to the read (`m2 = &x; m = copy m2`:
    // `m2` AND `m`), and by `L`'s walk. The per-local check at the end of each
    // resolution walks only that local's referent's guards, and `M`'s referent `x`
    // has none — so `M`'s chain is RE-RESOLVED with `P`'s guards as `extra`, which
    // every walk on the chain adds to its own (`reread_through`). `extra` is threaded
    // through every hop for the same reason one level further out.
    // Trust: 2026-09-17 (round A12) — every arm below that reads a reference OUT OF
    // `M`'s storage (`*M`, `(*M).f`, `M.idx`) hands back a referent whose guards
    // were walked from the definition of the local that STORED it (`x = &P` for
    // `M = &x`) to the uses of THAT local, and will be walked again from the
    // definition of the local being resolved; the hop through `M` — from `M`'s
    // definition to the read — is neither, so it is walked here on the same
    // referent (`referent_fold::is_stable`). The `[]` arm is `resolve_referent`
    // itself, already walked on `M`.
    let referent = match source.projections.as_slice() {
        // `L = Copy(M)` — L holds the same reference M does.
        [] => return resolve_referent_guarded(func, source.local, fuel - 1, extra),
        // `L = Copy(*M)` — M points to a slot holding the reference; follow it.
        [Projection::Deref] => {
            (match resolve_referent_guarded(func, source.local, fuel - 1, extra) {
                Some(slot) => {
                    let read = if slot.projections.is_empty() {
                        resolve_referent_guarded(func, slot.local, fuel - 1, extra)
                    } else {
                        referent_of_source(func, &slot, fuel - 1, extra)
                    }?;
                    reread_through(func, source.local, fuel - 1, extra, &slot, &read)
                        .then_some(read)
                }
                // M's referent is unknown because M is a never-written
                // parameter (e.g. `r: &&u32`). The reference value read from `*M` is then
                // fixed, and it points to `**M`; naming the deref relative to M lets two
                // reborrows of the same payload converge. A written/reseated M falls back
                // to the opaque `*M` name (no merge), preserving soundness.
                None if local_is_never_written(func, source.local) => Some(deref_of(source)),
                None => None,
            })?
        }
        // `L = Copy((*M).f…)` — a reference read out of a FIELD of M's pointee: the
        // closure-ENV upvar shape (`_6 = copy (*_1).0`, `_7 = copy (*_1).0`). Mirrors
        // the `[Deref]` arm: follow M's referent when it resolves; otherwise, for an
        // M that is never WHOLE-reseated (a closure env pointer — entry def only),
        // the reference lives in a fixed slot, so name its pointee definitionally as
        // `(*M).f*`. Two copies of the SAME upvar ref then converge on ONE name
        // (`_1*.0*`), which is what lets a guard read through one copy bound a use
        // read through another — the `&mut`-captured-upvar guard idiom
        // (`if acc < 1000 { acc += 1 }` inside a closure) previously FALSE-REFUTED
        // because each copy minted an opaque `_6*`/`_7*`.
        //
        // SOUND with the versioning fabric (the overlap-union mint): a write to the
        // slot (`(*M).f = other_ref`, name `_1*.0`), a write-back through the ref
        // (`(*(*M).f) = v`, name `_1*.0*`), and a Call/Drop havoc of M (base name
        // `_1`, M being a mut-pointer-carrying local) ALL name-overlap the pointee
        // read `_1*.0*`, so reads straddling any mutation channel mint DIFFERENT
        // version tokens and can never falsely unify. A whole-local reseat of M
        // itself has no name the fabric tracks relative to the old pointee, so it
        // fail-closes here (a local with an explicit whole-local def declines to the opaque
        // per-copy name — no merge, the pre-existing conservative behavior).
        [Projection::Deref, rest @ ..]
            if !rest.is_empty() && rest.iter().all(|p| matches!(p, Projection::Field(_))) =>
        {
            (match resolve_referent_guarded(func, source.local, fuel - 1, extra) {
                Some(slot) => {
                    let mut field_slot = slot.clone();
                    field_slot.projections.extend_from_slice(rest);
                    let read = referent_of_source(func, &field_slot, fuel - 1, extra)?;
                    reread_through(func, source.local, fuel - 1, extra, &slot, &read)
                        .then_some(read)
                }
                None if crate::local_defs::never_explicitly_reseated(func, source.local) => {
                    Some(deref_of(source))
                }
                None => None,
            })?
        }
        // `L = Copy(_agg.idx)` where `_agg = (op0, op1, …)` was built by an
        // `Aggregate`: `_agg.idx` IS the construction operand `op_idx` (a real value
        // equality), so L holds that operand's reference value. Fold through to it so a
        // tuple/struct-field copy of a reference names the SAME referent as the source —
        // e.g. `_23 = _6.0` with `_6 = (self, other)` makes `*_23` canonicalize to
        // `*self`, which lets `build_discriminant_cse_facts` tie `disc(*_23) ≡ disc(*self)`.
        // Only a CONSTRUCTED aggregate folds, so genuinely-distinct struct-field reads
        // never merge. For a never-written reference operand the referent is the
        // definitional `*op`, mirroring the `[Deref]` arm.
        [Projection::Field(idx)] => {
            if crate::local_defs::is_parameter(func, source.local) {
                return None;
            }
            let Some(Rvalue::Aggregate(_, operands)) =
                crate::local_defs::unique_value_def(func, source.local)
            else {
                return None;
            };
            let (Operand::Copy(p) | Operand::Move(p)) = operands.get(*idx)? else {
                return None;
            };
            referent_of_source(func, p, fuel - 1, extra).or_else(|| {
                (p.projections.is_empty() && local_is_never_written(func, p.local))
                    .then(|| deref_of(p))
            })?
        }
        _ => return None,
    };
    referent_fold::is_stable(func, source.local, &referent, extra).then_some(referent)
}

/// Trust: 2026-09-17 (round A12, fixer) — `read` was obtained by reading the
/// pointer stored in `slot`, where `slot` is `carrier`'s referent resolved under
/// `extra`. The read happens at a use of `carrier`, so `read`'s guards must be
/// stable over `carrier`'s region AND over the region of every local on
/// `carrier`'s own resolution chain: re-resolve `carrier` with them added to
/// `extra` and require the same slot. A resolution can only get MORE conservative
/// with more guards, so `false` is the only way this changes an answer.
fn reread_through(
    func: &VerifiableFunction,
    carrier: usize,
    fuel: u32,
    extra: &[Place],
    slot: &Place,
    read: &Place,
) -> bool {
    let read_guards = referent_fold::guards(read);
    if read_guards.is_empty() {
        return true;
    }
    let mut widened: Option<Vec<Place>> = None;
    for g in read_guards {
        let already = match &widened {
            Some(w) => w.contains(&g),
            None => extra.contains(&g),
        };
        if !already {
            let w = widened.get_or_insert_with(|| {
                let mut v = Vec::with_capacity(extra.len() + 2);
                v.extend_from_slice(extra);
                v
            });
            w.push(g);
        }
    }
    let Some(widened) = widened else {
        return true;
    };
    resolve_referent_guarded(func, carrier, fuel, &widened).as_ref() == Some(slot)
}

// `place` extended by one Deref — the place the reference *stored at*
// `place` points to, expressed definitionally when no more concrete referent exists.
fn deref_of(place: &Place) -> Place {
    let mut derefed = place.clone();
    derefed.projections.push(Projection::Deref);
    derefed
}

// Trust: 2026-09-17 (round A12) — THE FOLD IS AN ALIAS FACT, AND IT IS
// VERSION-SENSITIVE. `*r ≡ P` is INLINED into a name, not keyed on one: every
// later read or store through `r` is spelled by `P`'s name and versioned at the
// USE point with whatever reaching token `P`'s locals carry there — never with
// the token they carried at the borrow. So the fold is correct only while `P`
// denotes the same storage at the use as it did at the borrow, i.e. while every
// local that SELECTS that storage (the pointer at each `Deref` prefix of `P`,
// each `Index(l)`) still holds its borrow-time value. `referent_fold::is_stable`
// is that condition, walked over the CFG from the def of `local` to every use of
// it; a fold it refuses leaves `*local` the opaque `local*`, which makes
// `deref_pointer_is_opaque` true and routes a store through it to the
// deref-store havoc. The round-A11 review's witnesses are the counterexamples
// this closes (`sf_field_reseat_bug`: `let r = &mut p.a; p = o; *r = 3;
// t[p.a]` — `*r` was spelled `p*.0` at the post-reseat token, unified with the
// read, and PROVED kernel-certified while the store hit the OLD `p`).
fn resolve_referent(func: &VerifiableFunction, local: usize, fuel: u32) -> Option<Place> {
    resolve_referent_guarded(func, local, fuel, &[])
}

/// `resolve_referent`, with `extra` guards — the guards of a referent that will be
/// read OUT OF this local's pointee at its uses (see `referent_of_source`) — added
/// to every stability walk on the resolution chain.
///
/// Trust: 2026-10-11 (LAUNDERED-ALIAS-STORE, LAUNDERED-ALIAS-ELIDE-1) — a local whose
/// unique value is a RAW-POINTER CAST of another pointer folds like a copy of it when
/// the cast keeps the address and the pointee type ([`raw_pointer_cast_keeps_referent`]:
/// `p as *const T` for `p: *mut T`, the `as` after a `&mut` coercion). Before this arm
/// such a `q` resolved to nothing, so `*q` was the opaque `q*` while a store through `p`
/// was spelled by `p`'s referent; nothing related the two names, a read of `*q` before
/// and after the store shared one version, and an `x + 1` row bounded by a guard on the
/// NEW value was kernel-certified (its overflow check elided on the advisory lane).
/// The arm is the precision half of that fix; the soundness half, for the copies no fold
/// can see through (`cast_const()`, `wrapping_add(0)`, an opaque call), is
/// `generate::path_defs::write_havocs_function_list`.
fn resolve_referent_guarded(
    func: &VerifiableFunction,
    local: usize,
    fuel: u32,
    extra: &[Place],
) -> Option<Place> {
    if fuel == 0 {
        return None;
    }
    // Trust: 2026-09-30 — one step of the ambient per-function budget per resolution.
    // `fuel` bounds this recursion's DEPTH, not its size: `canonicalize_deref_guarded`
    // and `referent_of_source` each re-resolve for their re-read obligation
    // (`reread_through`), so a chain of pointer-to-pointer copies branches at every
    // hop, and a hop whose referent has no guard never reaches the stability walk's
    // own poll. A trip answers `None` — the unfolded, opaque name every caller already
    // treats as "no referent" — and the compiler's post-generation checkpoint
    // discards everything generated after it (see `referent_fold::is_stable`).
    if trust_types::verify_budget::budget_exhausted() {
        return None;
    }
    // Trust: 2026-09-17 (round A12, pass 2) — the fold asks the question that means
    // "does `local` hold ONE pointer value", NOT the wider `unique_value_def`, which
    // also refuses on a borrow of the POINTEE (`&mut (*local)[i]`) that cannot reseat
    // `local` at all. `referent_fold::is_stable` below carries the storage-identity
    // half the wider question used to stand in for; see
    // `local_defs::body_unique_value_def_modulo_pointee_borrows` for the argument and
    // the measured witness (`x3_ctl`, a correct program the wider question refuted).
    let referent = match crate::local_defs::unique_value_def_modulo_pointee_borrows(func, local)? {
        Rvalue::Ref { place, .. } | Rvalue::AddressOf(_, place) => {
            canonicalize_deref_guarded(func, place.clone(), fuel - 1, extra)
        }
        Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) => {
            referent_of_source(func, p, fuel - 1, extra)?
        }
        // Trust: 2026-10-11 (LAUNDERED-ALIAS-STORE) — `q = p as *const T` holds the
        // address `p` holds: fold it exactly like the `Use` arm above. Declined unless
        // both sides are raw pointers to the SAME pointee type (an int-to-pointer cast,
        // a pointee-changing cast and a reference source keep the opaque `q*` and the
        // havoc that goes with it). `referent_fold::is_stable` still runs on the result.
        Rvalue::Cast(Operand::Copy(p) | Operand::Move(p), to)
            if raw_pointer_cast_keeps_referent(func, p, to) =>
        {
            referent_of_source(func, p, fuel - 1, extra)?
        }
        _ => return None,
    };
    referent_fold::is_stable(func, local, &referent, extra).then_some(referent)
}

/// Trust: 2026-10-11 (LAUNDERED-ALIAS-STORE) — whether `from as to` copies a raw
/// pointer unchanged except for its mutability: `from` is typed `*mut T` / `*const T`
/// and `to` is `*mut T` / `*const T` with the IDENTICAL pointee `T`. Such a cast (MIR
/// `PtrToPtr` between those types) keeps the address and the metadata, so the cast's
/// result points where `from` points. This crate's `Rvalue::Cast` carries no cast
/// kind, so the question is asked of the two types alone; anything else — an integer
/// source (`IntToPtr`), a different pointee (`p as *const u8`, `p.cast::<U>()`'s
/// spelling), a reference or `NonNull` source, an unresolved source type — answers
/// `false`, which leaves the local unresolved (the pre-existing, conservative answer).
fn raw_pointer_cast_keeps_referent(func: &VerifiableFunction, from: &Place, to: &Ty) -> bool {
    let Ty::RawPtr { pointee: to_pointee, .. } = to else {
        return false;
    };
    matches!(
        place_ty_cow(func, from).as_deref(),
        Some(Ty::RawPtr { pointee: from_pointee, .. }) if from_pointee == to_pointee
    )
}

/// Trust: 2026-09-17 (round A12) — the stability walk behind `resolve_referent`.
/// See the comment on that function for what it decides and why.
mod referent_fold {
    use std::borrow::Cow;
    use std::cell::RefCell;
    use std::rc::Rc;

    use trust_types::fx::{FxHashMap, FxHashSet};
    use trust_types::{
        BlockId, ConstValue, LocalWrite, Operand, Place, Projection, Rvalue, Statement, Terminator,
        Ty, VerifiableFunction,
    };

    /// Fuel for a nested referent resolution of a pointer stored through inside
    /// the walked region. Mirrors `place_to_var_name`'s own budget so the nested
    /// answer agrees with the name the store will actually be minted under.
    const NESTED_FUEL: u32 = 16;

    /// One stability walk on the stack.
    struct Frame {
        func: usize,
        local: usize,
        /// Every local whose in-progress mark this walk — or anything it called,
        /// served memo hits and outcome enumerations included — CONSULTED, its own
        /// included. The walk's verdict is a function of `func`, its arguments, and
        /// the answers to exactly these consultations.
        consulted: FxHashSet<usize>,
    }

    thread_local! {
        /// The walks on the stack, outermost first. A nested resolution of a local
        /// already being decided answers `None` (opaque) — the conservative side —
        /// instead of recursing forever.
        static FRAMES: RefCell<Vec<Frame>> = const { RefCell::new(Vec::new()) };
    }

    fn func_identity(func: &VerifiableFunction) -> usize {
        std::ptr::from_ref(func) as usize
    }

    /// The locals of `func` whose walk is on the stack, outermost first.
    fn in_progress(func: usize) -> Vec<usize> {
        FRAMES.with(|f| f.borrow().iter().filter(|fr| fr.func == func).map(|fr| fr.local).collect())
    }

    /// Record, in the innermost walk of `func` (if any), that `locals`' in-progress
    /// marks were consulted.
    fn note_consulted<'a>(func: usize, locals: impl IntoIterator<Item = &'a usize>) {
        FRAMES.with(|f| {
            if let Some(top) = f.borrow_mut().last_mut()
                && top.func == func
            {
                top.consulted.extend(locals);
            }
        });
    }

    /// Is `local`'s walk on the stack? The question is itself a consultation.
    fn consult(func: usize, local: usize) -> bool {
        note_consulted(func, std::iter::once(&local));
        FRAMES.with(|f| f.borrow().iter().any(|fr| fr.func == func && fr.local == local))
    }

    /// A stored stability verdict and the STACK CERTIFICATE it replays under.
    ///
    /// Trust: 2026-09-30 — WHY A NESTED VERDICT CAN BE STORED AT ALL. The only
    /// input of [`is_stable`] beyond `func` and its arguments is the in-progress
    /// stack (the ambient budget aside: a verdict reached after a trip is never
    /// stored). The computation is deterministic given the answers to the
    /// in-progress questions it asks, and it asks them about exactly `consulted`. So
    /// in any stack `S'` with `S' ∩ consulted == cut`, every consultation is
    /// answered as it was when the verdict was computed, the same calls follow in
    /// the same order, and the verdict is the same — by induction on the
    /// computation. A stack that answers any consultation differently finds no valid
    /// entry and recomputes. The certificate changes COST, never an answer.
    ///
    /// Before this, a nested verdict was never stored (only a top-level one, the
    /// certificate whose `cut` is empty in the empty stack), so every enclosing walk
    /// re-ran every nested walk from scratch: a chain of `k` pointers each storing
    /// through the next cost `2^k` walks.
    pub(crate) struct FoldEntry {
        consulted: FxHashSet<usize>,
        /// `consulted ∩ (the stack the walk ran under)`, sorted — the consultations
        /// answered "in progress", i.e. CUT.
        cut: Vec<usize>,
        verdict: bool,
    }

    impl FoldEntry {
        fn replays_in(&self, stack: &[usize]) -> bool {
            if stack.is_empty() {
                return self.cut.is_empty();
            }
            if self.cut.is_empty() {
                return !stack.iter().any(|l| self.consulted.contains(l));
            }
            let mut cut: Vec<usize> =
                stack.iter().copied().filter(|l| self.consulted.contains(l)).collect();
            cut.sort_unstable();
            cut.dedup();
            cut == self.cut
        }
    }

    #[cfg(test)]
    thread_local! {
        /// Test-only: switch off the two exact shortcuts of 2026-09-30 (the outcome
        /// enumeration in `written_place_rebinds`, the known-bit skip in the walks) so
        /// the tests can compare every answer against the computation without them.
        static REFERENCE_WALK: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    }

    #[cfg(test)]
    fn shortcuts_enabled() -> bool {
        !REFERENCE_WALK.with(std::cell::Cell::get)
    }

    #[cfg(not(test))]
    fn shortcuts_enabled() -> bool {
        true
    }

    /// Run `f` with the 2026-09-30 shortcuts switched off (test-only reference).
    #[cfg(test)]
    fn reference_walk<T>(f: impl FnOnce() -> T) -> T {
        struct Restore(bool);
        impl Drop for Restore {
            fn drop(&mut self) {
                REFERENCE_WALK.with(|r| r.set(self.0));
            }
        }
        let _restore = Restore(REFERENCE_WALK.with(|r| r.replace(true)));
        f()
    }

    /// The body-global facts a stability walk asks per statement, per guard, per
    /// visited state — each a pure function of `func` — computed once per function.
    ///
    /// Trust: 2026-09-30 — every one of these was a WHOLE-BODY scan asked from the
    /// walk's inner loop: `callee_may_rebind` scanned every statement for a borrow of
    /// the guard at every `Call`/`Drop` terminator the walk visited, and
    /// `written_place_rebinds` scanned it again for `local_storage_borrowed_anywhere`
    /// at every direct write. On a body of `n` statements that made one walk
    /// `O(n²)` per guard, and the nested walks below multiplied it. The answers are
    /// unchanged — the index lists the same borrows the scans matched, and the
    /// `index_agrees_with_the_scans` test below checks it statement class by class.
    pub(crate) enum FoldBlockIndex {
        Identity(usize),
        Map(FxHashMap<BlockId, usize>),
    }

    impl FoldBlockIndex {
        #[inline]
        fn get(&self, id: &BlockId) -> Option<usize> {
            match self {
                FoldBlockIndex::Identity(len) => (id.0 < *len).then_some(id.0),
                FoldBlockIndex::Map(map) => map.get(id).copied(),
            }
        }
    }

    pub(crate) struct FoldIndex {
        /// Every `Rvalue::Ref` / `Rvalue::AddressOf` in a statement, by the borrowed
        /// place's ROOT local: its projections, and whether a write through it is
        /// defined (`&mut`, or a raw borrow of either mutability — `AliasKind`'s line).
        borrows: FxHashMap<usize, Vec<(Vec<Projection>, bool)>>,
        /// Locals with a borrow of their OWN storage (not `Deref`-first) anywhere —
        /// the reference scan `local_storage_borrowed_anywhere`'s answer.
        storage_borrowed: FxHashSet<usize>,
        /// `body.blocks` position of each `BlockId`.
        block_index: FoldBlockIndex,
        /// Answers of [`FoldIndex::slot_aliased`], per guard: `[Any, WriteCapable]`.
        alias_cache: RefCell<FxHashMap<Place, [Option<bool>; 2]>>,
        /// [`body_forges_a_pointer`], once.
        forges_cache: std::cell::Cell<Option<bool>>,
        /// [`slot_taint`] per guard.
        taint_cache: RefCell<FxHashMap<Place, Rc<SlotTaint>>>,
        /// [`def_position`] per local.
        def_position_cache: RefCell<FxHashMap<usize, DefStart>>,
    }

    impl FoldIndex {
        fn build(func: &VerifiableFunction) -> FoldIndex {
            let mut borrows: FxHashMap<usize, Vec<(Vec<Projection>, bool)>> = FxHashMap::default();
            let mut storage_borrowed: FxHashSet<usize> = FxHashSet::default();
            for block in &func.body.blocks {
                for stmt in &block.stmts {
                    let Statement::Assign { rvalue, .. } = stmt else { continue };
                    let (borrowed, write_capable) = match rvalue {
                        Rvalue::Ref { mutable, place } => (place, *mutable),
                        Rvalue::AddressOf(_, place) => (place, true),
                        _ => continue,
                    };
                    borrows
                        .entry(borrowed.local)
                        .or_default()
                        .push((borrowed.projections.clone(), write_capable));
                    if !matches!(borrowed.projections.first(), Some(Projection::Deref)) {
                        storage_borrowed.insert(borrowed.local);
                    }
                }
            }
            // PERF-COMPILER-VCGEN-697: canonical dense `BlockId`s (`b.id.0 == i`) need
            // zero heap allocation and resolve in O(1) by bounds-checked index.
            let block_index = if func.body.blocks.iter().enumerate().all(|(i, b)| b.id.0 == i) {
                FoldBlockIndex::Identity(func.body.blocks.len())
            } else {
                let mut map = FxHashMap::with_capacity_and_hasher(
                    func.body.blocks.len(),
                    Default::default(),
                );
                for (i, b) in func.body.blocks.iter().enumerate() {
                    map.insert(b.id, i);
                }
                FoldBlockIndex::Map(map)
            };
            crate::fn_memo::count_fold_index_builds();
            FoldIndex {
                borrows,
                storage_borrowed,
                block_index,
                alias_cache: RefCell::default(),
                forges_cache: std::cell::Cell::new(None),
                taint_cache: RefCell::default(),
                def_position_cache: RefCell::default(),
            }
        }

        /// The reference scan `slot_alias_scan`'s question — does a borrow of the
        /// storage AT `guard` (a prefix or sibling place, never one strictly inside
        /// it) of the `kind` counted exist anywhere — answered from the index.
        fn slot_aliased(&self, guard: &Place, kind: AliasKind) -> bool {
            let slot = usize::from(kind == AliasKind::WriteCapable);
            let hit = self.alias_cache.borrow().get(guard).and_then(|answers| answers[slot]);
            if let Some(hit) = hit {
                return hit;
            }
            let answer = self.borrows.get(&guard.local).is_some_and(|list| {
                list.iter().any(|(projections, write_capable)| {
                    (kind == AliasKind::Any || *write_capable)
                        && crate::local_defs::written_projections_rebind_path(
                            projections,
                            &guard.projections,
                        )
                })
            });
            self.alias_cache.borrow_mut().entry(guard.clone()).or_default()[slot] = Some(answer);
            answer
        }

        fn forges(&self, func: &VerifiableFunction) -> bool {
            if let Some(hit) = self.forges_cache.get() {
                return hit;
            }
            let answer = body_forges_a_pointer(func);
            self.forges_cache.set(Some(answer));
            answer
        }

        /// [`slot_taint`] per guard. A taint computed after the ambient budget
        /// tripped is fail-closed (`escaped`) and is not kept.
        fn taint(&self, func: &VerifiableFunction, guard: &Place) -> Rc<SlotTaint> {
            // The borrow is released before `slot_taint` runs: nothing here re-enters
            // the cache, but a `RefCell` held across a call is a panic waiting for the
            // one that does.
            let hit = self.taint_cache.borrow().get(guard).cloned();
            if let Some(hit) = hit {
                return hit;
            }
            let (computed, tripped) = slot_taint(func, self, guard);
            let computed = Rc::new(computed);
            if !tripped {
                self.taint_cache.borrow_mut().insert(guard.clone(), Rc::clone(&computed));
            }
            computed
        }

        fn def_position(&self, func: &VerifiableFunction, local: usize) -> DefStart {
            let hit = self.def_position_cache.borrow().get(&local).copied();
            if let Some(hit) = hit {
                return hit;
            }
            let answer = def_position(func, local);
            self.def_position_cache.borrow_mut().insert(local, answer);
            answer
        }
    }

    /// The fold index for `func`: shared for the whole VC-gen scope when one is
    /// active (`havoc_memo::fold_index`), built afresh otherwise.
    fn fold_index(func: &VerifiableFunction) -> Rc<FoldIndex> {
        super::havoc_memo::fold_index(func, || FoldIndex::build(func))
    }

    /// The components of `referent` whose VALUE selects the storage it denotes:
    /// the pointer stored at every `Deref` prefix (the root local itself for a
    /// leading `Deref`, a deeper slot such as `(*_1).0` for a nested one) and every
    /// `Index(l)` local. A referent with no `Deref` and no `Index` — a local, a
    /// field of a local, a constant-index element — names storage that is fixed for
    /// the body and needs no guard: a whole write of the root OVERWRITES that
    /// storage, which is exactly what a later read through the alias sees.
    pub(super) fn guards(referent: &Place) -> Vec<Place> {
        let mut out: Vec<Place> = Vec::new();
        for (i, proj) in referent.projections.iter().enumerate() {
            let guard = match proj {
                Projection::Deref => {
                    Place { local: referent.local, projections: referent.projections[..i].to_vec() }
                }
                Projection::Index(l) => Place::local(*l),
                _ => continue,
            };
            if !out.contains(&guard) {
                out.push(guard);
            }
        }
        out
    }

    /// Where the walk of `local` STARTS.
    ///
    /// Trust: 2026-09-17 (round A12, fixer) — the channel question is asked of the
    /// SEAM first, and this scan only LOCATES the statement the seam has already
    /// agreed is the local's single whole binding:
    ///
    ///  * `NoWrite` — nothing in `body.blocks` whole-writes the local
    ///    (`local_defs::never_explicitly_reseated`, which counts a `Call` destination
    ///    and an unlocatable write as a reseat). A parameter's one value, or a local
    ///    the body never binds: there is no region to walk and no rebinding to see.
    ///  * `At(b, k)` — exactly one whole binding
    ///    (`local_defs::is_single_static_assignment_modulo_pointee_borrows` since
    ///    round A12 pass 2 — the resolver's own escape classifier, which still refuses
    ///    every partial, own-storage-escape and unlocatable channel) AND it is an
    ///    `Assign` statement.
    ///  * `Unknown` — anything else, INCLUDING a parameter that is also written once
    ///    and a single binding that is a `Call` destination (no statement position to
    ///    start from). The caller refuses the fold.
    ///
    /// The earlier form scanned `Assign` alone and answered `Some` for a parameter
    /// with one write (whose ENTRY value is a second value) and `None` — read as
    /// "no region, pass" — for a call destination.
    #[derive(Clone, Copy)]
    enum DefStart {
        NoWrite,
        At(usize, usize),
        Unknown,
    }

    fn def_position(func: &VerifiableFunction, local: usize) -> DefStart {
        if crate::local_defs::never_explicitly_reseated(func, local) {
            return DefStart::NoWrite;
        }
        // Trust: 2026-09-17 (round A12, pass 2) — the SAME escape classifier the
        // resolver used. `resolve_referent_guarded` has already answered "this local
        // holds one pointer value" through
        // `unique_value_def_modulo_pointee_borrows`; asking the WIDER SSA question
        // here would answer `Unknown` — and refuse the fold — on the very shape that
        // resolver just admitted (`let a = &mut s[i]; let r = &mut *a;`: the reborrow
        // `&mut (*_a)` is an escape on the wide classifier and nothing at all on the
        // narrow one). `never_explicitly_reseated` above needs no twin: it treats the
        // `Escape` channel as a non-reseat already, so both classifiers agree on it.
        if !crate::local_defs::is_single_static_assignment_modulo_pointee_borrows(func, local) {
            return DefStart::Unknown;
        }
        for (b, block) in func.body.blocks.iter().enumerate() {
            for (k, stmt) in block.stmts.iter().enumerate() {
                if let Statement::Assign { place, .. } = stmt
                    && place.local == local
                    && place.projections.is_empty()
                {
                    return DefStart::At(b, k);
                }
            }
        }
        // The one binding the seam counted is not an `Assign` — a `Call`/`TailCall`
        // destination. No statement to start the walk from.
        DefStart::Unknown
    }

    fn place_mentions(place: &Place, local: usize) -> bool {
        place.local == local
            || place.projections.iter().any(|p| matches!(p, Projection::Index(i) if *i == local))
    }

    fn operand_mentions(op: &Operand, local: usize) -> bool {
        match op {
            Operand::Copy(p) | Operand::Move(p) => place_mentions(p, local),
            Operand::Constant(_) => false,
            // A symbolic or unsupported operand may name anything.
            _ => true,
        }
    }

    fn rvalue_mentions(rv: &Rvalue, local: usize) -> bool {
        match rv {
            Rvalue::Use(op)
            | Rvalue::UnaryOp(_, op)
            | Rvalue::Cast(op, _)
            | Rvalue::Repeat(op, _) => operand_mentions(op, local),
            Rvalue::BinaryOp(_, a, b)
            | Rvalue::CheckedBinaryOp(_, a, b)
            | Rvalue::UncheckedBinaryOp(_, a, b) => {
                operand_mentions(a, local) || operand_mentions(b, local)
            }
            Rvalue::Ref { place, .. }
            | Rvalue::AddressOf(_, place)
            | Rvalue::Discriminant(place)
            | Rvalue::Len(place)
            | Rvalue::CopyForDeref(place) => place_mentions(place, local),
            Rvalue::Aggregate(_, ops) => ops.iter().any(|op| operand_mentions(op, local)),
            Rvalue::PtrOffset { ptr, count } => {
                operand_mentions(ptr, local) || operand_mentions(count, local)
            }
            Rvalue::Unsupported { operands, .. } => {
                operands.iter().any(|op| operand_mentions(op, local))
            }
            // `#[non_exhaustive]`: an rvalue this walk does not know may read anything.
            _ => true,
        }
    }

    /// A USE of `local` — anything that reads it or stores through it. Storage
    /// markers are not uses; an unknown statement is (fail closed).
    fn stmt_mentions(stmt: &Statement, local: usize) -> bool {
        match stmt {
            Statement::Assign { place, rvalue, .. } => {
                place_mentions(place, local) || rvalue_mentions(rvalue, local)
            }
            Statement::SetDiscriminant { place, .. }
            | Statement::Deinit { place }
            | Statement::Retag { place }
            | Statement::PlaceMention(place) => place_mentions(place, local),
            Statement::Intrinsic { args, .. } => args.iter().any(|op| operand_mentions(op, local)),
            Statement::CopyNonOverlapping { src, dst, count, .. } => {
                operand_mentions(src, local)
                    || operand_mentions(dst, local)
                    || operand_mentions(count, local)
            }
            Statement::Unsupported { operands, .. } => {
                operands.iter().any(|op| operand_mentions(op, local))
            }
            Statement::StorageLive(_)
            | Statement::StorageDead(_)
            | Statement::Coverage
            | Statement::ConstEvalCounter
            | Statement::Nop => false,
            _ => true,
        }
    }

    /// The uses a terminator makes BEFORE its effect (its operands).
    fn terminator_mentions_before(term: &Terminator, local: usize) -> bool {
        match term {
            Terminator::SwitchInt { discr, .. } => operand_mentions(discr, local),
            Terminator::Call { args, .. } | Terminator::TailCall { args, .. } => {
                args.iter().any(|op| operand_mentions(op, local))
            }
            Terminator::Assert { cond, .. } => operand_mentions(cond, local),
            Terminator::Drop { place, .. } => place_mentions(place, local),
            Terminator::Goto(_)
            | Terminator::Return
            | Terminator::Unreachable
            | Terminator::Resume => false,
            // `Opaque` and any unknown terminator: fail closed.
            _ => true,
        }
    }

    /// The uses a terminator makes AFTER its effect: a call's destination store.
    fn terminator_mentions_after(term: &Terminator, local: usize) -> bool {
        match term {
            Terminator::Call { dest, .. } => place_mentions(dest, local),
            _ => false,
        }
    }

    /// True iff SOME borrow anywhere in the body aliases the storage AT `guard` (a
    /// prefix or sibling place, never one strictly inside it). Through such an alias
    /// the slot can be written at a place this walk never names, by any store through
    /// an opaque pointer and by any callee.
    ///
    /// Trust: 2026-09-17 (round A12, pass 2) — a SHARED `&guard` counts too. It used
    /// to be filtered out (`Rvalue::Ref { mutable: true, .. }` only) on the reasoning
    /// `trust_types::Statement::escapes_local` states: a shared reference cannot
    /// mutate, and `invalid_reference_casting` rejects the obvious cast. That
    /// reasoning is right about what a WELL-DEFINED program may do and wrong about
    /// what this walk may ASSUME, and the difference is a name that denotes a
    /// different cell than the store landed in:
    ///
    /// ```ignore (illustrative)
    /// #[inline(never)] fn launder(p: *const usize) -> *mut usize { p as *mut usize }
    /// let mut j = 0usize;
    /// let pj = launder(&j);       // shared borrow, laundered through a call
    /// let r  = &mut s[j];         // referent (*s)[j], guard j
    /// unsafe { *pj = k };         // rebinds j — DISMISSED before this change
    /// *r = 3;                     // spelled s*[j] with j == k; lands in s[0]
    /// if j >= s.len() { return 0; }
    /// t[s[j] as usize]            // PROVED; panics at runtime
    /// ```
    ///
    /// The write through `pj` is UB under Stacked/Tree Borrows, so this is hardening
    /// and not a live exploit — the same row is byte-identical on the sealed pristine
    /// driver, so it predates the campaign. It is fixed anyway because the fold's
    /// soundness argument must not rest on the ABSENCE of UB in the program under
    /// verification: this walk decides a NAME, and a name minted under an assumption
    /// the verifier does not itself check is the campaign's own failure mode.
    /// `local_storage_borrowed_anywhere` two helpers below already draws the line
    /// here; the two are adjacent and no longer disagree.
    ///
    /// # Flow-insensitive, deliberately
    ///
    /// Trust: 2026-09-17 (round A13, pass 2) — this is a BODY-GLOBAL scan: a borrow
    /// taken on a path that cannot reach the walked region, or taken strictly AFTER
    /// every use of the pointer local, counts exactly like one taken before it. That
    /// is an over-approximation in the safe direction (it can only taint), and it is
    /// load-bearing for cost: the walk asks this question once per guard per
    /// statement class and a region-bounded scan would have to be recomputed per
    /// walk state. It is also the reason a correct program can be refused — the
    /// round-A13 pass-2 review measured exactly that on `v7_shared_param_borrow_
    /// after_ctl`, whose only borrow of the guard executes after the refuted assert.
    /// Narrowing it to the walked region is the precision move if that class recurs;
    /// the capability split below is the one this round made instead.
    ///
    /// Trust: 2026-09-30 — this scan is now the REFERENCE definition; the walk asks
    /// [`FoldIndex::slot_aliased`], which answers the same question from a per-function
    /// index (`index_agrees_with_the_scans`).
    #[cfg(test)]
    pub(crate) fn slot_is_aliased_anywhere(func: &VerifiableFunction, guard: &Place) -> bool {
        slot_alias_scan(func, guard, AliasKind::Any)
    }

    /// The alias question as a CAPABILITY question, for the one caller that asks what
    /// an opaque CALLEE can do rather than what a store this body spells can do.
    ///
    /// Trust: 2026-09-17 (round A13, pass 2) — `slot_is_aliased_anywhere` counts a
    /// borrow of any mutability, and routing `callee_may_rebind` through it refused
    /// the fold for every `Call`/`Drop` in the region of a body that takes a SHARED
    /// `&guard` anywhere at all. Measured on three correct, panic-free, entirely safe
    /// programs (`v2_shared_param_call_ctl`, `v6_shared_param_drop_ctl`,
    /// `v7_shared_param_borrow_after_ctl`), each refuted with a counterexample no
    /// execution realizes and each PROVED by both the sealed driver and the A5-era
    /// stage1. A callee holding a `&T` of the guard's own storage cannot rebind it.
    ///
    /// The line is `trust_types::Statement::escapes_local`'s, to the letter:
    /// `Rvalue::Ref { mutable: true }`, plus `Rvalue::AddressOf` of EITHER raw
    /// mutability. The raw half is not an oversight — `&raw const g` laundered
    /// through a callee and written is the `u1_shared_cast_bug` /
    /// `j1_param_shared_launder_bug` shape, and it stays closed here whether or not
    /// the body itself spells the store. Only the shared REFERENCE half is dropped,
    /// and only for this question: a store this body SPELLS but cannot attribute is
    /// decided elsewhere, with no capability argument available for it.
    ///
    /// Trust: 2026-09-18 (reviewer) — that "elsewhere" MOVED and this paragraph used
    /// to name the old one ("`written_place_rebinds` keeps asking the wide
    /// `guard_reachable_by_pointer`"). It no longer does: the unattributable-store arm
    /// asks [`unattributable_store_rebinds`], which conjoins the same alias question
    /// with a forward provenance taint. `v3_shared_param_cast_store_bug`
    /// (`launder(&j)` then `*pj = k`) is therefore closed by the TAINT — the shared
    /// `&_3` is a seed, followed through `&raw const (*_13)` and through `launder`'s
    /// destination — not by the width of this predicate's sibling. Measured both ways
    /// in `tests/referent_fold_provenance.rs`.
    ///
    /// Trust: 2026-09-30 — the REFERENCE definition, like its sibling above.
    #[cfg(test)]
    pub(crate) fn slot_is_writably_aliased_anywhere(
        func: &VerifiableFunction,
        guard: &Place,
    ) -> bool {
        slot_alias_scan(func, guard, AliasKind::WriteCapable)
    }

    /// Which borrows an alias scan counts.
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum AliasKind {
        /// Every borrow of the slot: `&`, `&mut`, `&raw const`, `&raw mut`.
        Any,
        /// Only a borrow through which a write is a DEFINED operation: `&mut`, and a
        /// raw borrow of either mutability (`Statement::escapes_local`'s line, which
        /// deliberately does not credit `*const` with read-only-ness).
        WriteCapable,
    }

    #[cfg(test)]
    fn slot_alias_scan(func: &VerifiableFunction, guard: &Place, kind: AliasKind) -> bool {
        func.body.blocks.iter().any(|block| {
            block.stmts.iter().any(|stmt| {
                let Statement::Assign { rvalue, .. } = stmt else { return false };
                let borrowed = match rvalue {
                    Rvalue::Ref { mutable, place } => {
                        if kind == AliasKind::WriteCapable && !*mutable {
                            return false;
                        }
                        place
                    }
                    Rvalue::AddressOf(_, place) => place,
                    _ => return false,
                };
                borrowed.local == guard.local
                    && crate::local_defs::written_projections_rebind_path(
                        &borrowed.projections,
                        &guard.projections,
                    )
            })
        })
    }

    /// True iff a write this walk cannot attribute to a place — a store through an
    /// opaque pointer, a callee's side effect — may rebind `guard`: a slot behind a
    /// `Deref` lives in memory any pointer may reach; a local (or a field of one)
    /// only through an alias of it.
    fn guard_reachable_by_pointer(index: &FoldIndex, guard: &Place) -> bool {
        guard.projections.iter().any(|p| matches!(p, Projection::Deref))
            || index.slot_aliased(guard, AliasKind::Any)
    }

    /// Trust: 2026-09-18 — THE PROVENANCE QUESTION, for the ONE caller that holds the
    /// store's own pointer local: `written_place_rebinds`' unattributable-store arm.
    ///
    /// [`guard_reachable_by_pointer`] answers a body-global question — "does a borrow
    /// of this guard exist ANYWHERE" — and the arm below asks it about a store whose
    /// pointer it could not resolve. The two have no connection to each other, so any
    /// borrow of a guard plus any unresolvable store anywhere in the body refused the
    /// fold; a `vec![..]` in scope was enough, because its desugar stores through a
    /// raw pointer this seam cannot attribute. See the `docs/KNOWN_HAZARDS.md` entry
    /// "The referent fold refuses a correct program when a shared borrow meets an
    /// unattributable store (2026-09-18)" for the measured false refutations
    /// (`v6_shared_param_drop_ctl` at `-O0`, and the `r1_shared_plus_vec_ctl` shape the
    /// entry quotes).
    ///
    /// This predicate keeps the same two disjuncts and CONJOINS the alias half with
    /// provenance: could the value in `ptr` — the local the store dereferences — be
    /// derived from one of those borrows? It is therefore strictly narrower than
    /// `guard_reachable_by_pointer` (every `true` here is a `true` there), so it can
    /// only ever ADMIT a fold the old arm refused, never refuse one it admitted. READ
    /// THAT IN THE RIGHT DIRECTION: "strictly narrower" is the direction that mints
    /// proofs, so each admission it adds needs its own argument. [`slot_taint`]'s
    /// "THE FORGED-POINTER CHANNEL, AND WHAT IS STILL NOT COVERED" block names the
    /// shapes where that argument rests on the program being free of UB, where the
    /// old arm needed none. The sharpest of them — an address forged from an integer
    /// — is CLOSED there rather than accepted; the two that remain are named.
    ///
    /// The `Deref` disjunct stays UNCONDITIONAL. A guard whose own place sits behind a
    /// `Deref` lives in memory reached through a pointer, so an unattributable store
    /// can land on it with no syntactic borrow of it in this body at all, and no
    /// provenance argument over this body's locals is available for it.
    ///
    /// CAPABILITY IS NOT THE DISCRIMINATOR AND THIS DOES NOT MAKE IT ONE. Narrowing
    /// this arm to a write-capable alias scan was tried in round A13 and reverted
    /// under measurement: in `v3_shared_param_cast_store_bug`
    /// (`let pj = launder(&j); *pj = k;`) the unresolvable pointer IS the laundered
    /// SHARED borrow, and admitting it minted a kernel-certified false proof on a
    /// program that panics. The taint below counts that borrow exactly like a `&mut`
    /// one — `slot_taint`'s seeds are `slot_is_aliased_anywhere`'s borrows, of every
    /// mutability — and follows it through the `launder` call, so `v3` stays refused
    /// on provenance rather than on capability.
    fn unattributable_store_rebinds(taint: &TaintCache<'_>, ptr: usize, guard: &Place) -> bool {
        if guard.projections.iter().any(|p| matches!(p, Projection::Deref)) {
            return true;
        }
        // The cheap half first, and it is also the taint's own precondition: with no
        // borrow of the slot there is no seed, so the walk would answer `false` after
        // scanning the whole body. Bodies with no borrow of the guard — the
        // `r3b_vec_no_borrow_ctl` shape — never pay for the walk at all.
        if !taint.index.slot_aliased(guard, AliasKind::Any) {
            return false;
        }
        let t = taint.get(guard);
        t.escaped || t.tainted.contains(&ptr)
    }

    /// Which of this body's locals may hold a pointer derived from a borrow of one
    /// guard's slot, and whether that derivation left the set of locals this walk can
    /// name at all.
    ///
    /// `escaped` is the fail-closed sink and it subsumes `tainted`: once it is set,
    /// [`unattributable_store_rebinds`] answers `true` for EVERY store, which is
    /// byte-for-byte what the pre-2026-09-18 arm answered for such a body. So every
    /// DERIVATION CHANNEL this walk cannot follow costs precision and never soundness.
    ///
    /// That is a claim about channels, and it is NOT the same as "this arm is as safe
    /// as the old one" — see the "THE FORGED-POINTER CHANNEL, AND WHAT IS STILL NOT
    /// COVERED" block on [`slot_taint`] for the cases where the new answer is weaker
    /// than the old, and for which of them is closed.
    struct SlotTaint {
        tainted: FxHashSet<usize>,
        escaped: bool,
    }

    /// The state one stability walk shares across its precise run, its collapsed
    /// fallback and its borrow-time-constant fixpoints: the function's [`FoldIndex`]
    /// and the nested referent resolutions this walk has already made.
    ///
    /// `slot_taint` per guard is computed on first demand and — since 2026-09-30 —
    /// kept in the [`FoldIndex`], i.e. once per FUNCTION rather than once per walk: it
    /// is a pure function of `func` and the guard.
    ///
    /// COST. The taint is a monotone fixpoint over LOCALS: a round is one linear
    /// pass over the body, a round that changes nothing stops it, and a round that
    /// changes something adds at least one local to `tainted` or sets `escaped`. So it
    /// runs at most `locals + 2` rounds, i.e. `O(locals * body)` once per `(guard)`,
    /// and the cache makes that once per function rather than once per statement —
    /// which is the rate `written_place_rebinds` is asked at. A body that somehow
    /// exceeds the round budget answers `escaped` (refuse), not a wrong admission.
    ///
    /// Keyed by the guard PLACE, not its local: two guards can share a root
    /// (`(*_1).0` and `(*_1).1`) and their alias seeds differ.
    ///
    /// `resolved` is the walk's own cache of `resolve_referent(func, l, NESTED_FUEL)`
    /// for each pointer local `l` a store in the region goes through. It is exact:
    /// the only state that answer depends on beyond `func` and `l` is the set of
    /// walks in progress (`FRAMES`), and that set is the same at every point of one
    /// walk — this walk's own mark is in it for the walk's whole extent, and every
    /// nested walk removes the mark it added before it returns. (The in-progress
    /// questions the cached answer asked were recorded in this walk's frame when it
    /// was computed, so a reuse needs no second record.) Before 2026-09-30 the nested
    /// resolution ran once per visited
    /// state, per guard, per such store — a full nested stability walk each time. The
    /// ambient budget is the other input: an answer cached before a trip is the
    /// walk's exact answer, one cached after it is a refusal, and both are sound.
    ///
    /// `outcomes` is the same per-walk cache of [`outcomes`] over that resolution:
    /// every value it can take whichever way its own walks go, computed without
    /// running one. It is exact for the same reason `resolved` is.
    struct TaintCache<'f> {
        func: &'f VerifiableFunction,
        index: Rc<FoldIndex>,
        resolved: RefCell<FxHashMap<usize, Option<Place>>>,
        outcomes: RefCell<FxHashMap<usize, Option<ResolutionOutcomes>>>,
    }

    /// Every value one pointer's resolution can take (see [`outcomes`]).
    type ResolutionOutcomes = Rc<[Option<Place>]>;

    impl<'f> TaintCache<'f> {
        /// A walk-free cache over the function's index — the unit tests' entry point.
        #[cfg(test)]
        fn new(func: &'f VerifiableFunction) -> Self {
            Self::with_index(func, fold_index(func))
        }

        fn with_index(func: &'f VerifiableFunction, index: Rc<FoldIndex>) -> Self {
            Self { func, index, resolved: RefCell::default(), outcomes: RefCell::default() }
        }

        /// Every value `resolve(local)` can take (see [`outcomes`]), once per walk;
        /// `None` when there are too many to enumerate or the ambient budget tripped
        /// while they were enumerated (a trip truncates runs, so the set is not
        /// known to hold the real answer).
        fn outcomes(&self, local: usize) -> Option<ResolutionOutcomes> {
            let hit = self.outcomes.borrow().get(&local).cloned();
            if let Some(hit) = hit {
                return hit;
            }
            let computed = outcomes(|| super::resolve_referent(self.func, local, NESTED_FUEL))
                .filter(|_| !trust_types::verify_budget::exhausted_readonly())
                .map(ResolutionOutcomes::from);
            self.outcomes.borrow_mut().insert(local, computed.clone());
            computed
        }

        fn get(&self, guard: &Place) -> Rc<SlotTaint> {
            self.index.taint(self.func, guard)
        }

        /// `resolve_referent(func, local, NESTED_FUEL)`, once per walk. The borrow is
        /// released before the resolution runs: it re-enters the referent fold.
        fn resolve(&self, local: usize) -> Option<Place> {
            let hit = self.resolved.borrow().get(&local).cloned();
            if let Some(hit) = hit {
                return hit;
            }
            crate::fn_memo::count_fold_nested_resolutions();
            let computed = super::resolve_referent(self.func, local, NESTED_FUEL);
            // The test-only reference re-resolves at every store, as before 2026-09-30.
            if shortcuts_enabled() {
                self.resolved.borrow_mut().insert(local, computed.clone());
            }
            computed
        }
    }

    /// True iff `borrowed` is a borrow of the storage AT `guard` — the same line
    /// `slot_alias_scan` draws, so the taint's SEEDS are exactly the borrows
    /// [`slot_is_aliased_anywhere`] counts: the guard itself, a prefix of it, and a
    /// sibling. A borrow strictly INSIDE the guard — `&(*g)` or `&g.f` for the guard
    /// `g` — addresses a pointee, an element or a field that `g` REACHES, never `g`'s
    /// own bytes, so it is not a seed.
    fn borrow_aliases_slot(borrowed: &Place, guard: &Place) -> bool {
        borrowed.local == guard.local
            && crate::local_defs::written_projections_rebind_path(
                &borrowed.projections,
                &guard.projections,
            )
    }

    /// A read of `place` reads a tainted value iff its ROOT local is tainted (the
    /// bytes read are then inside, or reached through, a tainted pointer) or one of
    /// its `Index` locals is (a tainted offset applied to any base).
    fn place_reads_tainted(place: &Place, tainted: &FxHashSet<usize>) -> bool {
        tainted.contains(&place.local)
            || place
                .projections
                .iter()
                .any(|p| matches!(p, Projection::Index(l) if tainted.contains(l)))
    }

    fn operand_is_tainted(op: &Operand, tainted: &FxHashSet<usize>) -> bool {
        match op {
            Operand::Copy(p) | Operand::Move(p) => place_reads_tainted(p, tainted),
            Operand::Constant(_) => false,
            // A symbolic or unsupported operand may name anything (fail closed), the
            // same line `operand_mentions` above draws.
            _ => true,
        }
    }

    /// True iff the VALUE `rv` produces may be derived from a borrow of `guard`'s
    /// slot. Every rvalue class this crate does not model answers `true`: an
    /// untainted answer is what PERMITS the fold, so the unknown direction is taint.
    fn rvalue_is_tainted(rv: &Rvalue, guard: &Place, tainted: &FxHashSet<usize>) -> bool {
        match rv {
            // The SEED: a borrow of the guard's own storage. Also a re-derivation of
            // an already-tainted pointer's address (`&raw const (*p)`, the shape
            // `v3_shared_param_cast_store_bug` reaches `launder` through), and a
            // borrow of a tainted local's own bytes — a pointer to a tainted pointer,
            // which a later `Deref` read turns back into one.
            Rvalue::Ref { place, .. } | Rvalue::AddressOf(_, place) => {
                borrow_aliases_slot(place, guard) || place_reads_tainted(place, tainted)
            }
            Rvalue::Use(op)
            | Rvalue::UnaryOp(_, op)
            | Rvalue::Cast(op, _)
            | Rvalue::Repeat(op, _) => operand_is_tainted(op, tainted),
            Rvalue::BinaryOp(_, a, b)
            | Rvalue::CheckedBinaryOp(_, a, b)
            | Rvalue::UncheckedBinaryOp(_, a, b) => {
                operand_is_tainted(a, tainted) || operand_is_tainted(b, tainted)
            }
            Rvalue::PtrOffset { ptr, count } => {
                operand_is_tainted(ptr, tainted) || operand_is_tainted(count, tainted)
            }
            Rvalue::Discriminant(place) | Rvalue::Len(place) | Rvalue::CopyForDeref(place) => {
                place_reads_tainted(place, tainted)
            }
            Rvalue::Aggregate(_, ops) => ops.iter().any(|op| operand_is_tainted(op, tainted)),
            // `Unsupported`, and `#[non_exhaustive]`: an rvalue this walk cannot
            // classify may carry the borrow through.
            _ => true,
        }
    }

    /// Fuel for one [`ty_carries_pointer_provenance`] walk. The types this question
    /// is actually asked about are shallow — `NonNull<MaybeUninit<[u8; 3]>>`, the
    /// deepest one measured, finds its pointer two nodes in — but `Ty::Adt` nests
    /// without a declared bound and `Ty::Datatype` admits a by-name recursive
    /// reference, so the walk is metered rather than trusted. Exhausting the meter
    /// answers `unknown`, which each of the two call sites resolves in ITS OWN
    /// fail-closed direction — see [`ty_carries_pointer_provenance`]'s `unknown`
    /// parameter. The bound is real but not tight against the extractor's own
    /// `MAX_TYPE_LOWERING_PRODUCED_NODES` (8_000), which is why the unknown answer
    /// has to be directional rather than a constant `false`.
    const PROVENANCE_TY_FUEL: u32 = 4096;

    /// True iff a value of type `ty` can carry a POINTER's provenance: it is an
    /// address, or it structurally contains one.
    ///
    /// Trust: 2026-09-18 (reviewer round 2) — this is the discriminator that lets
    /// [`cast_forges_pointer_provenance`] separate the two casts below, and the
    /// separation is by SOURCE TYPE because that is where the two differ:
    ///
    ///  * `_28 = copy ((_16.0: Unique<…>).0: NonNull<…>) as *const MaybeUninit<[u8;3]>`
    ///    — the `vec![..]` desugar in `v6_shared_param_drop_ctl`. The cast's input is
    ///    already an address; the result's provenance is the input's, and the forward
    ///    taint below decides whether THAT is derived from a borrow of the guard.
    ///  * `_5 = copy _3 as *mut usize` where `_3: usize` — an address FORGED from
    ///    integer bits. It is constrained by nothing the taint walk can see, so it
    ///    may name the guard's own slot with no borrow of the guard anywhere.
    ///
    /// IT IS DELIBERATELY STRUCTURAL, AND MEASUREMENT IS WHY. The obvious spelling —
    /// "the source `Ty` is `RawPtr` or `Ref`" — is WRONG here and was measured wrong:
    /// `v6`'s source place `_16.0.0` resolves to `Ty::Adt { name:
    /// "core::ptr::non_null::NonNull", .. }`, a pointer NEWTYPE, at both `-O0` and
    /// `-O1`. Requiring the outermost spelling to be a pointer re-refuses the row the
    /// provenance narrowing exists to recover. So the question is asked of the whole
    /// type tree: `Box`, `Unique`, `NonNull` and every other wrapper answers `true`
    /// through its field.
    ///
    /// THE UNKNOWN ANSWER IS DIRECTIONAL, AND IT HAS TO BE. `unknown` is what this
    /// walk returns for a type it cannot classify — `Ty::Unsupported`, a variant added
    /// after this line through the `#[non_exhaustive]` wildcard, and an exhausted
    /// [`PROVENANCE_TY_FUEL`]. The two call sites in
    /// [`cast_forges_pointer_provenance`] need OPPOSITE answers there, because "does
    /// not carry a pointer" is the refusing direction on the SOURCE side and the
    /// ADMITTING one on the TARGET side:
    ///
    ///  * SOURCE — `unknown = false`. A source that cannot be shown to be an address
    ///    is treated as an integer, so the cast is FORGING and the fold is refused.
    ///  * TARGET — `unknown = true`. A target that cannot be shown NOT to be an
    ///    address is treated as one, so the cast is still examined.
    ///
    /// Trust: 2026-09-18 (adversarial round) — a single `false` for both was the
    /// shipped form, and it was MEASURED wrong in the false-PROVE direction: with the
    /// cast `_5 = _3 as <Unsupported>` and the store `(*_5) = _2`,
    /// `written_place_rebinds` answered ADMIT on a body whose only pointer was forged
    /// from a `usize`, while the accompanying doc on `PROVENANCE_TY_FUEL` claimed
    /// exhaustion was "the escaping, i.e. refusing, direction". `Ty::Unsupported` is
    /// reachable as a lowered type — `ty_convert`'s produced-node-budget degrade mints
    /// it — and the extractor's budget (8_000 nodes) is larger than this walk's fuel,
    /// so neither escape is hypothetical. No fixture in the 626-file corpus has a cast
    /// target outside `{Int, RawPtr, Ref}`, so the correction is inert on it.
    ///
    /// Every SCALAR is spelled out below rather than left to the wildcard, exactly so
    /// that the wildcard means "this walk does not know" and nothing else.
    fn ty_carries_pointer_provenance(ty: &Ty, fuel: &mut u32, unknown: bool) -> bool {
        if *fuel == 0 {
            return unknown;
        }
        *fuel -= 1;
        match ty {
            // A value of one of these types IS an address.
            Ty::RawPtr { .. }
            | Ty::Ref { .. }
            | Ty::FnPtr { .. }
            | Ty::FnDef { .. }
            | Ty::Dynamic { .. } => true,
            Ty::Adt { fields, variants, .. } => {
                fields.iter().any(|(_, t)| ty_carries_pointer_provenance(t, fuel, unknown))
                    || variants.iter().any(|v| {
                        v.fields
                            .iter()
                            .any(|(_, t)| ty_carries_pointer_provenance(t, fuel, unknown))
                    })
            }
            Ty::Datatype { variants, .. } => variants.iter().any(|(_, fs)| {
                fs.iter().any(|(_, t)| ty_carries_pointer_provenance(t, fuel, unknown))
            }),
            Ty::Tuple(elems) => {
                elems.iter().any(|t| ty_carries_pointer_provenance(t, fuel, unknown))
            }
            Ty::Array { elem, .. }
            | Ty::Slice { elem }
            | Ty::Seq { elem, .. }
            | Ty::SymArray { elem, .. } => ty_carries_pointer_provenance(elem, fuel, unknown),
            Ty::Closure { upvars, .. } | Ty::Coroutine { upvars, .. } => {
                upvars.iter().any(|t| ty_carries_pointer_provenance(t, fuel, unknown))
            }
            // Known scalars: a value of one of these is NOT an address, in either
            // direction. `Ty::PtrSizedInt` is `usize` — exactly the witness's source.
            Ty::Bool
            | Ty::Int { .. }
            | Ty::PtrSizedInt { .. }
            | Ty::Char
            | Ty::Float { .. }
            | Ty::Str
            | Ty::Bv(_)
            | Ty::Unit
            | Ty::Never => false,
            // `Ty::Unsupported`, and any variant added after this line.
            _ => unknown,
        }
    }

    /// True iff `rv` MINTS an address out of something that is not one — the
    /// integer-to-pointer channel, plus every spelling this crate lowers to the same
    /// `Rvalue::Cast`.
    ///
    /// Trust: 2026-09-18 (reviewer round 2) — `Rvalue::Cast(operand, to_ty)` carries
    /// NO `CastKind` in this crate's model, so `IntToPtr`, a `transmute::<usize,
    /// *mut T>`, and an ordinary `PtrToPtr` all arrive here as the same variant and
    /// are told apart only by their two types. That is the right granularity anyway:
    /// what matters is not the spelling the user wrote but whether the resulting
    /// address inherited a provenance the forward taint can follow. The target side
    /// is asked structurally too, so `transmute::<usize, NonNull<T>>` — an address
    /// forged into a pointer NEWTYPE — is caught by the same line as the bare
    /// `usize as *mut T`.
    fn cast_forges_pointer_provenance(func: &VerifiableFunction, rv: &Rvalue) -> bool {
        let Rvalue::Cast(op, to_ty) = rv else {
            return false;
        };
        let mut fuel = PROVENANCE_TY_FUEL;
        // TARGET: `unknown = true`. A target this walk cannot classify may still be an
        // address, and answering `false` here ADMITS the cast — the false-PROVE
        // direction. See `ty_carries_pointer_provenance`'s `unknown` parameter.
        if !ty_carries_pointer_provenance(to_ty, &mut fuel, true) {
            return false;
        }
        let mut fuel = PROVENANCE_TY_FUEL;
        match crate::operand_ty_cow(func, op) {
            // SOURCE: `unknown = false`. A source this walk cannot classify cannot be
            // SHOWN to have carried an address, so the cast is forging.
            Some(src) => !ty_carries_pointer_provenance(src.as_ref(), &mut fuel, false),
            // `operand_ty` is an `Option`, and `None` means this walk cannot say what
            // the cast consumed. An unknown source cannot be SHOWN to have carried an
            // address, so it is treated exactly like an integer one: fail closed.
            None => true,
        }
    }

    fn copy_count_may_be_nonzero(count: &Operand) -> bool {
        !matches!(count, Operand::Constant(ConstValue::Int(0) | ConstValue::Uint(0, _)))
    }

    fn direct_address_referent_before(
        func: &VerifiableFunction,
        ptr: &Place,
        limit_b: usize,
        limit_k: usize,
        fuel: u32,
    ) -> Option<Place> {
        if fuel == 0 || !ptr.projections.is_empty() {
            return None;
        }
        let mut found = None;
        'blocks: for (b, block) in func.body.blocks.iter().enumerate() {
            for (k, stmt) in block.stmts.iter().enumerate() {
                if b > limit_b || (b == limit_b && k >= limit_k) {
                    break 'blocks;
                }
                match stmt {
                    Statement::Assign { place, rvalue, .. }
                        if place.local == ptr.local && place.projections.is_empty() =>
                    {
                        if found.replace(rvalue).is_some() {
                            return None;
                        }
                    }
                    _ => match stmt.local_write(ptr.local) {
                        LocalWrite::Untouched => {}
                        LocalWrite::WholeNamed(_)
                        | LocalWrite::WholeOpaque
                        | LocalWrite::Partial
                        | LocalWrite::Escape
                        | LocalWrite::Unlocatable => return None,
                    },
                }
            }
        }
        match found? {
            Rvalue::Ref { place, .. } | Rvalue::AddressOf(_, place) => Some(place.clone()),
            Rvalue::Use(Operand::Copy(next) | Operand::Move(next)) => {
                direct_address_referent_before(func, next, limit_b, limit_k, fuel - 1)
            }
            _ => None,
        }
    }

    fn copy_destination_storage_ty<'a>(
        func: &'a VerifiableFunction,
        dst: &Operand,
        limit_b: usize,
        limit_k: usize,
    ) -> Option<Cow<'a, Ty>> {
        let (Operand::Copy(place) | Operand::Move(place)) = dst else {
            return None;
        };
        let referent = direct_address_referent_before(func, place, limit_b, limit_k, NESTED_FUEL)?;
        crate::place_ty_cow(func, &referent)
    }

    /// True iff a `CopyNonOverlapping` may write non-pointer bytes into storage whose
    /// declared value may carry pointer provenance.
    fn copy_nonoverlapping_forges_pointer_provenance(
        func: &VerifiableFunction,
        dst: &Operand,
        count: &Operand,
        elem_ty: &Ty,
        limit_b: usize,
        limit_k: usize,
    ) -> bool {
        if !copy_count_may_be_nonzero(count) {
            return false;
        }

        let mut fuel = PROVENANCE_TY_FUEL;
        if ty_carries_pointer_provenance(elem_ty, &mut fuel, false) {
            return false;
        }

        match copy_destination_storage_ty(func, dst, limit_b, limit_k) {
            Some(dst_ty) => {
                let mut fuel = PROVENANCE_TY_FUEL;
                ty_carries_pointer_provenance(dst_ty.as_ref(), &mut fuel, true)
            }
            None => true,
        }
    }

    /// Does this body mint an address out of something that is not one, ANYWHERE?
    ///
    /// Hoisted out of [`slot_taint`]'s fixpoint because it depends on no taint state:
    /// the answer is a property of the body alone, so it is computed once per walk
    /// instead of once per round. It seeds `escaped`, which is global — the same
    /// coarseness every other unmodelled channel in this walk has.
    fn body_forges_a_pointer(func: &VerifiableFunction) -> bool {
        func.body.blocks.iter().enumerate().any(|(b, block)| {
            block.stmts.iter().enumerate().any(|(k, stmt)| match stmt {
                Statement::Assign { rvalue, .. } => cast_forges_pointer_provenance(func, rvalue),
                Statement::CopyNonOverlapping { dst, count, elem_ty, .. } => {
                    copy_nonoverlapping_forges_pointer_provenance(func, dst, count, elem_ty, b, k)
                }
                _ => false,
            })
        })
    }

    /// The fail-closed forward taint of one guard's borrows over this body's locals.
    ///
    /// The invariant it maintains is: if the value of local `l` at any point is a
    /// pointer that DERIVES, through this body's own rvalues, from a borrow of
    /// `guard`'s storage, then `l ∈ tainted` or `escaped`.
    ///
    /// # THE FORGED-POINTER CHANNEL, AND WHAT IS STILL NOT COVERED
    ///
    /// Trust: 2026-09-18 (reviewer round 1, MEASURED). The invariant above is a
    /// PROVENANCE invariant, not an aliasing one, and the two differ on a pointer that
    /// addresses the guard with no derivation chain in this body. The sharpest
    /// instance was an integer cast to a pointer, and it was a real hole in the
    /// FALSE-PROVE direction:
    ///
    /// ```ignore (illustrative)
    /// let _q = &j;                       // any borrow of the guard: alias gate open
    /// let p = 0x7fff_1234usize as *mut usize;
    /// unsafe { *p = k };                 // unattributable store, taint-clean
    /// ```
    ///
    /// On that body `guard_reachable_by_pointer` answered `true` — REFUSE — and
    /// [`unattributable_store_rebinds`] answered `false` — ADMIT, so the fold stood
    /// and the referent kept its name across a store that may land in `j`'s slot.
    ///
    /// Trust: 2026-09-18 (reviewer round 2) — THAT CHANNEL IS NOW CLOSED, not
    /// accepted. [`body_forges_a_pointer`] seeds `escaped` for any body that mints an
    /// address out of a value that is not one, so the witness above is refused again,
    /// through the same sink every other unmodelled channel uses. It is pinned by
    /// `forged_pointer_channel` below, which runs both directions of the
    /// discriminator on hand-built MIR.
    ///
    /// Trust: 2026-09-23 — the same seed now covers the narrower
    /// `CopyNonOverlapping` byte-forge channel: a maybe-nonzero copy whose
    /// `elem_ty` cannot be shown to carry pointer provenance, into storage whose
    /// declared value may carry pointer provenance. This is intentionally not the
    /// statement-level taint arm: `src`/`dst` are pointer operands, and in the
    /// forged case neither pointer is derived from the guard. The destination storage
    /// is recognized only through direct `&/&raw` carriers; anything more complex
    /// stays in the fail-closed `unknown destination may carry provenance` bucket
    /// rather than calling back into the full referent-fold resolver from inside this
    /// body-global seed.
    ///
    /// The discriminator is the cast's SOURCE TYPE, not "the source is
    /// unattributable": `v6_shared_param_drop_ctl`'s own `_28` is a cast of a
    /// `NonNull` read out of a `Box` this body never borrowed the guard into, so a
    /// blanket "a pointer from an unattributable source ⇒ escaped" was measured to
    /// undo the fix outright. See [`ty_carries_pointer_provenance`] for why the test
    /// is structural — `NonNull` is `Ty::Adt`, not `Ty::RawPtr`, and the naive
    /// spelling re-refuses `v6`.
    ///
    /// WHAT IS STILL NOT COVERED. Two narrower shapes remain, both of which reach the
    /// guard with no derivation chain and neither of which this walk sees:
    ///
    ///  * an address forged FIELDWISE rather than by a cast — `NonNull { pointer:
    ///    0x7fff_1234 as *const _ }` built with an `Rvalue::Aggregate` and read back
    ///    through a `Field` projection. The inner `as` is itself a forging cast and is
    ///    caught, so the shape only escapes this net if the integer reaches the field
    ///    without a `Cast` at all;
    ///  * an address handed back by a CALLEE that received no tainted argument, or
    ///    `offset` walked out of a neighbouring object.
    ///
    /// Both are UB in Rust and this walk's answer for them still depends on that,
    /// which is the residual against the doctrine [`slot_is_aliased_anywhere`] states
    /// — "the fold's soundness argument must not rest on the ABSENCE of UB in the
    /// program under verification". Closing them needs a real provenance model (a
    /// foreign-provenance pointer cannot legally address a local of this frame), not a
    /// wider syntactic scan.
    ///
    /// It is FLOW-INSENSITIVE, like every other scan in this module — a borrow taken
    /// on a path that cannot reach the store counts exactly like one that does. That
    /// over-approximates in the safe direction and is what keeps the cost linear per
    /// round.
    ///
    /// `escaped` is set wherever a tainted value can leave the locals: stored INTO
    /// memory through a `Deref`, handed to a callee (which may stash it somewhere this
    /// body later loads from), dropped (drop glue is arbitrary code), or touched by a
    /// statement/terminator class this crate does not model. Handing a tainted value
    /// to a callee ALSO taints that call's destination, but the destination alone
    /// would not cover the callee that writes the pointer through an out-parameter,
    /// so both fire. That is deliberately coarse: `v3`'s `launder(&j)` is refused
    /// twice over, and a correct program that passes `&guard` to a call AND contains
    /// an unresolvable store keeps exactly the refusal it has today.
    ///
    /// The second component is `true` iff the ambient verification budget tripped
    /// during the fixpoint, in which case the answer is the fail-closed `escaped`
    /// and the caller must not keep it.
    fn slot_taint(
        func: &VerifiableFunction,
        index: &FoldIndex,
        guard: &Place,
    ) -> (SlotTaint, bool) {
        let mut tainted: FxHashSet<usize> = FxHashSet::default();
        // Trust: 2026-09-18 (reviewer round 2) — the forged-pointer channel, seeded
        // before the fixpoint because it is a property of the body and not of the
        // taint. A body that mints an address out of a non-address has a store this
        // walk cannot argue about at all, so it gets the pre-narrowing answer.
        let mut escaped = index.forges(func);
        let mut tripped = false;
        // Monotone: each productive round adds a local or sets `escaped`, so
        // `locals + 2` rounds is a bound and not a heuristic. Tripping it is a
        // malformed body, and it answers `escaped` (refuse).
        let budget = func.body.locals.len() + 2;
        'rounds: for round in 0usize.. {
            if escaped {
                break;
            }
            if round > budget {
                escaped = true;
                break;
            }
            let before = tainted.len();
            for block in &func.body.blocks {
                // Trust: 2026-09-30 — the ambient per-function budget, once per block
                // per round. A trip answers `escaped`: every unattributable store is
                // then a rebind, which refuses the fold (the opaque name).
                if trust_types::verify_budget::budget_exhausted() {
                    escaped = true;
                    tripped = true;
                    break 'rounds;
                }
                for stmt in &block.stmts {
                    match stmt {
                        Statement::Assign { place, rvalue, .. } => {
                            if rvalue_is_tainted(rvalue, guard, &tainted) {
                                if place.projections.iter().any(|p| matches!(p, Projection::Deref))
                                {
                                    // Written THROUGH a pointer: the taint is now in
                                    // memory, which this walk does not track.
                                    escaped = true;
                                } else {
                                    tainted.insert(place.local);
                                }
                            }
                        }
                        // These write a place but carry no value in, so they cannot
                        // create taint.
                        Statement::SetDiscriminant { .. }
                        | Statement::Deinit { .. }
                        | Statement::Retag { .. }
                        | Statement::PlaceMention(_)
                        | Statement::StorageLive(_)
                        | Statement::StorageDead(_)
                        | Statement::Coverage
                        | Statement::ConstEvalCounter
                        | Statement::Nop => {}
                        Statement::Intrinsic { args, .. } => {
                            if args.iter().any(|op| operand_is_tainted(op, &tainted)) {
                                escaped = true;
                            }
                        }
                        Statement::CopyNonOverlapping { src, dst, count, .. } => {
                            if operand_is_tainted(src, &tainted)
                                || operand_is_tainted(dst, &tainted)
                                || operand_is_tainted(count, &tainted)
                            {
                                escaped = true;
                            }
                        }
                        Statement::Unsupported { operands, .. } => {
                            if operands.iter().any(|op| operand_is_tainted(op, &tainted)) {
                                escaped = true;
                            }
                        }
                        // `#[non_exhaustive]`: a statement class this crate does not
                        // model may move the borrow anywhere.
                        _ => escaped = true,
                    }
                }
                match &block.terminator {
                    Terminator::Call { args, dest, .. } => {
                        if args.iter().any(|op| operand_is_tainted(op, &tainted)) {
                            escaped = true;
                            if !dest.projections.iter().any(|p| matches!(p, Projection::Deref)) {
                                tainted.insert(dest.local);
                            }
                        }
                    }
                    Terminator::TailCall { args, .. } => {
                        if args.iter().any(|op| operand_is_tainted(op, &tainted)) {
                            escaped = true;
                        }
                    }
                    Terminator::Drop { place, .. } => {
                        if place_reads_tainted(place, &tainted) {
                            escaped = true;
                        }
                    }
                    // Reads only; no destination and no memory effect.
                    Terminator::Goto(_)
                    | Terminator::SwitchInt { .. }
                    | Terminator::Assert { .. }
                    | Terminator::Return
                    | Terminator::Unreachable
                    | Terminator::Resume => {}
                    // `Opaque` and any unknown terminator: fail closed.
                    _ => escaped = true,
                }
            }
            if !escaped && tainted.len() == before {
                break;
            }
        }
        (SlotTaint { tainted, escaped }, tripped)
    }

    /// True iff some borrow (`&`, `&mut`, `&raw`) of `local`'s own storage — not of
    /// a pointee reached through it — exists anywhere in the body: a pointer into
    /// the local can then be the pointer stored at a `Deref` prefix of a guard, so
    /// a DIRECT write of the local can re-point that guard.
    ///
    /// Trust: 2026-09-30 — the REFERENCE definition; the walk asks
    /// `FoldIndex::storage_borrowed` (`index_agrees_with_the_scans`).
    #[cfg(test)]
    pub(crate) fn local_storage_borrowed_anywhere(func: &VerifiableFunction, local: usize) -> bool {
        func.body.blocks.iter().any(|block| {
            block.stmts.iter().any(|stmt| {
                matches!(
                    stmt,
                    Statement::Assign {
                        rvalue: Rvalue::Ref { place, .. } | Rvalue::AddressOf(_, place),
                        ..
                    } if place.local == local
                        && !matches!(place.projections.first(), Some(Projection::Deref))
                )
            })
        })
    }

    /// True iff a write to the (raw, un-canonicalized) place `written` rebinds
    /// `guard`. A store through a pointer is attributed to the pointer's own
    /// folded referent when it has one — the local under test resolves to
    /// `referent` by construction — and to "anything a pointer can reach"
    /// otherwise.
    ///
    /// Trust: 2026-09-17 (round A12, fixer) — the attributed place is compared
    /// with the guard CONSERVATIVELY. Only a write that lies strictly inside the
    /// guard BEHIND A `Deref` of it (a store through the pointer the guard holds,
    /// never into the pointer's own bytes) is dismissed on the root, and even that
    /// store lands in memory some pointer reaches, which may be the guard's own slot
    /// (`guard_reachable_by_pointer`). A write whose attributed place still carries a
    /// `Deref` is in pointer-reached memory and may be ANY guard slot a pointer can
    /// reach, whatever its root; a direct write of another local re-points a guard
    /// behind a `Deref` when that local's storage was ever borrowed. The previous
    /// form dismissed every differing root and every `Inside` path.
    ///
    /// Trust: 2026-09-18 — the UNATTRIBUTABLE-STORE arm (`folded == None`) now asks
    /// [`unattributable_store_rebinds`], which conjoins the body-global alias question
    /// with the PROVENANCE of this store's own pointer local. (The two other uses of
    /// `guard_reachable_by_pointer`, where the store's pointer DID resolve, were left
    /// as they were that day; since 2026-10-07 a store through ANOTHER pointer asks
    /// the provenance question there too — see below.) See the
    /// `docs/KNOWN_HAZARDS.md` entry of that date for the false refutation this closes
    /// and for why capability is not the discriminator.
    ///
    /// Trust: 2026-09-30 — A STORE THROUGH ANOTHER POINTER ASKS ITS OUTCOMES FIRST.
    /// Attributing `*q = v` needs `q`'s resolution, and that resolution runs `q`'s
    /// own stability walk nested inside this one — plus a walk for every pointer on
    /// `q`'s chain — each with its own region full of stores through yet other
    /// pointers. Regions that store through one another (every loop body that writes
    /// two `Vec`s by index: the `aterm-census` bodies that ran for hours) nested those
    /// walks through every ordering of the pointers. But the answer below reads only
    /// a few coarse features of the attributed place — its root, whether it passes a
    /// `Deref`, its prefix relation to the guard — and for most guards every value the
    /// resolution CAN take gives the same answer. [`TaintCache::outcomes`] lists those
    /// values without running a walk; when they all agree, that is the answer the
    /// real resolution would give, exactly (see [`outcomes`]), and no nested walk
    /// runs. Otherwise the resolution is run as before.
    ///
    /// Trust: 2026-10-07 (D41a of `fix/referent-fold-budget`, merged 2026-10-08) —
    /// ATTRIBUTING A STORE NEVER WIDENS ITS ANSWER. A store through ANOTHER pointer `y`
    /// that DID resolve, and whose attributed place lands in pointer-reached memory (a
    /// target with a `Deref`, or a place strictly inside the guard behind the guard's
    /// own `Deref`), asked the body-global [`guard_reachable_by_pointer`] ("is the
    /// guard borrowed anywhere"), while the SAME store left unresolved asks the
    /// narrower [`unattributable_store_rebinds`] (that, AND may `y` be derived from such
    /// a borrow). Those two arms now ask the latter about `y`: a store through `y` can
    /// land in the guard's slot only if `y`'s value is derived from a borrow of that
    /// slot, whatever place `y` was attributed to — the no-forged-pointer premise
    /// documented on [`slot_taint`], with its two named UB-only residuals, now covering
    /// attributed stores as well as unattributed ones. For a guard with a `Deref` both
    /// predicates answer `true`; for a deref-free guard the new answer is the old one
    /// conjoined with `y`'s provenance, so every attributed answer is at most the
    /// unattributed one (it can only admit a fold the old arm refused). The store
    /// through the pointer UNDER TEST, and a direct (`Deref`-free) write, keep the wide
    /// question: their target is the referent itself or a named place. Measured on the
    /// branch's adversarial captures (`tests/referent_fold_budget.rs`): three correct
    /// programs main refuted with a bogus stored value (`box_field_ctl`,
    /// `vec_slice_ctl`, `split_ctl`) prove; every panicking twin stays unproved. The
    /// answer is still a function of `folded`, so [`outcomes`] stays exact.
    fn written_place_rebinds(
        taint: &TaintCache<'_>,
        written: &Place,
        guard: &Place,
        under_test: usize,
        referent: &Place,
    ) -> bool {
        let Some((Projection::Deref, rest)) = written.projections.split_first() else {
            return attributed_write_rebinds(
                taint,
                written.local,
                &written.projections,
                &[],
                guard,
                None,
            );
        };
        if written.local == under_test {
            return attributed_write_rebinds(
                taint,
                referent.local,
                &referent.projections,
                rest,
                guard,
                None,
            );
        }
        if shortcuts_enabled()
            && let Some(outcomes) = taint.outcomes(written.local)
        {
            let mut answers = outcomes.iter().map(|folded| {
                store_through_rebinds(taint, written.local, folded.as_ref(), rest, guard)
            });
            if let Some(first) = answers.next()
                && answers.all(|answer| answer == first)
            {
                crate::fn_memo::count_fold_outcome_decisions();
                return first;
            }
        }
        let folded = taint.resolve(written.local);
        store_through_rebinds(taint, written.local, folded.as_ref(), rest, guard)
    }

    /// [`written_place_rebinds`] for a store through `ptr` (`*ptr` then `rest`), given
    /// `ptr`'s resolution `folded`.
    fn store_through_rebinds(
        taint: &TaintCache<'_>,
        ptr: usize,
        folded: Option<&Place>,
        rest: &[Projection],
        guard: &Place,
    ) -> bool {
        match folded {
            Some(slot) => attributed_write_rebinds(
                taint,
                slot.local,
                &slot.projections,
                rest,
                guard,
                Some(ptr),
            ),
            None => unattributable_store_rebinds(taint, ptr, guard),
        }
    }

    /// [`written_place_rebinds`] for a write ATTRIBUTED to `(target_local, target_prefix ++ target_rest)`.
    /// `through` is the pointer local the store went through when that pointer is NOT the one under
    /// test (its attribution came from its own resolution); `None` for the pointer
    /// under test and for a direct write. A landing in pointer-reached memory asks
    /// that pointer's provenance when there is one (see "ATTRIBUTING A STORE NEVER
    /// WIDENS ITS ANSWER" on [`written_place_rebinds`]), the body-global question
    /// otherwise.
    fn attributed_write_rebinds(
        taint: &TaintCache<'_>,
        target_local: usize,
        target_prefix: &[Projection],
        target_rest: &[Projection],
        guard: &Place,
        through: Option<usize>,
    ) -> bool {
        let index = &taint.index;
        let pointer_reached = || match through {
            Some(ptr) => unattributable_store_rebinds(taint, ptr, guard),
            None => guard_reachable_by_pointer(index, guard),
        };
        let has_deref = |ps: &[Projection]| ps.iter().any(|x| matches!(x, Projection::Deref));
        if target_local == guard.local {
            let g = &guard.projections;
            let t_len = target_prefix.len() + target_rest.len();
            if t_len > g.len()
                && g.iter().eq(target_prefix.iter().chain(target_rest.iter()).take(g.len()))
            {
                // Strictly inside the guard: a write into the guard's own bytes
                // unless the first projection below it is the `Deref` of the pointer
                // the guard stores.
                let next_proj = if g.len() < target_prefix.len() {
                    &target_prefix[g.len()]
                } else {
                    &target_rest[g.len() - target_prefix.len()]
                };
                return if matches!(next_proj, Projection::Deref) {
                    pointer_reached()
                } else {
                    true
                };
            }
            // A prefix (the guard itself included) or a sibling.
            return true;
        }
        if has_deref(target_prefix) || has_deref(target_rest) {
            return pointer_reached();
        }
        has_deref(&guard.projections) && index.storage_borrowed.contains(&target_local)
    }

    /// Trust: 2026-09-17 (round A13) — the walk's per-guard state, as a BITSET over
    /// the filtered guard vector: bit `i` SET means guard `i` is `Unknown` (it may no
    /// longer hold its borrow-time value), bit CLEAR means `Same`.
    ///
    /// This replaces ONE boolean shared by every guard, which a round-A12 review
    /// measured as a false refutation: a write of guard `a` refused the fold at a use
    /// that only guard `b` selects, and — with re-establishment below — a guard
    /// written and then RESTORED to its borrow-time value refused it too.
    ///
    /// A bitset, not a `Vec<GuardState>`: the state is the `visited` key, so it must
    /// be `Copy + Hash` and allocation-free. Guards past bit 63 SATURATE onto bit 63
    /// and re-establishment is then switched off outright, so a body with more than
    /// 64 guards decides exactly what the single-boolean form decided.
    type GuardMask = u64;

    const MASK_BITS: usize = 64;

    /// The bit of guard `i`, saturating on the last bit.
    fn guard_bit(i: usize) -> GuardMask {
        1u64 << if i < MASK_BITS { i } else { MASK_BITS - 1 }
    }

    /// Every guard `Unknown` — the single-boolean form's "tainted".
    fn all_unknown(guards: &[Place]) -> GuardMask {
        if guards.len() >= MASK_BITS { !0 } else { (1u64 << guards.len()) - 1 }
    }

    /// WHICH guards `stmt` may rebind. Every fail-closed arm of the pre-A13
    /// `stmt_rebinds` is kept and marks EVERY guard `Unknown`: an `Intrinsic`, a
    /// `CopyNonOverlapping`, an `Unsupported` statement and any statement class this
    /// crate does not model write through a pointer OPERAND, with no place to rule
    /// anything out by.
    ///
    /// Trust: 2026-09-30 — `known` are the guards whose bit cannot change the
    /// caller's state whatever this answers (already `Unknown`, and not re-establishable
    /// by this statement); they are not asked, and their bits come back clear. Asking
    /// them cost a `written_place_rebinds` each — for a store through another pointer,
    /// that pointer's resolution — to set a bit the caller already holds.
    fn guards_rebound_by_stmt(
        taint: &TaintCache<'_>,
        stmt: &Statement,
        guards: &[Place],
        under_test: usize,
        referent: &Place,
        known: GuardMask,
    ) -> GuardMask {
        match stmt {
            Statement::Assign { place, .. }
            | Statement::SetDiscriminant { place, .. }
            | Statement::Deinit { place } => guards.iter().enumerate().fold(0, |mask, (i, g)| {
                if known & guard_bit(i) == 0
                    && written_place_rebinds(taint, place, g, under_test, referent)
                {
                    mask | guard_bit(i)
                } else {
                    mask
                }
            }),
            // Writes through a pointer OPERAND, or a statement class this crate
            // does not model: no place to rule anything out by.
            Statement::Intrinsic { .. }
            | Statement::CopyNonOverlapping { .. }
            | Statement::Unsupported { .. } => all_unknown(guards),
            Statement::Retag { .. }
            | Statement::PlaceMention(_)
            | Statement::StorageLive(_)
            | Statement::StorageDead(_)
            | Statement::Coverage
            | Statement::ConstEvalCounter
            | Statement::Nop => 0,
            _ => all_unknown(guards),
        }
    }

    /// True iff a callee reached here may rebind `guard`: through a WRITE-CAPABLE
    /// alias of the slot handed out anywhere in the body, or — for a slot behind a
    /// `Deref`, which any pointer the callee holds may reach — unconditionally.
    ///
    /// Trust: 2026-09-17 (round A13, pass 2) — this used to forward to
    /// `guard_reachable_by_pointer`, whose alias half counts a SHARED `&guard` too.
    /// See `slot_is_writably_aliased_anywhere` for the three measured false
    /// refutations that cost, for why the `Deref` disjunct stays unconditional, and
    /// for why `written_place_rebinds` keeps the wide question.
    fn callee_may_rebind(index: &FoldIndex, guard: &Place) -> bool {
        guard.projections.iter().any(|p| matches!(p, Projection::Deref))
            || index.slot_aliased(guard, AliasKind::WriteCapable)
    }

    /// WHICH guards `term` may rebind — the terminator twin of
    /// `guards_rebound_by_stmt`, with the same fail-closed arms: `Opaque` and any
    /// terminator class this crate does not model mark EVERY guard `Unknown`.
    ///
    /// `known` is `guards_rebound_by_stmt`'s: guards not asked, bits returned clear.
    /// The cheap, body-global `callee_may_rebind` is asked before the store
    /// attribution (the disjunction is the same either way round).
    fn guards_rebound_by_terminator(
        taint: &TaintCache<'_>,
        term: &Terminator,
        guards: &[Place],
        under_test: usize,
        referent: &Place,
        known: GuardMask,
    ) -> GuardMask {
        let fold = |pred: &dyn Fn(&Place) -> bool| {
            guards.iter().enumerate().fold(0, |mask, (i, g)| {
                if known & guard_bit(i) == 0 && pred(g) { mask | guard_bit(i) } else { mask }
            })
        };
        match term {
            Terminator::Call { dest, .. } => fold(&|g| {
                callee_may_rebind(&taint.index, g)
                    || written_place_rebinds(taint, dest, g, under_test, referent)
            }),
            Terminator::TailCall { .. } => {
                fold(&|g| g.local == 0 || callee_may_rebind(&taint.index, g))
            }
            Terminator::Drop { place, .. } => fold(&|g| {
                callee_may_rebind(&taint.index, g)
                    || written_place_rebinds(taint, place, g, under_test, referent)
            }),
            Terminator::Goto(_)
            | Terminator::SwitchInt { .. }
            | Terminator::Return
            | Terminator::Assert { .. }
            | Terminator::Unreachable
            | Terminator::Resume => 0,
            // `Opaque` and any unknown terminator: fail closed.
            _ => all_unknown(guards),
        }
    }

    /// The guards `stmt` could re-establish ([`reestablishes_guard`]) — the only
    /// ones whose `Unknown` bit a statement can clear.
    fn reestablishable(stmt: &Statement, guards: &[Place]) -> GuardMask {
        guards.iter().enumerate().fold(0, |mask, (i, g)| {
            if reestablishes_guard(stmt, g).is_some() { mask | guard_bit(i) } else { mask }
        })
    }

    /// The value of a scalar constant, as a key equality may be decided on.
    ///
    /// Trust: 2026-09-17 (round A13) — `ConstValue` is `#[non_exhaustive]` and has NO
    /// `PartialEq`, and that is the right shape here: only the variants carrying a
    /// REAL value get a key. `OpaqueConst`, `OpaqueScalar`, `ConstParam`, `Str`,
    /// `UnitVariantRef`, a float — every one of them answers `None`, so no constant
    /// this walk cannot decide can ever re-establish a guard. A structural derive
    /// would have said two `OpaqueConst`s (two DIFFERENT unevaluated constants) are
    /// the same value, which is the false-proof direction.
    type ConstKey = (u8, i128, u32);

    fn scalar_const_key(c: &trust_types::ConstValue) -> Option<ConstKey> {
        use trust_types::ConstValue as C;
        match c {
            C::Bool(b) => Some((0, i128::from(*b), 1)),
            C::Int(v) => Some((1, *v, 0)),
            // A `u128` past `i128::MAX` has no key and therefore never re-establishes.
            C::Uint(v, width) => Some((2, i128::try_from(*v).ok()?, *width)),
            _ => None,
        }
    }

    /// `Some(c)` iff `stmt`'s ONLY effect on `guard` is to assign it the scalar
    /// constant `c`: the written place is the guard EXACTLY — same local, same
    /// projections — and the rvalue is a bare `Use` of a decidable constant.
    ///
    /// Everything else answers `None` and leaves the guard `Unknown`. That exclusion
    /// is the whole soundness margin of the re-establishment rule and it is drawn
    /// deliberately narrow: a non-constant rvalue (the round-A11 `j = k` witnesses), a
    /// `Call` destination, and a write whose attributed place merely OVERLAPS the
    /// guard (`_1` against the guard `(*_1).0`) each stay `Unknown`.
    fn reestablishes_guard(stmt: &Statement, guard: &Place) -> Option<ConstKey> {
        if !guard.projections.is_empty() {
            return None;
        }
        let Statement::Assign { place, rvalue, .. } = stmt else {
            return None;
        };
        if place != guard {
            return None;
        }
        let Rvalue::Use(Operand::Constant(c)) = rvalue else {
            return None;
        };
        scalar_const_key(c)
    }

    /// The constant lattice of ONE guard: `Bottom` (no path here yet) `<` `Const(c)`
    /// `<` `Top` (any value), with two different constants joining to `Top`.
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum CVal {
        Bottom,
        Const(ConstKey),
        Top,
    }

    impl CVal {
        fn join(self, other: CVal) -> CVal {
            match (self, other) {
                (CVal::Bottom, v) | (v, CVal::Bottom) => v,
                (CVal::Const(a), CVal::Const(b)) if a == b => CVal::Const(a),
                _ => CVal::Top,
            }
        }
    }

    /// `c0(g)` — the value `g` holds AT THE BORROW, when that value is one and the
    /// same constant on every path that reaches it.
    ///
    /// Trust: 2026-09-17 (round A13) — a forward constant fixpoint of `g` over the
    /// CFG, read at the statement that defines the pointer local (`b0`, `k0`), which
    /// is the point at which the referent's storage is selected. Entry is `Top` (a
    /// parameter's value, or uninit), so only a real constant assignment yields a
    /// `Const`, and two different ones on two paths yield `Top`.
    ///
    /// The transfer reuses the SAME rebinding classifier the stability walk itself
    /// uses, so every unattributable channel — an escape through an alias, an
    /// unlocatable or opaque store, a `Call`/`Drop` destination, anything
    /// `guard_reachable_by_pointer` admits — lands on `Top` here for exactly the
    /// reason it taints there. There is deliberately no second, weaker channel list.
    ///
    /// Only an empty-projection guard is asked: a projected guard (`(*_1).0`) names
    /// storage whose identity this fixpoint does not track.
    fn borrow_time_constant(
        func: &VerifiableFunction,
        taint: &TaintCache<'_>,
        guard: &Place,
        under_test: usize,
        referent: &Place,
        b0: usize,
        k0: usize,
    ) -> Option<ConstKey> {
        if !guard.projections.is_empty() {
            return None;
        }
        let n = func.body.blocks.len();
        if n == 0 {
            return None;
        }
        let single = std::slice::from_ref(guard);
        let index_of = &taint.index.block_index;
        let mut state = vec![CVal::Bottom; n];
        // `body.blocks[0]` is the entry block, as everywhere else in this crate.
        state[0] = CVal::Top;
        let mut work = vec![0usize];
        let mut at_def = CVal::Bottom;
        // Each block's state can rise at most twice (`Bottom` -> `Const` -> `Top`),
        // so the fixpoint pops at most `2n + 1` times; the budget only bounds a
        // malformed CFG, and tripping it answers `None` (no constant, no change).
        let budget = 4 * n + 64;
        let mut steps = 0usize;
        while let Some(b) = work.pop() {
            steps += 1;
            // Trust: 2026-09-30 — and the ambient per-function budget: a trip answers
            // `None` too (no constant, so no guard is ever re-established).
            if steps > budget || trust_types::verify_budget::budget_exhausted() {
                return None;
            }
            let block = &func.body.blocks[b];
            crate::fn_memo::count_fold_walk_steps(1);
            crate::fn_memo::count_fold_stmt_visits(block.stmts.len() as u64 + 1);
            let mut v = state[b];
            for (k, stmt) in block.stmts.iter().enumerate() {
                if b == b0 && k == k0 {
                    // The borrow statement READS the guard to select the storage, so
                    // the value that matters is the one BEFORE it.
                    at_def = at_def.join(v);
                }
                // Trust: 2026-09-30 — at `Top`, a rebinding that cannot re-establish
                // leaves `Top`: the answer is not needed (`guards_rebound_by_stmt`'s
                // `known`).
                let reestablishes = reestablishes_guard(stmt, guard);
                let known = if shortcuts_enabled() && v == CVal::Top && reestablishes.is_none() {
                    !0
                } else {
                    0
                };
                if guards_rebound_by_stmt(taint, stmt, single, under_test, referent, known) != 0 {
                    v = match reestablishes {
                        Some(c) => CVal::Const(c),
                        None => CVal::Top,
                    };
                }
            }
            let known = if shortcuts_enabled() && v == CVal::Top { !0 } else { 0 };
            if guards_rebound_by_terminator(
                taint,
                &block.terminator,
                single,
                under_test,
                referent,
                known,
            ) != 0
            {
                v = CVal::Top;
            }
            if !try_for_each_successor(&block.terminator, |succ| {
                let Some(idx) = index_of.get(&succ) else {
                    return false;
                };
                let merged = state[idx].join(v);
                if merged != state[idx] {
                    state[idx] = merged;
                    work.push(idx);
                }
                true
            }) {
                return None;
            }
        }
        match at_def {
            CVal::Const(c) => Some(c),
            CVal::Bottom | CVal::Top => None,
        }
    }

    /// `c0` per guard, computed on FIRST DEMAND — a walk that never meets a constant
    /// assignment to a guard never runs the fixpoint at all, which is the common case.
    struct BorrowTimeConsts<'f> {
        func: &'f VerifiableFunction,
        guards: &'f [Place],
        under_test: usize,
        referent: &'f Place,
        b0: usize,
        k0: usize,
        cache: Vec<Option<Option<ConstKey>>>,
    }

    impl<'f> BorrowTimeConsts<'f> {
        fn new(
            func: &'f VerifiableFunction,
            guards: &'f [Place],
            under_test: usize,
            referent: &'f Place,
            b0: usize,
            k0: usize,
        ) -> Self {
            Self { func, guards, under_test, referent, b0, k0, cache: vec![None; guards.len()] }
        }

        /// `taint` is passed in rather than held: the cache is created inside `walk`
        /// and so outlives neither `func` nor this struct's own `'f`.
        fn get(&mut self, taint: &TaintCache<'_>, i: usize) -> Option<ConstKey> {
            let func = self.func;
            let guard = &self.guards[i];
            let under_test = self.under_test;
            let referent = self.referent;
            let b0 = self.b0;
            let k0 = self.k0;
            *self.cache[i].get_or_insert_with(|| {
                borrow_time_constant(func, taint, guard, under_test, referent, b0, k0)
            })
        }
    }

    /// Calls `f` on every in-CFG successor (the unwind cleanup block included),
    /// stopping early and returning `false` if `f` returns `false`.
    fn try_for_each_successor(term: &Terminator, mut f: impl FnMut(BlockId) -> bool) -> bool {
        let mut ok = true;
        super::for_each_terminator_target(term, |succ| {
            if ok && !f(succ) {
                ok = false;
            }
        });
        if !ok {
            return false;
        }
        match term {
            Terminator::Call { unwind, .. }
            | Terminator::Assert { unwind, .. }
            | Terminator::Drop { unwind, .. } => {
                if let Some(cleanup) = unwind.cleanup_target() {
                    return f(cleanup);
                }
            }
            _ => {}
        }
        true
    }

    /// True iff `*local` may be spelled by `referent` at every use of `local`:
    /// on no path from `local`'s defining statement to a use of `local` (that
    /// does not pass through the definition again) does any guard of `referent`
    /// hold a VALUE other than the one it held at the borrow. Fail-closed on every
    /// channel the walk cannot attribute; a local with no defining statement (a
    /// parameter, a call destination) has no region and passes — its root value is
    /// then a guard of the caller's own referent, walked from the caller's
    /// definition.
    ///
    /// Trust: 2026-09-17 (round A13) — the guarantee is stated on the guard's VALUE.
    /// "No guard is WRITTEN" — what the walk decided through round A12 — is a
    /// strictly coarser sufficient condition for it, and a round-A12 review measured
    /// the gap as a false refutation on plain safe Rust: `let r = &mut s[j]; j = k;
    /// j = 0; *r = 3; t[s[j] as usize]` with `j == 0` at the borrow. The guard is
    /// written twice and holds its borrow-time value at every use of `r`, so the fold
    /// is correct; the coarser condition refused it, the deref was spelled by the
    /// opaque pointer name, the store havocked, and the later read was refuted with a
    /// counterexample no execution realizes (the sealed driver and the A5-era stage1
    /// both PROVE that row). `walk` decides the value condition directly:
    /// `guards_rebound_by_stmt` says WHICH guards a write can reach, and
    /// `reestablishes_guard` + `borrow_time_constant` are the one — deliberately
    /// narrow — way a guard returns to `Same`.
    ///
    /// Trust: 2026-09-17 (round A12, fixer) — `extra` are guards of a referent that
    /// will be read OUT OF `referent`'s storage at a use of `local` (see
    /// `referent_of_source` / `reread_through`); they must be stable over the same
    /// region. A "use" here is a SYNTACTIC mention of `local`; the only way this
    /// body reads `local`'s value without mentioning it is through a borrow of
    /// `local` itself — a `&mut`/`&raw` one makes
    /// `unique_value_def_modulo_pointee_borrows(local)` `None`, so no fold exists, and
    /// a shared `&local` is a carrier, whose uses are walked with these guards by the
    /// carrier's own re-resolution.
    ///
    /// Trust: 2026-09-17 (round A12, pass 2) — "a borrow of `local` itself" is now
    /// literally that, and the resolver's narrowing does not weaken this argument. The
    /// borrows it re-admits are `Deref`-first (`&mut (*local)[i]`): such a statement
    /// READS `local` to compute the address, so it MENTIONS `local` syntactically and
    /// the walk below sees it exactly like any other use; and the pointer it hands out
    /// addresses the pointee, not `local`'s own bytes, so nothing read through it is a
    /// read of `local`'s value.
    pub(super) fn is_stable(
        func: &VerifiableFunction,
        local: usize,
        referent: &Place,
        extra: &[Place],
    ) -> bool {
        let WalkPlan { index, guards, b0, k0 } = match prepare(func, local, referent, extra) {
            Prepared::Decided(verdict) => return verdict,
            Prepared::Walk(plan) => plan,
        };
        // Trust: 2026-09-30 — while [`outcomes`] enumerates what a resolution CAN
        // answer, the walk is not run: it is one free choice, and the enumeration
        // takes both. Everything `prepare` decided above — no guard, no region, a
        // stored verdict, an in-progress cut, a spent budget — is still decided
        // exactly, so a choice stands only for a walk that would really have run.
        if enumerating() {
            return choose();
        }
        let fid = func_identity(func);
        /// Pops this walk's frame on every exit — a budget trip or a panic unwinding
        /// through the walk must not leave the local permanently "in progress" for
        /// the rest of the thread.
        struct Unmark(bool);
        impl Unmark {
            /// Pop the frame and hand back what it consulted.
            fn finish(mut self) -> FxHashSet<usize> {
                self.0 = false;
                FRAMES.with(|f| f.borrow_mut().pop()).map(|fr| fr.consulted).unwrap_or_default()
            }
        }
        impl Drop for Unmark {
            fn drop(&mut self) {
                if self.0 {
                    FRAMES.with(|f| {
                        f.borrow_mut().pop();
                    });
                }
            }
        }
        FRAMES.with(|f| {
            f.borrow_mut().push(Frame {
                func: fid,
                local,
                consulted: std::iter::once(local).collect(),
            })
        });
        let unmark = Unmark(true);
        let verdict = walk(func, &index, local, referent, &guards, b0, k0);
        let consulted = unmark.finish();
        // The walk's consultations are its enclosing walk's too.
        note_consulted(fid, &consulted);
        // A verdict reached after the ambient budget tripped may be a budget refusal,
        // not a function of the stack certificate: never remember it.
        if !trust_types::verify_budget::exhausted_readonly() {
            let mut cut: Vec<usize> = FRAMES.with(|f| {
                f.borrow()
                    .iter()
                    .filter(|fr| fr.func == fid && consulted.contains(&fr.local))
                    .map(|fr| fr.local)
                    .collect()
            });
            cut.sort_unstable();
            cut.dedup();
            super::havoc_memo::store_fold_stable(
                func,
                local,
                referent,
                &guards,
                FoldEntry { consulted, cut, verdict },
            );
        }
        verdict
    }

    /// What [`is_stable`] decides BEFORE it walks: `Decided` when no walk is needed
    /// (or allowed), `Walk` with everything the walk needs otherwise.
    enum Prepared {
        Decided(bool),
        Walk(WalkPlan),
    }

    struct WalkPlan {
        index: Rc<FoldIndex>,
        /// The filtered guard list — also the verdict memo's key.
        guards: Vec<Place>,
        b0: usize,
        k0: usize,
    }

    /// [`is_stable`] up to the walk: the guard list and its filter, the region's
    /// start, the verdict memo, the ambient budget and the in-progress cut. It marks
    /// nothing in progress.
    fn prepare(
        func: &VerifiableFunction,
        local: usize,
        referent: &Place,
        extra: &[Place],
    ) -> Prepared {
        let mut all = guards(referent);
        for g in extra {
            if !all.contains(g) {
                all.push(g.clone());
            }
        }
        if all.is_empty() {
            return Prepared::Decided(true);
        }
        let index = fold_index(func);
        let guards: Vec<Place> = all
            .into_iter()
            // Trust: 2026-09-17 (round A12, fixer) — only a guard with NO body write
            // at all (a never-written parameter) is dropped. A single-static-
            // assignment local is NOT single-valued over a region inside a loop: its
            // one `Assign` re-executes every iteration, and whether that statement
            // lies between the borrow and a use is exactly what the walk decides.
            //
            // Trust: 2026-09-17 (round A12, pass 2) — MEASURED, because a review read
            // this conjunction as unsatisfiable and asked for the SSA half to be
            // dropped. It is satisfiable by exactly the guard named above: a
            // parameter's `whole` is seeded from `body_is_parameter`, so a
            // never-written one scores `1` on the SSA question and `0` body whole
            // writes on the reseat question. And the SSA half may NOT be dropped —
            // `never_explicitly_reseated` alone accepts a parameter that is
            // `&mut`-borrowed and written through (`Escape` is not a reseat), which
            // would drop a guard the store DOES rebind. Both halves are pinned by
            // `local_defs_tests::the_fold_guard_filter_drops_a_never_written_
            // parameter_and_not_an_aliased_one`.
            //
            // Trust: 2026-09-17 (round A13) — and the guard's own storage must not be
            // BORROWED anywhere. Both halves above are written in terms of
            // `Statement::escapes_local`, which counts `Rvalue::Ref { mutable: true }`
            // and `AddressOf` only, so a never-written parameter with a SHARED `&g`
            // taken of it scored on both and was dropped here — before
            // `guard_reachable_by_pointer` / `slot_is_aliased_anywhere`, which round
            // A12 pass 2 widened to see exactly that shared borrow, could be asked
            // about it. `local_storage_borrowed_anywhere` is that widened question,
            // and asking it here is what puts the widening in reach of a parameter
            // guard. Strictly conservative: it can only KEEP a guard the filter used
            // to drop.
            //
            // Trust: 2026-09-17 (round A13, pass 2) — the shape is
            // `v3_shared_param_cast_store_bug`: `let pj = launder(&j); *pj = k;` with
            // `j` a never-written parameter. This comment used to cite
            // `u1_shared_cast_bug` / `j1_param_shared_launder_bug`, which is wrong —
            // both take `&raw const j`, an `AddressOf` that `escapes_local` already
            // counts, so `never_explicitly_reseated` already fails for them and this
            // conjunct never decides their fate. Measured causally by the pass-2
            // review: replacing the conjunct with `true` flips `v3` from `Unknown` to
            // `Proved` at `-O0` on a program that panics.
            .filter(|g| {
                !(g.projections.is_empty()
                    && crate::local_defs::is_single_static_assignment(func, g.local)
                    && crate::local_defs::never_explicitly_reseated(func, g.local)
                    && !index.storage_borrowed.contains(&g.local))
            })
            .collect();
        if guards.is_empty() {
            return Prepared::Decided(true);
        }
        let (b0, k0) = match index.def_position(func, local) {
            // Nothing in the body binds the local: no region, nothing to rebind.
            DefStart::NoWrite => return Prepared::Decided(true),
            DefStart::At(b, k) => (b, k),
            // A parameter that is also written, a call destination, a local with a
            // channel the seam could not attribute: no region this walk can trust.
            DefStart::Unknown => return Prepared::Decided(false),
        };
        let fid = func_identity(func);
        // Trust: 2026-09-30 — a stored verdict whose stack certificate this stack
        // satisfies (see `FoldEntry`); before, only a top-level verdict was stored and
        // only an empty stack looked. Its consultations become the enclosing walk's.
        let stack = in_progress(fid);
        if let Some(hit) =
            super::havoc_memo::fold_stable(func, local, referent, &guards, |e| e.replays_in(&stack))
        {
            crate::fn_memo::count_fold_memo_hits();
            note_consulted(fid, &hit.consulted);
            return Prepared::Decided(hit.verdict);
        }
        // Trust: 2026-09-30 — the ambient per-function verification budget
        // (`trust_types::verify_budget`: the 120 s deadline and the step count the
        // compiler installs per function), polled once per walk decided and inside
        // every loop of the walk below. Before these polls the referent fold was a
        // VC-generation pass that consulted NO budget: its cost was exponential in
        // the number of pointers whose regions store through one another (each store
        // resolved the other pointer with a nested walk, and a nested walk was never
        // memoized), and `aterm-census`'s `lock_order::tarjan_sccs` spent >90
        // CPU-minutes in it under trust-6606d3bd with a 120 s function budget in
        // force. (Corrected 2026-10-02: this comment and 812ec72053's message named
        // `run_lock_order_census`, the body the 2026-09-27 report saw last. The
        // repro's dump order shows `tarjan_sccs` from t=600 s to the cap;
        // `run_lock_order_census`'s own overrun was the Vec-forwarder row replay,
        // `generate::row_replay_scope`.) The outcome enumeration and the certified
        // memo remove that cost wherever the answers allow; a family whose answers
        // genuinely depend on every ordering of its pointers is still exponential,
        // and this budget is
        // what bounds it. A trip REFUSES the fold — the answer an in-progress cut gives:
        // `*local` keeps its opaque name and a store through it havocs — and is never
        // memoized. The compiler's post-generation checkpoint
        // (`preprocessing_budget_exceeded`) then replaces the function's whole
        // inventory with one `Unknown` budget row, so nothing generated after the
        // trip can be `Proved`.
        if trust_types::verify_budget::budget_exhausted() {
            return Prepared::Decided(false);
        }
        // Already being decided further out: the cut, opaque.
        if consult(fid, local) {
            return Prepared::Decided(false);
        }
        Prepared::Walk(WalkPlan { index, guards, b0, k0 })
    }

    /// At most this many choice sequences are enumerated per resolution; a
    /// resolution with more reports no outcome set and is decided exactly.
    const MAX_OUTCOME_RUNS: usize = 32;

    /// One enumeration run's choices: the ones fixed by the enumeration so far, then
    /// the ones this run took (each `false` first).
    struct Choices {
        taken: Vec<bool>,
        next: usize,
    }

    thread_local! {
        /// The outcome enumeration in progress on this thread, if any.
        static ENUMERATION: RefCell<Option<Choices>> = const { RefCell::new(None) };
    }

    fn enumerating() -> bool {
        ENUMERATION.with(|e| e.borrow().is_some())
    }

    /// The next choice of the run in progress.
    fn choose() -> bool {
        ENUMERATION.with(|e| {
            let mut e = e.borrow_mut();
            let Some(run) = e.as_mut() else {
                // Only `is_stable` calls this, and only while `enumerating()`.
                return false;
            };
            let choice = match run.taken.get(run.next) {
                Some(&fixed) => fixed,
                None => {
                    run.taken.push(false);
                    false
                }
            };
            run.next += 1;
            choice
        })
    }

    /// Trust: 2026-09-30 — THE OUTCOME ENUMERATION. Every value `compute` can return
    /// when each stability walk it would run is replaced by a FREE CHOICE, both ways —
    /// or `None` when there are more than [`MAX_OUTCOME_RUNS`] choice sequences.
    ///
    /// Exact by construction, and this is the whole argument: everything a
    /// resolution computes other than its walks is a pure function of the body and
    /// of the in-progress set (the unique defs, the guard filter, the region start,
    /// the cut — all still decided by `prepare`), and the in-progress set does not
    /// change while no walk runs. So the run that takes, at every choice, the answer
    /// the real walk WOULD give computes the real resolution, and that run is among
    /// the ones enumerated. A caller whose answer is the same for EVERY enumerated
    /// value therefore has the answer the real resolution would give it, without
    /// running a walk. The set may also hold values no real run produces (two walks
    /// of one key answered differently); that only makes agreement rarer.
    ///
    /// Depth-first over the choice tree, re-running `compute` per leaf: a run replays
    /// its prefix, and the next prefix flips the last `false` it took.
    fn outcomes<T: PartialEq>(compute: impl Fn() -> T) -> Option<Vec<T>> {
        if enumerating() {
            // Not reachable — no walk runs while enumerating, and only a walk asks —
            // but a nested enumeration would share the outer run's choices.
            return None;
        }
        /// Ends the enumeration on every exit, a panic included: a stale run would
        /// turn every later walk on this thread into a choice.
        struct End;
        impl Drop for End {
            fn drop(&mut self) {
                ENUMERATION.with(|e| *e.borrow_mut() = None);
            }
        }
        let _end = End;
        let mut prefix: Vec<bool> = Vec::new();
        let mut out: Vec<T> = Vec::new();
        for _ in 0..MAX_OUTCOME_RUNS {
            ENUMERATION.with(|e| *e.borrow_mut() = Some(Choices { taken: prefix, next: 0 }));
            let value = compute();
            let taken = ENUMERATION
                .with(|e| e.borrow_mut().take())
                .map(|run| run.taken)
                .unwrap_or_default();
            crate::fn_memo::count_fold_outcome_runs();
            if !out.contains(&value) {
                out.push(value);
            }
            let Some(last_false) = taken.iter().rposition(|&choice| !choice) else {
                return Some(out);
            };
            prefix = taken[..last_false].to_vec();
            prefix.push(true);
        }
        None
    }

    /// The walk. Refuses at a mention of the pointer local iff ANY guard is
    /// `Unknown` there.
    ///
    /// Trust: 2026-09-17 (round A13) — the PRECISE walk carries one state per guard
    /// and may re-establish `Same`; its state space is `2^|guards|` per block, which
    /// is finite (so it terminates) but not free. Past a budget proportional to the
    /// body, the walk restarts COLLAPSED — one bit for all guards, no
    /// re-establishment — which is byte-for-byte the pre-A13 decision procedure, so
    /// the fallback's cost and its precision are the ones this round inherited. The
    /// collapsed mask is `0` or "all", so its state space is 2 per block and it can
    /// never trip a budget of its own.
    fn walk(
        func: &VerifiableFunction,
        index: &Rc<FoldIndex>,
        local: usize,
        referent: &Place,
        guards: &[Place],
        b0: usize,
        k0: usize,
    ) -> bool {
        crate::fn_memo::count_fold_walks();
        let budget = 6 * func.body.blocks.len() + 64;
        let mut c0 = BorrowTimeConsts::new(func, guards, local, referent, b0, k0);
        // Trust: 2026-09-18 — one provenance taint per guard for the WHOLE walk,
        // precise run and collapsed fallback together. `written_place_rebinds` is asked
        // per statement per guard per visited state; the taint underneath it is
        // computed at most once per guard, and only for a guard that is actually
        // borrowed and actually met an unresolvable store.
        let taint = TaintCache::with_index(func, Rc::clone(index));
        if let Some(verdict) =
            walk_states(func, &taint, local, referent, guards, b0, k0, Some(&mut c0), budget)
        {
            return verdict;
        }
        walk_states(func, &taint, local, referent, guards, b0, k0, None, usize::MAX)
            .unwrap_or(false)
    }

    /// `None` iff the budget tripped; otherwise the verdict.
    ///
    /// `c0 == None` selects the COLLAPSED mode described on `walk`. Precision is
    /// monotone between the two: the precise mask is always a subset of the bits the
    /// collapsed run would hold at the same point (it sets only the guards actually
    /// rebound, and may clear), so the precise run can only refuse where the
    /// collapsed one already did.
    fn walk_states(
        func: &VerifiableFunction,
        taint: &TaintCache<'_>,
        local: usize,
        referent: &Place,
        guards: &[Place],
        b0: usize,
        k0: usize,
        mut c0: Option<&mut BorrowTimeConsts<'_>>,
        budget: usize,
    ) -> Option<bool> {
        let index_of = &taint.index.block_index;
        let all = all_unknown(guards);
        // Saturated guard sets (more than 64) get the collapsed decision too.
        let exact = c0.is_some() && guards.len() <= MASK_BITS;
        let collapse = |mask: GuardMask| if exact || mask == 0 { mask } else { all };
        let mut visited: FxHashSet<(usize, GuardMask)> = FxHashSet::default();
        let mut work: Vec<(usize, usize, GuardMask)> = vec![(b0, k0 + 1, 0)];
        let mut steps = 0usize;
        while let Some((b, start, mut mask)) = work.pop() {
            steps += 1;
            if steps > budget {
                return None;
            }
            // Trust: 2026-09-30 — the ambient per-function budget, once per visited
            // state. A trip refuses the fold (see `is_stable`); it is not the walk's own
            // `budget` above, whose trip only selects the collapsed rerun.
            if trust_types::verify_budget::budget_exhausted() {
                return Some(false);
            }
            let block = &func.body.blocks[b];
            crate::fn_memo::count_fold_walk_steps(1);
            crate::fn_memo::count_fold_stmt_visits(
                block.stmts.len().saturating_sub(start) as u64 + 1,
            );
            let mut redefined = false;
            for (k, stmt) in block.stmts.iter().enumerate().skip(start) {
                if b == b0 && k == k0 {
                    redefined = true;
                    break;
                }
                // The mention is evaluated BEFORE this statement's own write takes
                // effect, exactly as the single-boolean form did.
                if mask != 0 && stmt_mentions(stmt, local) {
                    return Some(false);
                }
                // Trust: 2026-09-30 — a guard already `Unknown` stays `Unknown` unless
                // this statement can re-establish it, so its answer is not asked; in
                // the collapsed mode any set bit already means "all".
                let known = if !shortcuts_enabled() {
                    0
                } else if exact {
                    mask & !reestablishable(stmt, guards)
                } else if mask != 0 {
                    !0
                } else {
                    0
                };
                let rebound = guards_rebound_by_stmt(taint, stmt, guards, local, referent, known);
                if rebound != 0 {
                    let mut next = mask | rebound;
                    if exact && let Some(consts) = c0.as_deref_mut() {
                        for i in 0..guards.len() {
                            if rebound & guard_bit(i) != 0
                                && let Some(c) = reestablishes_guard(stmt, &guards[i])
                                && consts.get(taint, i) == Some(c)
                            {
                                next &= !guard_bit(i);
                            }
                        }
                    }
                    mask = collapse(next);
                }
            }
            if redefined {
                continue;
            }
            let term = &block.terminator;
            if mask != 0 && terminator_mentions_before(term, local) {
                return Some(false);
            }
            // A terminator never re-establishes: no terminator writes a guard with a
            // constant this walk can name (a `Call` destination is exactly the channel
            // the re-establishment rule excludes).
            let known = if !shortcuts_enabled() {
                0
            } else if exact {
                mask
            } else if mask != 0 {
                !0
            } else {
                0
            };
            let rebound = guards_rebound_by_terminator(taint, term, guards, local, referent, known);
            if rebound != 0 {
                mask = collapse(mask | rebound);
            }
            if mask != 0 && terminator_mentions_after(term, local) {
                return Some(false);
            }
            if !try_for_each_successor(term, |succ| {
                let Some(idx) = index_of.get(&succ) else {
                    return false;
                };
                if visited.insert((idx, mask)) {
                    work.push((idx, 0, mask));
                }
                true
            }) {
                return Some(false);
            }
        }
        Some(true)
    }

    /// THE PIN FOR THE FORGED-POINTER CHANNEL, on hand-built MIR.
    ///
    /// Trust: 2026-09-18 (reviewer round 2). The 2026-09-18 narrowing replaced
    /// [`written_place_rebinds`]' unattributable-store arm — "does a borrow of the
    /// guard exist ANYWHERE" — with [`unattributable_store_rebinds`], a provenance
    /// question about the store's own pointer local. That recovered a measured false
    /// refutation and opened a measured false-PROVE direction: a pointer FORGED from
    /// an integer has no derivation chain from any borrow, so the taint left it clean
    /// and the fold stood across a store that may land in the guard's own slot.
    ///
    /// Both directions are pinned here, on the SAME four-statement body, because the
    /// fix is a discriminator and a test of one direction alone cannot see it:
    ///
    /// ```ignore (illustrative)
    /// _4 = &_1                   // a SHARED borrow of the guard: the alias gate opens
    /// _3 = <source>              // an integer, or an address
    /// _5 = _3 as *mut usize      // the cast
    /// (*_5) = copy _2            // the unattributable store
    /// ```
    ///
    /// `_5`'s unique def is an `Rvalue::Cast`, which `resolve_referent` answers `None`
    /// for, so the unattributable arm is the arm reached in every row below — the
    /// `the_unattributable_arm_is_the_arm_reached` assertion keeps that true if the
    /// resolver ever grows a `Cast` case.
    #[cfg(test)]
    mod forged_pointer_channel {
        use trust_types::{
            BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue,
            SourceSpan, Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
        };

        use super::{TaintCache, slot_is_aliased_anywhere, written_place_rebinds};

        fn usize_ty() -> Ty {
            Ty::Int { width: 64, signed: false }
        }

        fn raw_mut(ty: Ty) -> Ty {
            Ty::RawPtr { mutable: true, pointee: Box::new(ty) }
        }

        fn raw_const(ty: Ty) -> Ty {
            Ty::RawPtr { mutable: false, pointee: Box::new(ty) }
        }

        fn raw_mut_usize() -> Ty {
            raw_mut(usize_ty())
        }

        fn raw_const_usize() -> Ty {
            raw_const(usize_ty())
        }

        /// The POINTER NEWTYPE `v6_shared_param_drop_ctl`'s `vec![..]` desugar actually
        /// casts from: `_28 = copy ((_16.0: Unique<_>).0: NonNull<_>) as *const _`. Its
        /// `Ty` is an `Adt`, NOT a `Ty::RawPtr` — which is why
        /// [`super::ty_carries_pointer_provenance`] is structural.
        fn non_null_usize() -> Ty {
            Ty::adt(
                "core::ptr::non_null::NonNull",
                vec![("pointer".to_string(), raw_const_usize())],
            )
        }

        fn assign(place: Place, rvalue: Rvalue) -> Statement {
            Statement::Assign { place, rvalue, span: SourceSpan::default() }
        }

        fn store_through_5() -> Place {
            Place { local: 5, projections: vec![Projection::Deref] }
        }

        /// `_1` is the guard, `_2` the stored value, `_3` the cast's source (declared
        /// `src_ty`, optionally defined by `src_def`), `_4` the shared borrow of the
        /// guard, `_5` the store's pointer.
        fn body(src_ty: Ty, src_def: Option<Rvalue>) -> VerifiableFunction {
            let locals = vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: usize_ty(), name: None },
                LocalDecl { index: 2, ty: usize_ty(), name: None },
                LocalDecl { index: 3, ty: src_ty, name: None },
                LocalDecl {
                    index: 4,
                    ty: Ty::Ref { mutable: false, inner: Box::new(usize_ty()) },
                    name: None,
                },
                LocalDecl { index: 5, ty: raw_mut_usize(), name: None },
            ];
            let mut stmts = vec![assign(
                Place::local(4),
                Rvalue::Ref { mutable: false, place: Place::local(1) },
            )];
            if let Some(def) = src_def {
                stmts.push(assign(Place::local(3), def));
            }
            stmts.push(assign(
                Place::local(5),
                Rvalue::Cast(Operand::Copy(Place::local(3)), raw_mut_usize()),
            ));
            stmts.push(assign(store_through_5(), Rvalue::Use(Operand::Copy(Place::local(2)))));
            VerifiableFunction {
                name: "forged_pointer_channel".to_string(),
                def_path: "test::forged_pointer_channel".to_string(),
                span: SourceSpan::default(),
                body: VerifiableBody {
                    locals,
                    blocks: vec![BasicBlock {
                        id: BlockId(0),
                        stmts,
                        terminator: Terminator::Return,
                    }],
                    arg_count: 2,
                    return_ty: Ty::Unit,
                    datatype_defs: Default::default(),
                },
                contracts: vec![],
                preconditions: vec![],
                postconditions: vec![],
                spec: Default::default(),
                tuple_layouts: Default::default(),
            }
        }

        /// The question the reviewer measured: does the store through `_5` refuse the
        /// fold of a referent guarded by `_1`? `under_test` is deliberately a local the
        /// body does not have, so the arm cannot short-circuit through the
        /// "`written.local` IS the local under test" case.
        fn rebinds(func: &VerifiableFunction) -> bool {
            let taint = TaintCache::new(func);
            written_place_rebinds(&taint, &store_through_5(), &Place::local(1), 9, &Place::local(9))
        }

        /// Neither direction below means anything unless the alias gate is OPEN (a
        /// borrow of the guard exists) and the store is genuinely unattributable.
        #[test]
        fn the_unattributable_arm_is_the_arm_reached() {
            for (src_ty, src_def) in
                [(usize_ty(), None), (raw_const_usize(), None), (non_null_usize(), None)]
            {
                let func = body(src_ty, src_def);
                assert!(
                    slot_is_aliased_anywhere(&func, &Place::local(1)),
                    "the shared `_4 = &_1` must keep the alias gate open, or every row here is vacuous"
                );
                assert!(
                    super::super::resolve_referent(&func, 5, super::NESTED_FUEL).is_none(),
                    "`_5`'s def is an `Rvalue::Cast`: the store must stay unattributable"
                );
            }
        }

        /// THE HOLE. A pointer forged from an integer can name ANY storage, the guard's
        /// slot included, with no borrow of the guard anywhere in its derivation. The
        /// forward taint sees no chain and would admit the fold; the fold's name would
        /// then survive a store that may rebind the guard — the FALSE-PROVE direction.
        ///
        /// It must REFUSE, and it must refuse on the source TYPE rather than on the
        /// presence of a definition for `_3`: an `Rvalue::Cast` carries no `CastKind`
        /// in this crate's model, so a `transmute::<usize, *mut usize>` is this same
        /// row.
        #[test]
        fn an_address_forged_from_an_integer_refuses_the_fold() {
            let literal = Rvalue::Use(Operand::Constant(ConstValue::Uint(0x7fff_1234, 64)));
            for src_def in [Some(literal), None] {
                let func = body(usize_ty(), src_def);
                assert!(
                    rebinds(&func),
                    "a `usize as *mut usize` store must still refuse the fold of a guard \
                     this body borrows"
                );
            }
        }

        fn copy_nonoverlapping_probe(
            elem_ty: Ty,
            count: Operand,
            source_rvalue: Rvalue,
        ) -> VerifiableFunction {
            let locals = vec![
                LocalDecl { index: 0, ty: Ty::Unit, name: None },
                LocalDecl { index: 1, ty: usize_ty(), name: None },
                LocalDecl { index: 2, ty: usize_ty(), name: None },
                LocalDecl { index: 3, ty: elem_ty.clone(), name: None },
                LocalDecl {
                    index: 4,
                    ty: Ty::Ref { mutable: false, inner: Box::new(usize_ty()) },
                    name: None,
                },
                LocalDecl { index: 5, ty: raw_mut_usize(), name: None },
                LocalDecl { index: 6, ty: raw_const(elem_ty.clone()), name: None },
                LocalDecl { index: 7, ty: raw_mut(raw_mut_usize()), name: None },
                LocalDecl { index: 8, ty: raw_mut(elem_ty.clone()), name: None },
            ];
            let stmts = vec![
                // the alias gate: a shared borrow of the guard
                assign(Place::local(4), Rvalue::Ref { mutable: false, place: Place::local(1) }),
                // source storage: a plain integer in the forging row, a pointer in controls
                assign(Place::local(3), source_rvalue),
                // &raw mut _5 is *mut *mut usize; copy::<usize> needs a pointer cast.
                // Neither pointer is derived from the borrow of the guard.
                assign(Place::local(6), Rvalue::AddressOf(false, Place::local(3))),
                assign(Place::local(7), Rvalue::AddressOf(true, Place::local(5))),
                assign(
                    Place::local(8),
                    Rvalue::Cast(Operand::Copy(Place::local(7)), raw_mut(elem_ty.clone())),
                ),
                // memcpy bytes INTO the pointer local
                Statement::CopyNonOverlapping {
                    src: Operand::Copy(Place::local(6)),
                    dst: Operand::Copy(Place::local(8)),
                    count,
                    elem_ty,
                    span: SourceSpan::default(),
                },
                // the unattributable store through the forged address
                assign(store_through_5(), Rvalue::Use(Operand::Copy(Place::local(2)))),
            ];
            VerifiableFunction {
                name: "copy_nonoverlapping_probe".to_string(),
                def_path: "test::copy_nonoverlapping_probe".to_string(),
                span: SourceSpan::default(),
                body: VerifiableBody {
                    locals,
                    blocks: vec![BasicBlock {
                        id: BlockId(0),
                        stmts,
                        terminator: Terminator::Return,
                    }],
                    arg_count: 2,
                    return_ty: Ty::Unit,
                    datatype_defs: Default::default(),
                },
                contracts: vec![],
                preconditions: vec![],
                postconditions: vec![],
                spec: Default::default(),
                tuple_layouts: Default::default(),
            }
        }

        /// THE `CopyNonOverlapping` CHANNEL — CLOSED AS OF 2026-09-23.
        ///
        /// `docs/KNOWN_HAZARDS.md` carried this as "STILL OPEN, none measured" since
        /// 2026-09-18. The 2026-09-22 measurement exposed the SECOND forged-pointer
        /// channel: same shape as
        /// [`an_address_forged_from_an_integer_refuses_the_fold`] above, except `_5`
        /// receives its address by MEMCPY of integer bytes rather than by a cast.
        ///
        /// It defeated both guards BY CONSTRUCTION: the only `Rvalue::Cast` is
        /// pointer-to-pointer, so it does not forge provenance; the normal
        /// `Statement::CopyNonOverlapping` taint arm sees only raw pointers to `_3`
        /// and `_5`, neither derived from the guard.
        ///
        /// The fix is deliberately narrower than "any memcpy forges": the body-global
        /// seed fires only for a maybe-nonzero copy whose element type cannot be shown
        /// to carry pointer provenance into storage whose declared value may carry it.
        /// That closes the false-PROVE row below without re-refusing the pointer-typed
        /// copy controls.
        #[test]
        fn copy_nonoverlapping_integer_bytes_into_pointer_storage_refuse_the_fold() {
            let func = copy_nonoverlapping_probe(
                usize_ty(),
                Operand::Constant(ConstValue::Uint(1, 64)),
                Rvalue::Use(Operand::Constant(ConstValue::Uint(0x7fff_1234, 64))),
            );
            assert!(
                slot_is_aliased_anywhere(&func, &Place::local(1)),
                "ANTI-VACUITY: the `_4 = &_1` alias gate must be open"
            );
            assert!(
                super::super::resolve_referent(&func, 5, super::NESTED_FUEL).is_none(),
                "ANTI-VACUITY: `_5` has no Assign def, so the store must be unattributable"
            );
            let Statement::Assign {
                place: cast_dest,
                rvalue: cast @ Rvalue::Cast(Operand::Copy(from), to),
                ..
            } = &func.body.blocks[0].stmts[4]
            else {
                panic!("the copy destination must be formed by an explicit pointer cast");
            };
            assert_eq!(cast_dest, &Place::local(8));
            assert_eq!(from, &Place::local(7));
            assert_eq!(to, &raw_mut_usize());
            assert_eq!(func.body.locals[7].ty, raw_mut(raw_mut_usize()));
            assert_eq!(func.body.locals[8].ty, raw_mut_usize());
            assert!(
                !super::cast_forges_pointer_provenance(&func, cast),
                "the *mut *mut usize to *mut usize cast must not seed a forge"
            );
            assert!(
                super::copy_destination_storage_ty(&func, &Operand::Copy(Place::local(8)), 0, 5,)
                    .is_none(),
                "the cast destination must take the unknown-storage fallback"
            );
            assert!(
                super::body_forges_a_pointer(&func),
                "ANTI-VACUITY: the memcpy forge must seed the fail-closed taint sink"
            );
            assert!(
                rebinds(&func),
                "integer bytes copied into pointer storage can forge the later store \
                 pointer and must refuse the referent fold"
            );

            let mut without_copy = func.clone();
            without_copy.body.blocks[0]
                .stmts
                .retain(|stmt| !matches!(stmt, Statement::CopyNonOverlapping { .. }));
            assert!(!super::body_forges_a_pointer(&without_copy));
            assert!(
                !rebinds(&without_copy),
                "without the copy, the pointer-to-pointer cast alone must admit the fold"
            );
        }

        #[test]
        fn copy_nonoverlapping_pointer_bytes_still_admit_the_fold() {
            let elem_ty = raw_mut_usize();
            let func = copy_nonoverlapping_probe(
                elem_ty,
                Operand::Constant(ConstValue::Uint(1, 64)),
                Rvalue::AddressOf(true, Place::local(2)),
            );
            assert!(
                !super::body_forges_a_pointer(&func),
                "a pointer-typed element carries provenance and must not trip the \
                 CopyNonOverlapping forge seed"
            );
            assert!(
                !rebinds(&func),
                "a pointer-typed copy should keep the same precision as the cast \
                 pointer-to-pointer recovery row"
            );
        }

        #[test]
        fn copy_nonoverlapping_zero_count_does_not_forge() {
            let func = copy_nonoverlapping_probe(
                usize_ty(),
                Operand::Constant(ConstValue::Uint(0, 64)),
                Rvalue::Use(Operand::Constant(ConstValue::Uint(0x7fff_1234, 64))),
            );
            assert!(
                !super::body_forges_a_pointer(&func),
                "a provably zero-length copy does not write integer bytes into pointer \
                 storage"
            );
            assert!(!rebinds(&func), "zero-length copy remains inert for the fold");
        }

        /// THE ROW THE REFUSAL ABOVE MAY NOT REACH — the recovery this whole fix
        /// exists for. `v6_shared_param_drop_ctl`'s `vec![..]` desugar casts a
        /// `NonNull` (and, one statement later, a `*const _`) into the pointer it
        /// stores through, while the body's only borrow of the guard is a shared one
        /// that nothing connects to it. Both spellings carry an address, so the
        /// forward taint — not a syntactic "the source is unattributable" — decides
        /// them, and here it decides ADMIT.
        ///
        /// The `NonNull` row is the one that makes the structural walk load-bearing:
        /// with a `matches!(src, Ty::RawPtr { .. } | Ty::Ref { .. })` test in
        /// [`super::ty_carries_pointer_provenance`] it reads REFUSE, and
        /// `a_vec_in_scope_no_longer_refutes_a_shared_borrow_of_the_guard` in
        /// `tests/referent_fold_provenance.rs` goes red with it.
        #[test]
        fn an_address_cast_from_an_address_still_admits_the_fold() {
            for src_ty in [raw_const_usize(), non_null_usize()] {
                let func = body(src_ty.clone(), None);
                assert!(
                    !rebinds(&func),
                    "a pointer-to-pointer cast carries provenance the taint follows; \
                     source {src_ty:?} must not re-refuse the fold"
                );
            }
        }

        /// Trust: 2026-09-18 (adversarial round) — the rows above pin the two
        /// SPELLINGS the reviewer measured. These pin the DIRECTIONS: every way a
        /// source can fail to be an address, and the target-side unknown that the
        /// shipped form answered in the admitting direction.
        mod both_unknown_directions {
            use trust_types::VariantDef;

            use super::*;

            /// Every spelling of "the source is NOT an address" must REFUSE, and each
            /// one is a real MIR shape, not a synthetic one.
            #[test]
            fn every_non_address_source_refuses() {
                let rows: Vec<(&str, Ty, Option<Rvalue>)> = vec![
                    // `usize` on the FAITHFUL extraction lane.
                    ("PtrSizedInt", Ty::PtrSizedInt { signed: false }, None),
                    // A type this crate could not lower at all.
                    ("Unsupported", Ty::Unsupported { kind: "k".into(), detail: "d".into() }, None),
                    // An ADT with no pointer anywhere — a struct-wrapped integer.
                    (
                        "Adt-without-pointer",
                        Ty::adt("W", vec![("0".to_string(), Ty::Int { width: 64, signed: false })]),
                        None,
                    ),
                    // An ENUM whose pointer lives only in a VARIANT field must be
                    // found (control for the `variants` recursion), so this
                    // pointer-free enum must still refuse.
                    (
                        "enum-without-pointer",
                        Ty::adt_enum(
                            "E",
                            vec![VariantDef {
                                name: "A".into(),
                                discriminant: 0,
                                fields: vec![("0".into(), Ty::Bool)],
                            }],
                        ),
                        None,
                    ),
                    ("Bv", Ty::Bv(64), None),
                    ("Float", Ty::Float { width: 64 }, None),
                    (
                        "int-literal-def",
                        Ty::Int { width: 64, signed: false },
                        Some(Rvalue::Use(Operand::Constant(ConstValue::Uint(0x7fff_1234, 64)))),
                    ),
                ];
                for (label, src_ty, def) in rows {
                    let func = body(src_ty, def);
                    assert!(rebinds(&func), "{label}: a forged address must REFUSE the fold");
                }
            }

            /// The cast's operand is the integer CONSTANT itself — what `-O1`
            /// const-propagation actually produces — with no `_3` in the chain.
            #[test]
            fn a_constant_integer_operand_refuses() {
                let mut func = body(Ty::Int { width: 64, signed: false }, None);
                let stmts = &mut func.body.blocks[0].stmts;
                stmts[1] = assign(
                    Place::local(5),
                    Rvalue::Cast(
                        Operand::Constant(ConstValue::Uint(0x7fff_1234, 64)),
                        raw_mut_usize(),
                    ),
                );
                assert!(rebinds(&func), "`0x7fff1234usize as *mut usize` must REFUSE the fold");
            }

            /// An ADT that carries its pointer only in a VARIANT must ADMIT — pins the
            /// `variants` half of the structural walk as load-bearing.
            #[test]
            fn a_pointer_in_an_enum_variant_still_admits() {
                let src = Ty::adt_enum(
                    "E",
                    vec![VariantDef {
                        name: "A".into(),
                        discriminant: 0,
                        fields: vec![("0".into(), raw_const_usize())],
                    }],
                );
                let func = body(src, None);
                assert!(!rebinds(&func), "a pointer inside a variant carries provenance");
            }

            /// THE PRECISION COST, MEASURED: the forging cast is UNRELATED to the
            /// store — a different local, a different pointer — and the store's own
            /// pointer is honestly address-derived. The seed is body-global, so this
            /// body is refused anyway. This is a NEW refusal; it must be a real one.
            #[test]
            fn an_unrelated_forging_cast_refuses_body_globally() {
                let mut func = body(raw_const_usize(), None);
                func.body.locals.push(LocalDecl { index: 6, ty: usize_ty(), name: None });
                func.body.locals.push(LocalDecl { index: 7, ty: raw_mut_usize(), name: None });
                // `_7 = _6 as *mut usize` — nothing to do with `_5` or the guard.
                func.body.blocks[0].stmts.push(assign(
                    Place::local(7),
                    Rvalue::Cast(Operand::Copy(Place::local(6)), raw_mut_usize()),
                ));
                assert!(
                    rebinds(&func),
                    "the seed is body-global: an unrelated forging cast refuses every \
                     unattributable store in the body"
                );
            }

            /// THE TARGET-SIDE UNKNOWN. A cast whose TARGET this crate could not lower
            /// (`Ty::Unsupported`, which `ty_convert`'s produced-node-budget degrade
            /// really mints) must still be examined: answering "not a pointer target"
            /// there ADMITS a fold across a store through an address forged from a
            /// `usize`, which is the false-PROVE direction. Measured ADMIT before the
            /// `unknown` parameter existed.
            #[test]
            fn an_unlowerable_cast_target_is_still_treated_as_an_address() {
                let opaque = Ty::Unsupported { kind: "k".into(), detail: "d".into() };
                let mut func = body(usize_ty(), None);
                func.body.locals[5].ty = opaque.clone();
                func.body.blocks[0].stmts[1] =
                    assign(Place::local(5), Rvalue::Cast(Operand::Copy(Place::local(3)), opaque));
                assert!(
                    rebinds(&func),
                    "a target this walk cannot classify must not ADMIT the fold: \
                     `unknown` is `true` on the target side"
                );
            }
        }
    }

    /// Trust: 2026-09-30 — the cost fix's exactness, cost and budget pins, and (2026-10-02)
    /// the pins of the verdict certificate, the outcome cap and the budget-trip filters:
    /// `referent_fold/fold_cost_fix.rs`.
    #[cfg(test)]
    mod fold_cost_fix;
}

/// True iff a store `*p = v` rooted at `local` (`p`) names an OPAQUE pointer —
/// i.e. `canonicalize_deref` cannot fold `*p` to a concrete referent place, so
/// `place_to_var_name(*p)` is the opaque `p*` that does NOT overlap the real
/// referent's name. This is EXACTLY when the store's mutation is invisible to the
/// name-based redef kill, so a fact about the referent survives stale.
///
/// Covers every non-foldable pointer provenance: a reseated / multiply-`&mut`-
/// borrowed pointer (no unique whole-local def), a pointer parameter, a
/// call-returned pointer, AND a CAST-laundered pointer (`&mut x as *mut T`,
/// `IntToPtr`, pointer arithmetic) whose unique def is an `Rvalue::Cast`/BinaryOp
/// that `resolve_referent` cannot fold (its `_ => None` arm).
///
/// THE CONTRACT IS STATED AGAINST THE MINT, NOT AGAINST THE RESOLVER:
///
/// > opaque ⟺ the mint kept the `local*` spelling, i.e.
/// > `canonicalize_deref(func, *local, 16)` came back as `*local`.
///
/// Trust: 2026-09-18 — THE BICONDITIONAL WAS BROKEN BY ROUND A12, and this is
/// the shape of the break. Until round A12 `canonicalize_deref` had exactly
/// three non-folding exits — no fuel, no leading `Deref`, and
/// `resolve_referent == None` — so a predicate spelled
/// `resolve_referent(func, local, 16).is_none()` did mirror the mint for the
/// bare `*local` probe, and the doc above said so. The A12 soundness fix added a
/// FOURTH exit in `canonicalize_deref_guarded`: when the referent folds further
/// (`folded != referent`) but the `reread_through` re-resolution refuses, the
/// mint returns the UNFOLDED `place` — and it does so on a path where
/// `resolve_referent_guarded` has ALREADY answered `Some(slot)` (the
/// `let Some(slot) = .. else { return place }` above it did not fire). On that
/// exit the old predicate answered FALSE while `place_to_var_name` spelled the
/// store `p*`: a store whose name does not overlap the name a READ of the same
/// storage gets, so `write_rebinds` is false, `formula_mentions_redef` does not
/// kill the stale fact, and `deref_store_havoc_names` — gated on THIS predicate —
/// produced an empty list. That is precisely the configuration the first
/// paragraph calls "invisible to the name-based redef kill".
///
/// HOW REACHABLE, measured by reading on 2026-09-18 and NOT by running: the
/// fourth exit needs `resolve_referent` to hand back a slot that still folds
/// further, and every slot it hands back has already been folded — the
/// `Rvalue::Ref` arm runs `canonicalize_deref_guarded` on the borrowed place,
/// and `referent_of_source`'s `deref_of` fallbacks fire only for a local with no
/// whole-local def, which is a fold fixpoint at every fuel. The induction leaves
/// exactly one base case: FUEL. The slot is resolved at `fuel - 2` and re-folded
/// at `fuel - 1`, so a reborrow chain deep enough to truncate at 16 folds one
/// hop further on the re-fold and lands on this exit. No witness program was
/// built — the fold re-resolves its carrier at every level, and a 1..=12
/// depth sweep of the shape did not terminate in 14 minutes of CPU. So this fix
/// is shipped as a fail-closed ALIGNMENT of a broken contract, not as the repair
/// of a demonstrated live false proof.
///
/// The fix asks the mint rather than re-deriving one of its exits, so a future
/// fifth exit cannot re-open the same hole. The `resolve_referent` disjunct is
/// KEPT rather than replaced: the probe reaches `resolve_referent_guarded` with
/// `fuel - 1` (15), where the old spelling asked at 16, and a resolution is NOT
/// monotone in fuel (`referent_of_source`'s `None if local_is_never_written`
/// fallbacks take a DIFFERENT branch when a deeper resolution succeeds), so a
/// bare replacement could answer FALSE where the old answered TRUE and REMOVE
/// havoc. As a disjunction the change only ever ADDS opacity — every old `true`
/// is still `true` — which is the fail-closed direction: more havoc can cost a
/// proof, never grant one.
///
/// WHAT THIS LOCAL-KEYED FORM DOES NOT COVER — and why every caller now asks
/// [`deref_store_is_opaque`] instead. The predicate is keyed on the LOCAL, so it
/// probes the bare `*local`; a store with further projections (`(*p)[_j]`,
/// `(*p).f`, `**p`) folds `slot ++ rest`, and the suffix changes the mint's
/// answer in two ways: `rest`'s own `Index`/`Deref` components ADD guards to
/// `reread_through`'s widened re-resolution (`guards(folded ++ rest) ⊇
/// guards(folded)`), and a `rest` that begins with `Deref` can make a referent
/// FOLD that was a fold fixpoint bare — which reaches the fourth exit on a path
/// where the bare probe returned at the third. A refusal on either route is
/// invisible to this probe. That residual is now MEASURED, not conjectured:
/// `a_projected_store_escapes_the_local_keyed_probe` builds the witness (a
/// shared `&x` of a `&mut` pointer, `**q = 7`, with the referent's index guard
/// rebound in between) on which this function answers `false` while the mint
/// keeps the opaque `_5**` spelling for the store. `deref_store_is_opaque` calls
/// this function FIRST and returns its `true` unchanged, so the local-keyed
/// answer survives as the fast path and as the monotonicity floor; it is no
/// longer the whole answer.
///
/// verifier-perf: `resolve_referent` walks every block/statement of `func`, and
/// this predicate is queried once per statement by several gen-set oracles, so
/// the raw form is quadratic in function size. Memoized per `(func, local)` —
/// a pure function of exactly those two, see `havoc_memo` for why a hit can
/// never replay another function's answer. The mint probe runs ONLY when the
/// resolver disjunct already answered `Some`, and `canonicalize_deref` is the
/// same family of walks `resolve_referent` already performs (its first act IS
/// `resolve_referent_guarded`), so the decision stays one memoized answer per
/// local — what `tests/vcgen_budget_realmir.rs` bounds by `locals_n`.
///
/// NO RE-ENTRY. Since 2026-09-18 this function's only non-test caller is
/// `deref_store_is_opaque`, which holds the four call sites this paragraph used
/// to name directly (`generate::path_defs` x3, `generate::block_defs` x1); the
/// argument is unchanged because the callee set is. None of them is
/// reachable from `canonicalize_deref`, `resolve_referent*`,
/// `referent_of_source`, `reread_through`, `referent_fold` or `local_defs`, so
/// probing the mint from inside the predicate cannot re-enter the predicate.
/// `havoc_memo::cached_flag` also releases its `RefCell` borrow before running
/// this closure, so the nested `referent_fold` memo traffic the probe generates
/// is safe — the `resolve_referent` disjunct already generated it.
pub(crate) fn deref_pointer_is_opaque(func: &VerifiableFunction, local: usize) -> bool {
    havoc_memo::opaque_pointer(func, local, || {
        // verifier-perf instrumentation (see `fn_memo`): count the opacity
        // DECISIONS this predicate actually RUNS, so the census budget
        // regression test can pin a deterministic work bound whichever memo
        // serves the query. Diagnostic only; never part of a verdict.
        fn_memo::count_deref_opacity();
        // The pre-A12 exit, kept verbatim: no referent at all. Asked first
        // because it is the answer for every non-pointer local, and a `None`
        // here saves the probe below.
        if resolve_referent(func, local, 16).is_none() {
            return true;
        }
        // The contract: ask the MINT. `place_to_var_name` canonicalizes with
        // `canonicalize_place(func, place, 16)`, whose first act is exactly this
        // call, so a `*local` that comes back unchanged is a `local*` name.
        // (`canonicalize_place` can still fold further through
        // `base_value_alias`; that only ever turns a name we called opaque into
        // a folded one, i.e. adds havoc.)
        let bare = deref_of(&Place::local(local));
        let folded = canonicalize_deref(func, bare.clone(), 16);
        folded == bare || fold_lands_behind_an_unresolved_pointer(func, &folded)
    })
}

/// True iff `folded` — the canonical place a deref folded to — still begins with a
/// `Deref` of a NON-parameter local whose own deref does not resolve: the fold
/// stopped one pointer short of the memory it names.
///
/// Trust (2026-09-29): `let z = &mut s[0]; *z = 250` folds `*z` to `(*s)[0 of 1]`,
/// so the store was judged a precise write of `s*[0;min=1]` with no deref-store
/// havoc. But `s` itself was an unsize cast of `&mut arr` (or the join of two
/// reborrows, or a pointer moved out of an `Option` or a one-element array), whose
/// referent does not resolve, so the same element is ALSO named through `arr`, and a
/// guard on `arr*[0;min=4]` survived the store: an adversarial audit found 14 such
/// programs PROVED that overflow or index out of bounds, all proved by the
/// 2026-09-17 pack as well (`tests/ui/trust/store_through_an_unresolved_pointer_refused.rs`).
/// A fold that lands on a PARAMETER's pointee stays precise: nothing else in the
/// body names that memory, which is what keeps `let x = &mut self.n; *x += 1` a
/// precise write of `self*.0`.
fn fold_lands_behind_an_unresolved_pointer(func: &VerifiableFunction, folded: &Place) -> bool {
    if folded.projections.first() != Some(&Projection::Deref)
        || local_defs::is_parameter(func, folded.local)
    {
        return false;
    }
    if resolve_referent(func, folded.local, 16).is_none() {
        return true;
    }
    let root = deref_of(&Place::local(folded.local));
    canonicalize_deref(func, root.clone(), 16) == root
}

/// THE STORE-SITE FORM of [`deref_pointer_is_opaque`]: is the store to `place`
/// — a deref store, `place.projections` beginning with `Deref` — one whose
/// minted name does NOT overlap the name a read of the referent gets, so that
/// the deref-store havoc must cover it?
///
/// Trust: 2026-09-18 — WHY THE KEY MOVED FROM THE LOCAL TO THE PLACE. The
/// contract [`deref_pointer_is_opaque`] states is about the MINT, and the mint
/// is a function of the written PLACE, not of its root local. The four call
/// sites all hold the written place and all asked about `place.local`, so a
/// store with projections beyond the leading `Deref` was decided by a probe of a
/// DIFFERENT place (`*local`) than the one being minted. When those two answers
/// disagree the store escapes the name kill (its name is the opaque `p*…`) AND
/// the havoc (the local-keyed probe said "folds"), which is the false-proof
/// shape the predicate exists to prevent. `a_projected_store_escapes_the_local_
/// keyed_probe` is that disagreement, built and run.
///
/// MONOTONICITY, which is the soundness obligation and is discharged by the
/// SHAPE of this function rather than by an induction. The local-keyed answer is
/// the FIRST DISJUNCT, evaluated first and returned unchanged: every local the
/// old predicate called opaque is still opaque, for every place rooted at it, by
/// construction. Nothing this function adds can REMOVE havoc — it can only add
/// it, the same fail-closed direction round A12's mint disjunct added, and for
/// the same reason (more havoc drops hypotheses, which can cost a proof and can
/// never grant one). That matters because resolution is NOT monotone in fuel: a
/// place probe spelled as a REPLACEMENT could answer `false` where the local one
/// answered `true` (the local disjunct asks `resolve_referent` at 16, while a
/// place probe reaches `resolve_referent_guarded` at 15), and that direction is
/// the one that mints false proofs.
///
/// EXIT BY EXIT, for the refinement itself. `canonicalize_deref(func, place, 16)`
/// returns `place` — the opaque spelling, hence `true` here — at exactly the four
/// non-folding exits of `canonicalize_deref_guarded`:
///   1. `fuel == 0`: unreachable at the top call (16).
///   2. no leading `Deref`: excluded by the guard below (and by every call site,
///      each of which tests the leading projection before asking).
///   3. `resolve_referent_guarded(place.local, 15, []) == None`: this is the
///      SAME call the bare probe makes (same local, same fuel, same empty
///      guards), so exit 3 adds nothing the local-keyed answer did not already
///      have — it is re-derived, never contradicted.
///   4. the referent folds further and `reread_through` refuses: the only exit
///      where the suffix can matter, and the one the witness lands on.
/// The non-`place` returns are the folded spellings, on which this function
/// answers `false` — i.e. it defers to the local-keyed answer already computed
/// above, which was also `false`. So the refinement is a pure superset.
///
/// COST, and the budget row it must keep true. `tests/vcgen_budget_realmir.rs`
/// asserts `deref_opacity_computed <= locals_n`. That counter keeps its exact
/// meaning — ONE DECISION PER LOCAL, counted in [`deref_pointer_is_opaque`] and
/// nowhere else — so the bound stands as written: a function still has one
/// local-keyed opacity decision per local. The refinement is a SECOND, smaller
/// key space, memoized by `havoc_memo::opaque_store_place` and entered only when
/// (a) the local-keyed answer was `false` and (b) the store place carries a
/// projection beyond the leading `Deref`. Its computations are therefore bounded
/// by the number of DISTINCT projected deref-store places in the body — at most
/// one per `Assign`, and one `canonicalize_deref` each, the same family of walks
/// `resolve_referent` already performs. NOT MEASURED HERE, and said plainly: the
/// census has no counter for the place key (adding one means editing
/// `fn_memo.rs`, outside this change's file set), so the budget test does not
/// yet bound this work. It is bounded by the memo, not by a test.
///
/// NO RE-ENTRY, re-derived for this form. The callee set is unchanged —
/// `deref_pointer_is_opaque` and `canonicalize_deref`, both of which this
/// function's predecessor already called — so the argument on
/// [`deref_pointer_is_opaque`] carries over verbatim: none of the four call
/// sites (`generate::path_defs` x3, `generate::block_defs` x1) is reachable from
/// `canonicalize_deref`, `resolve_referent*`, `referent_of_source`,
/// `reread_through`, `referent_fold` or `local_defs`, so probing the mint cannot
/// re-enter this predicate. The one NEW thing is the memo entry, and
/// `havoc_memo::opaque_store_place` releases its `RefCell` borrow before running
/// the closure exactly as `cached_flag` does, so the nested `fold_stable` memo
/// traffic the probe generates is safe.
pub(crate) fn deref_store_is_opaque(func: &VerifiableFunction, place: &Place) -> bool {
    // The fast path AND the monotonicity guarantee: today's answer, memoized per
    // local, returned unchanged whenever it is `true`.
    if deref_pointer_is_opaque(func, place.local) {
        return true;
    }
    // A BARE `*p` store needs no refinement: `canonicalize_deref(func, *p, 16) ==
    // *p` is literally the second disjunct the local-keyed answer just evaluated
    // to `false`. Re-asking it would cost a walk and a memo entry per store to
    // re-derive a known answer. A place with no leading `Deref` is not a deref
    // store at all (no call site asks about one); answering it with the
    // local-keyed `false` keeps this function's behaviour identical to the old
    // spelling there.
    let is_projected_deref_store =
        matches!(place.projections.first(), Some(Projection::Deref)) && place.projections.len() > 1;
    if !is_projected_deref_store {
        return false;
    }
    havoc_memo::opaque_store_place(func, place, || {
        let folded = canonicalize_deref(func, place.clone(), 16);
        folded == *place || fold_lands_behind_an_unresolved_pointer(func, &folded)
    })
}

// Rewrite a place by resolving a leading deref-of-reference to its referent,
// recursively. A non-deref place, or a deref of a reference whose referent
// cannot be uniquely determined (e.g. a function parameter), is returned as-is.
fn canonicalize_deref(func: &VerifiableFunction, place: Place, fuel: u32) -> Place {
    canonicalize_deref_guarded(func, place, fuel, &[])
}

// Trust: 2026-09-17 (round A12, fixer) — a place with MORE THAN ONE leading-chain
// `Deref` (`**q`, `(*(*q)).f`) folds `*q` to a slot `x` and then folds `*x`: the
// pointer stored in `x` is read at the use of `q`, not at a mention of `x`, so
// `x`'s own walk (def(x)..mentions of x) does not reach that read. The result of
// the inner fold must therefore be stable over `q`'s chain too — the same
// `reread_through` obligation `referent_of_source`'s `[Deref]` arm discharges for
// the `copy (*q)` spelling. A refused re-read keeps the whole place unfolded
// (`q**`), the opaque name.
fn canonicalize_deref_guarded(
    func: &VerifiableFunction,
    place: Place,
    fuel: u32,
    extra: &[Place],
) -> Place {
    if fuel == 0 {
        return place;
    }
    let Some((Projection::Deref, rest)) = place.projections.split_first() else {
        return place;
    };
    let Some(slot) = resolve_referent_guarded(func, place.local, fuel - 1, extra) else {
        return place;
    };
    let mut referent = slot.clone();
    referent.projections.extend_from_slice(rest);
    if fuel <= 1 || !matches!(referent.projections.first(), Some(Projection::Deref)) {
        return referent;
    }
    let folded = canonicalize_deref_guarded(func, referent.clone(), fuel - 1, extra);
    if folded == referent {
        return folded;
    }
    // `folded` is `referent` with its leading pointer read through; that pointer is
    // `slot`'s content, read at the use of `place.local`.
    if reread_through(func, place.local, fuel - 1, extra, &slot, &folded) { folded } else { place }
}

// true iff the storage rooted at `local` is fixed for the whole body:
// AT MOST ONE VALUE (a single construction, or ZERO body stores for a parameter,
// whose value is defined at entry) and no other mutation path: no projected store,
// no pointer that can write ANY place rooted at it (`&mut`, `&raw mut`, `&raw const`,
// a `Deref` included: `Statement::escapes_local`'s wide form, deliberately wider than
// `generate::borrow_write_target`), no set-discriminant, no
// deinit, and no whole/projected call-destination write.
// Stronger than `local_is_never_written` (which ignores call dests and allows no
// construction) and complementary to `array_local_index_naming_stable`
// (which permits const-index element stores so long as their names converge).
// Under this predicate a place expressed relative to `local` denotes the same
// value at every read.
//
// THE PARAMETER CLAUSE IS `local_defs::value_count`, NOT A BLOCK TALLY. This
// function said "or zero for a parameter" in prose while counting `whole_assigns
// <= 1`, which ADMITS a parameter reassigned once — and roughly a dozen of its
// callers (the witness-grounding alias trace, the immutable-read value tie, the
// container-length field reborrow, the float hull) have no parameter refinement of
// their own; the three that do (`unwrap_receiver_local_is_pinned`,
// `operand_is_stable_bound`, `stable_scalar_arg_formula`) each hand-rolled it.
// `place_source_is_stable_rejects_a_reassigned_parameter` is the row.
//
// Trust: 2026-10-14 (INTERIOR-MUT-CHANNEL-1) — AND no `UnsafeCell` byte of the local's
// own storage is covered by a SHARED borrow (`generate::shared_borrowed_cell_places`):
// `poke(&c)` rewrites an owned `c: Cell<usize>` through `Cell::set` with no store, no
// `&mut` and no `&raw` in this body. [`slot_source_is_stable`] is the rule without that
// clause, for a caller that asks about one PLACE and checks the cell places itself
// ([`place_is_body_stable`]).
pub(crate) fn place_source_is_stable(func: &VerifiableFunction, local: usize) -> bool {
    slot_source_is_stable(func, local)
        && generate::shared_borrowed_cell_places(func, local).is_empty()
}

/// [`place_source_is_stable`] reading a terminator `Drop` of the WHOLE local as the end
/// of its value rather than a write: `local_defs::body_slot_is_stable_modulo_whole_drops`
/// has the argument. The interior-mutability clause is unchanged.
///
/// Trust: 2026-11-07 (VCGEN-CENSUS-SITE-REDS-1) — this is the cell-aware rule stated in
/// `trust_types::local_defs::source_value_is_stable_modulo_whole_drops` (the escape
/// classifier `statement_escapes_local`, which adds a shared borrow of the local's own
/// `UnsafeCell` bytes), spelled as the indexed, cached slot half conjoined with
/// `generate::shared_borrowed_cell_places` so PERF-COMPILER-VCGEN-77's per-local cache
/// serves the witness walk. The two are the same predicate: a cell escape only ever adds
/// an `Escape`, which destabilises, and the memo is non-empty for `local` exactly when
/// some statement's `shared_borrow_of_local_covers_cell` holds.
/// `interior_mut_channel_tests::the_drop_narrowed_question_is_the_cell_aware_rule` pins
/// the agreement shape by shape on both of the slot half's paths: outside any
/// `FuncAnalysisScope` (the unindexed trust-types walk) and inside one (the indexed
/// `LocalWriteIndex` visit, then its per-local cache), the cached slot answer held to
/// the unindexed slot walk.
pub(crate) fn place_source_is_stable_modulo_whole_drops(
    func: &VerifiableFunction,
    local: usize,
) -> bool {
    local_defs::body_slot_is_stable_modulo_whole_drops(&func.body, local)
        && generate::shared_borrowed_cell_places(func, local).is_empty()
}

/// [`place_source_is_stable`] without its interior-mutability clause: the local's own slot
/// holds at most one value and no store, write-capable borrow, set-discriminant, deinit or
/// projected call destination reaches it. Its only caller outside
/// [`place_source_is_stable`] is [`place_is_body_stable`], which refuses a place that
/// overlaps a shared-borrowed cell itself, so a frozen sibling (`st.0` beside a
/// shared-borrowed `st.1: Cell`) stays stable.
pub(crate) fn slot_source_is_stable(func: &VerifiableFunction, local: usize) -> bool {
    local_defs::body_slot_is_stable(&func.body, local)
}

/// THE PLACE-STABILITY RULE: true iff the bytes AT `place` — not only the slot of
/// its root local — hold one value for the whole body, so a fact about them (a
/// `Vec` field's length, a field's value) read at one point describes them at every
/// point.
///
/// [`place_source_is_stable`] answers that for the root's OWN SLOT, which is the
/// whole question for a place with no `Deref`. A place BEHIND the root's `Deref`
/// lives in the root's POINTEE, which the slot question does not see:
/// a pointer stored IN the pointee is not the root at all, and a write through the
/// root's own pointee is what the own-storage rule (`generate::own_storage_write_borrow`)
/// leaves off (`&raw const (*root)…` addresses the pointee, not the slot; since 2026-10-03
/// [`place_source_is_stable`] also refuses it, fail-closed, but that is a property
/// of its current scan, not of the slot question). So a place with a `Deref` is stable only when, in addition:
///
///  * the `Deref` is its FIRST projection and its ONLY one. A second `Deref` reads
///    through a pointer stored in the pointee, and any copy of that pointer can
///    write what it points to (a raw pointer is `Copy`; see
///    `generate::path_defs::ty_reaches_unretagged_pointer`);
///  * the root is a REFERENCE (`&T` or `&mut T`). A raw-pointer or `Box` root's
///    pointee is not held to this rule's argument, and is refused;
///  * no pointer that can write memory under the root is minted anywhere in the
///    body: no `Statement::escapes_local` (`&mut`, `&raw mut`, `&raw const`
///    of ANY place, a `Deref` included) rooted at the root. For a `&mut` root that
///    is the whole argument: a `&mut` is unique, so every pointer that can write
///    its pointee while it is live is derived from it by one of those borrows (a
///    `Move` of the reference ends its use). For a `&` root the pointee is frozen
///    outside an `UnsafeCell` and the scan is defense in depth (the `UnsafeCell` bytes
///    are the cell clause below);
///  * no `Field` hop steps INTO an interior-mutability wrapper (`UnsafeCell`,
///    `Cell`, `RefCell`, `Mutex`, …, `guards::ty_is_interior_mut_wrapper`): a
///    shared reborrow of such a field hands a callee mutable bytes whatever the
///    root is. Asked of a `Deref`-free place too.
///
/// Trust (2026-09-30, the r8c union review's F1). `container_len`'s field-length
/// guard fact (`build_len_guard_field_map`) asked [`place_source_is_stable`] alone
/// about `(*self).v`. A callee handed `&raw const *self as *mut VH` clears the
/// `Vec` between `if self.v.len() < 4 { return }` and `self.v[3]` — defined under
/// Tree Borrows, since the pointer is derived from `&mut self` — and the index row
/// was kernel-certified PROVED on a body that panics (`len is 0 but the index is
/// 3`, -O0 and -O3). The `&raw mut *self` twin refuted: the slot rule counts
/// `&raw mut` of any place. The guards lane's field-place key
/// (`guards::shared_stable_field_reborrow_place`) asks this rule too, so the two
/// field-length lanes state the stability of a field place once.
///
/// Trust: 2026-10-14 (INTERIOR-MUT-CHANNEL-1) — and no `UnsafeCell` byte is AT `place`.
/// A place of the root's own storage is unstable when it overlaps a cell sub-place a
/// shared borrow of the root covers (`generate::shared_borrowed_cell_places`; the root's
/// SLOT rule, [`slot_source_is_stable`], is asked without that clause so a frozen
/// sibling stays stable). A place behind the root's `Deref` is unstable when its own
/// type may hold a cell (`generate::unsafe_cell_places`): any copy of the reference, or
/// a shared reborrow of the place through a `&mut` root, writes those bytes.
pub(crate) fn place_is_body_stable(func: &VerifiableFunction, place: &Place) -> bool {
    if !slot_source_is_stable(func, place.local) {
        return false;
    }
    let shared_cells = generate::shared_borrowed_cell_places(func, place.local);
    if !shared_cells.is_empty() {
        let name = place_to_var_name(func, place);
        if shared_cells
            .iter()
            .any(|cell| generate::place_names_overlap(&place_to_var_name(func, cell), &name))
        {
            return false;
        }
    }
    let root = place.local;
    if place.projections.is_empty() {
        return local_ty_ref(func, root).is_some();
    }
    let Some(root_ty) = local_ty_ref(func, root).map(std::borrow::Cow::Borrowed) else {
        return false;
    };
    let mut hops: &[trust_types::Projection] = &place.projections;
    let mut cur = root_ty;
    if let Some(deref_at) =
        place.projections.iter().position(|p| matches!(p, trust_types::Projection::Deref))
    {
        if deref_at != 0
            || place.projections[1..].iter().any(|p| matches!(p, trust_types::Projection::Deref))
            || !matches!(cur.as_ref(), Ty::Ref { .. })
        {
            return false;
        }
        let pointee_writable =
            any_local_write_stmt(func, &func.body.blocks, root, |_block, stmt| {
                // The wide form, with no read-only exemption: for a `&` root this
                // scan is defense in depth (`generate::borrow_write_target` would admit
                // `&raw const (*root).f` of `Freeze` data).
                stmt_escapes_local(func, stmt, root)
            });
        if pointee_writable {
            return false;
        }
        let Some(pointee) = step_place_ty_cow(cur, &trust_types::Projection::Deref) else {
            return false;
        };
        cur = pointee;
        hops = &place.projections[1..];
    }
    let behind_deref = hops.len() < place.projections.len();
    for hop in hops {
        if guards::ty_is_interior_mut_wrapper(cur.as_ref()) {
            return false;
        }
        // Trust: 2026-10-16 (INTERIOR-MUT-CHANNEL-2) — a field of a union behind the root's
        // `Deref` overlaps its siblings: a holder of the reference writes `(*r).n`
        // through `(*r).c.set(..)` for `union U { c: ManuallyDrop<Cell<usize>>, n:
        // usize }`, although `n`'s own type holds no cell. So the BYTE question is asked
        // of the union itself (every field, a `Vec`'s allocator included). The root's
        // own storage needs no such step: a shared borrow below a union names the cover
        // (`generate::shared_borrow_cell_places`), which the overlap test above sees.
        if behind_deref
            && matches!(hop, trust_types::Projection::Field(_))
            && generate::field_base_may_overlap_siblings(&func.body.datatype_defs, cur.as_ref())
            && generate::ty_may_hold_unsafe_cell(&func.body.datatype_defs, cur.as_ref())
        {
            return false;
        }
        let Some(next) = step_place_ty_cow(cur, hop) else {
            return false;
        };
        cur = next;
    }
    if behind_deref {
        let mut cells = Vec::new();
        generate::unsafe_cell_places(&func.body.datatype_defs, place, cur.as_ref(), &mut cells);
        if !cells.is_empty() {
            return false;
        }
    }
    true
}

/// Trust: 2026-10-14 (INTERIOR-MUT-CHANNEL-1) — THE ESCAPE QUESTION of the verifier's
/// scans: does `stmt` hand out an alias through which `local`'s own storage may be
/// written? [`trust_types::Statement::escapes_local`] (`&mut`, `&raw mut`, `&raw const`
/// of any place rooted at `local`) OR a SHARED borrow of `local`'s own storage that
/// covers an `UnsafeCell` byte (`generate::shared_borrow_cell_places`), through which a
/// holder writes those bytes with defined behaviour (`poke(&c)` and `Cell::set`). A shared
/// borrow of `Freeze` bytes stays off, as `escapes_local` leaves it.
///
/// Every `.escapes_local(` call in this crate's sources is this one
/// (`tests/write_channel_rule_is_not_restated.rs` refuses a bare call elsewhere). The
/// body-level form [`body_stmt_escapes_local`] is the same predicate for a question that
/// holds only a `VerifiableBody`.
pub(crate) fn stmt_escapes_local(
    func: &VerifiableFunction,
    stmt: &Statement,
    local: usize,
) -> bool {
    body_stmt_escapes_local(&func.body, stmt, local)
}

/// [`stmt_escapes_local`] for a caller holding only the body.
pub(crate) fn body_stmt_escapes_local(
    body: &trust_types::VerifiableBody,
    stmt: &Statement,
    local: usize,
) -> bool {
    trust_types::local_defs::statement_escapes_local(body, stmt, local)
}

// a struct/enum payload bound by a match arm reaches the arithmetic
// through a base-local value copy, not a reference: `_3 = Move(_1.downcast(0).field(0))`
// then `_3.field(0)` is the overflow operand, while the guard reads the same field
// via a reborrow (`_4 = &_1.downcast(0).field(0); *_4.field(0) < K`). The guard
// canonicalizes through the leading deref to `_1@0.0.0`, but the overflow operand
// stays `_3.0` — distinct SMT names, so the guard never constrains the overflow
// (a Goal-1 false-fail). When `_3` is a unique whole-local Copy/Move of a *stable*
// place `Q` (built only from static Field/Downcast projections), `_3.proj` denotes
// exactly `Q.proj`; return that rebased place so both reads converge. Soundness:
// both the alias local and `Q`'s root must be immutable (`place_source_is_stable`),
// so the rebase preserves the value at every read; otherwise return `None` and the
// opaque `_3` name is kept (fail-closed to a false-fail, never a false-prove).
fn base_value_alias(func: &VerifiableFunction, place: &Place) -> Option<Place> {
    // Only rebase a *projection into* the moved payload (`_3.field`), the struct-
    // field read that the guard sees as a deref-folded source field. A read of the
    // whole moved local (`_3`, empty projections) already converges with the guard
    // by its own name — folding it would only desync facts (e.g. scalar-payload
    // match guards #36/#50) keyed on that name, a precision regression.
    if place.projections.is_empty() || crate::local_defs::is_parameter(func, place.local) {
        return None;
    }
    let Rvalue::Use(Operand::Copy(src) | Operand::Move(src)) =
        crate::local_defs::unique_value_def(func, place.local)?
    else {
        return None;
    };
    if src.local == place.local {
        return None;
    }
    // Restrict to enum-variant *payload* extraction (`_1 as Variant.0`) — the
    // match-arm bind that splits the guard name (reborrow → deref-folded source)
    // from the overflow name (moved base local). A `Downcast` in the source marks
    // exactly that pattern; plain local/tuple/struct-field copies (no downcast)
    // keep their own identity, so def-propagation and abstract-interp keying stay
    // undisturbed. Only static structural projections (Field/Downcast) may be
    // carried onto the source: they have no runtime-varying component, unlike
    // Index (varying index) or Deref (depends on a separately-tracked referent).
    let mut has_downcast = false;
    for p in &src.projections {
        match p {
            Projection::Downcast(_) => has_downcast = true,
            Projection::Field(_) => {}
            _ => return None,
        }
    }
    if !has_downcast {
        return None;
    }
    // The alias local must hold its single constructed value unchanged.
    if !place_source_is_stable(func, place.local) {
        return None;
    }
    // The source storage must be immutable wherever the alias is later read.
    if !place_source_is_stable(func, src.local) {
        return None;
    }
    let mut projections = Vec::with_capacity(src.projections.len() + place.projections.len());
    projections.extend_from_slice(&src.projections);
    projections.extend_from_slice(&place.projections);
    Some(Place { local: src.local, projections })
}

// canonicalize a place by first folding leading reference derefs
// (`canonicalize_deref`) and then rebasing through base-local value aliases
// (`base_value_alias`), alternating until a fixpoint. This makes a payload read
// via a reborrowed reference (guard side) and via a moved base local (arithmetic
// side) converge to one name. Each rebase moves to a strictly different base local
// with a unique def, so the loop terminates; `fuel` is a safety bound.
fn canonicalize_place(func: &VerifiableFunction, place: Place, fuel: u32) -> Place {
    let mut p = canonicalize_deref(func, place, fuel);
    for _ in 0..fuel {
        let Some(rebased) = base_value_alias(func, &p) else {
            break;
        };
        p = canonicalize_deref(func, rebased, fuel);
    }
    p
}

/// Trust (2026-09-25, TRUST-09): the canonical PLACE `place_to_var_name` names `place`
/// by — the same fold under the same duplicate-index guard — for a caller that must
/// know which storage a name denotes, not just its spelling.
///
/// Trust: 2026-10-12 (UNION-SIBLING-WRITE-2) — `place_to_var_name` mints its name from
/// THIS function's answer (one fold, so the two cannot drift), and the answer is
/// memoized beside the name (`place_memo`, same key and scope):
/// `generate::union_write_cover_name` asks it for every written place.
pub(crate) fn canonical_place(func: &VerifiableFunction, place: &Place) -> Place {
    if place.projections.is_empty() {
        return Place::local(place.local);
    }
    canonical_place_in(func, place, None)
}

/// [`canonical_place`], for a caller that may already hold `func`'s local-name table.
/// `locals` is that table (`place_memo::local_names(func)`, nothing else); `None` asks
/// for it here, and only on a memo miss — which is all `canonical_place` ever did.
///
/// verifier-perf (2026-10-13): the table is asked for ONCE per uncached place name.
/// `place_to_var_name_uncached` holds it for the rest of its mint, and since
/// UNION-SIBLING-WRITE-2 it reached this fold through `canonical_place`, which asked
/// `place_memo::local_names` again. Inside a generation scope the second ask is a memo
/// hit. OUTSIDE one `local_names` is not a memo (it returns a fresh
/// `LocalNameTable::of(func)`), so every uncached name built the function's whole
/// table twice — and the StepBy-constructor root-charge replay
/// (`trust_verify/step_by_constructor.rs`, `ConstructorPlan::root_charges` ->
/// `generate_callsite_precondition_vcs`) ran outside a scope. Measured on stage-1
/// compilers one commit apart, the second table took a function from 108.8 s to
/// 152.9 s of wall time (`aterm-census`, `run_mainloop_census`): past its 120 s clock.
/// Since 2026-10-19 the call-site producers open their own scope
/// (`generate::EntryScope`), so that replay builds the table once per producer call;
/// an unscoped mint still builds exactly one.
///
/// The table is a pure function of `func.body.locals`, so which copy of it answers
/// `indices_unique` cannot change the place returned, and so no name changes.
/// `AnalysisMemoStats::local_name_tables_computed` counts the builds.
fn canonical_place_in(
    func: &VerifiableFunction,
    place: &Place,
    locals: Option<&LocalNameTable>,
) -> Place {
    if place.projections.is_empty() {
        return Place::local(place.local);
    }
    let memo_key = place_memo::key_for(place);
    if let Some(key) = &memo_key
        && let Some(cached) = place_memo::lookup_place(func, key)
    {
        return cached;
    }
    let indices_unique = match locals {
        Some(table) => table.indices_unique(func),
        None => place_memo::local_names(func).indices_unique(func),
    };
    let computed =
        if indices_unique { canonicalize_place(func, place.clone(), 16) } else { place.clone() };
    if let Some(key) = memo_key {
        place_memo::store_place(func, key, &computed);
    }
    computed
}

/// The characters a projection segment emitted by `place_to_var_name` may begin
/// with. `place_to_var_name` spells a place as `base ++ segments`, and this set is
/// the only thing that makes that concatenation decodable: a segment starts with
/// one of these, a base contains none of them, so the boundary is the first
/// occurrence in the string. Both halves of that invariant are ENFORCED, not
/// asserted — see the two uses in `place_to_var_name`. Adding a segment spelling
/// that starts with something else does not silently break the split: the emitter
/// prefixes `@` to any segment that would.
pub(crate) const PROJECTION_SEGMENT_LEAD: &[char] = &['.', '[', '*', '@'];

/// The BYTE form of [`PROJECTION_SEGMENT_LEAD`], for the place-name algebra's
/// byte-indexed boundary tests: `path_defs::place_names_overlap` (projection
/// descendant), `legacy_version_oracle::place_root` (the retired version oracle's
/// bucket key, kept as the SSA oracle's differential), `rebind_index::is_sep` (the
/// rebinder index the SSA oracle answers `write_rebinds`/`dest_write_rebinds`
/// through — it is exact only while it splits where they do),
/// `path_defs::write_covers_derived_slice_len` and
/// `block_defs::block_def_establish_stmt` (ancestor establishes descendant).
///
/// Trust (W4 fix round 1, 2026-09-25). Those four each spelled the set as
/// `b'.' | b'[' | b'*'`, WITHOUT `@` — the spelling of `Projection::Downcast` (and
/// of the opaque-cast / unsafe-binder segments). So a whole write of an enum local
/// `r` (an assignment, a call destination, a `SetDiscriminant`) neither killed nor
/// re-versioned any fact over its payload `r@1.0`: the name algebra said they were
/// unrelated places. The `binary_search` result facts
/// (`vec_region::slice_binary_search_result_definitions`) were the first producer
/// to key a fact on a payload name of a local that can be REASSIGNED, and four
/// kernel-certified false proofs followed (r12..r12d). One set, one definition:
/// `place_name_boundary_tests::segment_lead_byte_matches_the_char_set` pins this
/// predicate to [`PROJECTION_SEGMENT_LEAD`], so a future segment spelling cannot
/// be added to one and forgotten in the other.
///
/// Every reader that splits a name into its base and its projections, or asks
/// whether one name is a projection of another, must use this and not a
/// hand-written subset.
///
/// Trust (2026-09-29, local twin of the W4 fix): the same omission was measured
/// independently on the pointer side. `o@1.0*`, the pointee of a pointer moved out
/// of `o: Option<&mut u8>` (or out of an iterator's `Some`), was not a projection of
/// `o`: the conservative call havoc, which re-versions a pointer-carrying local by
/// its base name and relies on prefix overlap to reach its pointees, never reached
/// it. A guard on `*b` survived `b.make_ascii_uppercase()`, and `if *b > 96 {
/// b.make_ascii_uppercase(); *b - 90 }` over `iter_mut` was proved and panics.
#[inline]
pub(crate) fn is_projection_segment_lead(byte: u8) -> bool {
    matches!(byte, b'.' | b'[' | b'*' | b'@')
}

/// The `#`-token namespace the E4/E5 LOOP-TRANSITION model mints its HAVOCS in.
///
/// # Why this exists, and what it prevents
///
/// The `#`-suffix convention in this crate is overloaded. Almost every producer
/// mints an SSA VERSION token (`x#s6_t`) — a second spelling of the SAME dynamic
/// value — and `normalize_ssa_version_tokens` is built on that reading: for a
/// local with one static write, the establish token, every terminal token, and
/// the bare name all denote the one assigned value, so collapsing them to the
/// bare name is an identity that CONNECTS facts the spellings kept apart.
///
/// The loop-transition model mints something else entirely under the same `#`
/// syntax: a HAVOC. `symbolic_loop_transitions` writes `chunk#e45_call_bb2` for
/// "whatever the call at bb2 put in `chunk` during THIS iteration", and
/// `summarize_nested_loop` writes `x#e45_nested_bb3_1` for "whatever the inner
/// loop left in `x`". Neither denotes the same value as the bare name: the bare
/// name is the value at the header on ENTRY to the iteration, the token is the
/// value at the END of it. A single-static-assignment local does not make them
/// equal — one static write inside a loop executes once per iteration, with a
/// different value each time.
///
/// Collapsing a havoc token to its bare name is therefore NOT an identity; it
/// asserts that the iteration did not change the local. MEASURED, before this
/// namespace existed: with `invariant chunk == 0` on a loop whose body is
/// `chunk = observe(xs)`, the consecution row rendered as
/// `chunk == 0 AND guard AND NOT(chunk == 0)` — trivially UNSAT, i.e. PROVED —
/// for a program in which `observe` may return anything. That is a false proof
/// of a false invariant, produced with no bad callee summary anywhere in it.
///
/// Every mint site and every collapse site reads this ONE constant so the two
/// halves cannot drift apart.
pub(crate) const LOOP_TRANSITION_HAVOC_TOKEN_PREFIX: &str = "e45_";

/// True when a `#`-token is a loop-transition HAVOC rather than an SSA version,
/// i.e. when collapsing it onto its bare name would ASSERT that an iteration
/// left the local unchanged. See [`LOOP_TRANSITION_HAVOC_TOKEN_PREFIX`].
pub(crate) fn version_token_is_loop_transition_havoc(name: &str) -> bool {
    name.split_once('#')
        .is_some_and(|(_, token)| token.starts_with(LOOP_TRANSITION_HAVOC_TOKEN_PREFIX))
}

/// The `#`-token namespace the TINV row shim (`generate::tinv_rows`) mints its UNWIND
/// havocs in: `n#tinvu_s{b}` for a type-invariant field term that the terminator of block
/// `b` may write before its unwind edge is taken, and `n#tinvu_a{b}` for a term a
/// drop-and-replace overwrites in cleanup.
///
/// Like a loop-transition havoc, it is NOT a second spelling of the bare name: it is
/// "whatever the call or drop glue left there". Collapsing it onto the bare local
/// (`normalize_ssa_version_tokens`, `bare_ssa_guard_variant`) would assert the unwinding
/// terminator left the value unchanged and re-tie a havocked σ term to its pre-call
/// value: an unsound `I(σ)` proof. Today every σ term is a field projection, which the
/// collapse never touches; the exemption keeps a whole-local σ from becoming one.
pub(crate) const TINV_UNWIND_HAVOC_TOKEN_PREFIX: &str = "tinvu_";

/// True when a `#`-token is a TINV unwind havoc. See
/// [`TINV_UNWIND_HAVOC_TOKEN_PREFIX`].
pub(crate) fn version_token_is_tinv_unwind_havoc(name: &str) -> bool {
    name.split_once('#').is_some_and(|(_, token)| token.starts_with(TINV_UNWIND_HAVOC_TOKEN_PREFIX))
}

/// The `#`-token namespace of a GUARD-LOCAL path-guard spelling
/// (`generate::guard_value_spelling`, PATH-GUARD-VALUE-1): `x#gv_p{J}` is "the value
/// of `x` the guard tested, the join at node `J`", `x#gv_b{S}` "the value of `x` the
/// guard of an edge leaving block `S` tested". It is minted exactly when the
/// reaching-set token would have tied the guard to a DIFFERENT value the row reads,
/// so it is NOT a second spelling of the bare name or of any other version: collapsing
/// it (`normalize_ssa_version_tokens`, `bare_ssa_guard_variant`, the postcondition
/// canonical name) would re-create the tie the spelling exists to cut.
pub(crate) const GUARD_VALUE_TOKEN_PREFIX: &str = "gv_";

/// True when a `#`-token is a guard-local path-guard spelling. See
/// [`GUARD_VALUE_TOKEN_PREFIX`].
pub(crate) fn version_token_is_guard_value(name: &str) -> bool {
    name.split_once('#').is_some_and(|(_, token)| token.starts_with(GUARD_VALUE_TOKEN_PREFIX))
}

/// The formula name of the WHOLE local declared as `decl`: [`place_to_var_name`]
/// of `Place::local(decl.index)`, the spelling every block-def, guard and goal
/// uses for it.
///
/// A fact about a local keyed any other way names a different term, or none:
/// `decl.name` is the SOURCE name, which `place_to_var_name` deliberately does not
/// use when it is shared by two locals, reserved (`__ret`), projection-shaped or
/// spelled like a fallback `_<k>` — and in that last case the source name IS the
/// formula name of a DIFFERENT local, so the fact lands on the wrong value.
/// Measured on `pick` (`if b {1} else {2}` under an `ensures`, local 3 named
/// `__ret`): the interval domain seeded `__ret` while every transfer wrote `_3`,
/// so the environment carried `__ret in [i32::MIN, i32::MAX]`, a fact about no
/// term of the formula.
pub fn local_var_name(func: &VerifiableFunction, decl: &trust_types::LocalDecl) -> String {
    place_to_var_name(func, &Place::local(decl.index))
}

// Trust (leaf-assert-unhostage, 2026-07-11): `pub` (was `pub(crate)`) — the
// SINGLE SOURCE OF TRUTH for the VC formula variable vocabulary. trust-clean's
// guard-implied-assert augmentation (`prove.rs`, ordering-sentinel cmp facts)
// must spell the SAME names this emitter spells (`idx`, `self*.1`, `_6`, …) or
// its conjoined facts silently bind nothing; re-implementing the naming there
// would be a drift channel (canonicalization + the name-collision fallback
// live here). Exporting the one function keeps the two ends unforkable — the
// same rationale as `trust_types::total_call_summaries`.
pub fn place_to_var_name(func: &VerifiableFunction, place: &Place) -> String {
    // verifier-perf: memoized per `(func, place)` on the SAME key and the SAME
    // identity discipline as the place-type/Sort memo (see `place_memo`). This
    // function is a pure function of the function's local table and the place —
    // but it rebuilds an `FxHashSet` over every local and makes two more
    // O(locals) passes on every call, and the generator calls it once per place
    // occurrence in every formula it builds or rewrites. `key_for` returns
    // `None` outside a VC-gen scope and for projection paths it cannot encode
    // injectively, and those take the uncached path unchanged.
    let memo_key = place_memo::key_for(place);
    if let Some(key) = &memo_key
        && let Some(cached) = place_memo::lookup_name(func, key)
    {
        return cached.to_string();
    }
    let computed = place_to_var_name_uncached(func, place);
    if let Some(key) = memo_key {
        place_memo::store_name(func, key, &std::rc::Rc::from(computed.as_str()));
    }
    computed
}

/// What every uncached `place_to_var_name` mint asks of the function's LOCAL TABLE,
/// computed in one pass: whether declaration indices are unique, which declaration
/// (if exactly one) carries a given index, and how many declarations carry a given
/// source name.
///
/// verifier-perf: the mint used to answer each of these by scanning every local —
/// the first by building an `FxHashSet` over all of them — on EVERY uncached call,
/// i.e. once per distinct place, which is O(places × locals): on
/// `ever-init-many-locals` (18 locals per source local) it dominated building the
/// statement-version oracle. The answers are pure functions of `func.body.locals`,
/// memoized once per function by `place_memo::local_names`; under `cfg(test)` every
/// lookup is checked against the scan it replaces.
pub(crate) struct LocalNameTable {
    indices_unique: bool,
    /// `decl.index` -> (declarations carrying it, position of the first); `None` when
    /// `func.body.locals` has canonical dense indices (`decl.index == pos`).
    by_index: Option<trust_types::fx::FxHashMap<usize, (usize, usize)>>,
    /// Source name -> (declarations carrying it, position of the first).
    by_name: trust_types::fx::FxHashMap<String, (usize, usize)>,
}

impl LocalNameTable {
    fn of(func: &VerifiableFunction) -> LocalNameTable {
        // verifier-perf instrumentation (see `fn_memo`): count the tables actually
        // BUILT, memoized or not. Diagnostic only.
        fn_memo::count_local_name_table();
        // PERF-COMPILER-VCGEN-696: when `func.body.locals` has canonical dense indices
        // (`decl.index == pos`), skip allocating and populating `by_index` entirely and
        // size `by_name` to the number of source-named locals rather than `locals.len()`.
        let mut dense_identity = true;
        let mut named_count = 0usize;
        for (pos, decl) in func.body.locals.iter().enumerate() {
            if decl.index != pos {
                dense_identity = false;
            }
            if decl.name.is_some() {
                named_count = named_count.saturating_add(1);
            }
        }
        let mut by_name: trust_types::fx::FxHashMap<String, (usize, usize)> = if named_count == 0 {
            trust_types::fx::FxHashMap::default()
        } else {
            trust_types::fx::FxHashMap::with_capacity_and_hasher(named_count, Default::default())
        };
        if dense_identity {
            if named_count != 0 {
                for (pos, decl) in func.body.locals.iter().enumerate() {
                    if let Some(name) = decl.name.as_deref() {
                        if let Some((count, _)) = by_name.get_mut(name) {
                            *count = count.saturating_add(1);
                        } else {
                            by_name.insert(name.to_string(), (1, pos));
                        }
                    }
                }
            }
            return LocalNameTable { indices_unique: true, by_index: None, by_name };
        }
        let mut by_index: trust_types::fx::FxHashMap<usize, (usize, usize)> =
            trust_types::fx::FxHashMap::with_capacity_and_hasher(
                func.body.locals.len(),
                Default::default(),
            );
        let mut indices_unique = true;
        for (pos, decl) in func.body.locals.iter().enumerate() {
            let slot = by_index.entry(decl.index).or_insert((0, pos));
            slot.0 = slot.0.saturating_add(1);
            if slot.0 > 1 {
                indices_unique = false;
            }
            if let Some(name) = decl.name.as_deref() {
                if let Some((count, _)) = by_name.get_mut(name) {
                    *count = count.saturating_add(1);
                } else {
                    by_name.insert(name.to_string(), (1, pos));
                }
            }
        }
        LocalNameTable { indices_unique, by_index: Some(by_index), by_name }
    }

    /// `func.body.locals.iter().all(|decl| seen.insert(decl.index))`.
    fn indices_unique(&self, func: &VerifiableFunction) -> bool {
        #[cfg(test)]
        if generate::differential_enabled() {
            let mut seen = trust_types::fx::FxHashSet::default();
            assert_eq!(self.indices_unique, func.body.locals.iter().all(|d| seen.insert(d.index)));
        }
        let _ = func;
        self.indices_unique
    }

    /// `func.body.locals.iter().enumerate().all(|(pos, decl)| decl.index == pos)`.
    fn all_canonical(&self, func: &VerifiableFunction) -> bool {
        let canonical = self.by_index.is_none();
        #[cfg(test)]
        if generate::differential_enabled() {
            assert_eq!(
                canonical,
                func.body.locals.iter().enumerate().all(|(pos, d)| d.index == pos)
            );
        }
        let _ = func;
        canonical
    }

    /// The single declaration whose `index` is `local` (none, or ambiguous, is `None`).
    fn matching_decl<'f>(
        &self,
        func: &'f VerifiableFunction,
        local: usize,
    ) -> Option<&'f trust_types::LocalDecl> {
        let found = match &self.by_index {
            None => func.body.locals.get(local),
            Some(by_index) => by_index
                .get(&local)
                .and_then(|&(count, pos)| (count == 1).then(|| &func.body.locals[pos])),
        };
        #[cfg(test)]
        if generate::differential_enabled() {
            let mut scan = func.body.locals.iter().filter(|decl| decl.index == local);
            let want = scan.next().filter(|_| scan.next().is_none());
            assert_eq!(found.map(std::ptr::from_ref), want.map(std::ptr::from_ref));
        }
        found
    }

    /// The FIRST declaration whose `index` is `local` — `locals.iter().find(..)`.
    fn first_decl<'f>(
        &self,
        func: &'f VerifiableFunction,
        local: usize,
    ) -> Option<&'f trust_types::LocalDecl> {
        let found = match &self.by_index {
            None => func.body.locals.get(local),
            Some(by_index) => by_index.get(&local).map(|&(_, pos)| &func.body.locals[pos]),
        };
        #[cfg(test)]
        if generate::differential_enabled() {
            let want = func.body.locals.iter().find(|decl| decl.index == local);
            assert_eq!(found.map(std::ptr::from_ref), want.map(std::ptr::from_ref));
        }
        found
    }

    /// How many declarations carry the source name `name`.
    fn name_count(&self, func: &VerifiableFunction, name: &str) -> usize {
        let count = self.by_name.get(name).map_or(0, |&(count, _)| count);
        #[cfg(test)]
        if generate::differential_enabled() {
            assert_eq!(
                count,
                func.body.locals.iter().filter(|d| d.name.as_deref() == Some(name)).count()
            );
        }
        let _ = func;
        count
    }

    /// The single declaration whose source `name` is `name` (none, or ambiguous, is `None`).
    fn matching_named_decl<'f>(
        &self,
        func: &'f VerifiableFunction,
        name: &str,
    ) -> Option<&'f trust_types::LocalDecl> {
        let found = self
            .by_name
            .get(name)
            .and_then(|&(count, pos)| (count == 1).then(|| &func.body.locals[pos]));
        #[cfg(test)]
        if generate::differential_enabled() {
            let mut scan =
                func.body.locals.iter().filter(|decl| decl.name.as_deref() == Some(name));
            let want = scan.next().filter(|_| scan.next().is_none());
            assert_eq!(found.map(std::ptr::from_ref), want.map(std::ptr::from_ref));
        }
        found
    }

    /// `func.body.locals.iter().any(|d| d.index != local && d.name.as_deref() == Some(name))`.
    fn has_other_local_with_name(&self, func: &VerifiableFunction, local: usize, name: &str) -> bool {
        let found = match self.by_name.get(name) {
            None => false,
            Some(&(1, pos)) => func.body.locals[pos].index != local,
            Some(&(_, _)) if self.indices_unique => true,
            Some(&(_, _)) => {
                func.body.locals.iter().any(|d| d.index != local && d.name.as_deref() == Some(name))
            }
        };
        #[cfg(test)]
        if generate::differential_enabled() {
            assert_eq!(
                found,
                func.body.locals.iter().any(|d| d.index != local && d.name.as_deref() == Some(name))
            );
        }
        found
    }

    /// PERF-COMPILER-VCGEN-746: classify the declarations in `func.body.locals` matching
    /// `decl.name.as_deref() == Some(name) || parsed_local_index == Some(decl.index)` in O(1).
    fn lookup_formula_local_decl<'f>(
        &self,
        func: &'f VerifiableFunction,
        name: &str,
        parsed_local_index: Option<usize>,
    ) -> FormulaLocalDeclLookup<'f> {
        let found = match parsed_local_index {
            None => match self.by_name.get(name) {
                None => FormulaLocalDeclLookup::None,
                Some(&(1, pos)) => FormulaLocalDeclLookup::Unique(&func.body.locals[pos]),
                Some(_) => FormulaLocalDeclLookup::Ambiguous,
            },
            Some(idx) => {
                let idx_unique = self.matching_decl(func, idx);
                let idx_any = idx_unique.is_some() || self.first_decl(func, idx).is_some();
                match (self.by_name.get(name), idx_unique, idx_any) {
                    (None, None, false) => FormulaLocalDeclLookup::None,
                    (None, Some(d), _) => FormulaLocalDeclLookup::Unique(d),
                    (Some(&(1, pos)), None, false) => {
                        FormulaLocalDeclLookup::Unique(&func.body.locals[pos])
                    }
                    (Some(&(1, pos)), Some(d), _) if std::ptr::eq(&func.body.locals[pos], d) => {
                        FormulaLocalDeclLookup::Unique(d)
                    }
                    _ => FormulaLocalDeclLookup::Ambiguous,
                }
            }
        };
        #[cfg(test)]
        if generate::differential_enabled() {
            let mut scan = func.body.locals.iter().filter(|decl| {
                decl.name.as_deref() == Some(name) || parsed_local_index == Some(decl.index)
            });
            let want = match (scan.next(), scan.next()) {
                (None, _) => None,
                (Some(d), None) => Some(Some(std::ptr::from_ref(d))),
                (Some(_), Some(_)) => Some(None),
            };
            let got = match found {
                FormulaLocalDeclLookup::None => None,
                FormulaLocalDeclLookup::Unique(d) => Some(Some(std::ptr::from_ref(d))),
                FormulaLocalDeclLookup::Ambiguous => Some(None),
            };
            assert_eq!(got, want);
        }
        found
    }
}

/// Result of looking up declarations in `func.body.locals` matching a formula local
/// name (`decl.name.as_deref() == Some(name) || parsed_local_index == Some(decl.index)`).
#[derive(Clone, Copy, Debug)]
pub(crate) enum FormulaLocalDeclLookup<'a> {
    None,
    Unique(&'a trust_types::LocalDecl),
    Ambiguous,
}

/// PERF-COMPILER-VCGEN-746: classify declarations in `func.body.locals` matching
/// `decl.name.as_deref() == Some(name) || parsed_local_index == Some(decl.index)` via
/// `LocalNameTable` when scoped, falling back to a single pass over `func.body.locals`.
pub(crate) fn lookup_formula_local_decl<'f>(
    func: &'f VerifiableFunction,
    name: &str,
    parsed_local_index: Option<usize>,
) -> FormulaLocalDeclLookup<'f> {
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.lookup_formula_local_decl(func, name, parsed_local_index);
    }
    let mut decls = func.body.locals.iter().filter(|decl| {
        decl.name.as_deref() == Some(name) || parsed_local_index == Some(decl.index)
    });
    match (decls.next(), decls.next()) {
        (None, _) => FormulaLocalDeclLookup::None,
        (Some(decl), None) => FormulaLocalDeclLookup::Unique(decl),
        (Some(_), Some(_)) => FormulaLocalDeclLookup::Ambiguous,
    }
}

/// The single declaration of `func` whose `index` is `local` (none, or ambiguous, is
/// `None`) — by lookup in the per-function local table, not a scan of the locals.
pub(crate) fn unique_local_decl(
    func: &VerifiableFunction,
    local: usize,
) -> Option<&trust_types::LocalDecl> {
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.matching_decl(func, local);
    }
    let mut decls = func.body.locals.iter().filter(|d| d.index == local);
    let decl = decls.next()?;
    decls.next().is_none().then_some(decl)
}

/// The single declaration of `func` whose source `name` is `name` (none, or ambiguous, is
/// `None`) — by lookup in the per-function local table, not a scan of the locals.
pub(crate) fn unique_named_local_decl<'f>(
    func: &'f VerifiableFunction,
    name: &str,
) -> Option<&'f trust_types::LocalDecl> {
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.matching_named_decl(func, name);
    }
    let mut decls = func.body.locals.iter().filter(|d| d.name.as_deref() == Some(name));
    let decl = decls.next()?;
    decls.next().is_none().then_some(decl)
}

/// True iff `func` declares any local with `d.index != local` and `d.name == Some(name)`.
pub(crate) fn has_other_local_with_name(
    func: &VerifiableFunction,
    local: usize,
    name: &str,
) -> bool {
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.has_other_local_with_name(func, local, name);
    }
    func.body.locals.iter().any(|d| d.index != local && d.name.as_deref() == Some(name))
}

/// PERF-COMPILER-VCGEN-751: true iff `func.body.locals.iter().enumerate().all(|(pos, d)| d.index == pos)`,
/// answered in O(1) via `LocalNameTable` when scoped.
pub(crate) fn all_locals_canonical(func: &VerifiableFunction) -> bool {
    if let Some(table) = place_memo::local_names_scoped(func) {
        return table.all_canonical(func);
    }
    func.body.locals.iter().enumerate().all(|(position, decl)| decl.index == position)
}

fn place_to_var_name_uncached(func: &VerifiableFunction, place: &Place) -> String {
    // verifier-perf instrumentation (see `fn_memo`): count the mints actually
    // PERFORMED, whichever memo (or none) served the query. Diagnostic only.
    fn_memo::count_place_name();
    // Public callers can construct Trust IR directly. Every canonicalization
    // helper resolves locals by explicit `LocalDecl.index` or scans Place IDs,
    // so sparse/reordered tables remain well-defined and must not lose useful
    // alias convergence. Duplicate declaration indices are genuinely
    // ambiguous, however; proof entry points reject them and this standalone
    // helper declines canonicalization while retaining a unique `_N` fallback.
    let locals = place_memo::local_names(func);
    let canonical = canonical_place_in(func, place, Some(locals.as_ref()));
    let place = &canonical;
    // Trust #soundness (name-collision false proof): the base SMT name is the local's
    // SOURCE name, but a source name is NOT unique across distinct MIR locals — shadowing
    // (`let t = p`) or same-named bindings in sibling/parent scopes (incl. a parameter and
    // an inner local both named `t`) give two DISTINCT canonical locals the same name. A
    // FACT keyed to one local (the accumulator bound, a BV-mul dominating-guard operand
    // bound, a slice-length guard) would then be conjoined onto the OTHER local's VC and
    // vacuously discharge its real obligation — a confirmed FALSE PROOF
    // (`fn f(t:u16){ let t=0; for &x in &[255u8;4]{t+=x as u16;} ...; } t+60000` proved
    // while it overflows). Fix at the root: any source name shared by 2+ locals is
    // ambiguous, so fall back to the unique, SMT-safe per-local `_<local>` name for EVERY
    // local carrying it. Unique names (the overwhelming common case) are unchanged, so the
    // change is verdict-identical except where it CLOSES a fact leak. The accumulator's own
    // bound still discharges (its VC and its fact both resolve to the same `_<local>`); it
    // simply can no longer leak onto an unrelated same-named local.
    // Trust #soundness (fallback-collision false proof): the residual leak the
    // shared-source-name demotion above does NOT cover — a source name literally
    // spelled `_<k>` (a VALID Rust identifier) for one local collides with the
    // FALLBACK var `_<k>` an UNNAMED local at index k mints. Two distinct locals
    // would then share an SMT name and a fact keyed to one would vacuously
    // discharge the other's obligation (confirmed FALSE PROOF: a field/whole-
    // local guard on a closure-env local `_1` vs a param literally named `_1`).
    // Fix: a source name shaped like ANY local's fallback token is ambiguous —
    // demote it too. (Demoting `_<self>` is a no-op; it already equals fallback.)
    // The same rule applies to every shared synthetic Formula spelling: a
    // scalar source local `s__slice_len` must not alias the generated length of
    // slice `s`, nor may `__trust_constparam_0_N` alias const generic `N`.
    // `trust-types` owns the conservative namespace classifier so extraction,
    // contract admission, vcgen, and the native bridge cannot drift.
    // Trust #soundness (base/segment-boundary false proof, round 4): the residual
    // leak neither demotion above covers. Both of them make the BASE token unique
    // among bases; neither makes the CONCATENATION `base ++ segments` decodable. A
    // local literally named `q.0` mints the base `q.0` — character-for-character
    // what `Place { local: <the local named "q">, projections: [Field(0)] }` mints,
    // a different place over different storage. That name is unique among source
    // names and is not `_<digits>`-shaped, so it passes both prior filters.
    // Consumers that recover an obligation's subject by NAME-STRING equality then
    // accept a statement defining one of the two as the defining statement of the
    // other. `docs/audits/2026-07-30-forgery-audit-r4-verdict.md` §1 records that
    // mint against the `trust-clean` locators — `DivByZero` for a function
    // containing no division, and `NegationOverflow(W32)`; that half was not
    // re-executed here. What IS re-executed here is the collision itself:
    // `place_name_boundary_tests` drives `generate_vcs` over two asserts about two
    // different places and, without the demotion below, the whole function's
    // emitted vocabulary is the single name `q.0`.
    //
    // Fixed at the boundary, not at the shape. This function returns
    // `base ++ segments`, so make the split point recoverable from the string:
    //   (i) every segment begins with a `PROJECTION_SEGMENT_LEAD` character —
    //       enforced below where each segment is built, so it holds for the arms
    //       written today AND for any arm added later, rather than being a property
    //       someone must re-verify by reading the match; and
    //   (ii) a base contains no such character — a source name that does is
    //       ambiguous and demotes to the unique `_<local>` spelling, exactly as the
    //       two demotions above do for their shapes.
    // Therefore, for EVERY name this function returns, the base is the prefix up to
    // the first `PROJECTION_SEGMENT_LEAD` character; no base can absorb a leading
    // segment, and no `base ++ segments` can be read back as a bare base. That is a
    // decomposition argument over the whole encoding rather than an enumeration of
    // collision shapes — which is the respect in which it differs from the two
    // comments above, each of which closed one shape and left this one open.
    //
    // What this does NOT claim is injectivity on places. `place_to_var_name` stays
    // deliberately non-injective: `canonicalize_place` maps distinct places that denote the same
    // storage onto one name (that is its purpose), and two segment spellings
    // coincide by construction — a constant `Index` and the corresponding
    // `ConstantIndex` both print `[c;min=len]` (`constant_array_index_segment`
    // returns that format at :3383 and :3418, and the `ConstantIndex` arm below
    // builds it too), which names element `c` of the same base place either way.
    // The claim is only about the base/segment boundary.
    //
    // Cost, measured over crates/trust-clean/fixtures: 2326 functions, 16827
    // locals, 4923 of them source-named; 0 names contain `.`, `[`, `*` or `@` —
    // 0 contain any character outside `[A-Za-z0-9_]` at all — so this demotion
    // fires nowhere in that corpus. Re-running `generate_vcs` over all 2326 with
    // this conjunct removed hashes every VC list identically: 0 functions change,
    // 0 certificates withdrawn (trust-clean's suite is unchanged at 2460 passing).
    // Extraction has TWO local-name producers and neither applies a character
    // filter: `build_debug_name_map` copies rustc's `var_debug_info` name
    // (`trust-mir-extract/src/lib.rs:4014`) screening only for the synthetic
    // namespace (`:4028`), and `recover_direct_parameter_names` /
    // `merge_recovered_parameter_names` (`:3253-3337`, called at `:1426`) recovers
    // HIR parameter idents under the same screen (`:3320`) plus duplicate/occupancy
    // screens. So whether a rustc-produced `Symbol` can carry one of these
    // characters is NOT settled here — only that none does across the corpus
    // above. Nothing rests on that question, because the direction is fail-closed:
    // this demotion only ever SEPARATES names, never merges them. The demoted
    // spelling is `format!("_{}", place.local)` above, a function of the local index
    // alone, so no other local's whole-place can mint it (a source name spelled
    // `_<k>` is demoted by `name_is_fallback_shaped` to its OWN index), and no
    // projected place can, since every projected name carries a
    // `PROJECTION_SEGMENT_LEAD` character and `_<k>` carries none. The worst case is
    // therefore a lost fact convergence — a false-fail, never a grant.
    let name_is_fallback_shaped = |name: &str| -> bool {
        name.as_bytes().get(1).is_some_and(u8::is_ascii_digit)
            && name.strip_prefix('_').and_then(|s| s.parse::<usize>().ok()).is_some()
    };
    let name_is_projection_shaped =
        |name: &str| -> bool { name.bytes().any(is_projection_segment_lead) };
    let matching_decl = locals.matching_decl(func, place.local);
    let mut out = match matching_decl.and_then(|decl| decl.name.as_deref()) {
        Some(name)
            if locals.name_count(func, name) <= 1
                && !name_is_fallback_shaped(name)
                && !name_is_projection_shaped(name)
                && trust_types::source_contract_synthetic_name_collision(name).is_none() =>
        {
            name.to_string()
        }
        _ => format!("_{}", place.local),
    };

    if !place.projections.is_empty() {
        use std::fmt::Write as _;
        out.reserve(place.projections.len() * 3);
        for (pos, p) in place.projections.iter().enumerate() {
            let seg_start = out.len();
            match p {
                Projection::Field(i) => {
                    let _ = write!(out, ".{i}");
                }
                Projection::Index(i) => {
                    if let Some(segment) = constant_array_index_segment(func, place, pos, *i) {
                        out.push_str(&segment);
                    } else {
                        let _ = write!(out, "[_{i}]");
                    }
                }
                Projection::Deref => out.push('*'),
                Projection::Downcast(i) => {
                    let _ = write!(out, "@{i}");
                }
                Projection::OpaqueCast(_) => out.push_str("@opaque_cast"),
                Projection::UnwrapUnsafeBinder(_) => out.push_str("@unwrap_unsafe_binder"),
                Projection::ConstantIndex { offset, min_length, from_end } => {
                    if *from_end {
                        let _ = write!(out, "[-{offset};min={min_length}]");
                    } else {
                        let _ = write!(out, "[{offset};min={min_length}]");
                    }
                }
                Projection::Subslice { from, to, from_end } => {
                    if *from_end {
                        let _ = write!(out, "[{from}..-{to}]");
                    } else {
                        let _ = write!(out, "[{from}..{to}]");
                    }
                }
                // `Projection` is `#[non_exhaustive]`
                // (`trust-types/src/model.rs:5720`), so this arm exists for
                // variants that do not exist yet; the eight above are every
                // variant declared today. Its `unknown` spelling has no lead
                // character, which is exactly the hazard the wrapper below
                // catches — a future variant would otherwise mint a segment
                // that reads back as part of a base name.
                _ => out.push_str("unknown"),
            }
            // Half (i) of the base/segment-boundary invariant, enforced rather
            // than assumed: a segment that would not announce itself gets an
            // `@` so the decode point stays unambiguous. No-op today — every arm
            // above already starts with `.`, `[`, `*` or `@`, including all
            // three `Some` returns of `constant_array_index_segment`
            // (`[c;min=len]` at :3383 and :3418, `[c;slice]` at :3419).
            // `place_name_boundary_tests::every_projection_segment_leads` pins
            // ten spellings — one per `Projection` variant plus the `from_end`
            // twins of `ConstantIndex`/`Subslice` — and
            // `tests::arr_literal_const_index_read_name_matches_aggregate_write_name`
            // (:6706) pins `[c;min=N]`, and
            // `tests::deref_shared_slice_ref_const_index_converges` (tests.rs:7176)
            // pins `[c;slice]` as the golden string `s*[0;slice]` (:7204-7205).
            // Exactly ONE constructible spelling is pinned by no test: this wildcard
            // arm's `@unknown`. (An earlier draft said "two", missing the slice
            // golden because it grepped for the literal `c;slice` rather than for an
            // instantiated const — a coverage gap asserted, not measured.) Over
            // crates/trust-clean/fixtures the prefix fires 0 times: re-running
            // `generate_vcs` over all 2326 fixture functions with this branch
            // removed hashes every VC list identically.
            if !out.as_bytes().get(seg_start).copied().is_some_and(is_projection_segment_lead) {
                out.insert(seg_start, '@');
            }
        }
    }
    out
}

/// THE OPAQUE-DEREF CONTRACT: `deref_pointer_is_opaque` must answer TRUE
/// whenever the mint keeps the `local*` spelling for a store through `local`.
///
/// Trust: 2026-09-18 — this pins the property that MATTERS, not the predicate's
/// own definition: for every deref store in the family below, the store's minted
/// SMT name must be the same name a READ of the referent gets (so
/// `write_rebinds` kills the stale fact by name), or the pointer must be opaque
/// (so `deref_store_havoc_names` kills it by havoc). A store that is NEITHER is
/// a fact about the referent surviving across a write of it — the false-proof
/// `deref_pointer_is_opaque` exists to prevent.
///
/// The family is the `p = &mut *m` reborrow chain, with and without a rebind of
/// the referent's index guard between the last borrow and the store. The
/// no-rebind row is the CONTROL that pins the fold still happening
/// (over-opaquing everything passes the first assertion and fails the second).
///
/// WHAT THIS TEST DOES NOT DO, stated so nobody reads more into a green than is
/// there: it does NOT reproduce the round-A12 `reread_through` refusal that
/// broke the biconditional. Measured on this tree 2026-09-18, depths 1..=4:
///
/// ```text
/// depth 1 rebind false: store=s[_1] read=s[_1] opaque=false
/// depth 1 rebind true:  store=_4*   read=s[_1] opaque=true
/// depth 2 rebind false: store=s[_1] read=s[_1] opaque=false
/// depth 2 rebind true:  store=_5*   read=s[_1] opaque=true
/// depth 3 rebind false: store=s[_1] read=s[_1] opaque=false
/// depth 3 rebind true:  store=_6*   read=s[_1] opaque=true
/// depth 4 rebind false: store=s[_1] read=s[_1] opaque=false
/// depth 4 rebind true:  store=_7*   read=s[_1] opaque=true
/// ```
///
/// Every `opaque=true` row here is the PRE-A12 exit: the rebind is inside the
/// walked region of the outermost pointer, so `referent_fold::is_stable` refuses
/// at the TOP level and `resolve_referent` answers `None` before the fold's
/// fourth exit is ever reached. The fourth exit needs `resolve_referent` to hand
/// back a slot that STILL folds further, and every slot it hands back has
/// already been folded — `Rvalue::Ref`'s arm runs `canonicalize_deref_guarded`
/// on the borrowed place, and `referent_of_source`'s definitional fallbacks only
/// fire for a local with no whole-local def at all (so they are fold fixpoints
/// at every fuel). By induction the only base case left is fuel EXHAUSTION: the
/// slot is computed at `fuel - 2` and re-folded at `fuel - 1`, so a chain deep
/// enough to truncate at 16 can disagree by one hop. That regime is where the
/// defect lives, and it is not swept here — see the cost note on the test.
#[cfg(test)]
mod opaque_deref_mint_agreement_tests {
    use trust_types::{
        BasicBlock, BlockId, ConstValue, LocalDecl, Operand, Place, Projection, Rvalue, SourceSpan,
        Statement, Terminator, Ty, VerifiableBody, VerifiableFunction,
    };

    use super::{deref_pointer_is_opaque, deref_store_is_opaque, place_to_var_name};

    fn assign(place: Place, rvalue: Rvalue) -> Statement {
        Statement::Assign { place, rvalue, span: SourceSpan::default() }
    }

    fn deref(local: usize) -> Place {
        Place { local, projections: vec![Projection::Deref] }
    }

    /// `fn f(j: usize, k: usize) { let mut s = [0u32; 4];
    ///    let p1 = &mut s[j]; let p2 = &mut *p1; ... let pN = &mut *p(N-1);
    ///    [j = k;] *pN = 7; }`
    ///
    /// `_1` is `j`, `_2` is `k`, `_3` is `s`, `_4 ..= _(3+depth)` are the chain.
    fn reborrow_chain(depth: usize, rebind_index_guard: bool) -> VerifiableFunction {
        assert!(depth >= 1);
        let u32_ty = Ty::Int { width: 32, signed: false };
        let usize_ty = Ty::Int { width: 64, signed: false };
        let ptr_ty = Ty::Ref { mutable: true, inner: Box::new(u32_ty.clone()) };
        let mut locals = vec![
            LocalDecl { index: 0, ty: Ty::Unit, name: None },
            LocalDecl { index: 1, ty: usize_ty.clone(), name: Some("j".into()) },
            LocalDecl { index: 2, ty: usize_ty, name: Some("k".into()) },
            LocalDecl {
                index: 3,
                ty: Ty::Array { elem: Box::new(u32_ty), len: 4 },
                name: Some("s".into()),
            },
        ];
        let mut stmts = vec![assign(
            Place::local(4),
            Rvalue::Ref {
                mutable: true,
                place: Place { local: 3, projections: vec![Projection::Index(1)] },
            },
        )];
        locals.push(LocalDecl { index: 4, ty: ptr_ty.clone(), name: None });
        for step in 1..depth {
            let local = 4 + step;
            locals.push(LocalDecl { index: local, ty: ptr_ty.clone(), name: None });
            stmts.push(assign(
                Place::local(local),
                Rvalue::Ref { mutable: true, place: deref(local - 1) },
            ));
        }
        if rebind_index_guard {
            stmts.push(assign(Place::local(1), Rvalue::Use(Operand::Copy(Place::local(2)))));
        }
        stmts.push(assign(deref(3 + depth), Rvalue::Use(Operand::Constant(ConstValue::Int(7)))));
        VerifiableFunction {
            name: format!("reborrow_chain_{depth}"),
            def_path: "test::reborrow_chain".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals,
                blocks: vec![BasicBlock { id: BlockId(0), stmts, terminator: Terminator::Return }],
                arg_count: 2,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// The read the store must not silently pass: `s[j]`, the referent itself.
    fn read_place() -> Place {
        Place { local: 3, projections: vec![Projection::Index(1)] }
    }

    /// THE PIN. Depth is swept because the fold is FUEL-bounded: the slot
    /// `resolve_referent` hands back is computed with one less unit of fuel than
    /// the re-fold that follows it, so deep chains are exactly where the mint
    /// and the resolver can disagree. Every depth must satisfy the contract.
    ///
    /// The sweep stops at 4 for COST, not for coverage: measured 2026-09-18 on
    /// this tree, the referent-fold machinery (`resolve_referent` ->
    /// `canonicalize_deref_guarded` -> `reread_through` -> `resolve_referent`
    /// again) is super-linear in chain depth, and a 1..=12 sweep did not
    /// terminate in 14 minutes of CPU. That cost is PRE-EXISTING — the fold
    /// re-resolves the carrier on every level — and is recorded here rather
    /// than fixed; depths 1..=4 already cover the reborrow shape with and
    /// without the guard rebind.
    #[test]
    fn an_opaque_deref_store_never_escapes_both_the_name_kill_and_the_havoc() {
        for depth in 1..=4 {
            for rebind in [false, true] {
                let func = reborrow_chain(depth, rebind);
                let ptr = 3 + depth;
                let store = place_to_var_name(&func, &deref(ptr));
                let read = place_to_var_name(&func, &read_place());
                let opaque = deref_pointer_is_opaque(&func, ptr);
                eprintln!(
                    "depth {depth} rebind {rebind}: store={store} read={read} opaque={opaque}"
                );
                assert!(
                    store == read || opaque,
                    "depth {depth}, rebind {rebind}: the store through `_{ptr}` mints \
                     `{store}` while a read of the referent mints `{read}` — the names \
                     do not overlap, so the name-based redef kill cannot see the store — \
                     and `deref_pointer_is_opaque` is FALSE, so the deref-store havoc is \
                     empty too. A fact about the referent survives the write of it."
                );
            }
        }
    }

    /// THE CONTROL, in the opposite direction: with no rebind of the index guard
    /// the fold is legitimate and the store must converge on the referent's own
    /// name at the depths the fuel reaches. Without this a mutant that answers
    /// `true` unconditionally passes the pin above.
    #[test]
    fn a_guard_stable_reborrow_chain_still_folds_onto_the_referent_name() {
        let func = reborrow_chain(1, false);
        let store = place_to_var_name(&func, &deref(4));
        let read = place_to_var_name(&func, &read_place());
        assert_eq!(
            store, read,
            "a single `&mut s[j]` with no rebind must fold: the store and the read \
             name the same storage"
        );
        assert!(
            !deref_pointer_is_opaque(&func, 4),
            "a folded store must NOT be opaque, or every such body pays the whole-function havoc"
        );
    }

    /// `fn f(j: usize, k: usize) { let mut s = [0u32; 4];
    ///    let x = &mut s[j]; let q = &x; j = k; **q = 7; }`
    ///
    /// `_1` = j, `_2` = k, `_3` = s, `_4` = x (`&mut u32`), `_5` = q (`&&mut u32`,
    /// a SHARED borrow of `_4`, which `Statement::escapes_local_storage` does not
    /// count — so `_4` stays resolvable).
    fn shared_carrier_double_deref() -> VerifiableFunction {
        let u32_ty = Ty::Int { width: 32, signed: false };
        let usize_ty = Ty::Int { width: 64, signed: false };
        let ptr_ty = Ty::Ref { mutable: true, inner: Box::new(u32_ty.clone()) };
        let carrier_ty = Ty::Ref { mutable: false, inner: Box::new(ptr_ty.clone()) };
        let locals = vec![
            LocalDecl { index: 0, ty: Ty::Unit, name: None },
            LocalDecl { index: 1, ty: usize_ty.clone(), name: Some("j".into()) },
            LocalDecl { index: 2, ty: usize_ty, name: Some("k".into()) },
            LocalDecl {
                index: 3,
                ty: Ty::Array { elem: Box::new(u32_ty), len: 4 },
                name: Some("s".into()),
            },
            LocalDecl { index: 4, ty: ptr_ty, name: None },
            LocalDecl { index: 5, ty: carrier_ty, name: None },
        ];
        let stmts = vec![
            assign(
                Place::local(4),
                Rvalue::Ref {
                    mutable: true,
                    place: Place { local: 3, projections: vec![Projection::Index(1)] },
                },
            ),
            // SHARED borrow of the pointer local itself: `_5` points AT `_4`.
            assign(Place::local(5), Rvalue::Ref { mutable: false, place: Place::local(4) }),
            // The referent's index guard is rebound between the borrow and the store.
            assign(Place::local(1), Rvalue::Use(Operand::Copy(Place::local(2)))),
            assign(
                Place { local: 5, projections: vec![Projection::Deref, Projection::Deref] },
                Rvalue::Use(Operand::Constant(ConstValue::Int(7))),
            ),
        ];
        VerifiableFunction {
            name: "shared_carrier_double_deref".to_string(),
            def_path: "test::shared_carrier_double_deref".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals,
                blocks: vec![BasicBlock { id: BlockId(0), stmts, terminator: Terminator::Return }],
                arg_count: 2,
                return_ty: Ty::Unit,
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    /// THE WITNESS for the place-keyed fix, built and RUN on 2026-09-18 (not a
    /// compiled program: a hand-built body in this crate's own MIR types, so it
    /// demonstrates the predicate disagreement, not an end-to-end false PROVE).
    ///
    /// `**q = 7` is a store whose place is `_5` projected by TWO `Deref`s. The
    /// local-keyed probe asks about the bare `*_5`, which folds to `_4` — a fold
    /// FIXPOINT, so `canonicalize_deref` returns before it ever reaches the
    /// `reread_through` obligation — and answers "not opaque". The MINT, asked
    /// about the place actually written, appends the second `Deref`: the referent
    /// becomes `*_4`, which DOES fold (to `s[_1]`), so the re-read obligation is
    /// asked after all — and refused, because `_1` is rebound between the borrow
    /// and the store. The store therefore mints the opaque `_5**`, which does not
    /// overlap the `_3[_1]` a read of the referent mints, while the local-keyed
    /// predicate leaves the deref-store havoc EMPTY: a fact about `s[j]` survives
    /// a write of it, the false-proof shape.
    #[test]
    fn a_projected_store_escapes_the_local_keyed_probe() {
        let func = shared_carrier_double_deref();
        let store_place =
            Place { local: 5, projections: vec![Projection::Deref, Projection::Deref] };
        let store = place_to_var_name(&func, &store_place);
        let read = place_to_var_name(&func, &read_place());
        let local_keyed = deref_pointer_is_opaque(&func, 5);
        let place_keyed = deref_store_is_opaque(&func, &store_place);
        eprintln!("store={store} read={read} local_keyed={local_keyed} place_keyed={place_keyed}");
        assert_ne!(
            store, read,
            "the shape of this witness is that the store's name does NOT overlap the \
             referent read's name; if they converged there would be nothing to havoc"
        );
        assert!(
            !local_keyed,
            "the local-keyed probe is the DEFECT half of this witness: it must answer \
             false (it probes `*_5`, which folds to `_4`)"
        );
        assert!(
            place_keyed,
            "the place-keyed predicate must answer TRUE for `**_5`: the mint kept the \
             opaque `{store}` spelling for it, so only the havoc can kill a fact about \
             the referent this store writes"
        );
    }

    /// THE CONTROL for the witness above, in the opposite direction: with the
    /// guard rebind removed the double-deref store folds legitimately onto the
    /// referent's own name, and the place-keyed predicate must answer FALSE.
    /// Without this a mutant that returns `true` for every projected deref store
    /// passes the witness — and pays the whole-function havoc on every body that
    /// writes through a carried pointer.
    #[test]
    fn a_guard_stable_double_deref_store_still_folds_onto_the_referent_name() {
        let mut func = shared_carrier_double_deref();
        // Drop `_1 = _2`, the rebind of the referent's index guard.
        func.body.blocks[0].stmts.remove(2);
        let store_place =
            Place { local: 5, projections: vec![Projection::Deref, Projection::Deref] };
        let store = place_to_var_name(&func, &store_place);
        let read = place_to_var_name(&func, &read_place());
        assert_eq!(
            store, read,
            "with no rebind between the borrow and the store, `**q` must fold: the store \
             and the read name the same storage"
        );
        assert!(
            !deref_store_is_opaque(&func, &store_place),
            "a folded projected store must NOT be opaque, or every body that stores \
             through a carried pointer pays the whole-function havoc"
        );
    }

    /// The pre-A12 exits, unchanged by the 2026-09-18 restatement: a pointer
    /// PARAMETER has no referent at all, so it is opaque and its store is
    /// covered by the havoc rather than by a name.
    #[test]
    fn a_pointer_parameter_is_still_opaque() {
        let mut func = reborrow_chain(1, false);
        // Make `_4` a parameter with no def: drop its borrow statement.
        func.body.blocks[0].stmts.remove(0);
        assert!(
            deref_pointer_is_opaque(&func, 4),
            "a pointer with no resolvable referent must stay opaque"
        );
    }
}

