#[cfg(test)]
mod f5_e2e_repro {
    use trust_types::{
        BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, SourceSpan, Statement, Terminator,
        Ty, VcKind, VerifiableBody, VerifiableFunction,
    };

    use crate::modular::{FunctionSummary, SummaryDatabase};

    fn assign(place: Place, rvalue: Rvalue) -> Statement {
        Statement::Assign { place, rvalue, span: SourceSpan::default() }
    }

    #[test]
    fn f5_e2e_shape_dominance_fires() {
        let text =
            "(a) <= (1.0e150) && (a) >= (-(1.0e150)) && (b) <= (1.0e150) && (b) >= (-(1.0e150))";
        let pre = trust_types::parse_spec_expr(text).expect("parses");
        eprintln!("PARSED: {pre:?}");
        let func = VerifiableFunction {
            name: "caller".to_string(),
            def_path: "test::caller".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: Ty::f64_ty(), name: Some("_0".into()) },
                    LocalDecl { index: 1, ty: Ty::f64_ty(), name: Some("a".into()) },
                    LocalDecl { index: 2, ty: Ty::f64_ty(), name: Some("b".into()) },
                    LocalDecl { index: 3, ty: Ty::f64_ty(), name: None },
                    LocalDecl { index: 4, ty: Ty::f64_ty(), name: None },
                    LocalDecl { index: 5, ty: Ty::f64_ty(), name: None },
                ],
                blocks: vec![
                    BasicBlock {
                        id: BlockId(0),
                        stmts: vec![
                            assign(Place::local(3), Rvalue::Use(Operand::Copy(Place::local(1)))),
                            assign(Place::local(4), Rvalue::Use(Operand::Copy(Place::local(2)))),
                        ],
                        terminator: Terminator::Call {
                            unwind: trust_types::UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: crate::sep_engine::tests::fixture_key("test::callee"),
                            is_foreign: false,
                            func: "test::callee".to_string(),
                            args: vec![
                                Operand::Move(Place::local(3)),
                                Operand::Move(Place::local(4)),
                            ],
                            dest: Place::local(5),
                            target: Some(BlockId(1)),
                            span: SourceSpan::default(),
                            atomic: None,
                        },
                    },
                    BasicBlock {
                        id: BlockId(1),
                        stmts: vec![assign(
                            Place::local(0),
                            Rvalue::Use(Operand::Copy(Place::local(5))),
                        )],
                        terminator: Terminator::Return,
                    },
                ],
                arg_count: 2,
                return_ty: Ty::f64_ty(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![pre.clone()],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        };
        let mut db = SummaryDatabase::new();
        let summary = FunctionSummary::new("test::callee")
            .with_param_names(vec!["a".to_string(), "b".to_string()])
            .with_precondition(pre);
        db.insert(summary);
        let vcs = crate::generate::generate_callsite_precondition_vcs(&func, &db);
        let precond: Vec<_> =
            vcs.iter().filter(|vc| matches!(vc.kind, VcKind::Precondition { .. })).collect();
        assert!(
            precond.is_empty(),
            "F5 dominance must skip the exactly-matching precondition; got {:#?}",
            precond.iter().map(|vc| &vc.formula).collect::<Vec<_>>()
        );
    }
}

/// SPEC-FLOAT-EQ-STRUCTURAL-1 at the call site: `requires x == y` over two f64
/// formals, called as `c_xy(f64::NAN, f64::NAN)`. The callsite producer replaces
/// each formal with the actual's model, which for a float constant is its bit
/// pattern. With the contract spelled structural `Eq` (the old spelling) the
/// obligation was the well-sorted bit equation `not (= bvNaN bvNaN)`, which every
/// lane proved; spelled IEEE `FpEq` it is IEEE equality over bit vectors, which no
/// sort checker admits, so every lane declines it.
#[cfg(test)]
mod spec_float_eq_callsite_tests {
    use std::collections::BTreeMap;

    use trust_types::{
        BasicBlock, BlockId, ConstValue, Formula, LocalDecl, Operand, Place, Sort, SourceSpan,
        Terminator, Ty, VcKind, VerifiableBody, VerifiableFunction, check_formula_sort,
    };

    use crate::modular::{FunctionSummary, SummaryDatabase};

    fn caller_of_c_xy(x: f64, y: f64) -> VerifiableFunction {
        VerifiableFunction {
            name: "k_xy".to_string(),
            def_path: "test::k_xy".to_string(),
            span: SourceSpan::default(),
            body: VerifiableBody {
                locals: vec![LocalDecl { index: 0, ty: Ty::f64_ty(), name: None }],
                blocks: vec![
                    BasicBlock {
                        id: BlockId(0),
                        stmts: vec![],
                        terminator: Terminator::Call {
                            unwind: trust_types::UnwindEdge::Unreachable,
                            is_unsafe_sig: false,
                            callee_identity: None,
                            callee_key: crate::sep_engine::tests::fixture_key("test::c_xy"),
                            is_foreign: false,
                            func: "test::c_xy".to_string(),
                            args: vec![
                                Operand::Constant(ConstValue::Float(x)),
                                Operand::Constant(ConstValue::Float(y)),
                            ],
                            dest: Place::local(0),
                            target: Some(BlockId(1)),
                            span: SourceSpan::default(),
                            atomic: None,
                        },
                    },
                    BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
                ],
                arg_count: 0,
                return_ty: Ty::f64_ty(),
                datatype_defs: Default::default(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
            tuple_layouts: Default::default(),
        }
    }

    fn precondition_vcs(pre: Formula, x: f64, y: f64) -> Vec<Formula> {
        let mut db = SummaryDatabase::new();
        db.insert(
            FunctionSummary::new("test::c_xy")
                .with_param_names(vec!["x".to_string(), "y".to_string()])
                .with_precondition(pre),
        );
        crate::generate::generate_callsite_precondition_vcs(&caller_of_c_xy(x, y), &db)
            .into_iter()
            .filter(|vc| matches!(vc.kind, VcKind::Precondition { .. }))
            .map(|vc| vc.formula)
            .collect()
    }

    fn contract_x_eq_y() -> Formula {
        let sorts: BTreeMap<String, Sort> = ["x", "y"]
            .into_iter()
            .map(|name| (name.to_string(), Sort::Float { eb: 11, sb: 53 }))
            .collect();
        trust_types::retype_formula_variables(
            trust_types::parse_spec_expr("x == y").expect("parses"),
            &sorts,
        )
    }

    #[test]
    fn nan_call_obligation_is_ieee_equality_no_lane_admits() {
        let pre = contract_x_eq_y();
        assert!(matches!(pre, Formula::FpEq(..)), "{pre:?}");
        for (x, y) in [(f64::NAN, f64::NAN), (0.0, -0.0), (3.0, 3.0)] {
            let vcs = precondition_vcs(pre.clone(), x, y);
            assert_eq!(vcs.len(), 1, "({x}, {y}): {vcs:?}");
            let mut fp_eq_over_bits = false;
            vcs[0].visit(&mut |node| {
                if let Formula::FpEq(lhs, rhs) = node
                    && matches!(**lhs, Formula::BitVec { width: 64, .. })
                    && matches!(**rhs, Formula::BitVec { width: 64, .. })
                {
                    fp_eq_over_bits = true;
                }
            });
            assert!(fp_eq_over_bits, "({x}, {y}): {:?}", vcs[0]);
            assert!(
                check_formula_sort(&vcs[0]).is_err(),
                "({x}, {y}) must be sort-invalid, so every lane declines it: {:?}",
                vcs[0]
            );
        }
    }

    /// The BEFORE spelling, pinned so the difference is visible: structural `Eq`
    /// substitutes into a WELL-SORTED bit equation, which is what was proved for
    /// the NaN call.
    #[test]
    fn structural_spelling_made_a_well_sorted_bit_equation() {
        let f64s = Sort::Float { eb: 11, sb: 53 };
        let structural = Formula::Eq(
            Box::new(Formula::Var("x".to_string(), f64s.clone())),
            Box::new(Formula::Var("y".to_string(), f64s)),
        );
        let vcs = precondition_vcs(structural, f64::NAN, f64::NAN);
        assert_eq!(vcs.len(), 1);
        assert_eq!(check_formula_sort(&vcs[0]), Ok(Sort::Bool), "{:?}", vcs[0]);
    }

    /// T3 C07p: both callsite producers write every row they return into the caller's
    /// context through the row oracle, and return the rows the tree-only producers return.
    #[test]
    fn callsite_rows_go_through_the_row_oracle() {
        use trust_types::vc_context::{Oracle, ParityCount, VcContext, same_row};

        let f64s = Sort::Float { eb: 11, sb: 53 };
        let mut db = SummaryDatabase::new();
        db.insert(
            FunctionSummary::new("test::c_xy")
                .with_param_names(vec!["x".to_string(), "y".to_string()])
                .with_precondition(Formula::Eq(
                    Box::new(Formula::Var("x".to_string(), f64s.clone())),
                    Box::new(Formula::Var("y".to_string(), f64s)),
                )),
        );
        let caller = caller_of_c_xy(3.0, 3.0);
        let mut rows = VcContext::new();
        let interned =
            crate::generate::generate_callsite_precondition_vcs_rows(&caller, &db, &mut rows);
        let tree = crate::generate::generate_callsite_precondition_vcs(&caller, &db);
        assert!(!interned.is_empty());
        assert_eq!(interned.len(), tree.len());
        assert!(interned.iter().zip(&tree).all(|(a, b)| same_row(a, b)));
        let attributed = crate::generate::generate_callsite_precondition_vcs_attributed_rows(
            &caller, &db, &mut rows,
        );
        let attributed_tree =
            crate::generate::generate_callsite_precondition_vcs_attributed(&caller, &db);
        assert_eq!(attributed.len(), attributed_tree.len());
        for ((vc, substituted, guards), (tree_vc, tree_substituted, tree_guards)) in
            attributed.iter().zip(&attributed_tree)
        {
            assert!(same_row(vc, tree_vc));
            assert_eq!((substituted, guards), (tree_substituted, tree_guards));
        }
        let checked = (interned.len() + attributed.len()) as u64;
        assert_eq!(rows.parity(Oracle::Row), ParityCount { rows: checked, mismatches: 0 });
    }
}
